def keyboard_magnetic_mapping_sources(pid):
    """Decode current magnetic defaults while retaining their complete modules."""
    import host
    audit = host.HostLocalAudit()
    sets, files = audit.source_set(f"keyboard-mw-{pid}-current")
    main = next(row for row in files if Path(row["path"]).name.startswith("main."))
    runtime = next(row for row in files if Path(row["path"]).name.startswith("6737."))
    engine = next(row for row in files if Path(row["path"]).name.startswith("obmEngineKeyboard."))
    worker = next(row for row in files if Path(row["path"]).name.startswith("obmHelper.worker."))
    mapping_engine = next(row for row in files if Path(row["path"]).name.startswith("7795."))
    memory_engine = next(row for row in files if Path(row["path"]).name.startswith("obmEngineKeyboardCalMaxMem."))
    command_constants = next(row for row in files if Path(row["path"]).name.startswith("3159."))
    modules, originals = {}, {}
    for source, ids in [(main, [26061, 11469, 86191, 7414, 39158]),
                        (runtime, [32906, 72233, 51765, 93494, 36475, 68214, 4849,
                                   61450, 56839, 6258, 34737]),
                        (engine, [26803, 49886, 66487, 39674]),
                        (mapping_engine, [11936]), (memory_engine, [48363, 96236]),
                        (command_constants, [48967])]:
        rows = {row["module_id"]: row for row in keyboard_source_modules(audit.read(source).decode("utf-8"))}
        selected = set(ids)
        selected.update(mid for mid, row in rows.items() if isinstance(mid, int) and any(anchor in row["body"]
            for anchor in ["taskmakerSyncGlobalActuation", "ON_SYNC_GLOBAL_ACTUATION", "onTaskRunnerMapping",
                           "storeDeviceMapping", "compileAnalogMapping", "getAnalogInputMap",
                           "setActuationPoint", "getRazerKey", "convertInputMapping"]))
        for mid in sorted(selected):
            if mid not in rows:
                raise ValueError(f"Current magnetic module {pid}/{mid} is absent")
            row = rows[mid]
            start = row["byte_start"]
            body = row["body"].encode("utf-8")
            key = audit.retain_range("module_" + str(mid), source, start, start + len(body), "method_definition")
            modules[mid] = key
            originals[mid] = source
    def body(mid):
        return audit.owners[modules[mid]]["body"]
    def expression(text, name):
        found = re.search(r'(?<![\w$])' + re.escape(name) + r'=(\{|\[)', text)
        if found is None:
            raise ValueError("Current magnetic literal is absent: " + name)
        return text[found.end()-1:javascript_delimited(text, found.end()-1)]
    def literal(text):
        text = text.replace("!0", "true").replace("!1", "false")
        text = re.sub(r'([{,])(\d+):', r'\1"\2":', text)
        text = re.sub(r'(?<=[\[:,])\.(\d+)', r'0.\1', text)
        return static_js_literal(text)
    config, aliases, preset = body(26061), body(11469), body(72233)
    exports = dict(re.findall(r'([\w$]+):\(\)=>([\w$]+)', config))
    alias_exports = dict(re.findall(r'([\w$]+):\(\)=>([\w$]+)', aliases))
    strings = dict(re.findall(r'\b([\w$]+)="([^"\\]*)"(?=[,;])', aliases))
    mjm = re.search(r'\b' + re.escape(alias_exports["MJm"]) + r'=\(', aliases)
    mjm_body = aliases[mjm.end()-1:javascript_delimited(aliases, mjm.end()-1)]
    strings[alias_exports["MJm"]] = re.search(r',"([^"\\]*)"\)$', mjm_body)[1]
    alias_import = re.search(r'\b([\w$]+)=[\w$]+\(11469\)', config)[1]
    def config_literal(text):
        return literal(re.sub(r'`\$\{' + re.escape(alias_import) + r'\.([\w$]+)\}`',
            lambda match: json.dumps(strings[alias_exports[match[1]]]), text))
    values = {name: config_literal(expression(config, exports[name])) for name in
              ["DEFAULTPROFILE", "DEFAULTMAPPINGS", "FULLMAPPINGLIST", "BUTTON_LIST", "DEFAULT_FIRMWARE_MAPPINGS"]}
    if "bottomDeadzone" in exports or "bottomDeadzoneMap" in config:
        raise ValueError("Magnetic bottom deadzone product override requires an explicit branch")
    values["bottom_deadzone"] = literal(expression(body(34737), "Mt"))
    headers = {}
    for name in ["Eid", "r6_", "PeF"]:
        captured = audit.webpack_export("magnetic_command_" + name, [command_constants], 48967, name)
        header = re.fullmatch(r"new Uint8Array\((\[[^\[\]]+\])\)", captured["binding"]["body"].split("=", 1)[1])
        if header is None:
            raise ValueError("Magnetic command header is not a closed byte array: " + name)
        headers[name] = literal(header[1])
        if len(headers[name]) != 3 or any(type(value) is not int or not 0 <= value <= 255 for value in headers[name]):
            raise ValueError("Magnetic command header fields differ: " + name)
    values["interrupt_and_deadzone_headers"] = headers
    device = next(row for row in files if Path(row["path"]).name.startswith("rzDevice25."))
    for method, parameters in [("setAnalogKeyBottomDeadZoneValue", "t,n"),
                               ("setInterruptibleMacroSettings", "t,n,e,o,a=-1"),
                               ("setInterruptibleDynamicKeystrokeSettings", "t,n,e,o,a=-1"),
                               ("setSingleKeySnapTapCtrl", "t,n,e")]:
        owners = audit.retain("magnetic_" + method, device, method + "(" + parameters + "){", {"method_definition"})
        if len(owners) != 1:
            raise ValueError("Magnetic setter does not have one complete method owner: " + method)
    guest = audit.webpack_export("guest_profile_owner", files, 7414, "KK")
    values["guest_profile_owner"] = static_js_literal(guest["binding"]["body"].split("=", 1)[1])
    for name in ["DEFAULTMAPPINGS_JPN", "DEFAULTMAPPINGS_UK", "BUTTON_LIST_JP", "BUTTON_LIST_UK"]:
        if name in exports:
            values[name] = config_literal(expression(config, exports[name]))
    guids = literal(expression(preset, "f"))
    common = literal(expression(preset, "v"))
    common_call = re.search(r'\bm=\(\)=>\(\{(.*?)\}\)', preset)[1]
    common_keys = re.findall(r'([\w$]+):Object\.assign\(\{\},v\)', common_call)
    if ",".join(name + ":Object.assign({},v)" for name in common_keys) != common_call:
        raise ValueError("Current magnetic preset common keys contain unresolved expressions")
    def preset_literal(text):
        text = re.sub(r'\bf\.([\w$]+)', lambda match: json.dumps(guids[match[1]]), text)
        return literal(text.replace("m()", json.dumps({name: common for name in common_keys})))
    values.update({"preset_guids": guids, "preset_mappings": preset_literal(expression(preset, "y")),
                   "preset_actuation": preset_literal(expression(preset, "h")),
                   "preset_rapid_trigger": preset_literal(expression(preset, "_"))})
    for name in ["defaultActuation", "defaultRapidTrigger"]:
        at = preset.index("this." + name + "=") + len("this." + name + "=")
        values[name] = literal(preset[at:javascript_delimited(preset, at)])
    registration = body(86191)
    if "ignoreProfiles" in registration:
        raise ValueError("Magnetic onboard preset gate requires an explicit current branch")
    presets = preset_literal(expression(preset, "I"))
    if {row["guid"] for row in presets} != set(guids.values()) or len(presets) != len(guids):
        raise ValueError("Magnetic preset registration identities are incomplete")
    values["onboard_preset_guids"] = [row["guid"] for row in presets if row["guid"] != guids["GENERAL"]]
    scan_tables = []
    worker_table_source = worker
    if b"72:57414" not in audit.read(worker):
        bootstrap = audit.retain("macro_worker_bootstrap", worker, "importScripts(", {"call_expression"})
        if len(bootstrap) != 1 or not re.search(rb'7338:"([a-f0-9]+)"', audit.read(worker)):
            raise ValueError("Magnetic worker scancode import closure is unresolved")
        worker_table_source = next(row for row in files if Path(row["path"]).name.startswith("7338."))
    for source, role in [(worker_table_source, "macro_worker_scancodes"), (engine, "macro_engine_scancodes")]:
        owner = audit.retain(role, source, "72:57414", {"variable_declarator"})[0]
        fragment = audit.owners[owner]["body"]
        start = fragment.index("{")
        table = literal(fragment[start:javascript_delimited(fragment, start)])
        if any(not key.isdecimal() or type(value) is not int or not 0 <= int(key) <= 65535
               or not 0 <= value <= 0xffffffff for key, value in table.items()):
            raise ValueError("Magnetic macro HID conversion table contains invalid typed values")
        scan_tables.append(table)
    if scan_tables[0] != scan_tables[1]:
        raise ValueError("Magnetic worker and inline macro scancode tables differ")
    values["macro_scancodes"] = [{"hid": int(key), "scancode": value} for key, value in scan_tables[0].items()]
    at = registration.index("inputMapping:{keyboard:") + len("inputMapping:")
    firmware = literal(expression(body(32906), "a"))
    for mode, overrides in literal(registration[at:javascript_delimited(registration, at)])["keyboard"].items():
        firmware[mode].update(overrides)
    values["firmware_keyboard"] = firmware
    values["physical_keys"] = [{"inputID": key, "fwID": row["fwID"]}
        for key, row in firmware["NormalMode"].items()
        if type(row.get("fwID")) is int and row["fwID"] != 255 and any(
            button.get("inputID") == key and button.get("inputType") in ["KeyInput", "AnalogInput"]
            for button in values["BUTTON_LIST"])]
    values["obm_encoding"] = {"function_ids": literal(expression(body(36475), "o")),
        "modifier_bits": literal(expression(body(39674), "s")),
        "modifier_names": literal(expression(body(68214), "f")),
        "media_codes": literal(expression(body(39674), "n")),
        "media_names": literal(expression(body(68214), "d")),
        "power_codes": literal(expression(body(39674), "i")),
        "razer_codes": literal(expression(body(68214), "m"))}
    values["obm_default_buttons"] = {name: magnetic_default_button_bytes(rows, values["obm_encoding"])
                                    for name, rows in values.items() if name.startswith("BUTTON_LIST")}
    changed = audit.final_snapshot()
    if changed:
        raise ValueError("Magnetic mapping originals changed during query")
    return {"product_id": pid, "acquisition": sets, "parsers": audit.parser_versions,
            "complete_owners": audit.owners, "modules": modules, "values": values,
            "semantics": {"onboard_macro_hash": "Current4849.Zd delegates to11936.getHash, which canonicalizes through39158 stable stringify, excludes configured fields, escapes less-than and hashes MD5. Rust shares mapping_engine_hash::source_hash rather than a keyboard-specific encoder.",
                "memory_owner": "Current48363 selects maxMemoryType availableMemory;96236 selects macroMemoryType calculate. Complete66487 addMacro only invokes defrag for deviceType equal to literal mouse. Magnetic keyboard macro allocation updates its typed calculation ledger without automatically formatting/resetting profile or unrelated actuation, lighting and mapping state.",
                "macro_hid_conversion": "Current worker and complete66487 inline macro paths contain equal132-entry HID-to-scancode maps for both products. These include extended scancodes and are distinct from mapping-engine page key identities.",
                "preset_registration": "Current72233 isPreset uses the dynamic registration list. Current isObm feature omits ignoreProfiles, so its five onboard presets exclude GENERAL although the broader fixed preset/default table contains that sixth GUID."},
            "originals": list(audit.sources.values()), "inputs_unchanged": True,
            "target_execution": False, "runtime_acceptance": "unverified"}


def magnetic_default_button_bytes(rows, encoding):
    """Independently project the closed fixed BUTTON_LIST encoding branches.

    Sources are complete 66487 buttonMappingToFnDataByte/setSingleButtonMapping,
    26803 CS/Yc/S8/m4/qd and their 36475/39674/68214 constants. This parser never
    accepts a dynamic mapping or invents a protocol for an unknown branch.
    """
    def fields(value, required, optional=()):
        if type(value) is not dict or set(value) - set(required) - set(optional) or set(required) - set(value):
            raise ValueError("Magnetic fixed button fields are incomplete or changed")
    def byte(value):
        if type(value) is not int or not 0 <= value <= 255:
            raise ValueError("Magnetic fixed button value is outside u8")
        return value
    result = []
    ids = encoding["function_ids"]
    reverse_modifiers = {name: encoding["modifier_bits"][key] for key, name in encoding["modifier_names"].items()}
    media = {name: encoding["media_codes"][key] for key, name in encoding["media_names"].items()}
    for row in rows:
        kind = row.get("outputType")
        fields(row, {"inputID", "inputType", "keyInput", "outputType", kind}, {"isHyperShift"})
        if (row["inputType"] != "KeyInput" or type(row["inputID"]) is not str
                or type(row.get("isHyperShift", False)) is not bool):
            raise ValueError("Magnetic fixed button identity or shift branch differs")
        fields(row["keyInput"], {"pageID", "HID"})
        group, data = row[kind], [0] * 5
        if kind == "keyboardGroup":
            fields(group, {"key", "modifiers"}, {"extendedKey"})
            fields(group["key"], {"HID", "flag", "pageID"})
            modifiers = group["modifiers"]
            if modifiers == "Extended_Key" and group.get("extendedKey") == "Extended_00":
                modifiers = []
            if group["key"]["pageID"] != "7" or group["key"]["flag"] != 0 or type(modifiers) is not list:
                raise ValueError("Magnetic fixed keyboard page or flag differs")
            hid = byte(int(group["key"]["HID"]))
            if 224 <= hid <= 231:
                data[0] = 1 << (hid - 224)
            else:
                for modifier in modifiers:
                    if modifier != "Extended_Key":
                        if modifier not in reverse_modifiers:
                            raise ValueError("Magnetic fixed keyboard modifier is unresolved")
                        data[0] |= reverse_modifiers[modifier]
                data[1] = hid
            function, size = ids["KeyCode"], 2
        elif kind == "multimediaGroup":
            fields(group, {"multimediaAssignment"})
            code = media[group["multimediaAssignment"]]
            data[:2] = [code >> 8, code & 255]
            function, size = ids["MediaKeys"], 2
        elif kind == "profileNavigationGroup":
            fields(group, {"profileNavigationAssignment"}, {"profileId"})
            action = group["profileNavigationAssignment"]
            data[0] = {"Up": 1, "Down": 2, "Specific": 3, "CycleUp": 4, "CycleDown": 5}[action]
            if action == "Specific":
                data[1] = byte(group.get("profileId", 0))
            function, size = ids["Profile"], 2 if action == "Specific" else 1
        elif kind == "razerKeyGroup":
            fields(group, {"razerKeyAssignment"})
            data[0] = byte(encoding["razer_codes"][group["razerKeyAssignment"]])
            function, size = ids["RazerKey"], 1
        elif kind == "powerKeyGroup":
            fields(group, {"powerKeyAssignment"})
            data[0] = byte(encoding["power_codes"][group["powerKeyAssignment"]])
            function, size = ids["PowerKeys"], 1
        else:
            raise ValueError("Magnetic fixed button output is unresolved: " + str(kind))
        result.append({"input": row["inputID"], "hyper": row.get("isHyperShift", False),
                       "function_id": byte(function), "size": byte(size), "data": data})
    return result


def mapping_engine_literals(text):
    """Decode only complete source modules and their closed fixed expressions."""
    modules = {role: complete_raw_module(text, anchor) for role, anchor in {
        "keys": ".KEYS=", "constants": "SINGLE_STATE_INPUT_ID:",
        "events": ".DoubleClickEvent=", "event_selector": 'case"Play":return new',
        "factory": "this.generateDefaultTurbos=", "system": ".systemGroup.systemAssignment",
    }.items()}
    for module in modules.values():
        module["byte_start"] = len(text[:module["character_start"]].encode("utf-8"))
        module["byte_end"] = len(text[:module["character_end"]].encode("utf-8"))
        module["sha256"] = hashlib.sha256(module["body"].encode("utf-8")).hexdigest()
    key_body = modules["keys"]["body"]
    direct = re.search(r'\.KEYS=\[', key_body)
    if direct:
        start = direct.end() - 1
    else:
        alias = re.search(r'\.KEYS=([\w$]+)', key_body)[1]
        start = re.search(r'\b' + re.escape(alias) + r'=\[', key_body).end() - 1
    keys = static_js_literal(key_body[start:javascript_delimited(key_body, start)])
    factory = modules["factory"]["body"]
    start = factory.index("this.defaultTurbos=[", factory.index("this.generateDefaultTurbos=")) + len("this.defaultTurbos=")
    default_ids = static_js_literal(factory[start:javascript_delimited(factory, start)])
    selector = modules["event_selector"]["body"]
    classes = dict(re.findall(r'case"([^"]+)":return new\(0,[\w$]+\.([\w$]+)\)', selector))
    events_body = modules["events"]["body"]
    events = {}
    for name in default_ids:
        pattern = r'\.' + re.escape(classes[name]) + r'=class\{getData\(\)\{return\['
        start = re.search(pattern, events_body).end() - 1
        end = javascript_delimited(events_body, start)
        if not events_body[end:].startswith("}}"):
            raise ValueError("Event return contains nonliteral continuation: " + name)
        events[name] = static_js_literal(events_body[start:end])
    constants_body = modules["constants"]["body"]
    string_aliases = dict(re.findall(r'\b([\w$]+)=(?:[\w$]+\.[\w$]+=)?("(?:[^"\\]|\\.)*")(?=[,;])', constants_body))
    constants = {}
    for exported in ["SINGLE_STATE_INPUT_ID", "SCROLL_INPUT_ID", "SCROLL_TURBO_DELAY_MS"]:
        symbol = re.search(re.escape(exported) + r':\(\)=>([\w$]+)', constants_body)[1]
        expression = re.search(r'\b' + re.escape(symbol) + r'=(?:[\w$]+\.[\w$]+=)?(\[[^\[\]]*\]|\d+)(?=[,;])', constants_body)[1]
        if expression.startswith("["):
            expression = "[" + ",".join(string_aliases[part] for part in expression[1:-1].split(",")) + "]"
        constants[exported] = static_js_literal(expression)
    return {"keys": keys, "default_turbo_ids": default_ids,
            "turbo_events": events, "constants": constants}, modules


def mapping_engine_active_binding_182(family, factory, pid=182):
    """Verify the middleware selects this factory, rather than an unused bundle."""
    if family != "mouse" or pid not in (158, 182) or factory["module_id"] != 77898:
        raise ValueError("Selected mouse mapping requires its current factory 77898")
    receipt, original, text = verified_acquired_chunk(family, pid, "6259")
    captured = {row["module_id"]: row for row in keyboard_source_modules(text)}
    wrapper, caller = captured[32226], captured[30525]
    if ("var o=n(77898);" not in wrapper["body"]
            or not wrapper["body"].endswith("t.A=o.RzAppEngineMapping_default}")
            or "a=n(32226)" not in caller["body"]
            or any("a.A." + method not in caller["body"] for method in (
                "generateDefaultTurbos()", "generateAppEngineMultiMappings(e)",
                "generateAppEngineMappings(e)", "generateAppEngineData(t)"))):
        raise ValueError(f"PID{pid} active mapping factory linkage differs from current source")
    modules = {}
    for role, row in (("factory_export_wrapper", wrapper), ("profile_mapping_caller", caller)):
        modules[role] = {**row, "sha256": hashlib.sha256(row["body"].encode("utf-8")).hexdigest()}
    return {"acquisition": identity(receipt), "original": original, "complete_modules": modules,
            "factory_module": factory["module_id"], "wrapper_module": 32226, "caller_module": 30525,
            "scope": "Current product profile caller selects its independently decoded mapping factory; no other device capability is enabled"}


def audit_mapping_engine_literals(args):
    """Independently decode current KEYS/default events for the typed-table oracle."""
    if args.function != "mw" or not args.product:
        raise ValueError("mapping-engine requires selected products and function mw")
    if args.prepare and getattr(args, "receipt_only", False):
        raise ValueError("Mapping engine prepare and receipt-only are mutually exclusive")
    destination = a.ROOT / ".analysis/results/frontend/mapping-engine-current-data.json"
    data = json.loads(destination.read_bytes()) if destination.is_file() else {}
    products = []
    for pid in args.product:
        chunk = "1451" if pid == 756 else "7795" if pid in (158, 182, 740, 746) else "2520"
        receipt_path, source, text = verified_acquired_chunk(args.family, pid, chunk)
        data[str(pid)], modules = mapping_engine_literals(text)
        products.append({"product_id": pid, "acquisition": identity(receipt_path),
                         "original": source, "complete_modules": modules,
                          "keys": len(data[str(pid)]["keys"]),
                          "default_turbos": len(data[str(pid)]["default_turbo_ids"]), "failures": []})
        if pid in (158, 182):
            products[-1]["active_factory"] = mapping_engine_active_binding_182(args.family, modules["factory"], pid)
        if pid in (740, 746):
            products[-1]["magnetic_mapping"] = keyboard_magnetic_mapping_sources(pid)
        if pid == 756:
            # Current latest-restore defaults are runtime data. Decode only
            # the closed literal expressions below, never execute vendor JS.
            main_receipt, main_source, main_text = verified_acquired_chunk(args.family, pid, "main")
            mw_receipt, mw_source, mw_text = verified_acquired_chunk(args.family, pid, "6737")
            main_modules = {row["module_id"]: row for row in keyboard_source_modules(main_text)}
            mw_modules = {row["module_id"]: row for row in keyboard_source_modules(mw_text)}
            extra_captures = []
            extra_receipts, extra_originals = [], []
            for chunk, ids in [("1451", [61451, 59713]), ("5906", [11520]), ("rzDevice25", [44193, 31509]),
                               ("rzDevice30", [39438, 28525, 68602]),
                               ("rzHardwareEventsProtocol25Parser", [12121, 79885, 39674]),
                               ("obmEngineKeyboard", [2050])]:
                extra_receipt, extra_original, extra_text = verified_acquired_chunk(args.family, pid, chunk)
                captured = {row["module_id"]: row for row in keyboard_source_modules(extra_text)}
                extra_receipts.append(identity(extra_receipt))
                extra_originals.append(extra_original)
                extra_captures.extend({**captured[mid], "original": extra_original} for mid in ids)
            config, aliases = main_modules[26061]["body"], main_modules[11469]["body"]
            generic, preset = mw_modules[32906]["body"], mw_modules[72233]["body"]
            def expression(body, symbol):
                found = re.search(r'\b' + re.escape(symbol) + r'=(\{|\[)', body)
                if not found:
                    raise ValueError("756 restore literal is missing: " + symbol)
                return body[found.end()-1:javascript_delimited(body, found.end()-1)]
            def literal(body):
                body = body.replace("!0", "true").replace("!1", "false")
                body = re.sub(r'([{,])(\d+):', r'\1"\2":', body)
                body = re.sub(r'(?<=[\[:,])\.(\d+)', r'0.\1', body)
                return static_js_literal(body)
            exports = dict(re.findall(r'([\w$]+):\(\)=>([\w$]+)', aliases))
            strings = dict(re.findall(r'\b([\w$]+)="([^"\\]*)"(?=[,;])', aliases))
            # MJm is a comma expression ending with the literal string.
            mjm = re.search(r'\b' + re.escape(exports["MJm"]) + r'=\(', aliases)
            mjm_body = aliases[mjm.end()-1:javascript_delimited(aliases, mjm.end()-1)]
            strings[exports["MJm"]] = re.search(r',"([^"\\]*)"\)$', mjm_body)[1]
            def config_literal(body):
                return literal(re.sub(r'`\$\{r\.([\w$]+)\}`',
                    lambda match: json.dumps(strings[exports[match[1]]]), body))
            guids = literal(expression(preset, "v"))
            common = literal(expression(preset, "h"))
            common_call = re.search(r'\bE=\(\)=>\(\{(.*?)\}\)', preset)[1]
            common_keys = re.findall(r'([\w$]+):Object\.assign\(\{\},h\)', common_call)
            if ",".join(key + ":Object.assign({},h)" for key in common_keys) != common_call:
                raise ValueError("756 preset common actuation contains an unresolved expression")
            common_specific = {key: common for key in common_keys}
            def preset_literal(body):
                body = re.sub(r'\bv\.([\w$]+)', lambda match: json.dumps(guids[match[1]]), body)
                body = body.replace("E()", json.dumps(common_specific))
                return literal(body)
            registration = main_modules[86191]["body"]
            input_at = registration.index("inputMapping:{keyboard:") + len("inputMapping:")
            input_literal = registration[input_at:javascript_delimited(registration, input_at)]
            input_table = literal(input_literal)["keyboard"]
            firmware = literal(expression(generic, "a"))
            for mode, overrides in input_table.items():
                firmware[mode].update(overrides)
            feedback_at = registration.index('useFeature("profileSwitchEffectConfig","config",') + len('useFeature("profileSwitchEffectConfig","config",')
            feedback_config = literal(registration[feedback_at:javascript_delimited(registration, feedback_at)])
            runtime = {
                "product_id": pid,
                "device_name": re.search(r'\bl="([^"\\]*)",c=\[', config)[1],
                "guest_profile_owner": re.search(r'\bs="([0-9a-f]+)"', main_modules[7414]["body"])[1],
                "default_profile": config_literal(expression(config, "C")),
                "default_mappings": config_literal(expression(config, "O")),
                "full_mapping_list": config_literal(expression(config, "S")),
                "button_list": config_literal(expression(config, "K")),
                "firmware_keyboard": firmware,
                "profile_switch_effect": feedback_config,
                "navigation_keys": literal(expression(mw_modules[93494]["body"], "n")),
                "physical_keys": [{"inputID": key, "fwID": row["fwID"]}
                                  for key, row in firmware["NormalMode"].items()
                                  if isinstance(row.get("fwID"), (int, float)) and row["fwID"] != 255 and
                                  any(button.get("inputID") == key and button.get("inputType") in ["KeyInput", "AnalogInput"]
                                      for button in config_literal(expression(config, "K")))],
                "preset_guids": guids,
                "preset_profiles": preset_literal(expression(preset, "D")),
                "preset_actuation": preset_literal(expression(preset, "_")),
                "preset_rapid_trigger": preset_literal(expression(preset, "I")),
                "preset_mappings": preset_literal(expression(preset, "m")),
            }
            # The mounted UI and middleware use the five explicitly registered
            # OBMSpecs presets, not the preset engine's six-entry default list.
            obm_at = config.index("OBMSpecs:{") + len("OBMSpecs:")
            obm_config = config[obm_at:javascript_delimited(config, obm_at)]
            runtime["onboard_presets"] = literal(expression(obm_config, "presetProfiles")) if re.search(r'\bpresetProfiles=', obm_config) else literal(
                obm_config[obm_config.index("presetProfiles:[")+len("presetProfiles:"):
                           javascript_delimited(obm_config, obm_config.index("presetProfiles:[")+len("presetProfiles:"))])
            ui_receipt_path = a.ROOT / ".analysis/inputs/frontend/keyboard-756-current/acquisition.json"
            ui_receipt = json.loads(ui_receipt_path.read_bytes())
            if not ui_receipt.get("source_current_during_acquisition"):
                raise ValueError("756 UI deployment stability is not verified")
            ui_captures, ui_originals, ui_modules = [], [], {}
            for prefix, ids in [("main.", [78193, 54693, 31867, 69937, 3342, 35380, 21561]),
                                ("1874.", [55714]), ("3021.", [5962]), ("8459.", [43112])]:
                original = next(row for row in ui_receipt["files"] if
                                "/ui/static/js/" + prefix in row["url"] and row["url"].endswith(".js"))
                if not valid(original):
                    raise ValueError("756 UI original byte identity failed: " + original["path"])
                captured = {row["module_id"]: row for row in keyboard_source_modules((a.ROOT / original["path"]).read_text(encoding="utf-8"))}
                ui_originals.append(original)
                for mid in ids:
                    ui_modules[mid] = captured[mid]
                    ui_captures.append({**captured[mid], "original": original})
            ui_aliases = ui_modules[54693]["body"]
            ui_exports = dict(re.findall(r'([\w$]+):\(\)=>([\w$]+)', ui_aliases))
            def ui_key(alias):
                return re.search(r'(?<![\w$])' + re.escape(ui_exports[alias]) + r'="([^"\\]*)"', ui_aliases)[1]
            ui_config = ui_modules[78193]["body"]
            runtime["profile_transfer_target"] = {
                "productId": pid, "dongleId": 757, "bleId": 758,
                "deviceName": runtime["device_name"], "category": "KEYBOARD",
                "is8kAnalogDevice": "is8kAnalogDevice:!0" in ui_config,
                "presetProfiles": runtime["onboard_presets"],
            }
            ui_constants = ui_modules[69937]["body"]
            runtime["import_non_analog_ids"] = literal(expression(ui_constants, "Ve"))
            runtime["import_keymap_passthrough_ids"] = literal(expression(ui_constants, "ft"))
            for name in ["actuationInfo", "actuationHighSensitivityInfo"]:
                at = ui_config.index(name + ":{") + len(name) + 1
                runtime["profile_transfer_target"][name] = literal(ui_config[at:javascript_delimited(ui_config, at)])
            layout_constants = literal(expression(main_modules[93490]["body"], "Pn"))
            imported_layouts = expression(aliases, "oe")
            runtime["import_restricted_layouts"] = [layout_constants[name] for name in re.findall(r'o\.Z7j\.([\w$]+)', imported_layouts)]
            runtime["import_restricted_input_ids"] = literal(expression(aliases, "ae"))
            css_originals = [row for row in ui_receipt["files"] if "/ui/static/css/" in row["url"] and row["url"].endswith(".css")]
            if not css_originals or not all(valid(row) for row in css_originals):
                raise ValueError("756 profile CSS closure failed")
            menu_owner = ui_modules[55714]["body"]
            expected_menu = '[{action:S.gjU},{action:S.yE7},{action:"divider"},{action:S.L$3},{action:S.Nwd},{action:S.s1I},{action:"divider"},{action:S.Pie},{action:S.mjN},{action:S.l1q},{action:"divider"},{action:S.sG0},{action:S.SJi}]'
            if expected_menu not in menu_owner:
                raise ValueError("756 current menu owner changed")
            menu = []
            for command, alias, disabled, hidden in [
                ("add", "gjU", [], []), ("import", "yE7", ["no_selected_profile"], []),
                (None, None, [], []),
                ("linked_games", "L$3", ["no_selected_profile"], ["linked_games_empty"]),
                ("link_games", "Nwd", ["no_selected_profile"], ["linked_games_present"]),
                (None, None, [], []),
                ("rename", "Pie", ["no_selected_profile", "analog_preset_profile"], []),
                ("duplicate", "mjN", ["no_selected_profile", "analog_preset_profile"], []),
                ("export", "l1q", ["no_selected_profile", "analog_preset_profile"], []),
                (None, None, [], []),
                ("reset", "sG0", ["no_selected_profile", "analog_preset_profile"], []),
                ("delete", "SJi", ["no_selected_profile", "single_profile", "onboard_profile", "analog_preset_profile"], []),
            ]:
                menu.append({"kind": "separator"} if command is None else {
                    "kind": "action", "command": command, "label_key": ui_key(alias),
                    "disabled_when": ["profile_switch_disabled"] + disabled, "hidden_when": hidden})
            menu_path = a.builtin_data_path("razer-pages", "SOURCE_PROFILE_MENU_DATA", macro_name="source_profile_menu_data")
            menu_data = json.loads(menu_path.read_bytes())
            menu_data["products"] = [row for row in menu_data["products"] if row["product_id"] != pid] + [{
                "product_id": pid, "category": "KEYBOARD", "menu": menu,
                "rename": {"max_length": 32}, "menu_width": 155, "menu_max_width": 280,
                "menu_width_mode": "max-content", "capabilities": {"reset_profile": True, "share_profile": False},
                "confirmations": [
                    {"name": "reset", "label_key": ui_key("DgD"), "description_key": ui_key("iN2"),
                     "width": 300, "top": 42, "delay_ms": 100,
                     "button_keys": [ui_key("hJ0"), ui_key("vMs")], "outside_click_closes": True},
                    {"name": "delete", "label_key": "DELETE_PROFILE_TITLE", "description_key": "DELETE_PROFILE_MSG",
                     "width": 300, "top": 42, "delay_ms": 100, "button_keys": ["REMOVE"], "outside_click_closes": True}],
                "import_export": {"width": 602, "height": 481, "top": 104, "left": "calc(50% - 300px)",
                                  "locale_keys": [ui_key(alias) for alias in ["pcO", "ov8", "M88", "QN3", "BXZ", "u4O", "v3x"]]},
                "source": {"originals": ui_originals, "css_originals": css_originals, "module_id": 55714},
                "coverage": {"online_share_removed": True, "source_acquisition": True,
                             "runtime_acceptance": "not executed"}}]
            a.save(menu_path, menu_data)
            migration_receipt_path = a.ROOT / ".analysis/inputs/frontend/profile-migration-current/acquisition.json"
            if not migration_receipt_path.is_file():
                a.fetch_frontend(SimpleNamespace(url="https://apps.razer.com/profile-migration/",
                    output=a.rel(migration_receipt_path.parent), no_refresh_gaps=True), refresh_ledger=False)
            migration = json.loads(migration_receipt_path.read_bytes())
            migration["caller"] = {"original": ui_originals[1], "module_id": 55714,
                "expression": "new SharedWorker(`${window.location.origin}/profile-migration/worker.js`,{name:'s3FileWorker'})"}
            for url in ["https://apps.razer.com/profile-migration/worker.js",
                        "https://apps.razer.com/synapse/profile-migration/worker.js"]:
                if not any(row["url"] == url for row in migration["files"]):
                    migration["files"].append(a.download(url, migration_receipt_path.parent))
            publish_frontend_acquisition(migration_receipt_path, migration)
            for name, label in [("defaultActuation", "default_actuation"),
                                ("defaultRapidTrigger", "default_rapid_trigger")]:
                at = preset.index("this." + name + "=") + len("this." + name + "=")
                runtime[label] = literal(preset[at:javascript_delimited(preset, at)])
            runtime_path = a.builtin_data_path("razer-device", "KEYBOARD_LATEST_RESTORE")
            a.save(runtime_path, runtime)
            products[-1]["latest_restore"] = {
                "acquisitions": [identity(main_receipt), identity(mw_receipt)] + extra_receipts,
                "original_inputs": [main_source, mw_source] + extra_originals,
                "complete_modules": [main_modules[mid] for mid in [26061, 11469, 86191, 3327, 7414, 93490]] +
                                    [mw_modules[mid] for mid in [32906, 72233, 42656, 15691, 99048, 32637, 75938, 1101,
                                                               6258, 56839, 31982, 61450, 4368, 88758, 18065, 4753,
                                                               89423, 90994, 50574, 34938, 73932, 51765, 14339, 93494, 46329,
                                                               26192, 87142, 13881, 93182, 26568, 4849]] + extra_captures,
                "ui_acquisition": identity(ui_receipt_path), "ui_complete_modules": ui_captures,
                "ui_css_originals": css_originals, "profile_menu": identity(menu_path),
                "profile_migration_acquisition": identity(migration_receipt_path),
                "runtime": identity(runtime_path), "firmware_modes": {mode: len(keys) for mode, keys in firmware.items()},
            }
    a.save(destination, data)
    generated = None
    generated_magnetic = None
    if args.prepare:
        import rust_data
        generated = rust_data.prepare_mapping_engine_data(data)
        generated = rust_data.prepare_mapping_engine_data(data, check=True)
        magnetic = {row["product_id"]: row["magnetic_mapping"] for row in products if "magnetic_mapping" in row}
        if magnetic:
            for pid in {740, 746} - set(magnetic):
                magnetic[pid] = keyboard_magnetic_mapping_sources(pid)
                products.append({"product_id": pid, "magnetic_mapping": magnetic[pid], "generator_dependency": True,
                                 "keys": len(data[str(pid)]["keys"]), "failures": []})
            generated_magnetic = rust_data.prepare_magnetic_source({pid: row["values"] for pid, row in magnetic.items()})
            generated_magnetic = rust_data.prepare_magnetic_source({pid: row["values"] for pid, row in magnetic.items()}, check=True)
    report_path = a.ROOT / f".analysis/results/frontend/{args.family}-mw-audit.json"
    report = json.loads(report_path.read_bytes()) if report_path.exists() else {"schema_version": 1}
    report.setdefault("queries", {})["mapping-engine"] = {
        "recorded_at_utc": a.stamp(), "tool": identity(Path(__file__)),
        "method": "Complete original webpack modules and constrained literal parsing; no JavaScript evaluation",
        "products": products, "fixture": identity(destination), "target_execution": False,
        "generated_typed_tables": generated,
        "generated_magnetic_source": generated_magnetic,
    }
    a.save(report_path, report)
    print(json.dumps({"receipt": a.rel(report_path), "fixture": a.rel(destination),
                      "products": [{"product_id": row["product_id"], "keys": row["keys"]} for row in products]}), flush=True)


def audit_audio_leviathan(args):
    """Retain complete current 1352 sound, Noa framing, event and media owners."""
    import sys
    import importlib.metadata
    import evidence
    sys.path.insert(0, str(a.ROOT / "tools/analyzers/python-static"))
    from tree_sitter import Language, Parser
    import tree_sitter_javascript
    if args.family != "audio" or args.function != "mw" or set(args.product or [1352]) != {1352}:
        raise ValueError("audio-leviathan requires audio/mw/1352")
    parser = Parser(Language(tree_sitter_javascript.language()))
    row = {"product_id": 1352, "failures": [], "complete_owners": [], "source_sets": {},
           "target_execution": False, "runtime_acceptance": "unverified"}
    sources, trees, modules = {}, {}, {}
    for layer, name in (("ui", "audio-1352-current"), ("mw", "audio-mw-1352-current")):
        receipt = a.ROOT / f".analysis/inputs/frontend/{name}/acquisition.json"
        capture_path = a.ROOT / f".analysis/results/frontend/{name}/analysis.json"
        acquired = json.loads(receipt.read_bytes())
        deployment = evidence.frontend_deployment_sources(acquired)
        captured = json.loads(capture_path.read_bytes())
        if acquired.get("source_current_during_acquisition") is not True or deployment["failures"]:
            raise ValueError("Noa current deployment is unverified: " + json.dumps(deployment["failures"]))
        capture_inputs = {item["path"]: item for item in captured.get("original_inputs", [])}
        reachable = {acquired["entry_url"], urllib.parse.urljoin(acquired["entry_url"], "asset-manifest.json" if layer == "ui" else "webpackManifest.json")}
        while True:
            next_urls = reachable | {edge["to"] for edge in acquired.get("edges", []) if edge["from"] in reachable}
            if next_urls == reachable: break
            reachable = next_urls
        originals = [item for item in acquired["files"] if item.get("path") and item["url"] in reachable]
        for original in originals:
            if not valid(original): raise ValueError("Noa original bytes differ: " + original["path"])
            if original["path"].endswith(".js"):
                if capture_inputs.get(original["path"], {}).get("sha256") != original["sha256"]:
                    raise ValueError("Noa complete capture input differs: " + original["path"])
                sources.setdefault(layer, []).append((original, (a.ROOT / original["path"]).read_bytes()))
        row["source_sets"][layer] = {"acquisition": identity(receipt), "capture": identity(capture_path),
            "capture_tool": captured.get("tool"), "original_inputs": originals,
            "closure_unresolved": acquired.get("unresolved", []), "deployment": deployment,
            "capture_failures": [command for command in captured.get("commands", []) if command.get("exit_code")]}

    def retain(layer, role, anchor, module_id=None):
        matches = []
        needle = anchor.encode("utf-8")
        for original, raw in sources[layer]:
            if needle not in raw: continue
            if original["path"] not in trees: trees[original["path"]] = parser.parse(raw)
            tree = trees[original["path"]]
            start = 0
            while (offset := raw.find(needle, start)) >= 0:
                start = offset + len(needle)
                node = tree.root_node.descendant_for_byte_range(offset, start)
                owner, module = None, None
                while node is not None:
                    if owner is None and node.type in {"function_expression", "function_declaration", "generator_function", "generator_function_declaration", "arrow_function", "method_definition"}:
                        owner = node
                    key = node.child_by_field_name("key") if node.type == "pair" else None
                    if key is not None and key.type == "number":
                        module = (int(raw[key.start_byte:key.end_byte]), node)
                        break
                    node = node.parent
                if module_id is not None and (module is None or module[0] != module_id): continue
                if module is not None:
                    mid, node = module
                    key = original["sha256"] + ":" + str(mid)
                    body = raw[node.start_byte:node.end_byte]
                    modules.setdefault(key, {"original": original, "module_id": mid, "byte_start": node.start_byte,
                        "byte_end": node.end_byte, "body_sha256": hashlib.sha256(body).hexdigest(), "body": body.decode("utf-8")})
                else:
                    key = None
                if owner is None: owner = module[1] if module else tree.root_node
                body = raw[owner.start_byte:owner.end_byte]
                candidate = {"role": role, "original": original, "module": key,
                    "byte_start": owner.start_byte, "byte_end": owner.end_byte, "node_type": owner.type,
                    "anchor_byte": offset, "body_sha256": hashlib.sha256(body).hexdigest(), "body": body.decode("utf-8")}
                if not any(item["original"]["path"] == original["path"] and item["byte_start"] == owner.start_byte for item in matches): matches.append(candidate)
        if not matches: row["failures"].append("Missing complete current owner: " + role)
        row["complete_owners"].extend(matches)
        return matches

    for role, anchor, module_id in (
        ("product_feature_registration", 'useFeature("rzDeviceType","rzDevice25Noa")', None),
        ("physical_noa_adapter", 'this.name="rzDevice25Noa"', 71052),
        ("physical_noa_send", 'sendCommand(e,t,r=new Uint8Array([])', 71052),
        ("physical_noa_receive", '_getUSBTransferInResult(e,t,r){', 71052),
        ("base_transaction_and_checksum", '_getTransactionId(){', 87969),
        ("protocol_helpers", 'OB:()=>', 71668),
        ("audio_enums", 'Soundbar_Speaker_Subwoofer:0', 70617),
        ("transport_defaults", 'SLEEP_TIME_BETWEEN_IN:()=>', 68560),
        ("sound_local_storage_order", 'function Ao(', 30525),
        ("sound_device_task", 'function Wo(', 85191),
        ("input_task_caller", 'function En(', 30525),
        ("input_read_before_conditional_set", 'getAudioSource(0)', 87887),
        ("source_restore", 'case"subWooferLevel"', None),
        ("headphone_observation_request", 'G.YM.Lu._H', 50350),
        ("headphone_observation_event_enum", 'd="audio_output_source_ui_request"', 26219),
        ("hardware_state_consumer", 'case o.Ym.CAMERA_TRACKING_STATUS', 84910),
        ("hardware_event_parser", 'this.parseNotificationEvents=e=>', 87262),
        ("hardware_event_enums", 'CAMERA_TRACKING_STATUS:29', 49065),
        ("source_enum_and_float_helpers", 'np:()=>', 76912),
    ): retain("mw", role, anchor, module_id)
    for role, anchor in (
        ("ui_sound_output_reducer", 'soundbarHeadsetToggleReducer:function'),
        ("ui_sound_mode_reducer", 'audioModeReducer:function'),
        ("ui_sound_bass_reducer", 'subWooferReducer:function'),
        ("ui_audible_video_owner", 'src:"/synapse/assets/videos/audio_mode.mov"'),
        ("ui_bass_control", 'const e=(0,F.useSelector)(e=>e.subWooferReducer.subWoofer),a='),
        ("ui_headphone_observation_mount", 'type:"audio_output_source_ui_request"'),
        ("ui_headphone_observation_lifecycle", 'this.getInitialAuidoOutPutSource()'),
        ("ui_source_output_enum", 'SOUNDBAR:"SOUNDBAR",HEADSET:"HEADSET"'),
    ): retain("ui", role, anchor)
    media_url = "https://apps.razer.com/synapse/assets/videos/audio_mode.mov"
    media_receipt = a.ROOT / ".analysis/inputs/frontend/audio-1352-current/local-media-acquisition.json"
    media_callers = [item for item in row["complete_owners"] if item["role"] == "ui_audible_video_owner"]
    cached_media = json.loads(media_receipt.read_bytes()) if media_receipt.is_file() else None
    cache_valid = (cached_media is not None and cached_media.get("original", {}).get("url") == media_url
                   and valid(cached_media["original"]) and cached_media.get("source_caller") == media_callers)
    if getattr(args, "prepare", False) and not cache_valid:
        original = a.download(media_url, media_receipt.parent)
        if original.get("http_status") != 200 or not valid(original):
            row["failures"].append({"media_acquisition": original})
        else:
            a.save(media_receipt, {"schema_version": 1, "original": original,
                "source_caller": media_callers,
                "purpose": "Offline original audible demo resource; target code was not executed"})
    if media_receipt.is_file():
        media = json.loads(media_receipt.read_bytes())
        if valid(media["original"]) and media.get("source_caller") == media_callers and media["original"].get("url") == media_url:
            row["local_demo_original"] = {"receipt": identity(media_receipt), **media["original"]}
            a.index_files(rows_for_index([media["original"]], media_receipt))
            if not valid(media["original"]): raise ValueError("Local demo original changed while indexing")
            if getattr(args, "prepare", False):
                row["local_demo_preparation"] = prepare_audible_demo(media["original"])
        else: row["failures"].append("Local demo original byte identity differs")
    row["semantics"] = {"report_bytes": 65, "set_report_id": 8, "get_report_id": 8, "claim_interface": 4,
        "transaction_range": [0, 30], "out_attempts": 20, "in_attempts": 10, "out_to_in_ms": 5, "in_to_in_ms": 5,
        "timeout_status_keeps_get_retrying": True, "setters": {"bass": {"profile": 1, "command": [2,8,7], "range": [1,7]},
        "output": {"profile": 1, "command": [2,8,17]}, "mode": {"profile": 0, "command": [2,8,16], "range": [0,3]}},
        "input": {"profile": 0, "read": [2,8,138], "conditional_set": [2,8,10], "bluetooth": 3},
        "setter_getter_ui_refresh": False, "local_save_precedes_sound_enqueue": True,
        "event_output_keys": ["Soundbar", "Headset"], "ui_output_values": ["SOUNDBAR", "HEADSET"],
        "runtime_acceptance": "unverified"}
    path = a.ROOT / ".analysis/results/frontend/audio-MapAudio-audit.json"
    report = json.loads(path.read_bytes()) if path.is_file() else {"schema_version": 1}
    report["leviathan"] = {"recorded_at_utc": a.stamp(), "tool": identity(Path(__file__)),
        "static_parser": {name: importlib.metadata.version(name) for name in ("tree-sitter", "tree-sitter-javascript")},
        "products": [row], "complete_modules": modules}
    a.save(path, report)
    print(json.dumps({"receipt": a.rel(path), "product_id": 1352, "complete_owners": len(row["complete_owners"]),
        "complete_modules": len(modules), "media": row.get("local_demo_original"), "failures": row["failures"]}), flush=True)


def audit_audio_demo(args):
    """Bind all four mounted audible players to current complete UI owners."""
    import importlib.metadata
    import sys
    import evidence
    sys.path.insert(0, str(a.ROOT / "tools/analyzers/python-static"))
    from tree_sitter import Language, Parser
    import tree_sitter_javascript
    if args.family != "audio":
        raise ValueError("audio-demo requires the audio family")
    parser = Parser(Language(tree_sitter_javascript.language()))
    media_url = "https://apps.razer.com/synapse/assets/videos/audio_mode.mov"
    receipt = a.ROOT / ".analysis/inputs/frontend/audio-1352-current/local-media-acquisition.json"
    media = json.loads(receipt.read_bytes())
    if media["original"]["url"] != media_url or not valid(media["original"]):
        raise ValueError("The current shared audible original differs")
    prepared_path = a.ROOT / ".analysis/results/frontend/audio-MapAudio-audit.json"
    prepared_report = json.loads(prepared_path.read_bytes()) if prepared_path.is_file() else {}
    prepared_products = prepared_report.get("leviathan", {}).get("products", [])
    prepared = prepared_products[0].get("local_demo_preparation") if prepared_products else None
    preparation_ready = (prepared is not None and prepared["original"]["sha256"] == media["original"]["sha256"]
                         and valid(prepared["prepared"]))
    if preparation_ready:
        index_media_preparation("audible_demo", prepared, [prepared["prepared"]])
    rows, descriptors = [], []
    for pid in args.product or [1352, 1392, 1442, 3942]:
        if pid not in {1352, 1392, 1442, 3942}:
            raise ValueError("No mounted demo policy for product " + str(pid))
        acquisition_path = a.ROOT / f".analysis/inputs/frontend/audio-{pid}-current/acquisition.json"
        capture_path = a.ROOT / f".analysis/results/frontend/audio-{pid}-current/analysis.json"
        acquired = json.loads(acquisition_path.read_bytes())
        captured = json.loads(capture_path.read_bytes())
        deployment = evidence.frontend_deployment_sources(acquired)
        if acquired.get("source_current_during_acquisition") is not True or deployment["failures"]:
            raise ValueError("Current demo deployment is unverified: " + str(pid))
        capture_inputs = {item["path"]: item for item in captured["original_inputs"]}
        reachable = {acquired["entry_url"], urllib.parse.urljoin(acquired["entry_url"], "asset-manifest.json")}
        while True:
            next_urls = reachable | {edge["to"] for edge in acquired.get("edges", []) if edge["from"] in reachable}
            if next_urls == reachable: break
            reachable = next_urls
        row = {"product_id": pid, "acquisition": identity(acquisition_path), "capture": identity(capture_path),
               "original_inputs": [], "complete_owners": [], "styles": [], "failures": [],
               "closure_unresolved": acquired.get("unresolved", []), "target_execution": False,
               "runtime_acceptance": "unverified"}
        seen, rules = set(), set()
        for original in acquired["files"]:
            if not original.get("path") or original["url"] not in reachable: continue
            if not valid(original): raise ValueError("Current demo original differs: " + original["path"])
            row["original_inputs"].append(original)
            raw = (a.ROOT / original["path"]).read_bytes()
            if original["path"].endswith(".js"):
                if capture_inputs.get(original["path"], {}).get("sha256") != original["sha256"]:
                    raise ValueError("Current demo capture differs: " + original["path"])
                anchors = [b'"/synapse/assets/videos/audio_mode.mov"', b'custom-fullscreen-toggle',
                           b'demoFloatingVideoEnabled', b'video-react-play-control', b'video-react-fullscreen-control',
                           b'dragAndDropWrapper', b'className:"am-selector"', b'defaultShortcuts',
                           b'key:"canBeClicked",value:', b'key:"handleFullscreenChange",value:',
                           b'FULLSCREEN_CHANGE:return', b'key:"toggleFullscreen",value:', b'fullscreenchange',
                           b'demo-play-wrapper', b'key:"getActions",value:', b'key:"dispatch",value:',
                           b'dG=e=>', b'rm=e=>', b'Ln=e=>']
                if not any(anchor in raw for anchor in anchors): continue
                tree = parser.parse(raw)
                for anchor in anchors:
                    start = 0
                    while (offset := raw.find(anchor, start)) >= 0:
                        start = offset + len(anchor)
                        node = tree.root_node.descendant_for_byte_range(offset, start)
                        owners = []
                        while node is not None:
                            if node.type in {"arrow_function", "function_expression", "function_declaration", "method_definition"}:
                                owners.append(node)
                            node = node.parent
                        # Include the mounted component above an async resource
                        # loader; retain the full library method for controls.
                        owner = next((node for node in owners if node.end_byte-node.start_byte < 150000
                                      and (b'demo-preview' in raw[node.start_byte:node.end_byte]
                                           or (b'demoFloatingVideoEnabled' in raw[node.start_byte:node.end_byte]
                                               and b'.jsx' in raw[node.start_byte:node.end_byte]))),
                                     owners[0] if owners else None)
                        if owner is None:
                            row["failures"].append({"anchor": anchor.decode(), "original": original["path"], "offset": offset})
                            continue
                        key = (original["path"], owner.start_byte, owner.end_byte)
                        if key in seen: continue
                        seen.add(key)
                        body = raw[owner.start_byte:owner.end_byte]
                        row["complete_owners"].append({"original": original, "byte_start": owner.start_byte,
                            "byte_end": owner.end_byte, "body_sha256": hashlib.sha256(body).hexdigest(),
                            "anchor": anchor.decode(), "body": body.decode("utf-8")})
            elif original["path"].endswith(".css"):
                for anchor in [b'.demo-body', b'.demo-preview', b'.custom-video-react', b'.custom-control-bar',
                               b'.video-react', b'.floating-video', b'.fullscreen-selector',
                               b'.custom-play-toggle', b'.custom-fullscreen-toggle', b'.custom-progress-bar',
                               b'dragAndDrop', b'.repositionText', b'.am-selector']:
                    start = 0
                    while (offset := raw.find(anchor, start)) >= 0:
                        start = offset + len(anchor)
                        left = max(raw.rfind(b'}', 0, offset), raw.rfind(b'{', 0, offset)) + 1
                        right = raw.find(b'}', offset)
                        if right < 0: continue
                        key = (original["path"], left, right+1)
                        if key in rules: continue
                        rules.add(key)
                        body = raw[left:right+1]
                        row["styles"].append({"original": original, "byte_start": left, "byte_end": right+1,
                            "body_sha256": hashlib.sha256(body).hexdigest(), "body": body.decode("utf-8")})
        callers = [owner for owner in row["complete_owners"] if '"/synapse/assets/videos/audio_mode.mov"' in owner["body"]]
        if not callers or not row["styles"]: raise ValueError("Mounted audible player is unresolved: " + str(pid))
        row["media"] = {"acquisition": identity(receipt), "original": media["original"],
                        "prepared": prepared, "preparation_verified": preparation_ready}
        row["semantics"] = {"loop": pid != 1352, "custom_controls": pid != 1352,
                            "system_default_render_endpoint": True, "muted": False,
                            "profile_owned": False, "floating": pid != 1352}
        rows.append(row)
        if pid != 1352:
            descriptors.append({"product_id": pid, "asset": "synapse/audio-demo-poster.png", "width": 800, "height": 450,
                "presentation": {"button_width": 40, "glyph_size": 18}, "object_fit": "cover" if pid == 3942 else "fill",
                "title": "DEMO_TITLE_DESC", "floating_label": "FLOATING_VIDEO_CHECKBOX_LABEL", "floating_default": True,
                "current_source_receipt": ".analysis/results/frontend/audio-demo-audit.json"})
        if any(not valid(original) for original in row["original_inputs"]):
            raise ValueError("Demo inputs changed during the static query")
    result = {"schema_version": 1, "recorded_at_utc": a.stamp(), "tool": identity(Path(__file__)),
        "static_parser": {name: importlib.metadata.version(name) for name in ("tree-sitter", "tree-sitter-javascript")},
        "products": rows, "media_preparation_verified": preparation_ready, "runtime_acceptance": "unverified"}
    independent_preparation = a.ROOT / ".analysis/inputs/prepared-media/preparation.json"
    if independent_preparation.is_file():
        controls = json.loads(independent_preparation.read_bytes()).get("preparations", {}).get("video_controls")
        if controls is not None:
            originals = {original["path"]: original for row in rows for original in row["original_inputs"]}
            if (all(valid(item["prepared"]) for item in controls["glyphs"])
                    and all(item["original"] == originals.get(item["original"]["path"])
                            for item in controls["sources"])):
                result["prepared_controls"] = controls
    a.save(a.ROOT / ".analysis/results/frontend/audio-demo-audit.json", result)
    if getattr(args, "prepare", False):
        if {row["product_id"] for row in descriptors} != {1392,1442,3942}:
            raise ValueError("Descriptor publication requires the complete mounted product set")
        a.save(a.builtin_data_path("razer-pages", "AUDIO_DEMO_DATA"), descriptors)
        result["prepared_controls"] = prepare_audio_demo_icons(rows)
        a.save(a.ROOT / ".analysis/results/frontend/audio-demo-audit.json", result)
    print(json.dumps({"receipt": ".analysis/results/frontend/audio-demo-audit.json",
        "products": [row["product_id"] for row in rows], "owners": sum(len(row["complete_owners"]) for row in rows),
        "failures": [failure for row in rows for failure in row["failures"]],
        "media_preparation_verified": preparation_ready}), flush=True)


def audio_carol_ffi_binding(raw, parser):
    """Read the complete current Carol ABI table and its lexical initializer."""
    tree = parser.parse(raw)
    if tree.root_node.has_error:
        raise ValueError("Carol FFI source has JavaScript grammar errors")
    pending, tables = [tree.root_node], []
    while pending:
        node = pending.pop()
        if (node.type == "array" and node.named_children
                and all(child.type == "object" for child in node.named_children)):
            keys = [pair.child_by_field_name("key") for child in node.named_children
                    for pair in child.named_children if pair.type == "pair"]
            if any(key.text == b"GetDLLVersion" for key in keys):
                tables.append(node)
        pending.extend(reversed(node.named_children))
    if len(tables) != 1:
        raise ValueError("Carol FFI configuration is absent or ambiguous")
    table = tables[0]
    owner = table
    while owner is not None:
        if owner.type == "assignment_expression":
            left = owner.child_by_field_name("left")
            if left is not None and left.text == b"this.initElectron":
                break
        owner = owner.parent
    if owner is None:
        raise ValueError("Carol ABI table is outside its complete initializer")
    groups = []
    for obj in table.named_children:
        group = []
        for pair in obj.named_children:
            if pair.type != "pair":
                raise ValueError("Carol ABI table has a dynamic property")
            key, value = pair.child_by_field_name("key"), pair.child_by_field_name("value")
            if key.type != "property_identifier" or value.type != "array":
                raise ValueError("Carol ABI name/signature is dynamic")
            group.append({"name": key.text.decode(), "signature": json.loads(value.text)})
        groups.append(group)
    def retained(node):
        return {"byte_start": node.start_byte, "byte_end": node.end_byte, "syntax": node.type,
                "body": node.text.decode(), "body_sha256": hashlib.sha256(node.text).hexdigest()}
    return {"configuration": retained(table), "initializer": retained(owner), "groups": groups,
            "focus_apis": [item["name"] for group in groups for item in group
                           if re.search(r"Ctc|Virtualizer|Spatial|BassManagement", item["name"], re.I)]}


