def collect_audio_1446_quick_output_chain(audit):
    previous, shared, roles, dependencies, native = _audio_1446_quick_output_dependencies(audit)
    result = _audio_1446_quick_output_sources(audit, previous, shared, roles)
    result["source_contract"] = _audio_1446_quick_output_source_contract(
        {role: audit.owners[key] for role, key in roles.items()})
    result.update(kind="current_audio_1446_quick_output_chain", upstream_sections=dependencies,
        shared_native_owners=native, failures=[], bounded_observation_complete=True, source_chain_complete=False,
        whole_product_complete=False, product_code_modified=False, target_execution=False,
        real_device_operations=False, rust_independent_implementation="not_implemented_by_this_query", ui_backend_wiring="unverified",
        official_dll_comparison="unverified", runtime_acceptance="unverified",
        unresolved_chains=["The selected eight effects' native numeric algorithms remain a separate shared chain; this boundary proves routing, frame transport and stop semantics only",
            "Independent Rust implementation, UI/backend wiring and actual official DLL/device output, cancellation and restoration comparisons remain unverified"])
    return result


def audit_audio_1446_quick_output_chain(args):
    import host
    if (args.family != "audio" or args.function != "mw" or getattr(args, "prepare", False)
            or sorted(set(args.product or [1446])) != [1446]):
        raise ValueError("audio-1446-quick-output-chain requires only PID1446 middleware without preparation")
    audit = host.HostLocalAudit()
    report = {"schema_version": 1, "parser": audit.parser_versions, "kind": "current_audio_1446_quick_output_chain",
        "query": "audio-1446-quick-output-chain", "failures": [], "bounded_observation_complete": False,
        "source_chain_complete": False, "whole_product_complete": False, "target_execution": False,
        "real_device_operations": False, "rust_independent_implementation": "not_implemented_by_this_query", "ui_backend_wiring": "unverified",
        "official_dll_comparison": "unverified", "runtime_acceptance": "unverified"}
    try:
        for name in ("tools/families.py", "tools/host.py", "tools/frontend.py", "tools/evidence.py"):
            audit.artifact(a.ROOT / name)
        report.update(collect_audio_1446_quick_output_chain(audit))
    except (OSError, ValueError, KeyError, IndexError, TypeError, StopIteration) as error:
        report["failures"].append(type(error).__name__ + ": " + str(error))
    changed = audit.final_snapshot() + host._keypad_temporary_keymap_dependency_changes(report.get("upstream_sections", []))
    if changed:
        report["failures"].extend("1446 quick output input changed during query: " + name for name in changed)
    report.update(recorded_at_utc=a.stamp(), changed_during_query=changed, snapshot_stable=not changed,
        bounded_observation_complete=not report["failures"], complete_originals=list(audit.sources.values()),
        complete_source_owners=list(audit.owners.values()), verified_artifacts=list(audit.artifacts.values()))
    destination = a.ROOT / ".analysis/results/frontend/audio-mw-audit.json"
    host.publish_host_static_query(report, destination, a, "quick_output_1446_chain")
    print(json.dumps({"receipt": a.rel(destination), "query": report["query"], "failures": report["failures"],
        "bounded_observation_complete": report["bounded_observation_complete"], "target_execution": False}), flush=True)
    if report["failures"]:
        raise ValueError("Current 1446 quick output observation remains unresolved")
    return report


def _quick_effect_binding_1446_dependencies(audit):
    """Pin completed product routing and shared computations by exact section."""
    audio_path = ".analysis/results/frontend/audio-mw-audit.json"
    host_path = ".analysis/results/host-current/local-audit.json"
    wheel_path = ".analysis/results/lighting-runtime-comparison.json"
    documents = {path: json.loads((a.ROOT / path).read_bytes()) for path in (audio_path, host_path, wheel_path)}
    upstream = []
    for path, pointer, expected in (
            (audio_path, "/quick_output_1446_chain", "03503eeebb9cb0e7d73a68c74bf1ee636d0c6d640b707d305aaaf232f5eccb84"),
            (audio_path, "/mute_mapping_1446_chain", "434a4198ceaf9a99892c45bed069358861d0d15a819d458de7bc85a0321c0ea2"),
            (host_path, "/lighting_static_layer", "7098bd4b6ad0bd00beb0d9f23098316b4e6e05d58fb3b302e7f816bfa2330dca"),
            (host_path, "/lighting_timed_effects", "d7acdae5a8b1933915f3b77e1b12f16292a3bd237ea57ad53299fe90dc199573"),
            (host_path, "/lighting_audio_effect_chain", "a97b4c60167f42a6a64f3deaa161f7bb246dacdb9548827f313a5062229cd957"),
            (wheel_path, "/attempts/5/evidence/functions/50", "55e35785ea586bb1da54aa811cc46f8dd3d9e225ce01e3f3940e0305cd1c3e86"),
            (wheel_path, "/attempts/5/evidence/functions/51", "e37d69fe3bb6b102de51502092534c50c0c05d5424f0bf5c1a94cbf3b24c57dd"),
            (wheel_path, "/attempts/5/evidence/functions/52", "261bab75359b04c84dc737468e93ff55492d56615f008e60e9de99821d4b58c9")):
        value = documents[path]
        for key in pointer.strip("/").split("/"):
            value = value[int(key)] if isinstance(value, list) else value[key]
        if _audio_auto_pause_hid_digest(value) != expected:
            raise ValueError("1446 Quick binding upstream requires review: " + pointer)
        upstream.append({"receipt": path, "pointer": pointer, "canonical_sha256": expected, "recaptured": False})
    audio, shared = documents[audio_path], documents[host_path]
    for name, section in ((name, audio[name]) for name in ("quick_output_1446_chain", "mute_mapping_1446_chain")):
        if not section["snapshot_stable"] or not section["bounded_observation_complete"] or section["failures"]:
            raise ValueError("1446 Quick binding incomplete dependency: " + name)
    return audio, shared, documents[wheel_path], upstream


def _quick_effect_binding_1446_sources(audit, audio, shared):
    import frontend
    import host
    quick, mute = audio["quick_output_1446_chain"], audio["mute_mapping_1446_chain"]
    owners, reused, roles, bindings, selections = {}, [], {}, [], []

    def reuse(role, section, key, pointer):
        owner = next(row for row in section["complete_source_owners"] if row["id"] == key)
        host.verify_profiles_owner(audit, owner)
        owners[role] = owner
        reused.append({"role": role, "receipt": ".analysis/results/frontend/audio-mw-audit.json"
            if pointer in ("/mute_mapping_1446_chain", "/quick_output_1446_chain") else ".analysis/results/host-current/local-audit.json",
            "section_pointer": pointer, "owner_id": key,
            **{name: owner[name] for name in ("original", "syntax", "byte_start", "byte_end", "body_sha256")}})

    for role in ("quick_effects", "ui_quick_effects", "effect_defaults", "ui_effect_defaults", "effect_ids", "ui_effect_ids"):
        reuse(role, mute, mute["roles"][role], "/mute_mapping_1446_chain")
    for role in ("mw_quick_effect_maker", "engine_region_quick_effect", "engine_software_quick_effect",
                 "le_replace_effect", "le_device_info_configure"):
        reuse(role, quick, quick["roles"][role], "/quick_output_1446_chain")
    for role, key in (("facade_add", "2578:addEffect"), ("mode_playback", "2578:getModeWithPlayback"),
                      ("native_add", "2198:AddEffect")):
        section = shared["lighting_timed_effects"]
        reuse(role, section, section["selected"][key], "/lighting_timed_effects")
    section = shared["lighting_audio_effect_chain"]
    for role in ("rgb_conversion", "add_effect_action"):
        reuse(role, section, section["selected"][role], "/lighting_audio_effect_chain")
    for side, url, pattern in (("mw", "https://apps.razer.com/synapse/products/1446/mw/", "audio-mw-1446-*"),
            ("le", "https://apps.razer.com/synapse/lighting-engine/", "synapse-lighting-engine-*")):
        selected = frontend.current_source_selection(url, audit,
            candidates=sorted((a.ROOT / ".analysis/inputs/frontend").glob(pattern + "/acquisition.json")),
            verify_capture=False)
        expected = next(row for row in quick["source_selections"] if row["side"] == side)
        if any(selected[key] != expected[key] for key in ("name", "acquisition")):
            raise ValueError("1446 Quick binding current source selection requires review: " + side)
        selections.append({"side": side, **{key: selected[key] for key in ("name", "acquisition")}})
    converter = next(row for row in quick["complete_source_owners"] if row["id"] == quick["roles"]["le_converter"])
    original = converter["original"]
    node = host.verify_profiles_owner(audit, converter).child_by_field_name("value")
    for name in ("convertUItoLighting", "getStarlightEffectDuration", "strColorToHex"):
        _, key = audit.callable_member("quick_effect_binding_1446_" + name, original, node, name)
        roles[name] = key
        owners[name] = audit.owners[key]
    for role, name in (("normalize_native_id", "o"), ("quick_parameters", "r")):
        item = audit.binding("quick_effect_binding_1446_" + role, original, name, owners["le_replace_effect"]["byte_start"])
        if item.get("resolution") != "declaration":
            raise ValueError("1446 Quick binding lexical declaration unresolved: " + role)
        roles[role] = item["owner_id"]
        owners[role] = audit.owners[item["owner_id"]]
        bindings.append(item)
    for role, module, name in (("native_effect_ids", 4317, "cR"), ("wave_speed", 5596, "ol"),
            ("spectrum_duration", 5596, "pL"), ("breathing_duration", 5596, "I2"),
            ("density_denominator", 5596, "JG"), ("transparent_color", 5596, "FU")):
        item = audit.webpack_export("quick_effect_binding_1446_" + role, [original], module, name)
        roles[role] = item["binding"]["owner_id"]
        owners[role] = audit.owners[roles[role]]
        bindings.append(item)
    manifest = json.loads(audit.read(quick["lighting_manifest"]["original"]))
    if (manifest["category"] != "BROADCASTER" or manifest["isHardwareEffectsOnly"] is not False
            or any(key in manifest for key in ("quickEffectCustomization", "customConfig", "wheel"))):
        raise ValueError("1446 Quick binding actual manifest branch requires review")
    return owners, {"roles": roles, "reused_source_owners": reused, "source_selections": selections,
        "bindings": bindings, "lighting_manifest": {"original": quick["lighting_manifest"]["original"],
            "category": manifest["category"], "logical_matrix": [5, 12], "wheel_customization_present": False}}


