def _audio_1446_multi_function_shared_transport(audit):
    """Reuse only the exact Host/native layer; product framing remains local."""
    receipt = ".analysis/results/frontend/audio-mw-audit.json"
    pointer = "/auto_pause_hid_chain/shared_feature_transport"
    shared = json.loads((a.ROOT / receipt).read_bytes())["auto_pause_hid_chain"]["shared_feature_transport"]
    digest = _audio_auto_pause_hid_digest(shared)
    if (digest != "67e27512eb528b218f1acfb1f567f8e7e086740f61cedb943eee640d691964b5"
            or shared["canonical_sha256"] != _audio_auto_pause_hid_digest(
                {key: value for key, value in shared.items() if key != "canonical_sha256"})):
        raise ValueError("1446 multi function shared transport requires review")
    sources, release = _audio_auto_pause_hid_host_inputs(audit, shared)
    for owner in shared["complete_source_owners"]:
        raw = audit.read(owner["original"])[owner["byte_start"]:owner["byte_end"]]
        if raw.decode() != owner["body"] or hashlib.sha256(raw).hexdigest() != owner["body_sha256"]:
            raise ValueError("1446 multi function reused Host source owner differs")
    native, addon = shared["native"], audit.read(sources["addon"])
    if not native["capture_complete"] or native["target_execution"]:
        raise ValueError("1446 multi function reused native capture is incomplete")
    audit.artifact(a.ROOT / native["capture_receipt"]["path"], native["capture_receipt"])
    for row in native["functions"]:
        if not all(row[key] for key in ("assembly_captured", "pseudocode_captured", "input_chunks_verified")):
            raise ValueError("1446 multi function reused native function is incomplete")
        audit.artifact(a.ROOT / row["artifact"]["path"], row["artifact"])
        for chunk in row["verified_original_chunks"]:
            length = int(chunk["end"], 16) - int(chunk["start"], 16)
            offset = chunk["file_offset"]
            if hashlib.sha256(addon[offset:offset + length]).hexdigest() != chunk["sha256"]:
                raise ValueError("1446 multi function reused native PE bytes differ")
    dependency = {"receipt": receipt, "pointer": pointer, "canonical_sha256": digest,
        "reused_source_owners": len(shared["complete_source_owners"]), "reused_native_functions": len(native["functions"]),
        "product_framing_reused": False, "recaptured": False}
    return dependency, {"host_version": release["version"], "node_rz_hid_version": release["node_rz_hid_version"],
        "native_input": native["input"], "host_source_contract": shared["source_contract"],
        "native_contract": shared["native_contract"], "capture_failures": native["failures"],
        "selected_native_functions_verified": len(native["functions"]),
        "unrelated_capture_failure_is_not_selected_function_success": True}


def collect_audio_1446_multi_function_chain(audit):
    dependency, shared = _audio_1446_multi_function_shared_transport(audit)
    result = _audio_1446_multi_function_sources(audit)
    result["source_contract"] = _audio_1446_multi_function_source_contract(
        {role: audit.owners[key] for role, key in result["roles"].items()})
    result.update(kind="current_audio_1446_multi_function_chain", upstream_sections=[dependency],
        shared_transport_dependency=dependency, shared_transport_contract=shared, source_slice_complete=True,
        source_chain_complete=False, whole_product_complete=False, failures=[], target_execution=False,
        real_device_operations=False, official_dll_comparison="unverified", rust_independent_implementation="unverified",
        ui_backend_wiring="unverified", runtime_acceptance="unverified", product_code_modified=False,
        unresolved_chains=["Actual HID/device ACK, malformed replies, disconnect/cancellation and worker/callback drain require separate explicit comparison; no target was executed.",
            "Independent Rust implementation, UI/backend wiring and runtime acceptance remain unverified; source local defaults, optimistic UI and completed task messages are not measured device state.",
            "Mute mapping, other audio feature chains and Marie initialization/termination retain their separate existing owners and gaps."])
    return result


def audit_audio_1446_multi_function_chain(args):
    import host
    if (args.family != "audio" or args.function != "mw" or getattr(args, "prepare", False)
            or sorted(set(args.product or [1446])) != [1446]):
        raise ValueError("audio-1446-multi-function-chain requires only PID1446 middleware without preparation")
    audit = host.HostLocalAudit()
    report = {"schema_version": 1, "parser": audit.parser_versions, "kind": "current_audio_1446_multi_function_chain",
        "query": "audio-1446-multi-function-chain", "failures": [], "bounded_observation_complete": False,
        "source_chain_complete": False, "whole_product_complete": False, "target_execution": False,
        "official_dll_comparison": "unverified", "runtime_acceptance": "unverified"}
    try:
        for name in ("tools/families.py", "tools/host.py", "tools/frontend.py", "tools/evidence.py"):
            audit.artifact(a.ROOT / name)
        report.update(collect_audio_1446_multi_function_chain(audit))
        report["bounded_observation_complete"] = not report["failures"]
    except (OSError, ValueError, KeyError, IndexError, TypeError, StopIteration) as error:
        report["failures"].append(type(error).__name__ + ": " + str(error))
    changed = audit.final_snapshot() + host._keypad_temporary_keymap_dependency_changes(report.get("upstream_sections", []))
    if changed:
        report["failures"].extend("1446 multi function input changed during query: " + name for name in changed)
        report["bounded_observation_complete"] = False
    report.update(recorded_at_utc=a.stamp(), changed_during_query=changed, snapshot_stable=not changed,
        complete_originals=list(audit.sources.values()), complete_source_owners=list(audit.owners.values()),
        verified_artifacts=list(audit.artifacts.values()))
    destination = a.ROOT / ".analysis/results/frontend/audio-mw-audit.json"
    host.publish_host_static_query(report, destination, a, "multi_function_1446_chain")
    print(json.dumps({"receipt": a.rel(destination), "query": report["query"], "failures": report["failures"],
        "bounded_observation_complete": report["bounded_observation_complete"], "target_execution": False}), flush=True)
    if report["failures"]:
        raise ValueError("Current 1446 multi function observation remains unresolved")
    return report


