def _audio_auto_pause_sources(audit):
    """Parse latest mounted earbuds bytes and the PID2657 UI source owners."""
    import frontend
    selected, products, roles = [], [], {}

    def keep(label, files, anchor, kinds, *, callable_only=False):
        matches = {}
        for source in files:
            if not source["path"].endswith(".js"):
                continue
            for hit in re.finditer(anchor, audit.read(source)):
                node = audit.tree(source).root_node.descendant_for_byte_range(hit.start(), hit.end() - 1)
                while node is not None:
                    value = node.child_by_field_name("value")
                    if node.type in kinds and (not callable_only or node.type != "variable_declarator"
                            or value is not None and value.type in {"arrow_function", "function_expression"}):
                        break
                    node = node.parent
                if node is None or node.end_byte - node.start_byte > 50_000:
                    raise ValueError("Audio auto pause complete owner boundary differs: " + label)
                owner = audit.retain_range("audio_auto_pause_" + label, source,
                    node.start_byte, node.end_byte, node.type)
                matches[owner] = (source, node)
        if len(matches) != 1:
            raise ValueError("Audio auto pause owner is absent or ambiguous: " + label)
        key, pair = next(iter(matches.items()))
        roles[label] = key
        return pair

    for pid in _AUDIO_AUTO_PAUSE_PRODUCTS:
        source = frontend.current_source_selection(f"https://apps.razer.com/synapse/products/{pid}/mw/", audit,
            candidates=sorted((a.ROOT / ".analysis/inputs/frontend").glob(f"audio-mw-{pid}-*/acquisition.json")))
        files = [row for row in source["originals"] if f"/products/{pid}/" in row["path"]]
        selected.append({key: source[key] for key in ("name", "acquisition", "candidate_decisions",
            "capture_failures", "failed_acquisition", "unresolved_acquisition")})
        selected[-1]["complete_capture"] = source["capture"]["manifest"] if source["capture"] else None
        selected[-1]["selected_owner_analysis"] = "Complete AST owners parsed directly from verified latest original bytes"
        prefix = str(pid) + "_"
        feature_source, feature = keep(prefix + "feature", files,
            rb'this\.featureKey="audioAutoPauseControlFeature"', {"class_declaration"})
        keep(prefix + "feature_export", files,
            rb'AudioAutoPauseControlFeature:\(\)=>', {"pair"})
        event_source, event = keep(prefix + "event", files,
            rb'eventKey:"SET_AUDIO_AUTO_PAUSE_CONTROL"', {"variable_declarator"})
        keep(prefix + "registration", files,
            rb'featureKey:"audioAutoPauseControlFeature",featureConfig:\{\}', {"call_expression"})
        keep(prefix + "transport_registration", files,
            rb'useFeature\("rzDeviceType","rzDevice40",\{hardwareEventParserType:', {"call_expression"})
        keep(prefix + "default_profile", files,
            rb'audioAutoPauseControl:\{isEnabled:!0\}', {"variable_declarator"})
        keep(prefix + "device_get", files,
            rb'getAudioAutoPauseControl\(\)\{', {"method_definition"})
        keep(prefix + "device_set", files,
            rb'setAudioAutoPauseControl\(e\)\{', {"method_definition"})
        protocol_source, protocol_get = keep(prefix + "protocol_get", files,
            rb'getAudioAutoPauseStatus\(\w+\)\{', {"method_definition"})
        _, protocol_set = keep(prefix + "protocol_set", files,
            rb'setAudioAutoPauseStatus\(\w+,\w+\)\{', {"method_definition"})
        for suffix, node in (("get", protocol_get), ("set", protocol_set)):
            command_source = protocol_source
            if b"new Uint8Array" not in node.text:
                forwarded = re.search(rb'return (\w+)\.(\w+)\(this,', node.text)
                if forwarded is None:
                    raise ValueError("Audio auto pause current command helper is unresolved")
                imported = audit.binding("audio_auto_pause_" + prefix + "protocol_import_" + suffix,
                    command_source, forwarded.group(1).decode(), node.start_byte + forwarded.start(1))
                required = re.search(r'=\w+\((\d+)\)$', imported.get("body", ""))
                if imported.get("resolution") != "declaration" or required is None:
                    raise ValueError("Audio auto pause current command helper import differs")
                exported = audit.webpack_export("audio_auto_pause_" + prefix + "protocol_helper_" + suffix,
                    files, int(required.group(1)), forwarded.group(2).decode())
                bound = exported["binding"]
                roles[prefix + "protocol_helper_" + suffix] = bound["owner_id"]
                command_source = exported["original"]
                node = audit.tree(command_source).root_node.descendant_for_byte_range(bound["start_byte"], bound["end_byte"] - 1)
                while node is not None and (node.start_byte != bound["start_byte"] or node.end_byte != bound["end_byte"]):
                    node = node.parent
                if node is None:
                    raise ValueError("Audio auto pause helper boundary differs")
            text = node.text.decode("utf-8")
            header = re.search(r'new Uint8Array\((\w+)(?:\.(\w+))?\[0\]\)', text)
            parser = re.search(r'return (\w+)\(\w+\),\w+', text)
            if header is None or parser is None:
                raise ValueError("Audio auto pause protocol binding is unresolved")
            for role, match in (("command_" + suffix, header), ("parse_" + suffix, parser)):
                bound = audit.binding("audio_auto_pause_" + prefix + role, command_source,
                    match.group(1), node.start_byte + match.start(1))
                if bound.get("resolution") != "declaration":
                    raise ValueError("Audio auto pause protocol dependency is not lexical")
                if role.startswith("command_") and match.group(2) is not None:
                    required = re.search(r'=\w+\((\d+)\)$', bound.get("body", ""))
                    if required is None:
                        raise ValueError("Audio auto pause current command constant import differs")
                    exported = audit.webpack_export("audio_auto_pause_" + prefix + role, files,
                        int(required.group(1)), match.group(2))
                    bound = exported["binding"]
                roles[prefix + role] = bound["owner_id"]
        # Both minifier variants import the same actual profile-cache module.
        event_raw = event.text.decode("utf-8")
        access = re.search(r'const \w+=\(0,(\w+)\.(\w+)\)\(\w+\);let', event_raw)
        if access is None:
            raise ValueError("Audio auto pause profile storage access is unresolved")
        imported = audit.binding("audio_auto_pause_" + prefix + "storage_import", event_source,
            access.group(1), event.start_byte + access.start(1))
        required = re.search(r'=\w+\((\d+)\)$', imported.get("body", ""))
        if imported.get("resolution") != "declaration" or required is None:
            raise ValueError("Audio auto pause profile storage import differs")
        export = audit.webpack_export("audio_auto_pause_" + prefix + "profile_storage", files,
            int(required.group(1)), access.group(2))
        roles[prefix + "profile_storage"] = export["binding"]["owner_id"]
        roles[prefix + "storage_factory"] = export["complete_factory_owner"]
        products.append({"product_id": pid, "source_set": source["name"],
            "feature_original": audit.sources[feature_source["path"]],
            "roles": {key.removeprefix(prefix): value for key, value in roles.items() if key.startswith(prefix)},
            "scope": "Actual feature registration, shared middleware/profile and command owners; UI consumers reviewed separately for PID2657"})

    ui = frontend.current_source_selection("https://apps.razer.com/synapse/products/2657/ui/", audit,
        candidates=sorted((a.ROOT / ".analysis/inputs/frontend").glob("audio-2657-*/acquisition.json")))
    selected.append({key: ui[key] for key in ("name", "acquisition", "candidate_decisions",
        "capture_failures", "failed_acquisition", "unresolved_acquisition")})
    selected[-1]["complete_capture"] = ui["capture"]["manifest"] if ui["capture"] else None
    selected[-1]["selected_owner_analysis"] = "Complete AST owners parsed directly from verified latest original bytes"
    files = [row for row in ui["originals"] if "/products/2657/" in row["path"]]
    ui_source, toggle = keep("ui_toggle", files, rb'\w+\.autoPauseReducer\.autoPause',
        {"variable_declarator", "function_declaration"}, callable_only=True)
    toggle_name = toggle.child_by_field_name("name").text
    keep("ui_mount", files, rb'\.jsx\)\(' + re.escape(toggle_name) + rb',\{',
        {"variable_declarator", "function_declaration"}, callable_only=True)
    keep("ui_reducer", files, rb'\[autoPauseReducer\] Posting to MW:',
        {"variable_declarator", "function_declaration"}, callable_only=True)
    keep("ui_default", files, rb'autoPause:\{isEnabled:!1\},actionsFromUI:', {"variable_declarator"})
    keep("ui_profile_consumer", files, rb'case"audioAutoPauseControl"', {"assignment_expression"})
    # Capture the complete shared task manager; false, exception and abort consumers are distinct.
    middleware = [row for row in audit.sources.values() if "/audio-mw-2657-" in row["path"]
                  and "/products/2657/" in row["path"]]
    keep("generic_manager", middleware, rb'\[taskMakerHandler\] Updating local storage', {"class_declaration"})
    keep("generic_lazy_registry", middleware, rb'audioAutoPauseControlFeature:\(\)=>', {"variable_declarator"})
    keep("ui_action_new", files, rb'delete \w+\.errorActions;const', {"function_declaration"})
    keep("ui_action_event", files, rb'super\("rz_ui_action"\)', {"class_declaration"})
    # Bind reducer aliases to their actual exported action constants, not to their spelling.
    reducer = audit.owners[roles["ui_reducer"]]
    namespace = re.search(r'case (\w+)\.(\w+):', reducer["body"])
    bound = audit.binding("audio_auto_pause_ui_action_import", ui_source,
        namespace.group(1), reducer["byte_start"] + namespace.start(1))
    required = re.search(r'=\w+\((\d+)\)$', bound.get("body", ""))
    if required is None:
        raise ValueError("Audio auto pause UI action import differs")
    aliases = [match.group(1) for match in re.finditer(re.escape(namespace.group(1)) + r'\.(\w+)', reducer["body"])]
    for number, alias in enumerate(dict.fromkeys(aliases)):
        exported = audit.webpack_export("audio_auto_pause_ui_action_" + str(number), files,
            int(required.group(1)), alias)
        roles["ui_action_" + str(number)] = exported["binding"]["owner_id"]
    return {"products": products, "source_sets": selected, "roles": roles}


def audio_auto_pause_source_contract(owners):
    """Keep reviewed source behavior separate from real device confirmation."""
    grouped = {}
    for role, owner in owners.items():
        body = owner["body"].encode("utf-8")
        if hashlib.sha256(body).hexdigest() != owner["body_sha256"] or len(body) != owner["byte_end"] - owner["byte_start"]:
            raise ValueError("Audio auto pause source contract owner identity differs: " + role)
        group = role.split("_", 1)[0] if role.split("_", 1)[0].isdigit() else "ui"
        grouped.setdefault(group, {})[role] = {"original_sha256": owner["original"]["sha256"],
            **{key: owner[key] for key in ("byte_start", "byte_end", "syntax", "body_sha256")}}
    actual = {key: hashlib.sha256(json.dumps(value, sort_keys=True, separators=(",", ":")).encode()).hexdigest()
              for key, value in grouped.items()}
    if actual != _AUDIO_AUTO_PAUSE_REVIEWED:
        raise ValueError("Audio auto pause source contract selection requires review: " + json.dumps(actual, sort_keys=True))
    return {"product_ids": list(_AUDIO_AUTO_PAUSE_PRODUCTS), "ui_product_ids": [2657],
        "profile_id": 1, "commands": {"get": [1, 24, 158], "set": [2, 24, 30]},
        "payloads": {"get": [1], "set_disabled": [1, 0], "set_enabled": [1, 1]},
        "successful_response": {"profileId": "data[0]", "state": "data[1]"},
        "storage": {"scope": "serial metadata active GUID; first profile when that metadata has no active GUID", "field": "audioAutoPauseControl.isEnabled",
            "profile_default": True, "restore_missing_field_default": True,
            "runtime_source": "local profile; replaces the preexisting event", "runtime_reads_device": False,
            "restore_reads_device_before_conditional_write": True, "restore_set_false_blocks_ui_update": False,
            "device_get_failure": {"isEnabled": False}, "device_get_failure_is_observation": False},
        "task": {"persist_before_device_access": True, "category": "NORMAL_SKIPPABLE",
            "false_return": "result false, value.status completed; completion notice still says completed",
            "exception": "result false, value null and rejected task; error completion",
            "abort_check": "after awaited execute, before postExecute and completed marker",
            "passes_abort_signal_to_auto_pause_setter": False, "rollback_or_readback": False},
        "ui": {"initial_enabled": False, "toggle_updates_before_mw_reply": True,
            "disabled_when_earbud_disconnected": True, "profile_consumer": "local profile field",
            "reducer_handles_generic_completion_names": False},
        "lifetime": {"auto_pause_owns_timer_listener_or_shutdown": False,
            "generic_shutdown": "calls only feature shutdown methods that exist",
            "whole_transport_quiescence_proven": False},
        "reviewed_selection_sha256": actual}


def collect_audio_auto_pause_chain(audit):
    result = _audio_auto_pause_sources(audit)
    result["source_contract"] = audio_auto_pause_source_contract(
        {role: audit.owners[key] for role, key in result["roles"].items()})
    result.update(kind="current_audio_auto_pause_chain", failures=[], source_slice_complete=True,
        source_chain_complete=False, whole_product_complete=False, target_execution=False,
        real_device_operations=False, runtime_acceptance="unverified",
        unresolved_chains=["Native HID transport, exact hardware reply/readback, other products' full UI consumers and real cancellation/drain remain outside this source slice"])
    return result


def audit_audio_auto_pause_chain(args):
    import host
    if (args.family != "audio" or args.function != "mw" or getattr(args, "prepare", False)
            or sorted(set(args.product or _AUDIO_AUTO_PAUSE_PRODUCTS)) != list(_AUDIO_AUTO_PAUSE_PRODUCTS)):
        raise ValueError("audio-auto-pause-chain requires the five reviewed earbuds middleware products without preparation")
    audit = host.HostLocalAudit()
    report = {"schema_version": 1, "recorded_at_utc": a.stamp(), "parser": audit.parser_versions,
        "kind": "current_audio_auto_pause_chain", "failures": [], "bounded_observation_complete": False,
        "source_chain_complete": False, "whole_product_complete": False, "target_execution": False,
        "real_device_operations": False, "rust_implementation": "not_reviewed",
        "official_dll_comparison": "not_executed", "runtime_acceptance": "unverified"}
    try:
        for name in ("tools/families.py", "tools/host.py", "tools/frontend.py", "tools/evidence.py"):
            audit.artifact(a.ROOT / name)
        report.update(collect_audio_auto_pause_chain(audit))
        report["bounded_observation_complete"] = not report["failures"]
    except (OSError, ValueError, KeyError, IndexError, TypeError, StopIteration) as error:
        report["failures"].append(str(error))
    changed = audit.final_snapshot()
    if changed:
        report["failures"].extend("Audio auto pause input changed during query: " + name for name in changed)
        report["bounded_observation_complete"] = False
    report.update(tool=identity(Path(__file__)), changed_during_query=changed, snapshot_stable=not changed,
        complete_originals=list(audit.sources.values()), complete_source_owners=list(audit.owners.values()),
        verified_artifacts=list(audit.artifacts.values()))
    destination = a.ROOT / ".analysis/results/frontend/audio-mw-audit.json"
    host.publish_host_static_query(report, destination, a, "auto_pause_chain")
    print(json.dumps({"receipt": a.rel(destination), "query": "auto_pause_chain", "owners": len(audit.owners),
        "failures": report["failures"], "bounded_observation_complete": report["bounded_observation_complete"]}), flush=True)
    if report["failures"]:
        raise ValueError("Current audio auto pause source observation remains unresolved")
    return report


