def _audio_auto_pause_hid_digest(value):
    return hashlib.sha256(json.dumps(value, ensure_ascii=False, sort_keys=True,
        separators=(",", ":")).encode()).hexdigest()


def _audio_auto_pause_hid_dependencies(audit):
    """Reuse stable MW/UI and shared Host owners without recapturing them."""
    import frontend
    sections, upstream, selected = {}, [], {}
    for name, expected in _AUDIO_AUTO_PAUSE_HID_UPSTREAM.items():
        receipt = ".analysis/results/frontend/" + ("accessories-main-audit.json"
            if name.startswith("hanbo_") else "audio-mw-audit.json")
        section = json.loads((a.ROOT / receipt).read_bytes())[name]
        digest = _audio_auto_pause_hid_digest(section)
        if (digest != expected or section["failures"] or not section["bounded_observation_complete"]
                or not section["snapshot_stable"] or section["target_execution"]):
            raise ValueError("Audio auto pause HID upstream section requires review: " + name)
        # The destination also contains other queries; only this pointer is frozen.
        upstream.append({"receipt": receipt, "pointer": "/" + name, "canonical_sha256": digest,
            "reused_complete_owners": len(section["complete_source_owners"]), "recaptured": False})
        for owner in section["complete_source_owners"]:
            body = audit.read(owner["original"])[owner["byte_start"]:owner["byte_end"]]
            if (body.decode("utf-8") != owner["body"]
                    or hashlib.sha256(body).hexdigest() != owner["body_sha256"]):
                raise ValueError("Audio auto pause HID reused complete owner differs: " + owner["id"])
        sections[name] = section
    for pid in _AUDIO_AUTO_PAUSE_PRODUCTS:
        for function, pattern in (("mw", f"audio-mw-{pid}-*"), ("ui", f"audio-{pid}-*")):
            selection = frontend.current_source_selection(f"https://apps.razer.com/synapse/products/{pid}/{function}/",
                audit, candidates=sorted((a.ROOT / ".analysis/inputs/frontend").glob(pattern + "/acquisition.json")),
                verify_capture=False)
            if function == "mw" or pid == 2657:
                previous, = [row for row in sections["auto_pause_chain"]["source_sets"]
                    if row["name"] == selection["name"]]
            else:
                previous, = [row for row in sections["auto_pause_ui_consumers"]["products"]
                    if row["product_id"] == pid]
            if previous["acquisition"] != selection["acquisition"]:
                raise ValueError("Audio auto pause HID current source selection differs")
            selected[(pid, function)] = selection
    return sections, upstream, selected


def _audio_auto_pause_hid_host_inputs(audit, prior):
    """Bind the shared route to the current retained Host package and addon."""
    import host
    indexed = json.loads(audit.artifact(a.ROOT / ".analysis/inputs.json"))
    release = host.verified_host_release_receipt(index=indexed)
    audit.artifact(a.ROOT / release["receipt"]["path"], release["receipt"])
    for dependency in release["verified_dependencies"]:
        audit.artifact(a.ROOT / dependency["path"], dependency)
    members = host.current_host_asar_members(audit, indexed, release)
    originals = {row["path"]: row for row in indexed["inputs"]}
    sources, ancestry = {}, []
    for role, suffix in (("host", "electron/UsbRzDeviceAction.js"), ("main", "electron/main.js"),
            ("preload", "electron/preload.js"), ("nodehid", "node_modules/node-rz-hid/nodehid.js"),
            ("package", "node_modules/node-rz-hid/package.json"), ("mutex", "electron/lib/RzMutx.js")):
        source, = [row for row in members if row["path"].endswith("/" + suffix)]
        archive = originals[source["container"]]
        package, = [row for row in release["files"] if row.get("path") == archive["container"]
            and row.get("sha256") == archive["container_sha256"] and row.get("manifest_identity_verified")]
        raw = audit.read(source)
        if (source.get("unpacked") or type(source.get("offset")) is not int
                or source["container_sha256"] != archive["sha256"]
                or audit.read(archive)[source["offset"]:source["offset"] + len(raw)] != raw):
            raise ValueError("Audio auto pause HID Host member/package ancestry differs: " + role)
        audit.artifact(a.ROOT / package["path"], package)
        sources[role] = source
        ancestry.append({"role": role, "member": source, "archive": archive,
            "package": package, "member_offset_verified": True})
    addon, = [row for row in host.current_host_extracted_inputs(indexed, release)
        if row["path"].endswith("/node-rz-hid/build/Release/HID.node")]
    alias, = [row for row in members if row["path"].endswith("/node-rz-hid/build/Release/HID.node")]
    if (not alias["unpacked"] or alias["container"] != sources["nodehid"]["container"]
            or addon["container"] != ancestry[0]["package"]["path"]
            or addon["container_sha256"] != ancestry[0]["package"]["sha256"]
            or audit.read(alias) != audit.read(addon)
            or {key: addon[key] for key in ("path", "bytes", "sha256")} != prior["native"]["input"]
            or release["receipt"] != prior["host_release"]["acquisition"]):
        raise ValueError("Audio auto pause HID current addon/package differs from shared Host evidence")
    audit.artifact(a.ROOT / addon["extraction_receipt"]["path"], addon["extraction_receipt"])
    package = json.loads(audit.read(sources["package"]))
    if package["main"] != "./nodehid.js" or host.inspect_pe(audit.read(addon))["architecture"] != "x64":
        raise ValueError("Audio auto pause HID package entry or native architecture differs")
    sources["addon"] = addon
    return sources, {"version": release["version"], "acquisition": release["receipt"],
        "members": ancestry, "addon": addon, "addon_asar_alias": alias,
        "addon_alias_bytes_equal": True, "node_rz_hid_version": package["version"],
        "actual_loaded_addon_observed": False}


def _audio_auto_pause_hid_sources(audit, sections, selections, sources):
    """Review rzDevice40 differences once; retain each selected product owner."""
    import host
    roles, products = {}, []

    def keep(role, source, needle, kinds):
        owner, = audit.retain("audio_auto_pause_hid_" + role, source, needle, kinds)
        roles[role] = owner
        return owner

    def imported(role, source, namespace, export, position, files):
        bound = audit.binding("audio_auto_pause_hid_" + role + "_import", source, namespace, position)
        required = re.fullmatch(r'\w+=\w+\((\d+)\)', bound.get("body", ""))
        if bound.get("resolution") != "declaration" or required is None:
            raise ValueError("Audio auto pause HID import is not a selected lexical module: " + role)
        resolved = audit.webpack_export("audio_auto_pause_hid_" + role, files, int(required[1]), export)
        roles[role] = resolved["binding"]["owner_id"]
        roles[role + "_export"] = resolved["export_definition_owner"]
        return resolved

    mw = sections["auto_pause_chain"]
    reused = {row["id"]: row for row in mw["complete_source_owners"]}
