        prefix, selected = str(pid) + "_", selections[(pid, "mw")]
        files = selected["originals"]
        protocol = reused[mw["roles"][prefix + "protocol_get"]]
        source = protocol["original"]
        node = audit.tree(source).root_node.descendant_for_byte_range(protocol["byte_start"], protocol["byte_end"] - 1)
        while node is not None and node.type not in {"class", "class_declaration"}:
            node = node.parent
        if node is None:
            raise ValueError("Audio auto pause HID protocol has no owning class")
        for name in ("constructor", "sendCommand", "_getUSBTransferInResult", "_createDataSend",
                "_calculateChecksum", "_getTransactionId", "releaseHIDMutex", "connectDevice"):
            _, roles[prefix + name] = audit.callable_member("audio_auto_pause_hid_" + prefix + name, source, node, name)
        heritage, = [child for child in node.children if child.type == "class_heritage"]
        base = re.fullmatch(rb'extends (\w+)\.(\w+)', heritage.text)
        if base is None:
            raise ValueError("Audio auto pause HID base class is unresolved")
        resolved = imported(prefix + "base", source, base[1].decode(), base[2].decode(),
            heritage.start_byte + base.start(1), files)
        declaration = host._help_binding_node(audit, resolved["original"], resolved["binding"])
        base_class = declaration.child_by_field_name("value")
        if base_class is None or base_class.type not in {"class", "class_declaration"}:
            raise ValueError("Audio auto pause HID selected base is not a class")
        for name in ("constructor", "generateDefaultResult", "destroy", "terminate"):
            _, roles[prefix + "base_" + name] = audit.callable_member("audio_auto_pause_hid_" + prefix + "base_" + name,
                resolved["original"], base_class, name)
        constructor = audit.owners[roles[prefix + "base_constructor"]]
        for label, pattern in (("version", r'this\.version=(\w+)\.(\w+)'),
                ("retry_in", r'\w+=(\w+)\.(\w+),\w+=\w+\.\w+,\w+=\{owner:'),
                ("retry_out", r'\w+=\w+\.\w+,\w+=(\w+)\.(\w+),\w+=\{owner:')):
            match = re.search(pattern, constructor["body"])
            if match is None:
                raise ValueError("Audio auto pause HID base constant is unresolved: " + label)
            imported(prefix + label, resolved["original"], match[1], match[2],
                constructor["byte_start"] + len(constructor["body"][:match.start(1)].encode())
                if label == "version" else base_class.start_byte, files)
        main = reused[mw["roles"][prefix + "device_get"]]["original"]
        keep(prefix + "instance_factory", main, "rzDevice40:{getRzDevice:", {"pair"})
        lazy = keep(prefix + "class_loader", main, "rzDevice40:()=>", {"pair"})
        module = re.search(r'\.bind\(\w+,(\d+)\)', audit.owners[lazy]["body"])
        if module is None:
            raise ValueError("Audio auto pause HID class loader target is unresolved")
        exported = audit.webpack_export("audio_auto_pause_hid_" + prefix + "selected_class", files, int(module[1]), "default")
        class_binding = exported["binding"]
        for depth in range(4):
            declaration = host._help_binding_node(audit, exported["original"], class_binding)
            value = declaration.child_by_field_name("value")
            if declaration.type == "class_declaration" or value is not None and value.type == "class":
                target = declaration if declaration.type == "class_declaration" else value
                break
            if value is None or value.type != "identifier":
                raise ValueError("Audio auto pause HID selected class export alias is unresolved")
            class_binding = audit.binding("audio_auto_pause_hid_" + prefix + "selected_class_alias_" + str(depth),
                exported["original"], value.text.decode(), value.start_byte)
            roles[prefix + "selected_class_alias_" + str(depth)] = class_binding["owner_id"]
        else:
            raise ValueError("Audio auto pause HID selected class export alias did not terminate")
        if exported["original"]["path"] != source["path"] or target.start_byte != node.start_byte:
            raise ValueError("Audio auto pause HID actual class loader differs from protocol owner")
        roles[prefix + "selected_class_export"] = exported["export_definition_owner"]
        send = audit.owners[roles[prefix + "sendCommand"]]
        bridge_call = re.search(r'\(0,(\w+)\.(\w+)\)\(', send["body"])
        if bridge_call is None:
            raise ValueError("Audio auto pause HID bridge call is unresolved")
