    changed = {0x34ca0, 0x34f30, 0x35280, 0x4c0c0, 0x5a9c0}
    extra_hashes = {0x34a40: "bfdd978e2894bb2e4e37fdca8f7f39381c8a006c985a1832a2c77d59baed2af6",
        0x34a60: "4f712a0338461b2f677618eeac602834b0a43955f2af398e6aecd8b75a473a26"}
