            left, right = bytes.fromhex(before["bytes"]), bytes.fromhex(after["bytes"])
            if (len(left) != 7 or len(right) != 7 or left[:3] != right[:3]
                    or left[:3] not in (b"\x48\x8d\x0d", b"\x48\x8d\x05", b"\x48\x8d\x15", b"\x48\x8d\x35",
                        b"\x48\x8d\x1d", b"\x4c\x8d\x3d", b"\x4c\x8d\x25", b"\x4c\x8d\x0d")):
                raise ValueError("Audio Marie 1446 non-address instruction changed")
            address = int(before["rva"], 16)
            old_target = address + 7 + struct.unpack("<i", left[3:])[0]
