def audit_camera_3595_3596_processing_control_chain(args):
    import host
    if (args.family != "accessories" or args.function != "main" or getattr(args, "prepare", False)
            or sorted(set(args.product or [3595, 3596])) != [3595, 3596]):
        raise ValueError("camera-3595-3596-processing-control-chain requires PID3595 and PID3596 accessories main without production preparation")
    audit = host.HostLocalAudit()
    report = {"schema_version": 1, "recorded_at_utc": a.stamp(), "parser": audit.parser_versions,
        "kind": "current_camera_3595_3596_processing_control_chain", "product_ids": [3595, 3596], "failures": [],
        "bounded_observation_complete": False, "source_chain_complete": False, "whole_product_complete": False,
        "target_execution": False, "official_dll_comparison": "not_executed", "runtime_acceptance": "unverified"}
    try:
        for name in ("tools/families.py", "tools/host.py", "tools/frontend.py", "tools/evidence.py"):
            audit.artifact(a.ROOT / name)
        report.update(collect_camera_3595_3596_processing_control_chain(audit))
        report["bounded_observation_complete"] = not report["failures"]
    except (OSError, ValueError, KeyError, IndexError, TypeError, StopIteration) as error:
        report["failures"].append(type(error).__name__ + ": " + str(error))
    changed = audit.final_snapshot()
    changed.extend(host._keypad_temporary_keymap_dependency_changes(report.get("upstream_sections", [])))
    if changed:
        report["failures"].extend("3595/3596 DNR source changed during query: " + name for name in changed)
        report["bounded_observation_complete"] = False
    report.update(changed_during_query=changed, snapshot_stable=not changed, complete_originals=list(audit.sources.values()),
        complete_source_owners=list(audit.owners.values()), verified_artifacts=list(audit.artifacts.values()))
    destination = a.ROOT / ".analysis/results/frontend/accessories-camera-local-pages-audit.json"
    host.publish_host_static_query(report, destination, a, "camera_3595_3596_processing_control_chain")
    print(json.dumps({"receipt": a.rel(destination), "query": "camera-3595-3596-processing-control-chain", "failures": report["failures"],
        "bounded_observation_complete": report["bounded_observation_complete"], "target_execution": False}), flush=True)
    if report["failures"]:
        raise ValueError("Current3595/3596 DNR processing-control observation remains unresolved")
    return report


