def _camera_3595_3596_low_light_sources(audit, pid, document):
    import frontend
    import host
    receipt = ".analysis/results/frontend/accessories-camera-local-pages-audit.json"
    section = document["camera_3595_3596_processing_control_chain"]
    index = next(i for i, row in enumerate(section["products"]) if row["product_id"] == pid)
    product = section["products"][index]
    retained = {row["id"]: row for row in section["complete_source_owners"]}
    roles, owners, reused, layers, selections = {}, {}, {}, {}, {}

    def keep(role, source, node):
        roles[role] = audit.retain_range(f"camera_{pid}_low_light_{role}", source, node.start_byte, node.end_byte, node.type)
        owners[role] = audit.owners[roles[role]]
        return node

    def reuse(role, owner, pointer):
        node = host.verify_profiles_owner(audit, owner)
        owners[role] = owner
        reused[role] = {"receipt": receipt, "pointer": pointer,
            **{key: owner[key] for key in ("id", "original", "syntax", "byte_start", "byte_end", "body_sha256")}}
        return node

    def bound(role, source, name, at):
        value = audit.binding(f"camera_{pid}_low_light_{role}", source, name, at)
        return keep(role, source, host._help_binding_node(audit, source, value))

    def anchor(role, source, token, kinds, root=None):
        root = root if root is not None else audit.tree(source).root_node
        found = {}
        for hit in re.finditer(re.escape(token.encode()), root.text):
            at = root.start_byte + hit.start()
            node = root.descendant_for_byte_range(at, at + len(token.encode()) - 1)
            while node is not None and node.type not in kinds:
                node = node.parent
            if node is not None and root.start_byte <= node.start_byte < node.end_byte <= root.end_byte:
                found[(node.start_byte, node.end_byte)] = node
        if len(found) != 1:
            raise ValueError("3595/3596 low-light owner absent or ambiguous: " + role)
        return keep(role, source, next(iter(found.values())))

    def exported(role, side, module, name):
        value = audit.webpack_export(f"camera_{pid}_low_light_{role}", layers[side], module, name)
        source = value["original"]
        node = host._help_binding_node(audit, source, value["binding"])
        return source, keep(role, source, node)

    for side, prefix in (("ui", f"accessories-{pid}-current"), ("mw", f"accessories-mw-{pid}-current")):
        selected = frontend.current_source_selection(f"https://apps.razer.com/synapse/products/{pid}/{side}/", audit,
            candidates=sorted((a.ROOT / ".analysis/inputs/frontend").glob(prefix + "*/acquisition.json")), verify_capture=False)
