    image_product = image["products"][image_index]
    image_owners = {row["id"]: row for row in image["complete_owners"]}
    for role in ("product_feature", "cache_request", "cache_response_reducer", "ui_cache_request"):
        reuse(role, image_owners[image_product["roles"][role]], f"/image_properties/products/{image_index}/roles/{role}")
    ui, mw = owners["processing_page"]["original"], retained[product["roles"]["dispatch"]]["original"]
    for role, module, name in (("ui_action", 5305, "bg"), ("ui_action_type", 3254, "wJu"),
            ("ui_incoming_type", 3254, "fuz")):
        exported(role, "ui", module, name)
    bound("ui_action_import", ui, "qI" if pid == 3595 else "vI", owners["processing_page"]["byte_start"])
