def _camera_3595_mjpeg_sources(audit, document):
    import frontend
    import host
    previous = document["camera_3595_hdr_chain"]
    receipt = ".analysis/results/frontend/accessories-camera-local-pages-audit.json"
    retained = {row["id"]: row for row in previous["complete_source_owners"]}
    roles, reused, owners, layers, selections = {}, {}, {}, {}, {}

    def keep(role, original, node):
        roles[role] = audit.retain_range("camera_3595_mjpeg_" + role, original,
            node.start_byte, node.end_byte, node.type)
        owners[role] = audit.owners[roles[role]]
        return node

    def borrow(role, owner, pointer):
        if "body" not in owner:
            owner = {**owner, "roles": ["camera_3595_mjpeg_" + role],
                "body": audit.read(owner["original"])[owner["byte_start"]:owner["byte_end"]].decode()}
        host.verify_profiles_owner(audit, owner)
        owners[role] = owner
        reused[role] = {"receipt": receipt, "pointer": pointer,
            **{key: owner[key] for key in ("id", "original", "syntax", "byte_start", "byte_end", "body_sha256")}}

    def bound(role, original, name, at):
        value = audit.binding("camera_3595_mjpeg_" + role, original, name, at)
        return keep(role, original, host._help_binding_node(audit, original, value))

    def exported(role, side, module, name):
        value = audit.webpack_export("camera_3595_mjpeg_" + role, layers[side], module, name)
        return keep(role, value["original"], host._help_binding_node(audit, value["original"], value["binding"]))

    def anchor(role, original, token, kinds):
        root, found = audit.tree(original).root_node, {}
        for hit in re.finditer(re.escape(token.encode()), root.text):
            node = root.descendant_for_byte_range(hit.start(), hit.start() + len(token.encode()) - 1)
            while node is not None and node.type not in kinds:
                node = node.parent
            if node is not None:
                found[(node.start_byte, node.end_byte)] = node
        if len(found) != 1:
            raise ValueError("3595 MJPEG complete source owner absent or ambiguous: " + role)
        return keep(role, original, next(iter(found.values())))

    for side, stem in (("ui", "accessories-3595-current"), ("mw", "accessories-mw-3595-current")):
        current = frontend.current_source_selection(f"https://apps.razer.com/synapse/products/3595/{side}/", audit,
            candidates=sorted((a.ROOT / ".analysis/inputs/frontend").glob(stem + "*/acquisition.json")), verify_capture=False)
        if current["acquisition"] != previous["source_sets"][side]["acquisition"]:
            raise ValueError("3595 MJPEG current source selection differs: " + side)
        layers[side] = current["originals"]
        selections[side] = {key: current[key] for key in ("name", "acquisition", "candidate_decisions",
            "capture_failures", "failed_acquisition", "unresolved_acquisition")}
    for role, owner in previous["reused_source_owners"].items():
        if role != "ui_3596_processing_page":
            borrow(role, owner, owner["pointer"])
    for role in ("ui_hdr_panel", "ui_action_import", "ui_restart_type", "mw_default_profile"):
        borrow(role, retained[previous["roles"][role]], "/camera_3595_hdr_chain/roles/" + role)
    ui, mw = owners["ui_hdr_panel"]["original"], owners["replay_camera"]["original"]
    bound("ui_mode_constants", ui, "go", owners["ui_hdr_panel"]["byte_start"])
    for role, side, module, name in (("ui_action", "ui", 5305, "LX"), ("ui_action_type", "ui", 3254, "JhX"),
            ("ui_incoming_type", "ui", 3254, "gI2"), ("maker", "mw", 30525, "SZM"),
            ("runner", "mw", 85191, "CKA"), ("result_consumer", "mw", 85191, "xnY")):
        exported(role, side, module, name)
    for role, original, token, kinds in (("ui_reducer", ui, 'type:"ON_SET_MJPEG_QUALITY"', {"switch_case"}),
            ("ui_incoming_reducer", ui, "case j.gI2:", {"switch_case"}),
            ("dispatch", mw, 'case"ON_SET_MJPEG_QUALITY":', {"switch_case"}),
            ("state_event", mw, 'ON_SET_MJPEG_QUALITY:{actions:"setMJPEGQualityAction"}', {"pair"}),
            ("state_action", mw, "setMJPEGQualityAction:(0,o.LM)", {"pair"}),
            ("replay_mjpeg", mw, 'case"mjpegQuality":', {"switch_case"})):
        anchor(role, original, token, kinds)
    section = document["image_host_chain"]
    adapter = {row["id"]: row for row in section["complete_source_owners"]}[section["roles"]["mw_3595_camera_adapter"]]
    adapter_node = host.verify_profiles_owner(audit, adapter)
    for name, signature in (("setAdaptiveMJPEGQuality", '["bool",["string","bool","long"]]'),
            ("setFixedMJPEGQuality", '["bool",["string","long"]]')):
        node, _ = audit.callable_member("camera_3595_mjpeg_" + name, adapter["original"], adapter_node, name)
        keep("adapter_" + name, adapter["original"], node)
        anchor("abi_" + name, adapter["original"], name[0].upper() + name[1:] + ":" + signature, {"pair"})
    return owners, {"product_id": 3595, "roles": roles, "reused_source_owners": reused, "source_sets": selections}


