def _camera_3595_mjpeg_packets(name, value, mode=0):
    """Static packet witnesses for the reviewed native low-byte assignments."""
    if type(value) is not int or type(mode) is not int:
        raise ValueError("3595 MJPEG packet witness requires native integer values")
    if name == "SetAdaptiveMJPEGQuality":
        return bytes((0xc0, 0x0e, 9, value & 255, 0, 0, mode & 255, 0))
    if name == "SetFixedMJPEGQuality":
        return bytes((0xc0, 0x0e, 11, value & 255, 0, 0, 0, 0))
    raise ValueError("3595 MJPEG packet witness has no selected command: " + name)


def _camera_3595_mjpeg_native_contract(native):
    roles = {0x5df30: "set_adaptive_export", 0x5e160: "set_fixed_export", 0x4e190: "base_adaptive_command",
        0x4e290: "base_fixed_command", 0x4edf0: "instance_isp_guard", 0x4e6b0: "base_topology_isp_exchange"}
    selected = native["complete_selected_functions"]
    if (not native["capture_complete"] or native["target_execution"] or len(selected) != len(roles)
            or {int(row["capture"]["rva"], 0): row["role"] for row in selected} != roles
            or any(row["failures"] or not row["input_chunks_verified"] or not row["assembly_captured"]
                or not row["pseudocode_captured"] for row in selected)):
        raise ValueError("3595 MJPEG complete native selection changed")
    rows = [[row["capture"]["rva"], row["role"], "\n".join(line["text"] for line in row["capture"]["pseudocode"]["lines"]),
        [(line["rva"], line["text"], line["bytes"]) for line in row["capture"]["assembly"]]] for row in selected]
    reviewed = hashlib.sha256(json.dumps(sorted(rows, key=lambda row: int(row[0], 0)),
        ensure_ascii=False, separators=(",", ":")).encode()).hexdigest()
    if reviewed != "71289c87fe538253194b36db973033860552abf7e192ab8e47fa90d1580a29bc":
        raise ValueError("3595 MJPEG complete native boundary changed: " + reviewed)
    slots = [(row["role"], row["vtable_rva"], row["slot_byte_offset"], row["target_rva"])
             for row in native["verified_indirect_slots"]]
    if (slots != [("adaptive_set", "0xb84b8", 256, "0x4e190"), ("fixed_set", "0xb84b8", 272, "0x4e290"),
            ("base_isp", "0xb84b8", 344, "0x4e6b0")]
            or not all(row["actual_pe_bytes_verified"] for row in native["verified_indirect_slots"])):
        raise ValueError("3595 MJPEG actual provider slots changed")
    return {"complete_native_fingerprint": reviewed, "native_pid": "0x0e0b", "vtable_rva": "0xb84b8",
        "SetAdaptiveMJPEGQuality": {"export_rva": "0x5df30", "slot_byte_offset": 256, "command_rva": "0x4e190",
            "request": [192, 14, 9, "enabled_u8", 0, 0, "mode_u8", 0]},
        "SetFixedMJPEGQuality": {"export_rva": "0x5e160", "slot_byte_offset": 272, "command_rva": "0x4e290",
            "request": [192, 14, 11, "quality_u8", 0, 0, 0, 0]},
        "values": "Exact-container lookup or false;current0E0B base slots consume low8 bits without range clamp. Command owns zeroed8-byte response,copies response[3] into a private output;export discards that output and returns command ACK bool. Extra decompiler logger register is not another business argument.",
        "transport": "Reuse HDR actual per-instance mutex,base-filter recovery/exact membership,slot344 IKs topology SET8 bytes then10ms GET8 bytes. SET failure still proceeds to GET;ACK requires GET HRESULT exactly0 and response[0]==0. Busy/preview/parameter/no-device codes log failure without generic retry. Each command locks separately;no cross-command atomicity or rollback.",
        "release": "Reuse captured node/topology COM Release+16 and instance unlock paths;current Host/adapter/device lifetime stays exact prior dependency. No per-call cancellation,whole-session drain or applied-setting getter is added.",
        "post_write_get": False, "flash_save": False, "rollback": False, "ack_is_consumed_by_mjpeg_runner": False}


def collect_camera_3595_mjpeg_chain(audit):
    document, upstream = _camera_3595_mjpeg_dependencies()
    owners, product = _camera_3595_mjpeg_sources(audit, document)
    source = _camera_3595_mjpeg_source_contract(owners)
    original = document["camera_3595_hdr_chain"]["native"]["input"]
    for manifest in document["image_properties"]["native_manifests"]:
        resource = manifest["resource"]
        if (resource["resourceVersion"] != "1.0.35.0" or resource["sha256"].lower() != original["sha256"]
                or resource["size"] != original["bytes"]):
            raise ValueError("3595 MJPEG native declaration changed")
        audit.read(manifest["installer"])
        audit.read(manifest["manifest"])
    slots = [{"role": role, "vtable_rva": 0xb84b8, "slot_byte_offset": offset, "target_rva": target}
        for role, offset, target in (("adaptive_set", 256, 0x4e190), ("fixed_set", 272, 0x4e290), ("base_isp", 344, 0x4e6b0))]
    native = audit.families.verify_native_functions(original,
        {0x5df30: "set_adaptive_export", 0x5e160: "set_fixed_export", 0x4e190: "base_adaptive_command",
         0x4e290: "base_fixed_command", 0x4edf0: "instance_isp_guard", 0x4e6b0: "base_topology_isp_exchange"},
        slots, exports={"SetAdaptiveMJPEGQuality": 0x5df30, "SetFixedMJPEGQuality": 0x5e160})
    native_contract = _camera_3595_mjpeg_native_contract(native)
    for row in native["complete_selected_functions"]:
        audit.artifact(a.ROOT / row["artifact"]["path"], row["artifact"])
        row["rva"] = row.pop("capture")["rva"]
    audit.read(original)
    audit.artifact(a.ROOT / native["capture_receipt"]["path"], native["capture_receipt"])
    return {"schema_version": 1, "kind": "current_camera_3595_mjpeg_chain", "query": "camera-3595-mjpeg-chain",
        **product, "control": "mjpegQuality", "semantics": source, "native": native, "native_contract": native_contract,
        "upstream_sections": upstream, "resumes_upstream_pointer": "/camera_3595_hdr_chain/remaining_local_chains/0",
        "reused_boundaries": "Exact3595 HDR/low-light/processing/media/Host observations own shared queue,storage,preview locks,device selection and lifecycle;only actual MJPEG autoQuality switch/current original-triple consumers are added",
        "selected_mjpeg_semantics_reviewed": True, "source_slice_complete": True,
        "source_chain_complete": False, "whole_page_complete": False, "whole_product_complete": False,
        "target_execution": False, "real_device_operations": False, "product_code_modified": False,
        "rust_implementation": "not_reviewed", "ui_backend_wiring": "unverified", "official_dll_comparison": "not_executed",
        "runtime_acceptance": "unverified", "new_native_captures": 0, "temporary_artifacts_created": [], "analysis_sessions_created": [],
        "remaining_local_chains": ["Other actual mounted Camera/Image actions and product/firmware branches remain at existing receipt boundaries;unused LDC or hidden MJPEG selectors do not authorize new controls.",
            "Independent Rust,UI/backend,pure/mock behavior and actual DLL/device input/output/state/error/cancel/restore/release comparison remain unverified"]}


def audit_camera_3595_mjpeg_chain(args):
    import host
    if (args.family != "accessories" or args.function != "main" or getattr(args, "prepare", False)
            or (args.product or [3595]) != [3595]):
        raise ValueError("camera-3595-mjpeg-chain requires PID3595 accessories main without production preparation")
    audit = host.HostLocalAudit()
    report = {"schema_version": 1, "query": "camera-3595-mjpeg-chain", "kind": "current_camera_3595_mjpeg_chain",
        "failures": [], "bounded_observation_complete": False, "source_chain_complete": False,
        "target_execution": False, "official_dll_comparison": "not_executed", "runtime_acceptance": "unverified"}
    try:
        for name in ("tools/families.py", "tools/host.py", "tools/frontend.py", "tools/evidence.py"):
            audit.artifact(a.ROOT / name)
        report.update(collect_camera_3595_mjpeg_chain(audit))
    except (OSError, ValueError, KeyError, IndexError, TypeError, StopIteration) as error:
        report["failures"].append(type(error).__name__ + ": " + str(error))
    changed = audit.final_snapshot() + host._otfm_macro_encoding_dependency_changes(report.get("upstream_sections", []))
    if changed:
        report["failures"].extend("3595 MJPEG input changed: " + name for name in changed)
    report.update(recorded_at_utc=a.stamp(), changed_during_query=changed, snapshot_stable=not changed,
        bounded_observation_complete=not report["failures"], selected_mjpeg_semantics_reviewed=not report["failures"],
        complete_originals=list(audit.sources.values()), complete_source_owners=list(audit.owners.values()),
        verified_artifacts=list(audit.artifacts.values()))
    destination = a.ROOT / ".analysis/results/frontend/accessories-camera-local-pages-audit.json"
    host.publish_host_static_query(report, destination, a, "camera_3595_mjpeg_chain")
    print(json.dumps({"receipt": a.rel(destination), "query": report["query"], "failures": report["failures"],
        "bounded_observation_complete": report["bounded_observation_complete"], "target_execution": False}), flush=True)
    if report["failures"]:
        raise ValueError("Current3595 MJPEG observation remains unresolved")
    return report


def _camera_3594_initial_get_sources(audit, document):
    import frontend
    import host
    roles, reused, layers, selections = {}, {}, {}, {}
    receipt = ".analysis/results/frontend/accessories-camera-local-pages-audit.json"
    replay = document["camera_3594_profile_replay_chain"]

    def borrow(section_name, names):
        section = document[section_name]
        owners = {row["id"]: row for row in section["complete_source_owners"]}
        for name in names:
            row = owners[section["roles"][name]]
            node = host.verify_profiles_owner(audit, row)
            roles[name] = audit.retain_range("camera_3594_initial_get_" + name, row["original"],
                node.start_byte, node.end_byte, node.type)
            reused[name] = {"receipt": receipt, "pointer": "/" + section_name + "/roles/" + name,
                **{key: row[key] for key in ("id", "original", "syntax", "byte_start", "byte_end", "body_sha256")}}

    def bound(role, source, name, at):
        value = audit.binding("camera_3594_initial_get_" + role, source, name, at)
        if value["resolution"] == "destructuring_requires_value_analysis":
            node = audit.tree(source).root_node.descendant_for_byte_range(value["start_byte"], value["end_byte"] - 1)
            while node is not None and (node.start_byte != value["start_byte"] or node.end_byte != value["end_byte"]):
                node = node.parent
            if node is None or node.text.decode() != value["body"]:
                raise ValueError("3594 initial GET destructuring owner differs: " + role)
        else:
            node = host._help_binding_node(audit, source, value)
        roles[role] = audit.retain_range("camera_3594_initial_get_" + role, source,
            node.start_byte, node.end_byte, node.type)
        return node

    def exported(role, side, module, name, namespace=None):
        value = audit.webpack_export("camera_3594_initial_get_" + role, layers[side], module, name, namespace=namespace)
        source = value["original"]
        node = host._help_binding_node(audit, source, value["binding"])
        roles[role] = audit.retain_range("camera_3594_initial_get_" + role, source,
            node.start_byte, node.end_byte, node.type)
        return source, node

    for side, stem in (("ui", "accessories-3594-current"), ("mw", "accessories-mw-3594-current")):
        current = frontend.current_source_selection(f"https://apps.razer.com/synapse/products/3594/{side}/", audit,
            candidates=sorted((a.ROOT / ".analysis/inputs/frontend").glob(stem + "*/acquisition.json")), verify_capture=False)
        if current["acquisition"] != replay["source_sets"][side]["acquisition"]:
            raise ValueError("3594 initial GET current source selection differs: " + side)
        layers[side] = current["originals"]
        selections[side] = {key: current[key] for key in ("name", "acquisition", "candidate_decisions",
            "capture_failures", "failed_acquisition", "unresolved_acquisition")}
    methods = ["getBrightness", "getContrast", "getSaturation", "getWhiteBalance",
        *[row[0] for row in _camera_3594_initial_get_specs()], "getAntiFlicker"]
    borrow("camera_3594_profile_replay_chain", ["adapter_init", "adapter_terminate", "adapter_handleBeforeUnload",
        *["adapter_" + name for name in methods], "advanced_cache_read", "advanced_cache_dispatch",
        "device_setup", "device_connect_current", "device_load_native", "connect_replay", "runtime_replay", "ui_reload_action"])
    borrow("camera_3594_exposure_chain", ["product_bootstrap", "host_call", "host_async_export", "ui_reducer",
        "ui_root_render", "ui_root_componentDidMount", "ui_root_componentWillUnmount"])
    borrow("image_host_chain", ["host_invoke", "host_async", "preload_async", "host_async_dispatch"])
    ui = replay["reviewed_inputs"]["ui"]
    cache = audit.owners[roles["advanced_cache_read"]]
    dispatch = audit.owners[roles["advanced_cache_dispatch"]]
    for role, source, name, at in [("mw_cache_import", dispatch["original"], "Z", dispatch["byte_start"] + 30),
            ("mw_result_import", dispatch["original"], "i", dispatch["byte_start"] + 30),
            ("mw_request_import", dispatch["original"], "U", dispatch["byte_start"] + 30),
            ("mw_dispatch_runtime_import", dispatch["original"], "m", dispatch["byte_start"] + 30),
            ("mw_read_runtime_import", cache["original"], "f", cache["byte_start"] + 30),
            ("mw_device_import", cache["original"], "o", cache["byte_start"] + 30),
            ("mw_host_import", audit.owners[roles["host_call"]]["original"], "r", audit.owners[roles["host_call"]]["byte_start"] + 30),
            ("mw_electron_bridge", audit.owners[roles["host_async_export"]]["original"], "r", audit.owners[roles["host_async_export"]]["byte_start"] + 10),
            ("ui_result_import", ui, "j", 5215698), ("ui_initial_state", ui, "Zo", 5215698),
            ("ui_cache_consumer", ui, "pm", 5751232), ("ui_field_actions_import", ui, "qI", 5751232)]:
        bound(role, source, name, at)
    for role, side, module, name in [("mw_cache_export", "mw", 87887, "db"),
            ("mw_async_export", "mw", 88382, "oE"), ("mw_result_constant", "mw", 67061, "YQJ"),
            ("mw_request_namespace", "mw", 78624, "YM"), ("mw_request_group", "mw", 26219, "Lu"),
            ("mw_runtime_owner", "mw", 94417, "A"), ("ui_result_constant", "ui", 3254, "YQJ"),
            ("ui_reload_export", "ui", 5305, "E0")]:
        exported(role, side, module, name)
    exported("mw_request_constant", "mw", 26219, "Cy", "o")
    for left, right in (("mw_cache_export", "advanced_cache_read"), ("mw_async_export", "host_async_export"),
            ("ui_reload_export", "ui_reload_action")):
        if roles[left] != roles[right]:
            raise ValueError("3594 initial GET imported/exported owner differs: " + left)
    return {"roles": roles, "source_sets": selections, "reviewed_inputs": replay["reviewed_inputs"],
        "adapter_methods": methods, "reused_source_owners": reused}


def _camera_3594_initial_get_native_contract(native, raw):
    import host
    functions = {row["capture"]["rva"]: row["capture"] for row in native["complete_functions"]}
    specs = _camera_3594_initial_get_specs()
    if set(functions) != {"0x4c310", "0x4b980", *[hex(row[2]) for row in specs]}:
        raise ValueError("3594 initial GET native selected boundary differs")
    reviewed = _camera_3594_profile_replay_digest({rva: {"pseudocode": row["pseudocode"],
        "assembly": [(line["rva"], line["bytes"]) for line in row["assembly"]]} for rva, row in functions.items()})
    if reviewed != _CAMERA_3594_INITIAL_GET_NATIVE_REVIEWED:
        raise ValueError("3594 initial GET complete native owners need renewed semantic review")
    pe = host.inspect_pe(raw)
    if pe["architecture"] != "x64" or pe["image_base"] != "0x180000000":
        raise ValueError("3594 initial GET native architecture/base differs")

    def data(rva, length):
        section = next((row for row in pe["sections"] if row["rva"] <= rva
            and rva + length <= row["rva"] + row["bytes"]), None)
        if section is None or length <= 0:
            raise ValueError("3594 initial GET native span is outside actual PE bytes")
        offset = section["file_offset"] + rva - section["rva"]
        return raw[offset:offset + length]

    instruction_count, exports, required = 0, [], []
    for function in functions.values():
        for line in function["assembly"]:
            encoded = bytes.fromhex(line["bytes"])
            if not encoded or data(int(line["rva"], 16), len(encoded)) != encoded:
                raise ValueError("3594 initial GET native instruction differs from actual PE bytes")
            instruction_count += 1
    for method, name, rva, ordinal, prop in specs:
        rows = [row for row in pe["exports"] if name in row["names"]]
        if len(rows) != 1 or rows[0]["rva"] != hex(rva) or rows[0]["ordinal"] != ordinal or rows[0].get("forwarder"):
            raise ValueError("3594 initial GET actual native export differs: " + name)
        exports.append({"method": method, "name": name, "rva": hex(rva), "ordinal": ordinal, "property_id": prop})
        required.extend((hex(rva), target) for target in ("0x3bb80", "0x4c310", "0x7ec40", "0x7ebc0", "0xbb00"))
    required.extend(("0x4c310", target) for target in ("0x4af80", "0x4b980", "0x69f94", "0x69f9c"))
    required.append(("0x4b980", "0x41ba0"))
    image_base = int(pe["image_base"], 16)
    edges = {(hex(int(row["from"], 16) - image_base), hex(int(row["function"], 16) - image_base))
        for row in native["direct_edges"] if row["function"]}
    if set(required) - edges:
        raise ValueError("3594 initial GET native lookup/property/result edge is absent")
    guid = "7033e1c6ac30d011a18c00a0c9118956"
    if data(0xa93e8, 16).hex() != guid:
        raise ValueError("3594 initial GET IAMCameraControl GUID differs")
    com = []
    for role, rva, encoded, offset in (("QueryInterface", 0x4ba2d, "ff10", 0),
            ("Get", 0x4ba63, "ff5028", 40), ("Release", 0x4bb27, "ff5010", 16)):
        row = next((row for row in functions["0x4b980"]["assembly"] if row["rva"] == hex(rva)), None)
        if row is None or row["bytes"] != encoded or data(rva, len(bytes.fromhex(encoded))).hex() != encoded:
            raise ValueError("3594 initial GET actual COM slot differs: " + role)
        com.append({"role": role, "instruction_rva": hex(rva), "slot_byte_offset": offset, "raw_hex": encoded})
    return {"reviewed_selection_sha256": reviewed, "verified_instruction_count": instruction_count,
        "exports": exports, "interface": {"name": "IAMCameraControl", "guid_rva": "0xa93e8", "guid_hex": guid,
            "actual_com_calls": com},
        "required_direct_edges": [{"caller_rva": caller, "target_rva": target} for caller, target in required],
        "get": {"property_ids": {row[1]: row[4] for row in specs},
            "query_interface_success": "signed HRESULT>=0; no independent nonnull output check before Get",
            "out_parameters": "Windows LONG value and flags initialized0 before Get; failure may leave initial or partially overwritten values",
            "get_failure_still_serializes": True, "success_status_in_json": False,
            "value": "JSON tag5 signed integer,sign-extended Windows LONG; no range query,clamping or scaling",
            "isAuto": "JSON tag4 boolean,true only when flags==1,not when any auto bit is set",
            "query_interface_failure": "empty string when filter exists but QI fails",
            "missing_instance_or_filter": "{}; filter absent triggers shared reconnect once before deciding",
            "retry_after_failed_get": False, "write_or_restore": False},
        "result_allocation_reference": {"pointer": "/image_native/native_contract/result_allocation",
            "required_free_export": {"name": "FreeMalloc", "ordinal": 8, "rva": "0x576b0"},
            "scope": "Same strlen+1 allocation/copy/temporary-string destruction and actual FreeMalloc chain; shared JSON dump is /image_native/native_contract/json_result"},
        "ownership": "Exact-container lookup returns a bare instance.4C310 locks instance+136,reconnects missing filter,performs Get then normally unlocks. Successful QI releases nonnull interface at+16 after successful or failed Get; QI failure skips release. No native abort,generation check,whole-session I/O/callback drain or blanket exception cleanup is proved",
        "target_execution": False, "official_dll_comparison": "not_executed"}


