def collect_camera_3594_profile_replay_chain(audit):
    """Review current PID3594 reset and all actual replay fields without executing the target."""
    document, upstream, reused = _camera_3594_profile_replay_dependencies(audit)
    result = _camera_3594_profile_replay_sources(audit, document)
    result["semantics"] = _camera_3594_profile_replay_contract({role: audit.owners[key] for role, key in result["roles"].items()})
    for key, collect in (("reset_native", collect_camera_3594_profile_reset_native_chain),
            ("controls_native", collect_camera_3594_profile_controls_native_chain),
            ("image_native", collect_camera_3594_profile_image_native_chain),
            ("view_native", collect_camera_3594_profile_view_native_chain)):
        result[key] = collect(audit, document)
        upstream.extend(result[key]["upstream_sections"])
    expected = {"RestoreDefaults", *[re.search(r'action:"([\w$]+)"', audit.owners[result["roles"]["adapter_" + name]]["body"])[1]
        for name in result["adapter_methods"] if name.startswith("set")]}
    observed = {"SetEVCompensation", result["reset_native"]["native_contract"]["export"]["name"]}
    for key in ("controls_native", "image_native", "view_native"):
        observed.update(row["name"] for row in result[key]["native_contract"]["exports"])
    if expected != observed:
        raise ValueError("3594 profile replay actual setter/native coverage differs: "
            + json.dumps({"missing": sorted(expected - observed), "unexpected": sorted(observed - expected)}))
    instance = result["controls_native"]["native_contract"]["instance_selection"]
    if instance.get("product_id") != 3594 or instance.get("vtable_rva") != "0xb9690":
        raise ValueError("3594 profile replay exact native instance selection differs")
    reference = result["view_native"]["native_contract"].get("intra_report_reference")
    if (not isinstance(reference, dict) or reference.get("pointer") != "/controls_native/native_contract/instance_selection"
            or reference.get("required_fields") != {key: instance.get(key)
                for key in ("initializer_rva", "product_id", "vtable_rva")}):
        raise ValueError("3594 profile replay view native instance reference differs")
    upstream = list({(row["receipt"], row["pointer"]): row for row in upstream}.values())
    result.update(schema_version=1, kind="current_camera_3594_profile_replay_chain", product_id=3594,
        failures=[], upstream_sections=upstream, reused_source_owners=reused,
        native_setter_exports=sorted(observed), selected_reset_replay_semantics_reviewed=True,
        source_slice_complete=True, source_chain_complete=False, whole_page_complete=False, whole_product_complete=False,
        target_execution=False, real_device_operations=False, rust_implementation="not_reviewed", ui_backend_wiring="unverified",
        official_dll_comparison="not_executed", runtime_acceptance="unverified", new_native_captures=0, temporary_artifacts_created=[],
        remaining_local_chains=[
            "Reset and every actual current MW default camera/image/imageMode full/diff replay field are statically reviewed; native advanced-camera cache GET construction/response consumers and whole native device lifetime,callback/I/O drain and release remain unresolved independently.",
            "Current acquisition failures and unacquired host/device dependencies,other Camera/Processing/Image/Help interactions,products/firmware/transports remain retained; PID3594 mounts no MIC page. No unrelated adjacent feature is inferred.",
            "Independent Rust,production/UI/backend migration,pure/mock product behavior,actual official DLL/device input/output/state/error/cancel/restore/release comparison and window acceptance remain unverified."])
    return result


def audit_camera_3594_profile_replay_chain(args):
    import host
    if (args.family != "accessories" or args.function != "main" or getattr(args, "prepare", False)
            or sorted(set(args.product or [3594])) != [3594]):
        raise ValueError("camera-3594-profile-replay-chain requires PID3594 accessories main without production preparation")
    audit = host.HostLocalAudit()
    report = {"schema_version": 1, "recorded_at_utc": a.stamp(), "parser": audit.parser_versions,
        "kind": "current_camera_3594_profile_replay_chain", "product_id": 3594, "failures": [],
        "bounded_observation_complete": False, "source_chain_complete": False, "whole_product_complete": False,
        "target_execution": False, "official_dll_comparison": "not_executed", "runtime_acceptance": "unverified"}
    try:
        for name in ("tools/families.py", "tools/host.py", "tools/frontend.py", "tools/evidence.py"):
            audit.artifact(a.ROOT / name)
        report.update(collect_camera_3594_profile_replay_chain(audit))
        report["bounded_observation_complete"] = not report["failures"]
    except (OSError, ValueError, KeyError, IndexError, TypeError, StopIteration) as error:
        report["failures"].append(type(error).__name__ + ": " + str(error))
    changed = audit.final_snapshot()
    changed.extend(_camera_3594_profile_replay_upstream_changes(report.get("upstream_sections", [])))
    if changed:
        report["failures"].extend("3594 profile replay source changed during query: " + name for name in changed)
        report["bounded_observation_complete"] = False
    report.update(changed_during_query=changed, snapshot_stable=not changed, complete_originals=list(audit.sources.values()),
        complete_source_owners=list(audit.owners.values()), verified_artifacts=list(audit.artifacts.values()))
    destination = a.ROOT / ".analysis/results/frontend/accessories-camera-local-pages-audit.json"
    host.publish_host_static_query(report, destination, a, "camera_3594_profile_replay_chain")
    print(json.dumps({"receipt": a.rel(destination), "query": "camera-3594-profile-replay-chain", "failures": report["failures"],
        "bounded_observation_complete": report["bounded_observation_complete"], "target_execution": False}), flush=True)
    if report["failures"]:
        raise ValueError("Current3594 reset/profile replay observation remains unresolved")
    return report


