    if name == "SetFDAFMode":
        return bytes([192, 10, 1, byte, 0, 0, 0, other])
    if name == "SetWatermark":
        return bytes([192, 8, 1, byte, other, 0, 0, 0])
    if name == "SetDynamicNoiseReduction":
        return bytes([160, 6, other, 0, 0, 0, 0, 0])
    raise ValueError("3594 controls setter is not an ISP packet: " + str(name))


