def _camera_ultra_watermark_host_dependency(audit=None):
    import host
    receipt = ".analysis/results/frontend/accessories-camera-local-pages-audit.json"
    previous = json.loads((a.ROOT / receipt).read_bytes())
    shared = previous["image_host_chain"]
    value = shared["source_contract"]
    digest = hashlib.sha256(json.dumps(value, ensure_ascii=False, sort_keys=True, separators=(",", ":")).encode()).hexdigest()
    if (digest != _CAMERA_ULTRA_WATERMARK_HOST_REVIEWED or shared["failures"]
            or not shared["bounded_observation_complete"] or not shared["snapshot_stable"]):
        raise ValueError("Ultra watermark shared Host source contract changed")
    if audit is not None:
        indexed = json.loads(audit.artifact(a.ROOT / ".analysis/inputs.json"))
        release = host.verified_host_release_receipt(index=indexed)
        if release["receipt"] != shared["host_release"]["acquisition"]:
            raise ValueError("Ultra watermark current shared Host release changed")
        audit.artifact(a.ROOT / release["receipt"]["path"], release["receipt"])
        for row in release["verified_dependencies"]:
            audit.artifact(a.ROOT / row["path"], row)
        available = {row["path"]: row for row in host.current_host_asar_members(audit, indexed, release)}
        for member in shared["host_release"]["members"]:
            source, archive = member["member"], member["archive"]
            body, parent = audit.read(source), audit.read(archive)
            if available.get(source["path"]) != source or parent[source["offset"]:source["offset"] + len(body)] != body:
                raise ValueError("Ultra watermark current shared Host member differs")
            package = member["official_package"]
            audit.artifact(a.ROOT / package["path"], package)
        owners = {row["id"]: row for row in shared["complete_source_owners"]}
        for role, key in shared["roles"].items():
            if role.startswith(("host_", "preload_")) or role == "disposed_webcontents":
                owner = owners[key]
                node = host.verify_profiles_owner(audit, owner)
                audit.retain_range("camera_ultra_watermark_shared_" + role, owner["original"], node.start_byte, node.end_byte, node.type)
    return {"receipt": receipt, "pointer": "/image_host_chain/source_contract", "canonical_sha256": digest,
        "scope": "Reuse the reviewed current main-process camera Host channel/mutex/invocation/pointer-copy/FreeMalloc and release limitations; no other camera product semantics are inferred"}


