def audit_mouse_power_190_consumers(args):
    import host
    if (args.family != "mouse" or args.function != "mw" or getattr(args, "prepare", False)
            or sorted(set(args.product or [190])) != [190]):
        raise ValueError("mouse-power-190-consumers requires only current mouse190 middleware without preparation")
    audit = host.HostLocalAudit()
    report = {"schema_version": 1, "kind": "current_mouse_power_190_consumers", "product_id": 190,
        "query": "mouse-power-190-consumers", "recorded_at_utc": a.stamp(), "parser": audit.parser_versions,
        "failures": [], "bounded_observation_complete": False, "source_chain_complete": False, "target_execution": False,
        "official_dll_comparison": "unverified", "runtime_acceptance": "unverified"}
    try:
        for name in ("tools/families.py", "tools/host.py", "tools/frontend.py", "tools/evidence.py"):
            audit.artifact(a.ROOT / name)
        report.update(collect_mouse_power_190_consumers(audit))
        report["bounded_observation_complete"] = not report["failures"]
    except (OSError, ValueError, KeyError, IndexError, TypeError, StopIteration) as error:
        report["failures"].append(str(error))
    changed = audit.final_snapshot()
    if changed:
        report["failures"].extend("Mouse 190 power input changed during query: " + name for name in changed)
        report["bounded_observation_complete"] = False
    report.update(tool=identity(Path(__file__)), changed_during_query=changed, snapshot_stable=not changed,
        complete_originals=list(audit.sources.values()), complete_source_owners=list(audit.owners.values()),
        verified_artifacts=list(audit.artifacts.values()))
    destination = a.ROOT / ".analysis/results/frontend/mouse-mw-audit.json"
    host.publish_host_static_query(report, destination, a, "mouse_power_190_consumers")
    print(json.dumps({"receipt": a.rel(destination), "query": "mouse_power_190_consumers",
        "complete_ast_owners": len(audit.owners), "failures": report["failures"],
        "runtime_acceptance": "unverified"}), flush=True)
    if report["failures"]:
        raise ValueError("Current mouse 190 power source observation remains unresolved")
    return report


