def _mouse_power_196_consumers_digest(value):
    return hashlib.sha256(json.dumps(value, ensure_ascii=False, sort_keys=True,
        separators=(",", ":")).encode("utf-8")).hexdigest()


def _mouse_power_196_consumers_dependency_changes(dependencies):
    """Recheck only consumed sections when another query publishes the same file."""
    import frontend
    changes, documents = [], {}
    for dependency in dependencies:
        name, pointer = dependency["receipt"], dependency["pointer"]
        try:
            if name not in documents:
                documents[name] = json.loads((a.ROOT / name).read_bytes(),
                    object_pairs_hook=frontend._strict_receipt_pairs)
            value = documents[name]
            for field in pointer.strip("/").split("/"):
                field = field.replace("~1", "/").replace("~0", "~")
                value = value[int(field)] if isinstance(value, list) else value[field]
            if _mouse_power_196_consumers_digest(value) != dependency["canonical_sha256"]:
                changes.append(name + "#" + pointer + ": consumed section changed")
        except (OSError, ValueError, KeyError, IndexError, TypeError) as error:
            changes.append(name + "#" + pointer + ": " + str(error))
    return changes


def _mouse_power_196_consumers_dependencies():
    import frontend
    name = ".analysis/results/frontend/mouse-mw-audit.json"
    document = json.loads((a.ROOT / name).read_bytes(), object_pairs_hook=frontend._strict_receipt_pairs)
    dependencies = [{"receipt": name, "pointer": pointer, "canonical_sha256": digest}
        for pointer, digest in _mouse_power_196_consumers_upstream.items()]
    for dependency in dependencies:
        value = document
        for field in dependency["pointer"].strip("/").split("/"):
            value = value[int(field)] if isinstance(value, list) else value[field]
        if _mouse_power_196_consumers_digest(value) != dependency["canonical_sha256"]:
            raise ValueError("Mouse 196 power upstream section requires review: " + dependency["pointer"])
    previous = document["mouse_power_190_consumers"]
    if (document["queries"]["mouse-receiver-polling"]["power_task_memory_batch"]["products"][58]
            ["endpoint_product_id"] != 196 or previous.get("failures")
            or previous.get("selected_consumer_semantics_reviewed") is not True):
        raise ValueError("Mouse 196 power upstream selection is incomplete")
    return dependencies, previous


def _mouse_power_196_consumers_sources(audit):
    import frontend
    root = a.ROOT / ".analysis/inputs/frontend"
    selections = {layer: frontend.current_source_selection(
        f"https://apps.razer.com/synapse/products/196/{layer}/", audit,
        candidates=sorted(root.glob(prefix + "*/acquisition.json")))
        for layer, prefix in (("ui", "mouse-196-"), ("mw", "mouse-mw-196-"))}
    def single(rows, role):
        if len(rows) != 1:
            raise ValueError("Mouse 196 power current source absent or ambiguous: " + role)
        return rows[0]
    ui = single([row for row in selections["ui"]["originals"]
        if re.search(r"/196/ui/static/js/main\.[^/]+\.js$", row["path"])], "ui")
    main = single([row for row in selections["mw"]["originals"]
        if re.search(r"/196/mw/main\.[^/]+\.js$", row["path"])], "mw_main")
    shared = single([row for row in selections["mw"]["originals"] if row["path"].endswith(".js")
        and b'actionType:"taskMakerSetPowerSavingValue"' in audit.read(row)], "mw_power")
    roles, nodes = {}, {}
    def retain(role, source, anchor, kinds):
        keys = audit.retain(role, source, anchor, kinds)
        if len(keys) != 1:
            raise ValueError("Mouse 196 power owner is ambiguous: " + role)
        key = keys[0]
        owner = audit.owners[key]
        node = audit.tree(source).root_node.descendant_for_byte_range(owner["byte_start"], owner["byte_end"] - 1)
        if (node.start_byte, node.end_byte, node.type) != (
                owner["byte_start"], owner["byte_end"], owner["syntax"]):
            raise ValueError("Mouse 196 power owner is not a complete AST boundary: " + role)
        roles[role], nodes[role] = key, node
        return owner
    def binding(role, source, name, owner, anchor=None):
        reference = owner["byte_start"] + owner["body"].index(anchor or name)
        if anchor is not None:
            reference += anchor.rindex(name)
        row = audit.binding(role, source, name, reference)
        if row["resolution"] != "declaration":
            raise ValueError("Mouse 196 power lexical dependency is unresolved: " + role)
        roles[role] = row["owner_id"]
        return audit.owners[row["owner_id"]]
    for role, anchor, kinds in (
            ("ui_card", "this.changePowerSaving=", {"class_declaration"}),
            ("ui_connected_props", "powerSavingValue:e.mousePowerSavingReducer.powerSavingValue", {"variable_declarator"}),
            ("ui_action_export", "setPowerSaving:()=>yS", {"call_expression"}),
            ("ui_action", 'console.log("setPowerSaving",e)', {"variable_declarator"}),
            ("ui_default", "powerSavingValue:5,actionsFromUI", {"variable_declarator"}),
            ("ui_reducer", '$e(E,e,"mousePowerSavingReducer")', {"variable_declarator"}),
            ("ui_power_page", "(wS,{})", {"class_declaration"}),
            ("ui_power_alias", "jS=XS", {"variable_declarator"}),
            ("ui_product_navigation", "(jS,{", {"class_declaration"}),
            ("ui_setup", "class Lm extends", {"class_declaration"}),
            ("ui_response_wrapper", "this.initUIBroadcastChannelHandler=", {"class_declaration"})):
        retain(role, ui, anchor, kinds)
    reducer = audit.owners[roles["ui_reducer"]]
    for name, role in (("Se", "ui_append_action"), ("le", "ui_local_receipt"), ("Re", "ui_device_receipt"),
            ("Ne", "ui_completed_receipt"), ("de", "ui_external_action"), ("ue", "ui_external_receipt"),
            ("Ce", "ui_external_completed")):
        binding(role, ui, name, reducer, name + "(")
    event = binding("ui_event", ui, "ce", reducer, "new ce")
    binding("ui_event_tick", ui, "De", event, "new De")
    setup = audit.owners[roles["ui_setup"]]
    binding("ui_navigation_connection", ui, "Dm", setup, "(Dm,")
    wrapper = audit.owners[roles["ui_response_wrapper"]]
    binding("ui_setup_connection", ui, "Pm", wrapper, "(Pm,")
    for name, role in (("H_", "ui_bridge_send"), ("g_", "ui_bridge_channel"),
            ("iT", "ui_bridge_initialize"), ("nT", "ui_bridge_subscribe")):
        binding(role, ui, name, wrapper, name + "(")
    initializer = audit.owners[roles["ui_bridge_initialize"]]
    binding("ui_bridge_receive", ui, "tT", initializer, "onmessage=tT")
    binding("ui_bridge_unload", ui, "_T", initializer, '"beforeunload",_T')
    bootstrap = retain("mw_bootstrap", main, 'injectData("initMemoryStorageCache"', {"arrow_function"})
    binding("mw_injected_initializer", main, "a", bootstrap, '"initMemoryStorageCache",a')
    runtime = audit.webpack_export("mw_product_runtime", [main], 11579, "Z")
    roles["mw_product_runtime"] = runtime["binding"]["owner_id"]
    device_info = audit.webpack_export("mw_product_definition", selections["mw"]["originals"], 4638, "DeviceInfo")
    roles["mw_product_definition"] = device_info["binding"]["owner_id"]
    feature_getter = audit.webpack_export("mw_feature_selection", [main], 88443, "N$")
    roles["mw_feature_selection"] = feature_getter["binding"]["owner_id"]
    return selections, [ui, main, shared], roles, retain


