    if (report.get("query") != "mouse-power-196-consumers" or report.get("product_id") != 196
            or report.get("boundaries") != _mouse_power_196_consumers_contract()
            or report.get("failures") or report.get("source_snapshot_changed")
            or report.get("snapshot_stable") is not True
            or report.get("selected_consumer_semantics_reviewed") is not True
            or any(report.get(key) is not False for key in ("target_execution", "product_code_modified",
                "real_device_operations", "source_chain_complete", "whole_page_complete"))
            or any(report.get(key) != "unverified" for key in ("rust_implementation_acceptance",
                "ui_backend_wiring", "official_dll_comparison", "runtime_acceptance"))):
        raise ValueError("Mouse 196 power static scope was changed or promoted")
    audit, seen = host.HostLocalAudit(), set()
    for owner in report["complete_source_owners"]:
        raw = audit.read(owner["original"])
        start, end = owner["byte_start"], owner["byte_end"]
        if (owner["id"] in seen or not 0 <= start < end <= len(raw)
                or owner["id"] != owner["original"]["sha256"] + ":" + str(start) + ":" + str(end)
                or owner["body"] != raw[start:end].decode("utf-8")
                or owner["body_sha256"] != hashlib.sha256(raw[start:end]).hexdigest()):
            raise ValueError("Mouse 196 power complete owner bytes differ")
        node = audit.tree(owner["original"]).root_node.descendant_for_byte_range(start, end - 1)
        if (node.start_byte, node.end_byte, node.type) != (start, end, owner["syntax"]):
            raise ValueError("Mouse 196 power complete owner AST boundary differs")
        seen.add(owner["id"])
    if not set(report["roles"].values()).issubset(seen):
        raise ValueError("Mouse 196 power role lost its complete owner")
    digest = _mouse_power_196_consumers_digest(_mouse_power_196_consumers_projection(report))
    if digest != _mouse_power_196_consumers_reviewed or report.get("reviewed_selection_sha256") != digest:
        raise ValueError("Mouse 196 power selected bytes require semantic review: " + digest)
    changes = _mouse_power_196_consumers_dependency_changes(report["upstream_sections"])
    if changes:
        raise ValueError("Mouse 196 power upstream changed: " + "; ".join(changes))
    return {"complete_ast_owners": len(seen), "reused_shared_owners": len(report["shared_owner_reuse"]),
        "reviewed_selection_sha256": digest, "whole_page_complete": False,
        "official_dll_comparison": "unverified"}


