        caller = retain("6259.js", "logical_device_factory_getter_and_setter", "Ne=(e=1)", 87887)
        branch = retain("6259.js", "high_speed_selector_Ze_export_g2", "hyperPollingMaster", 96183)
        pairing = retain("6259.js", "pairing_lookup_QC_and_logical_dongle_restore_FR", "hyperPollingMaster", 66825)
