def mouse_receiver_indicator_source_review(row):
    """Retain current implementation evidence beside complete source owners.

    Code markers locate implemented branches; they are not behavioral proofs,
    whole-page completion, compilation, or device/window acceptance.
    """
    names = ["crates/razer-pages/src/features/mouse/customize/mouse_receiver_indicator.rs",
             "crates/razer-pages/src/features/mouse/customize/mouse_receiver_indicator_state.rs",
             "crates/razer-pages/src/data/mouse_receiver_indicator_data.rs",
             "crates/razer-pages/src/features/mouse/mod.rs",
             "crates/razer-pages/src/features/mouse/polling/mouse_polling_view.rs",
             "crates/razer-widgets/src/theme.rs",
             "crates/razer-widgets/src/synapse_select.rs",
             "crates/razer-widgets/src/synapse_select_pointer.rs",
             "crates/razer-pages/src/features/workspace/source_workspace/mouse_receiver_indicator.rs",
             "crates/razer-pages/src/features/workspace/product_workspace_receiver_indicator.rs",
             "crates/razer-shell/src/shell/mouse/mouse_receiver_indicator.rs",
             "crates/razer-discovery/src/direct/mouse_indicator_led.rs",
             "crates/razer-storage/src/receiver/receiver_indicator.rs",
             "crates/razer-pages/src/features/mouse/polling/mouse_polling.rs",
             "crates/razer-device/src/mouse/mouse_indicator_led.rs"]
    current = []
    for name in names:
        path = a.ROOT / name
        if path.is_file():
            body = path.read_bytes()
            current.append({"path": name, "bytes": len(body), "sha256": hashlib.sha256(body).hexdigest(),
                            "complete_body": body.decode("utf-8")})
    rust = {item["path"]: item["complete_body"] for item in current}
    roles = {item["role"]: item for item in row["complete_regions"]}
    checks = []

    def implementation(key, source_roles, source_fact, rust_fact, locations):
        located = []
        for name, markers in locations:
            text = rust.get(name, "")
            located.append({"path": name, "markers": [
                {"text": marker, "present": marker in text,
                 "line": text.count("\n", 0, text.index(marker)) + 1 if marker in text else None}
                for marker in markers]})
        present = all(marker["present"] for owner in located for marker in owner["markers"])
        checks.append({"id": key, "status": "implementation_present" if present else "implementation_requires_review",
            "source_fact": source_fact, "current_rust_fact": rust_fact,
            "complete_source_owners": [{"role": role, "original": roles[role]["original"],
                "byte_start": roles[role]["byte_start"], "byte_end": roles[role]["byte_end"],
                "body_sha256": roles[role]["body_sha256"]} for role in source_roles],
            "rust_locations": located, "behavior_verified_by_markers": False,
            "product_code_modified_by_review": False})

    implementation("hover_preview_key", ["receiver_guide_hover_preview", "receiver_guide_hover_scale"],
        "The mounted preview stores a string key, starts at none, retains that key when activeTab changes and looks it up in the new mode table.",
        "The retained preview is a string; tab changes retain it and preview_colors selects the new table by key.",
        [(names[0], ['preview: &\'static str', 'guide_tab = index']),
         (names[1], ['pub(super) fn preview_colors', 'key.parse::<u32>()'])])
    implementation("hover_scale_geometry", ["receiver_guide_hover_scale"],
        "SVG height 37; width 405 or 442; interval 97 for four values and 77 otherwise; start x 28.5/48.5/57; line and circles at y=5, centered Roboto labels at y=30. Russian connection labels use 13px, other labels 14px. Only circles carry hover handlers.",
        "Canvas paints source geometry and shaped text; GuideScale shares exact circle geometry with pointer hit testing.",
        [(names[0], ['fn receiver_guide_scale', 'family: "Roboto".into()', 'line.width / 2.']),
         (names[1], ['pub(super) struct GuideScale', '28.5', '48.5', '97.', '77.', '<= 25.'])])
    implementation("help_gradient_sections", ["receiver_help_sections", "receiver_help_gradient"],
        "The first two carousel pages use a 4x85px gradient bar and plain labels spaced vertically. The last two use colored 3px list dots.",
        "The first two sections use the source three-stop gradient; the last two retain the separate colored-dot list.",
        [(names[0], ['if self.section < 2', 'img(help_gradient())', 'offset=".325"', 'offset=".985"'])])
    implementation("help_next_artwork", ["receiver_help_next_svg_complete", "receiver_help_carousel"],
        "Next uses the retained complete 20x20 SVG path filled #CCCCCC.",
        "The source path is retained in the SVG asset used by the carousel's pointer-only Next command.",
        [(names[0], ['img(help_next_icon())', 'M6 17.2889L6.62222 18L14 10.3556'])])
    implementation("dpi_active_row_fallback", ["receiver_live_image_and_color_selectors"],
        "The source increments visible-stage count until the one-based active row is encountered; an absent active row returns #FF0000. An existing active row with zero visible stages yields the missing table entry.",
        "active_dpi_color preserves missing-row red separately from an existing invisible row's absent table color.",
        [(names[1], ['pub(super) fn active_dpi_color', 'Some(0xff0000)', 'return dpi_color(visible)'])])
    implementation("battery_observation", ["receiver_live_image_and_color_selectors", "receiver_source_defaults"],
        "The live image selects batteryReducer.batteryValue, independently of quality, polling and configuration.",
        "The source battery observation is delivered through retained shell, Product/Source and Mouse owners; setup and event publication gates are separate. Runtime/native closure is reviewed by receiver_indicator_runtime.",
        [(names[0], ['self.receiver_indicator.battery = battery']),
         (names[8], ['receiver_monitor_matches(monitor, cx)', 'body.observe_receiver_battery']),
         (names[10], ['read_battery_state_in_session', 'Update::Battery', 'BatteryRead::Setup'])])
    implementation("polling_ui_value", ["receiver_live_image_and_color_selectors"],
        "Ya selects pollingRate.pollingRateWireless; a getter diagnostic does not replace that reducer field.",
        "The LED image uses the local pollingRateWireless UI draft, independently of polling readback diagnostics.",
        [(names[0], ['let rate = self.draft["pollingRateWireless"]'])])
    implementation("help_position_and_hover_bridge", ["receiver_indicator_widget"],
        "The mounted child is help.indicator-led > tip. Its current CSS sets left:36%, top:19px and a 10px pseudo-element bridge; the full CSS is retained separately.",
        "A retained Help owner preserves icon/bridge/tip hover and the source offset, colors and carousel state.",
        [(names[0], ['struct Help', '"mouse-receiver-help-bridge"', '.left(relative(0.36))', '.top(surface::css(19.))'])])
    implementation("modal_keyboard_and_mount", ["receiver_guide_modal", "receiver_mounted_customize_owner"],
        "CO mounts Ja only for dongle and non-macro display; ja has native buttons and a click propagation boundary, without autofocus, focus trap/restore or Escape/backdrop dismissal.",
        "Guide uses semantic popup/backdrop parts without Kit Dialog's unconditional focus trap. Unmount clears local guide/carousel state while the MW event/battery owner survives a profile change.",
        [(names[0], ['sync_receiver_widget_mount', '.role(Role::Dialog)', 'DialogPopup::new()']),
         (names[13], ['pub fn same_device_connection', 'connection_epoch'])])
    implementation("dropdown_pointer_behavior", ["receiver_indicator_widget"],
        "Ja uses current dropdown7734/option7278: clickable divs, no tabIndex/key handlers, window click/blur close, 27px trigger, 25px rows, max-height180 and original placement branch.",
        "The pointer presentation retains SelectState events and source geometry without adding selector keyboard activation or focus restoration; complete dependency modules are retained by this query independently of these implementation markers.",
        [(names[0], ['synapse_select::select_pointer']),
         (names[7], ['.focusable(false)', 'css(27.)', 'css(25.)', '180.', 'render_pointer'])])
    implementation("raw_configuration_and_selector_identity", ["receiver_indicator_widget", "receiver_live_image_and_color_selectors"],
        "Ja and Ya find the first strictly numeric LED index and fall back only for a nullish mode. Ja maps every existing matching index on click. Ya switches on the raw value without coercion; dropdown7734 separately uses dataSet[value] for its title and strict equality for selected rows.",
        "The source array retains ordering, duplicate indices, unknown values and metadata. Existing numeric matches alone are edited. Selector labels and strict row selection are separate, including a string mode's label without a checked row; unknown values do not become default colors.",
        [(names[0], ['configuration: Value', 'source::with_mode', 'source::selector_label', '.selected_text(t(label))']),
         (names[1], ['pub(super) fn selector_label', 'fn property_index', 'pub(super) fn with_mode']),
         (names[7], ['self.selected_text.clone().or_else'])])
    if row["product_id"] == 239:
        implementation("product_239_literal_copy", ["receiver_indicator_widget", "receiver_guide_modal"],
            "This product passes literal Show Guide, LED GUIDE and the full English status description to its actual Localizer; it does not pass the other two products' SHOW_GUIDE/LED_GUIDE/LED_CHECK_STATUS keys.",
            "Product source data retains the literal branch and the shared owner sends those exact strings through the localizer.",
            [(names[0], ['t(&spec.show_guide)', 't(&spec.guide_title)', 't(&spec.guide_description)']),
             (names[2], ['"show_guide": "Show Guide"', '"guide_title": "LED GUIDE"'])])
    refs = []
    pattern = re.compile(r'\b(?:MouseReceiverIndicatorRequested|MouseReceiverMonitorRequested|finish_receiver_indicator|observe_receiver_quality)\b')
    for path in sorted((a.ROOT / "crates").rglob("*.rs")):
        if "src" not in path.parts:
            continue
        body = path.read_bytes()
        text = body.decode("utf-8")
        found = [{"line": text.count("\n", 0, match.start()) + 1, "symbol": match[0]}
                 for match in pattern.finditer(text)]
        if found:
            refs.append({"path": a.rel(path), "bytes": len(body), "sha256": hashlib.sha256(body).hexdigest(), "occurrences": found})
    return {"recorded_at_utc": a.stamp(), "review_writes_product_code": False,
        "complete_current_rust_owners": current, "source_implementation_review": checks,
        "marker_checks_prove_behavior": False, "runtime_event_symbol_occurrences": refs,
        "remaining_source_audit": [
            "Continue comparing retained full dropdown7734/option7278, localizer and CSS/resource dependencies with placement, pointer-event and text-measurement behavior; markers do not prove equivalent interaction.",
            "Continue receiver_indicator_runtime's explicit native/portable event and final indirect-call closure; registration wrappers do not prove the native ABI.",
            "Finish source-versus-current review of raw/irregular profile arrays, every mounting branch, typography, clipping and measurement against locked GPUI APIs.",
            "Record the current complete modification batch's static/pure/simulated validation separately after edits; real window/device acceptance is prohibited and remains unverified."],
        "source_to_rust_ui_backend_complete": False, "runtime_acceptance": "unverified", "target_execution": False}


def audit_mouse_receiver_indicator(args):
    """Retain complete current mouse receiver UI owners and resource closure."""
    import importlib.metadata
    import sys
    sys.path.insert(0, str(a.ROOT / "tools/analyzers/python-static"))
    from tree_sitter import Language, Parser
    import tree_sitter_javascript
    if args.family != "mouse" or args.function != "main":
        raise ValueError("mouse-receiver-indicator requires current mouse main captures")
    ids = sorted(set(args.product or [190, 229, 239]))
    if set(ids) - {190, 229, 239}:
        raise ValueError("The three-LED receiver owner must first be resolved for this product")
    parser = Parser(Language(tree_sitter_javascript.language()))
    rows, preparations = [], []
    for pid in ids:
        row = {"product_id": pid, "complete_regions": [], "failures": [],
               "runtime_acceptance": "unverified", "whole_page_complete": False}
        rows.append(row)
        try:
            receipt_path = a.ROOT / f".analysis/inputs/frontend/mouse-{pid}-current/acquisition.json"
            acquired = json.loads(receipt_path.read_bytes())
            if not acquired.get("source_current_during_acquisition"):
                raise ValueError("Current deployment stability has not been verified")
            files = {item["url"]: item for item in acquired["files"] if item.get("path")}
            roots = [acquired["entry_url"], urllib.parse.urljoin(acquired["entry_url"], "asset-manifest.json")]
            if any(url not in files or not valid(files[url]) for url in roots):
                raise ValueError("Current entry/asset manifest identity differs")
            assets = json.loads((a.ROOT / files[roots[1]]["path"]).read_bytes())
            main_url = urllib.parse.urljoin(roots[1], assets["files"]["main.js"])
            css_url = urllib.parse.urljoin(roots[1], assets["files"]["main.css"])
            html = a.References()
            html.feed((a.ROOT / files[roots[0]]["path"]).read_text(encoding="utf-8"))
            mounted = {urllib.parse.urljoin(roots[0], literal) for literal, _ in html.refs}
            if main_url not in mounted or css_url not in mounted:
                raise ValueError("Current main JS/CSS is not mounted by the original entry")
            originals = [files[url] for url in (*roots, main_url, css_url)]
            if any(not valid(item) for item in originals):
                raise ValueError("Current receiver original input bytes differ")
            captured_path = a.ROOT / f".analysis/results/frontend/mouse-{pid}-current/analysis.json"
            captured = json.loads(captured_path.read_bytes())
            if not captured.get("input_bytes_unchanged"):
                raise ValueError("Complete static capture did not preserve its original inputs")
            row.update({"acquisition": identity(receipt_path), "deployments": paired_deployments(pid),
                        "complete_originals": originals, "parser_capture": identity(captured_path),
                        "parser_tool": captured["tool"],
                        "parser_modules": source_capture_modules(captured, files[main_url]),
                        "capture_failures": [command for command in captured.get("commands", []) if command.get("exit_code")],
                        "unresolved_acquisition": acquired.get("unresolved", []),
                        "failed_acquisition": [item for item in acquired["files"] if not item.get("path")]})
            source = files[main_url]
            content = (a.ROOT / source["path"]).read_bytes()
            text = content.decode("utf-8")
            tree = parser.parse(content)

            def retain(role, needle, kinds=("variable_declarator", "class_declaration")):
                offset = content.find(needle.encode("utf-8"))
                if offset < 0:
                    raise ValueError("Current receiver UI owner is unresolved: " + role)
                node = tree.root_node.descendant_for_byte_range(offset, offset + len(needle.encode("utf-8")) - 1)
                while node is not None and node.type not in kinds:
                    node = node.parent
                if node is None:
                    raise ValueError("Complete receiver UI AST boundary is unresolved: " + role)
                body = node.text.decode("utf-8")
                item = {"role": role, "original": source, "syntax": node.type,
                        "byte_start": node.start_byte, "byte_end": node.end_byte,
                        "body_sha256": hashlib.sha256(node.text).hexdigest(), "body": body}
                if node.type == "variable_declarator":
                    item["binding"] = node.child_by_field_name("name").text.decode("utf-8")
                row["complete_regions"].append(item)
                return item

            panel = retain("receiver_indicator_widget", 'className:"indicator-led__container"')
            retain("receiver_live_image_and_color_selectors", 'className:"indicator-led-image__wrapper"')
            retain("receiver_guide_modal", 'className:"popup-overlay"')
            retain("receiver_guide_hover_preview", 'className:"indicator-wrapper"')
            scale = retain("receiver_guide_hover_scale", 'height:"37",viewBox:')
            if not all(token in scale["body"] for token in ("onMouseEnter:", "onMouseLeave:", "textAnchor:", "activeTab")):
                raise ValueError("Receiver guide scale capture is not its complete component")
            retain("receiver_help_carousel", 'className:"indicator-led-tooltip"')
            retain("receiver_help_sections", 'renderType:"gradient"')
            retain("receiver_help_color_list", 'className:"list-wrapper"')
            retain("receiver_help_gradient", 'className:"gradient-wrapper"')
            retain("receiver_led_svg_complete", 'M8 16C12.4183')
            retain("receiver_help_next_svg_complete", 'M6 17.2889L6.62222 18')
            retain("receiver_battery_color_function", 'return e<0&&(e=0),e>100&&(e=100)')
            retain("receiver_connection_quality_colors", 'Connection_Quality_Status_Red:1')
            retain("receiver_source_defaults", 'connectionQuality:4}')
            # Anchor inside the actual postMessage, rather than an action-name
            # constant or the unrelated battery reducer.
            dispatch = text.find('postMessage({type:"ON_SET_INDICATOR_LED_CONFIGURATION"')
            if dispatch < 0:
                raise ValueError("Current receiver setter broadcast is unresolved")
            retain("receiver_reducer_and_MW_dispatch", text[dispatch:dispatch + 90])
            calls = list(re.finditer(r'(?:jsx|jsxs)\)\(' + re.escape(panel["binding"]) + r',', text))
            if len(calls) != 1:
                raise ValueError("Current receiver mounted caller is ambiguous")
            retain("receiver_mounted_customize_owner", text[calls[0].start():calls[0].end() + 10],
                   ("class_declaration", "variable_declarator"))
            row["mounted_calls"] = [{"character_offset": match.start(),
                                      "context": text[max(0, match.start() - 180):match.end() + 120]} for match in calls]
            # Resolve the actual same-scope imports. Matching a familiar symbol
            # elsewhere in this bundle can select another webpack module.
            import evidence
            preview = next(item for item in row["complete_regions"] if item["role"] == "receiver_guide_hover_preview")
            copy_namespace = re.search(r'case ([\w$]+)\.orY:', preview["body"])[1]
            constants_namespace = re.search(r'return ([\w$]+)\.jop\.LED_1', preview["body"])[1]
            dropdown_namespace = re.search(r'\)\(([\w$]+)\.A,\{dataSet:', panel["body"])[1]
            option_binding = re.search(r'dataSet:([\w$]+),', panel["body"])[1]
            panel_binding = re.search(r'return\(0,[\w$]+\.jsxs\)\(([\w$]+),\{title:', panel["body"])[1]
            shared_modules = keyboard_source_modules(text)
            resolved, pending = {}, [(name, panel["byte_start"]) for name in (
                copy_namespace, constants_namespace, dropdown_namespace, option_binding, panel_binding)]
            while pending:
                name, reference = pending.pop(0)
                if name in resolved:
                    continue
                binding = evidence.javascript_binding(content, tree, name, reference)
                if binding["resolution"] != "declaration":
                    raise ValueError("Receiver dependency binding is unresolved: " + json.dumps(binding))
                resolved[name] = {**binding, "original": source}
                imported = re.fullmatch(re.escape(name) + r'=[\w$]+\((\d+)\)', binding["body"])
                if imported:
                    candidates = [module for module in shared_modules if module["module_id"] == int(imported[1])]
                    if len(candidates) != 1:
                        raise ValueError("Receiver dependency webpack owner is ambiguous: " + name)
                    module = candidates[0]
                    resolved[name]["complete_imported_module"] = {**module, "source": source,
                        "body_sha256": hashlib.sha256(module["body"].encode("utf-8")).hexdigest()}
                    # The original dropdown's actual option and localizer are
                    # independent mounted components, not arbitrary substitutes.
                    if name == dropdown_namespace:
                        for role, anchor in (("receiver_dropdown_option", 'className:"option'),
                                             ("receiver_localizer", 'text:U===')):
                            if role == "receiver_localizer":
                                localizer_match = re.search(r'\)\(([\w$]+)\.A,\{text:[\w$]+===[\w$]+\.x3E&&', module["body"])
                                if localizer_match is None:
                                    raise ValueError("Receiver dropdown localizer caller is unresolved")
                                localizer = localizer_match[1]
                                imported_option = re.search(r'(?<![\w$])' + re.escape(localizer) + r'=[\w$]+\((\d+)\)', module["body"])
                            else:
                                option_namespace = re.search(r'\)\(([\w$]+)\.A,\{notLocalize:', module["body"])[1]
                                imported_option = re.search(r'(?<![\w$])' + re.escape(option_namespace) + r'=[\w$]+\((\d+)\)', module["body"])
                            if imported_option is None:
                                raise ValueError("Receiver dropdown nested import is unresolved: " + role)
                            children = [item for item in shared_modules if item["module_id"] == int(imported_option[1])]
                            if len(children) != 1:
                                raise ValueError("Receiver dropdown nested module is ambiguous: " + role)
                            child = children[0]
                            row.setdefault("complete_dependency_modules", []).append({"role": role, **child,
                                "source": source, "body_sha256": hashlib.sha256(child["body"].encode("utf-8")).hexdigest()})
                wrapped = re.search(r'\)\(([\w$]+)\)$', binding["body"])
                if name == panel_binding and wrapped:
                    pending.append((wrapped[1], binding["start_byte"]))
            row["resolved_dependencies"] = list(resolved.values())
            copy_module = resolved[copy_namespace]["complete_imported_module"]
            labels = []
            for exported in sorted(set(re.findall(re.escape(copy_namespace) + r'\.([\w$]+)',
                    " ".join(item["body"] for item in row["complete_regions"] + row["resolved_dependencies"])) )):
                alias = re.search(r'(?<![\w$])' + re.escape(exported) + r':\(\)=>([\w$]+)', copy_module["body"])
                literal = re.search(r'(?<![\w$])' + re.escape(alias[1]) + r'="([^"\\]+)"', copy_module["body"]) if alias else None
                if literal:
                    labels.append({"namespace": copy_namespace, "export": exported, "binding": alias[1], "source_key": literal[1]})
            row["source_copy_keys"] = labels
            label_values = {(item["namespace"], item["export"]): item["source_key"] for item in labels}
            def source_copy(role, class_name):
                body = next(item["body"] for item in row["complete_regions"] if item["role"] == role)
                match = re.search(r'className:"' + re.escape(class_name)
                    + r'",children:.*?\{text:("(?:[^"\\]|\\.)*"|[\w$]+\.[\w$]+)\}', body)
                if match is None:
                    raise ValueError("Receiver source copy caller is unresolved: " + class_name)
                expression = match[1]
                if expression.startswith('"'):
                    return json.loads(expression)
                namespace, export = expression.split(".", 1)
                if (namespace, export) not in label_values:
                    raise ValueError("Receiver source copy export is unresolved: " + expression)
                return label_values[(namespace, export)]
            row["source_descriptor_copy"] = {
                "show_guide": source_copy("receiver_indicator_widget", "indicator-led__link-text"),
                "guide_title": source_copy("receiver_guide_modal", "popup-title"),
                "guide_description": source_copy("receiver_guide_modal", "popup-description"),
            }
            css = (a.ROOT / files[css_url]["path"]).read_text(encoding="utf-8")
            row["complete_css_rules"] = [match[0] for match in re.finditer(r'[^{}]+\{[^{}]*\}', css)
                if any(token in match[0].split("{", 1)[0] for token in (
                    "indicator-led", "indicator-wrapper", "led-popup", "popup-overlay", "tab-group", "tab-btn",
                    "close-btn", "popup-title", "popup-description", "gradient-", "list-item", "dot-wrapper", "next-icon"))]
            row["complete_shared_css_rules"] = [match[0] for match in re.finditer(r'[^{}]+\{[^{}]*\}', css)
                if any(token in match[0].split("{", 1)[0] for token in (
                    ".body-widgets", ".widget ", ".tip", ".dropdown", ".s3-dropdown", ".s3-options", ".drop-tips"))]
            requests = {}
            for pattern, alias in ((r'"(static/media/dongle\.[^"/]+\.avif)"', f"synapse/mouse-receiver-indicator/{pid}.png"),
                                   (r'"(static/media/arrow-icon-green\.[^"/]+\.svg)"', f"synapse/mouse-receiver-indicator/{pid}-guide.svg")):
                literals = set(re.findall(pattern, text))
                if len(literals) != 1:
                    raise ValueError("Receiver resource export is ambiguous")
                url = urllib.parse.urljoin(acquired["entry_url"], next(iter(literals)))
                image = files.get(url)
                if args.prepare and (image is None or image.get("http_status") != 200):
                    previous = image
                    image = a.download(url, receipt_path.parent)
                    row.setdefault("supplemental_acquisition", []).append(image)
                    if image.get("http_status") != 200 or not valid(image):
                        raise ValueError("Current official receiver resource could not be verified: " + url)
                    if previous is not None:
                        if (image["sha256"], image["bytes"]) != (previous.get("sha256"), previous.get("bytes")):
                            raise ValueError("Official receiver resource differs from retained bytes")
                        image["previous_attempts"] = previous.get("previous_attempts", []) + [
                            {key: value for key, value in previous.items() if key != "previous_attempts"}]
                        acquired["files"][acquired["files"].index(previous)] = image
                    else:
                        acquired["files"].append(image)
                    files[url] = image
                    publish_frontend_acquisition(receipt_path, acquired)
                if image is None or not valid(image):
                    raise ValueError("Receiver resource bytes do not verify")
                row.setdefault("resources", []).append({"original": image, "alias": alias})
                requests[image["path"]] = alias
            preparations.append({"acquisition": a.rel(receipt_path), "resources": requests})
            row["source_descriptor"] = {"product_id": pid, "image": row["resources"][0]["alias"],
                "guide_icon": row["resources"][1]["alias"], **row["source_descriptor_copy"]}
            row["acquisition"] = identity(receipt_path)
            row["semantics"] = {
                "visibility": "Use the complete mounted caller per product; component availability alone does not imply a mount",
                "telemetry": "Image is source artwork. LED colors derive from source reducer battery/quality/polling/DPI values, not a fabricated successful device read",
                "setter": "Map the matching index, update the optimistic source array and post ON_SET_INDICATOR_LED_CONFIGURATION; do not invent setter-ACK rollback",
                "modal": "Four tabs, a product image, hover-only scale previews and explicit Close; original overlay stops propagation and does not close on backdrop",
                "scope": "This receiver widget audit does not complete the full mouse page or other product families"}
            row["source_review"] = mouse_receiver_indicator_source_review(row)
        except (OSError, ValueError, KeyError, StopIteration, TypeError) as error:
            row["failures"].append(str(error))
    report_path = a.ROOT / ".analysis/results/frontend/mouse-main-audit.json"
    report = json.loads(report_path.read_bytes()) if report_path.is_file() else {"schema_version": 1}
    report["receiver_indicator"] = {"recorded_at_utc": a.stamp(), "tool": identity(Path(__file__)),
        "parser": {name: importlib.metadata.version(name) for name in ("tree-sitter", "tree-sitter-javascript")},
        "products": rows, "resource_preparation_requests": preparations, "target_execution": False,
        "runtime_acceptance": "unverified"}
    a.save(report_path, report)
    if args.prepare and preparations:
        import workspace
        report["receiver_indicator"]["resource_preparation"] = workspace.prepare_resources(preparations)
        if not any(row["failures"] for row in rows):
            data_path = a.builtin_data_path("razer-pages", "MOUSE_RECEIVER_INDICATOR_DATA")
            a.save(data_path, [row["source_descriptor"] for row in rows])
            report["receiver_indicator"]["generated_descriptor"] = identity(data_path)
        a.save(report_path, report)
    print(json.dumps({"receipt": a.rel(report_path), "products": len(rows),
                      "failures": [{"product_id": row["product_id"], "failures": row["failures"]}
                                   for row in rows if row["failures"]]}), flush=True)
    if any(row["failures"] for row in rows):
        raise ValueError("Current receiver indicator source chain remains unresolved")


def review_current_multipairing(acquired, captured, files, main, css, parser, owners):
    """Join the current standalone pairing page's full owners without JS execution."""
    import evidence as e

    raw = (a.ROOT / main["path"]).read_bytes()
    tree = parser.parse(raw)
    if tree.root_node.has_error:
        raise ValueError("Current MultiPairing main has JavaScript parse errors")
    deployment = e.frontend_deployment_sources(acquired)
    if deployment["failures"]:
        raise ValueError("Current MultiPairing HTML/manifest identity or mounting differs: " + json.dumps(deployment["failures"]))
    for original in (main, css):
        source = next(item for item in deployment["sources"] if item["url"] == original["url"])
        if source["deployment_role"] != "html_include" or not source["identity_verified"]:
            raise ValueError("Current MultiPairing main JS/CSS is not an actual HTML include")

    result = {"deployment": deployment, "complete_owners": [], "unresolved_chains": [],
              "source_chain_complete": False, "whole_page_complete": False}
    references = {}

    def keep(role, node, *, source=main):
        key = f"{source['sha256']}:{node.start_byte}:{node.end_byte}"
        if key not in owners:
            owners[key] = {"original": source, "byte_start": node.start_byte, "byte_end": node.end_byte,
                "node_type": node.type, "body_sha256": hashlib.sha256(node.text).hexdigest(),
                "body": node.text.decode("utf-8"), "capture_modules": source_capture_modules(captured, source)}
        item = {"role": role, "key": key}
        if item not in result["complete_owners"]:
            result["complete_owners"].append(item)
        return key

    def binding(name, role):
        if name not in references:
            found = e.javascript_binding(raw, tree, name, raw.index(b"class yc extends") + 20)
            if found["resolution"] != "declaration":
                raise ValueError("MultiPairing source binding is unresolved: " + name + ": " + found["resolution"])
            node = tree.root_node.descendant_for_byte_range(found["start_byte"], found["end_byte"] - 1)
            while node and (node.start_byte != found["start_byte"] or node.end_byte != found["end_byte"]):
                node = node.parent
            if node is None:
                raise ValueError("MultiPairing complete binding boundary differs: " + name)
            references[name] = node
        keep(role, references[name])
        return references[name]

    roles = {
        "root_host_focus_and_accessibility": ["Lc", "Rc", "bc", "Tc", "Pc"],
        "root_store_language_and_mount": ["Ac", "Cc", "yc", "_c", "Sc", "Z", "$", "H", "V", "F"],
        "mounted_pairing_state_machine": ["hc", "pc", "uc", "cc", "lc", "dc", "pe", "Oe", "Ne", "De", "Me", "Ie"],
        "mounted_pairing_cards_and_confirmation": ["Zl", "Cl", "yl", "Sl", "el", "Qa", "Ma", "nc"],
        "local_pairing_storage_and_identity": ["tt", "nt", "it", "rt", "lt", "ct", "dt", "ut", "pt", "Ul", "Et", "ht", "_e", "Se", "ge", "ve", "ye", "Ce", "Re", "be"],
        "broadcast_request_response_and_cleanup": ["jt", "hr", "Er", "ia", "ra", "sa", "aa", "la", "ca", "da", "ua", "pa"],
        "window_service_and_storage_event_adapter": ["Ge", "We", "en", "Qt"],
    }
    for role, names in roles.items():
        for name in names:
            binding(name, role)

    # Include every complete declaration in the mounted page's local subtrees,
    # not only the named buttons. This retains CSS bindings, SVG variants,
    # filter/identity helpers, Redux actions and all conditional branches.
    regions = [("v", "Le", "complete_state_and_host_adapter_subtree"),
               ("tt", "Et", "complete_local_storage_subtree"),
               ("ia", "hc", "complete_mounted_pairing_subtree"),
               ("mc", "yc", "complete_root_parameter_subtree")]
    selected_nodes = {}
    for left, right, role in regions:
        start = binding(left, role).start_byte
        end = binding(right, role).end_byte
        pending = [tree.root_node]
        while pending:
            node = pending.pop()
            if node.end_byte <= start or node.start_byte >= end:
                continue
            if node.type in {"variable_declarator", "function_declaration", "class_declaration"} and start <= node.start_byte and node.end_byte <= end:
                keep(role, node)
                selected_nodes[(node.start_byte, node.end_byte)] = node
                continue
            pending.extend(reversed(node.named_children))

    # Resolve text identifiers through the real export module and all retained
    # locale dictionaries. No JavaScript expression is evaluated.
    modules = {}
    pending = [tree.root_node]
    while pending:
        node = pending.pop()
        if node.type == "pair":
            key = node.child_by_field_name("key")
            if key is not None and key.text.isdigit():
                modules[int(key.text)] = node
        pending.extend(reversed(node.named_children))
    text_module = modules.get(4693)
    if text_module is None:
        raise ValueError("MultiPairing complete text export module 4693 is unavailable")
    keep("complete_text_export_module", text_module)
    exports = {}
    pending = [text_module]
    while pending:
        node = pending.pop()
        if node.type == "pair":
            key, value = node.child_by_field_name("key"), node.child_by_field_name("value")
            if key is not None and value is not None and value.type == "arrow_function":
                body = value.child_by_field_name("body")
                if body is not None and body.type == "identifier":
                    exports[key.text.decode()] = body
        pending.extend(reversed(node.named_children))
    labels = {}
    for node in selected_nodes.values():
        for match in re.finditer(rb"\bIt\.([\w$]+)", node.text):
            export = match[1].decode()
            if export not in exports:
                raise ValueError("MultiPairing mounted text export is absent: " + export)
            identifier = exports[export]
            found = e.javascript_binding(raw, tree, identifier.text.decode(), identifier.start_byte)
            value = tree.root_node.descendant_for_byte_range(found["start_byte"], found["end_byte"] - 1).child_by_field_name("value")
            if found["resolution"] != "declaration" or value is None or value.type != "string":
                raise ValueError("MultiPairing mounted text key is nonliteral: " + export)
            key = json.loads(value.text)
            item = labels.setdefault(key, {"export": export, "source_key": key, "callers": []})
            item["callers"].append({"byte_offset": node.start_byte + match.start(),
                "complete_owner": f"{main['sha256']}:{node.start_byte}:{node.end_byte}"})
    result["source_copy_keys"] = sorted(labels.values(), key=lambda item: item["source_key"])
    result["locales"] = []
    for source in files.values():
        match = re.search(r"/trans-([\w-]+)\.[^/]+\.chunk\.js$", source["url"])
        if match:
            locale_raw = (a.ROOT / source["path"]).read_bytes()
            locale_tree = parser.parse(locale_raw)
            if locale_tree.root_node.has_error:
                raise ValueError("MultiPairing locale has JavaScript parse errors: " + match[1])
            locale_exports, locale_declarations = {}, {}
            pending = [locale_tree.root_node]
            while pending:
                node = pending.pop()
                if node.type == "pair":
                    key, value = node.child_by_field_name("key"), node.child_by_field_name("value")
                    if key is not None and value is not None and value.type == "arrow_function":
                        body = value.child_by_field_name("body")
                        key_text = json.loads(key.text) if key.type == "string" else key.text.decode()
                        if key_text in labels and body is not None and body.type == "identifier":
                            locale_exports.setdefault(key_text, []).append(body)
                if node.type == "variable_declarator":
                    name = node.child_by_field_name("name")
                    if name is not None and name.type == "identifier":
                        locale_declarations.setdefault(name.text, []).append(node)
                pending.extend(reversed(node.named_children))
            locale_values, locale_resolutions, locale_owners = {}, [], {}
            for key in sorted(labels):
                matches = locale_exports.get(key, [])
                if len(matches) != 1:
                    raise ValueError("MultiPairing locale export is missing or ambiguous: " + match[1] + ":" + key)
                identifier = matches[0]
                candidates = locale_declarations.get(identifier.text, [])
                if len(candidates) != 1:
                    found = e.javascript_binding(locale_raw, locale_tree, identifier.text.decode(), identifier.start_byte)
                    if found["resolution"] != "declaration":
                        raise ValueError("MultiPairing locale binding is unresolved: " + match[1] + ":" + key)
                    value_owner = locale_tree.root_node.descendant_for_byte_range(found["start_byte"], found["end_byte"] - 1)
                else:
                    value_owner = candidates[0]
                # Export identifier and constant must belong to the same actual
                # webpack module. A unique spelling elsewhere is insufficient.
                def module_owner(node):
                    while node is not None:
                        module_key = node.child_by_field_name("key") if node.type == "pair" else None
                        if module_key is not None and module_key.text.isdigit():
                            return node
                        node = node.parent
                    raise ValueError("MultiPairing locale module owner is unavailable")
                export_owner, declaration_owner = module_owner(identifier), module_owner(value_owner)
                if (export_owner.start_byte, export_owner.end_byte) != (declaration_owner.start_byte, declaration_owner.end_byte):
                    raise ValueError("MultiPairing locale constant belongs to another module")
                value = value_owner.child_by_field_name("value")
                if value is None or value.type != "string":
                    raise ValueError("MultiPairing locale value is nonliteral: " + match[1] + ":" + key)
                locale_values[key] = json.loads(value.text)
                locale_resolutions.append({"key": key, "export_byte": identifier.start_byte,
                    "value_byte_start": value_owner.start_byte, "value_byte_end": value_owner.end_byte,
                    "complete_binding": value_owner.text.decode(),
                    "binding_sha256": hashlib.sha256(value_owner.text).hexdigest()})
                owner_key = keep("complete_mounted_locale_module", declaration_owner, source=source)
                locale_owners[owner_key] = {"key": owner_key}
            result["locales"].append({"locale": match[1], "original": source, "values": locale_values,
                "resolutions": locale_resolutions, "complete_owners": list(locale_owners.values())})
    if not {"en", "zh-CN"} <= {item["locale"] for item in result["locales"]}:
        raise ValueError("MultiPairing English/Chinese mounted source copy is unavailable")

    # Complete original CSS is retained separately; map every mounted CSS-module
    # binding to complete rules while preserving surrounding media/keyframes.
    css_text = (a.ROOT / css["path"]).read_text(encoding="utf-8")
    class_bindings = []
    for node in selected_nodes.values():
        if node.type != "variable_declarator":
            continue
        value = node.child_by_field_name("value")
        if value is not None and value.type == "string":
            literal = json.loads(value.text)
            if re.fullmatch(r"[\w-]+__[\w-]+", literal):
                class_bindings.append({"binding": node.child_by_field_name("name").text.decode(),
                    "class": literal, "complete_owner": f"{main['sha256']}:{node.start_byte}:{node.end_byte}"})
    blocks, stack, cursor, boundary = [], [], 0, 0
    while cursor < len(css_text):
        character = css_text[cursor]
        if css_text.startswith("/*", cursor):
            end = css_text.find("*/", cursor + 2)
            if end < 0:
                raise ValueError("MultiPairing CSS has an unterminated comment")
            cursor = end + 2
            continue
        if character in "\"'":
            quote = character
            cursor += 1
            while cursor < len(css_text):
                if css_text[cursor] == "\\":
                    cursor += 2
                    continue
                if css_text[cursor] == quote:
                    break
                cursor += 1
            if cursor >= len(css_text):
                raise ValueError("MultiPairing CSS has an unterminated string")
        elif character == "\\":
            cursor += 2
            continue
        elif character == "{":
            start = boundary
            while start < cursor and css_text[start].isspace():
                start += 1
            stack.append((start, css_text[start:cursor]))
            boundary = cursor + 1
        elif character == "}":
            if not stack:
                raise ValueError("MultiPairing CSS has an unmatched block end")
            start, selector = stack.pop()
            body = css_text[start:cursor + 1]
            blocks.append({"character_start": start, "character_end": cursor + 1,
                "selector": selector, "body": body, "body_sha256": hashlib.sha256(body.encode()).hexdigest()})
            boundary = cursor + 1
        elif character == ";" and not stack:
            boundary = cursor + 1
        cursor += 1
    if stack:
        raise ValueError("MultiPairing CSS has an unclosed block")
    class_names = {item["class"] for item in class_bindings}
    selected_rules = [block for block in blocks if class_names & set(re.findall(r"\.([\w-]+)", block["selector"]))]
    matched_names = set().union(*(set(re.findall(r"\.([\w-]+)", block["selector"])) for block in selected_rules))
    result["mounted_css"] = {"original": css, "class_bindings": class_bindings,
        "complete_rules": selected_rules,
        "complete_enclosing_at_rules": [block for block in blocks if block["selector"].lstrip().startswith("@") and
            any(block["character_start"] < rule["character_start"] and rule["character_end"] <= block["character_end"] for rule in selected_rules)],
        "bindings_without_matching_selector": [item for item in class_bindings if item["class"] not in matched_names],
        "complete_css_retained": True}
    result["resource_references"] = [{"reference": edge, "original": files.get(edge.get("to"))}
        for edge in acquired.get("edges", [])]
    result["mounted_chain"] = ["createRoot.render -> Lc", "Lc -> Ac -> Cc -> yc",
        "yc -> hc=pc -> uc=cc", "cc -> lc -> Ma + nc + Zl -> Cl=memo(yl) -> el + Sl"]
    result["semantics"] = {
        "initialization": "_c/Sc normalize actual query parameters and connectedDeviceInfo fallback; yc accepts same-origin multiDevicePairingInit, sends multiDevicePairingReady and initializes container-specific UI/MW broadcast channels.",
        "host_focus": "Lc/Rc/bc check visible/minimized status and the selected Synapse tab, then change body display; child components remain mounted. The tab-message subscription returns its source cleanup.",
        "states": {"LOADING": 0, "LOADED": 1, "SCANNING": 2, "SCANNED": 3, "PAIRING": 4, "PAIRED": 5,
            "PAIR_FAILED": 6, "UNPAIRING": 7, "JUSTUNPAIR": 8, "UNPAIRED": 9, "UNPAIR_FAILED": 10, "JUST_PAIRED": 11},
        "scan_and_pair": "cc sends DUALLINK_SCAN_DEVICE status=1 with per-category payloads; Zl preserves per-category automatic pairing and existing-pair exclusions. Refresh is disabled while scanning. Keyboard completion may start mouse scanning via dc.",
        "warning_cancel": "Dongle 713 uses nc warning; continue dispatches the existing flag before binding, cancel dispatches cancelPairing then cc sends DUALLINK_CANCEL followed by DUALLINK_BIND_INFO.",
        "confirmation": "yl mounts two inline Sl dialogs for Pair/Unpair; Sl focuses Cancel by default, cycles Tab/Shift+Tab, handles Escape and nonbutton Enter/Space, and dismisses on backdrop. Confirm closes local dialog state before invoking the caller. No focus-restoration owner is present in these complete source bodies.",
        "card_keyboard": "Card action divs have role=button/tabIndex and a Tab-only key handler that cycles actions in data-device-card-scope. The full source handler contains no Enter/Space activation branch for those divs.",
        "external_unpair": "lc.V routes to the actual owning master MW/UI channels; distinct dongle/product identities trigger a second unbind after the first response or 2s fallback, with 10s total timeout. Local entries are removed after successful matching responses; errors close the temporary channel.",
        "external_reclaim": "lc.H requests the previous master's unbind; a successful response or 2s timeout closes the temporary channel and scans the current master. Full identity/category/serial/power filters remain in lc/Zl/Ul.",
        "persistence": "Successful bind first changes reducer/Redux pairedInfo, then ut requires real master claimInterface before writing duallink-devices and emitting its local event; stale-slot pruning runs after 300ms. Successful unbind marks connected=0 and removes matching stored entries via pt.",
        "responses_and_errors": "Oe/cc preserve command-specific errors, 4s delayed resets, optimistic unpair state and per-category branches; these are not generic ACK rollback.",
        "cleanup": "yc removes the host message listener, closes its primary channel and deletes the wrapper; cc removes MW_RESPONSE_UI listeners; lc removes WindowStorage/storage/custom-event listeners; yl clears its delayed activation timer. da closes sa without resetting it to null. Pending lc temporary channels/timers, cc's 300ms prune and shared De timer have no additional unmount cleanup in the complete reviewed owners. Tc creates a MutationObserver without a disconnect cleanup in its complete body.",
        "resources": "Re constructs product/edition/category-specific dashboard3x.avif URLs and el implements source edition/default/fallback behavior. Actual compatible-device/master branch images need a separate retained-input closure; a manifest list alone is insufficient.",
        "excluded_remote_action": "Ma's compatible-devices hyperlink calls be, opening the source remote URL. This Internet-dependent catalog link is excluded from the local product UI, while local pairing remains required."}
    result["unresolved_chains"] = [
        "DUALLINK commands must be joined through each current product MW/HID export to native request/notification bodies; standalone app completion does not establish native protocol completion",
        "Dynamic compatible-device/master product/edition image closure from Re requires matching current retained originals; source key/CSS extraction is not whole-page acceptance",
        "WindowService/API adapter owners are retained; their exact host dispatch and current service response/lifecycle join remains a separate required chain",
        "Acquisition failures/unresolved references and capture validation failures are retained; they are not cleared by successful semantic extraction"]
    return result


def mouse_rotation_ble_source(audit, files):
    """Retain PID226's selected Protocol30 implementation without executing it."""
    selected = [source for source in files if Path(source["path"]).name.startswith("rzDevice30.")
                and source["path"].endswith(".js")]
    if len(selected) != 1:
        raise ValueError("Rotation BLE current device chunk is absent or ambiguous")
    source = selected[0]
    if "/mouse-mw-226-current/" not in source["path"]:
        raise ValueError("Rotation BLE source belongs to another product deployment")
    actual = audit.webpack_export("rotation_ble_selected_class", selected, 20063, "default")
    tree = audit.tree(source)

    def declaration(binding):
        if binding["resolution"] != "declaration":
            raise ValueError("Rotation BLE lexical declaration is unresolved")
        node = tree.root_node.descendant_for_byte_range(binding["start_byte"], binding["end_byte"] - 1)
        while node is not None and (node.start_byte != binding["start_byte"] or node.end_byte != binding["end_byte"]):
            node = node.parent
        if node is None:
            raise ValueError("Rotation BLE lexical owner is absent")
        return node

    alias = declaration(actual["binding"])
    value = alias.child_by_field_name("value")
    if value is None or value.type != "identifier":
        raise ValueError("Rotation BLE exported class alias differs")
    class_binding = audit.binding("rotation_ble_complete_class", source, value.text.decode(), value.start_byte)
    device_class = declaration(class_binding)
    if device_class.type != "class_declaration":
        raise ValueError("Rotation BLE actual class declaration differs")

    def imported(name, reference):
        binding = audit.binding("rotation_ble_actual_import_" + name, source, name, reference)
        node = declaration(binding)
        value = node.child_by_field_name("value")
        arguments = value.child_by_field_name("arguments") if value is not None and value.type == "call_expression" else None
        if arguments is None or len(arguments.named_children) != 1 or arguments.named_children[0].type != "number":
            raise ValueError("Rotation BLE actual import is not one numeric webpack module")
        return javascript_integer_literal(arguments.named_children[0].text.decode())

    heritage = next((node for node in device_class.named_children if node.type == "class_heritage"), None)
    parent = heritage.named_children[0] if heritage is not None and len(heritage.named_children) == 1 else None
    if parent is None or parent.type != "member_expression":
        raise ValueError("Rotation BLE superclass import differs")
    base_id = imported(parent.child_by_field_name("object").text.decode(), parent.start_byte)
    base = audit.webpack_export("rotation_ble_actual_base", files, base_id, parent.child_by_field_name("property").text.decode())
    methods, method_nodes = {}, {}
    for name in ("constructor", "connectDevice", "_getTransactionId", "_createDataSend", "_getDataLengthFromHeader",
                 "sendCommand", "getProximitySensorAngleTune", "setProximitySensorAngleTune"):
        node, owner = audit.callable_member("rotation_ble_" + name, source, device_class, name)
        method_nodes[name], methods[name] = node, owner

    command_owners = {}
    expected = {"getProximitySensorAngleTune": [0, 15, 148], "setProximitySensorAngleTune": [2, 15, 20]}
    for name, command in expected.items():
        method = method_nodes[name]
        calls = list(re.finditer(rb'\.sendCommand\(([\w$]+),"(?:Get|Set) Sensor Angle Tune",([\w$]+),0(?=[,)])', method.text))
        if len(calls) != 1:
            raise ValueError("Rotation BLE actual angle-tune sendCommand call differs")
        call = calls[0]
        binding = audit.binding("rotation_ble_header_" + name, source, call[1].decode(), method.start_byte + call.start())
        node = declaration(binding)
        value = node.child_by_field_name("value")
        if value is not None and value.type == "new_expression":
            constructor = value.child_by_field_name("constructor")
            arguments = value.child_by_field_name("arguments")
            if constructor is None or constructor.text != b'Uint8Array' or len(arguments.named_children) != 1:
                raise ValueError("Rotation BLE command bytes constructor differs")
            value = arguments.named_children[0]
        if value is None or value.type != "array" or static_js_literal(value.text.decode()) != command:
            raise ValueError("Rotation BLE actual command bytes differ")
        command_owners[name] = {"command": command, "owner": binding["owner_id"]}
    if not re.search(rb'jsonData=\{state:([\w$]+)\.data\[0\],angleTune:\1\.data\[1\]\}', method_nodes["getProximitySensorAngleTune"].text):
        raise ValueError("Rotation BLE getter no longer reads two unprefixed payload bytes")

    constants = {}
    constructor = method_nodes["constructor"]
    constant_alias = re.search(rb'this\.serviceUUID=([\w$]+)\.Ij', constructor.text)
    if constant_alias is None:
        raise ValueError("Rotation BLE service UUID owner differs")
    constant_id = imported(constant_alias[1].decode(), constructor.start_byte + constant_alias.start())
    expected_constants = {"Ij": "52401523f97c7f900e7f6c6f4e36db1c", "xe": "52401524f97c7f900e7f6c6f4e36db1c",
        "ex": "52401525f97c7f900e7f6c6f4e36db1c", "w6": 2, "ah": 150, "lI": 2, "lz": 30, "y2": 20,
        "_p": 1, "J$": 3, "z$": "timeout"}
    for name, value in expected_constants.items():
        exported = audit.webpack_export("rotation_ble_transport_constant_" + name, files, constant_id, name)
        body = exported["binding"]["body"]
        if "=" not in body or static_js_literal(body.split("=", 1)[1]) != value:
            raise ValueError("Rotation BLE transport constant differs: " + name)
        constants[name] = {"value": value, "export": exported}
    connect = method_nodes["connectDevice"]
    edition_call = re.search(rb'const [\w$]+=yield ([\w$]+)\.([\w$]+)\(this\)', connect.text)
    if edition_call is None:
        raise ValueError("Rotation BLE connection edition call is unresolved")
    edition_id = imported(edition_call[1].decode(), connect.start_byte + edition_call.start())
    edition = audit.webpack_export("rotation_ble_connection_edition", files, edition_id, edition_call[2].decode())
    return {"product_id": 226, "physical_product_id": 228, "source_class": "rzDevice30",
        "actual_class_export": actual, "class_owner": class_binding["owner_id"], "base_export": base,
        "method_owners": methods, "commands": command_owners, "constants": constants,
        "connection_edition": edition, "target_execution": False, "runtime_acceptance": "unverified",
        "semantics": {
            "frame": "_createDataSend allocates payload+8 bytes. Transaction is0..30; bytes1..3 contain little-endian payload length,4/5 command class/id,6 profile,7 parameter. Mounted Rotation passes profile1/parameter0; SET payload is enabled then signed-angle byte, GET has no payload. No Protocol25 report/profile prefix or checksum is introduced.",
            "response": "The selected host GATT strategy matches transaction and success status2. rzDevice30 uses its20-byte response-header boundary, then eight bytes when the declared nonzero payload length differs. Rotation GET reads raw payload bytes0/1; SET completion uses the actual ACK and does not invoke GET.",
            "lifecycle": "connectDevice uses the source connection retry constants and then actual Get Edition Information. sendCommand holds the physical lock and retries only timeout/status1/status3 with the same generated frame. Rust reuses the existing GATT identity/notification/CCCD/handle owner, finishes it before releasing the container lock, and treats cleanup failure as failure.",
            "scope": "This retains Protocol30 framing/commands and source connection semantics. Mounted logical226/BLE228 selection and its current UI/task consumer belong to the surrounding Rotation audit; original source acquisition and runtime acceptance remain independent."}}


def javascript_feature_calls(tree):
    """Inventory literal member calls without treating strings/comments as code.

    Literal computed names are included and nonliteral arguments stay explicit.
    Dynamically selected methods and aliased calls require separate resolution.
    """
    result = []
    stack = [tree.root_node]
    while stack:
        node = stack.pop()
        if node.type == "call_expression":
            function = node.child_by_field_name("function")
            if function is not None and function.type in {"member_expression", "subscript_expression"}:
                member = function.child_by_field_name("property") if function.type == "member_expression" else function.child_by_field_name("index")
                if member is not None:
                    name = member.text.decode("utf-8")
                    if member.type == "string" and name[:1] == name[-1:] and name[:1] in {'"', "'"}:
                        name = name[1:-1]
                    if name == "useFeature":
                        arguments = node.child_by_field_name("arguments")
                        values = [argument for argument in arguments.named_children if argument.type != "comment"]
                        def literal(index):
                            if index >= len(values) or values[index].type != "string":
                                return None
                            value = values[index].text.decode("utf-8")
                            return value[1:-1] if "\\" not in value else None
                        result.append({"byte_start": node.start_byte, "byte_end": node.end_byte,
                            "callee": function.text.decode("utf-8"), "feature": literal(0),
                            "variant": literal(1), "arguments": [value.text.decode("utf-8") for value in values]})
        stack.extend(reversed(node.named_children))
    return result


def javascript_bootstrap_features(raw, parser, singleton_module, singleton_export):
    """Resolve startup registrations to the actual imported injector singleton."""
    import evidence
    tree = parser.parse(raw)
    if tree.root_node.has_error:
        raise ValueError("Receiver bootstrap JavaScript grammar failed")
    bindings = evidence.JavascriptBindings(raw, tree)
    calls = javascript_feature_calls(tree)
    if not calls:
        raise ValueError("Receiver bootstrap has no feature registrations")
    result, seen, import_bindings = [], set(), {}
    for call in calls:
        node = tree.root_node.descendant_for_byte_range(call["byte_start"], call["byte_end"] - 1)
        while node is not None and (node.start_byte, node.end_byte) != (call["byte_start"], call["byte_end"]):
            node = node.parent
        function = node.child_by_field_name("function")
        receiver = function.child_by_field_name("object")
        if receiver is None or receiver.type != "member_expression":
            raise ValueError("Receiver feature receiver requires explicit singleton resolution")
        alias, exported = receiver.child_by_field_name("object"), receiver.child_by_field_name("property")
        if alias.type != "identifier" or exported.text.decode() != singleton_export:
            raise ValueError("Receiver feature call selects a different singleton export")
        binding = bindings.resolve(alias.text.decode(), node.start_byte)
        if binding["resolution"] != "declaration" or binding["syntax"] != "variable_declarator":
            raise ValueError("Receiver feature singleton import is shadowed or unresolved")
        declaration = tree.root_node.descendant_for_byte_range(binding["start_byte"], binding["end_byte"] - 1)
        while declaration is not None and (declaration.start_byte, declaration.end_byte) != (binding["start_byte"], binding["end_byte"]):
            declaration = declaration.parent
        value = declaration.child_by_field_name("value")
        arguments = value.child_by_field_name("arguments") if value is not None and value.type == "call_expression" else None
        if (arguments is None or len(arguments.named_children) != 1
                or arguments.named_children[0].type != "number"
                or javascript_integer_literal(arguments.named_children[0].text.decode()) != singleton_module):
            raise ValueError("Receiver feature singleton import selects a different module")
        if call["feature"] is None or call["variant"] is None:
            raise ValueError("Receiver feature registration has a dynamic name or variant")
        if call["feature"] in seen:
            raise ValueError("Receiver feature registration requires ordered duplicate-feature review")
        seen.add(call["feature"])
        import_bindings[(binding["start_byte"], binding["end_byte"])] = binding
        result.append({**call, "singleton_import": binding})
    # Rebinding the namespace after require would invalidate every apparent
    # member-to-export connection, even when its declaration still resolves.
    stack = [tree.root_node]
    while stack:
        node = stack.pop()
        stack.extend(reversed(node.named_children))
        if node.type not in {"assignment_expression", "augmented_assignment_expression", "update_expression"}:
            continue
        left = node.child_by_field_name("left") or node.child_by_field_name("argument")
        if left is None or left.type != "identifier":
            continue
        binding = bindings.resolve(left.text.decode(), left.start_byte)
        if (binding.get("start_byte"), binding.get("end_byte")) in import_bindings:
            raise ValueError("Receiver feature singleton namespace is reassigned")
    return {"registrations": result, "feature_names": [row["feature"] for row in result],
        "singleton_module": singleton_module, "singleton_export": singleton_export,
        "scope": "Current source startup calls and namespace binding; arbitrary external JavaScript injection is not executed or inferred"}


def legacy_receiver_bootstrap_features(raw, parser, singleton_module, singleton_export):
    """Resolve the legacy receiver's selected Protocol25 boolean config."""
    result = javascript_bootstrap_features(raw, parser, singleton_module, singleton_export)
    tree = parser.parse(raw)
    chosen = [row for row in result["registrations"] if row["feature"] == "rzDeviceType"]
    if len(chosen) != 1 or chosen[0]["variant"] != "rzDevice25":
        raise ValueError("Receiver bootstrap does not select the reviewed Protocol25 factory")
    selected = chosen[0]
    selected_node = tree.root_node.descendant_for_byte_range(selected["byte_start"], selected["byte_end"] - 1)
    while selected_node is not None and selected_node.type != "call_expression":
        selected_node = selected_node.parent
    values = selected_node.child_by_field_name("arguments").named_children
    config = {}
    if len(values) > 2:
        if len(values) != 3 or values[2].type != "object":
            raise ValueError("Receiver Protocol25 feature config requires literal field review")
        for pair in values[2].named_children:
            key, value = pair.child_by_field_name("key"), pair.child_by_field_name("value")
            if pair.type != "pair" or key is None or key.type != "property_identifier" or value is None:
                raise ValueError("Receiver Protocol25 feature config has an indirect field")
            if key.text.decode() in config:
                raise ValueError("Receiver Protocol25 feature config repeats a field")
            if value.text not in {b"!0", b"!1", b"true", b"false"}:
                raise ValueError("Receiver Protocol25 feature config has a nonliteral boolean")
            config[key.text.decode()] = value.text in {b"!0", b"true"}
    return {**result, "protocol25_config": config}


def review_legacy_duallink_protocol(pid, files, captured, parser, owners):
    """Retain per-product factory, protocol and event selection from originals."""
    import evidence as e
    sources = [source for source in files.values() if source["path"].endswith(".js")
               and f"/products/{pid}/mw/" in source["url"]
               and not Path(source["path"]).name.startswith(("translations", "service-worker"))]
    capture_inputs = {source["path"]: source for source in captured["original_inputs"]}
    raw_inputs, trees, modules, binding_indexes = {}, {}, {}, {}
    result = {"complete_owners": [], "export_resolutions": [], "wrapper_calls": [],
              "protocol_commands": [], "source_chain_complete": False, "whole_page_complete": False,
              "target_execution": False, "runtime_acceptance": "unverified"}
    for source in sources:
        if not valid(source) or capture_inputs.get(source["path"]) != {key: source[key] for key in ("path", "bytes", "sha256")}:
            raise ValueError("Legacy DualLink current original/capture identity differs: " + source["path"])
        raw_inputs[source["path"]] = (a.ROOT / source["path"]).read_bytes()

    def tree_for(source):
        if source["path"] not in trees:
            trees[source["path"]] = parser.parse(raw_inputs[source["path"]])
            if trees[source["path"]].root_node.has_error:
                raise ValueError("Legacy DualLink JavaScript grammar failed: " + source["path"])
        return trees[source["path"]]

    def binding_for(source, name, at):
        if source["path"] not in binding_indexes:
            binding_indexes[source["path"]] = e.JavascriptBindings(raw_inputs[source["path"]], tree_for(source))
        return binding_indexes[source["path"]].resolve(name, at)

    def module_at(source, offset):
        node = tree_for(source).root_node.descendant_for_byte_range(offset, offset)
        while node is not None:
            key = node.child_by_field_name("key") if node.type == "pair" else node.child_by_field_name("name") if node.type == "method_definition" else None
            if key is not None and key.type == "number":
                return node
            node = node.parent
        return None

    def keep(role, source, node):
        key = f"{source['sha256']}:{node.start_byte}:{node.end_byte}"
        owners.setdefault(key, {"original": source, "byte_start": node.start_byte, "byte_end": node.end_byte,
            "node_type": node.type, "body": node.text.decode("utf-8"), "body_sha256": hashlib.sha256(node.text).hexdigest(),
            "capture_modules": source_capture_modules(captured, source)})
        ref = {"role": role, "key": key}
        if ref not in result["complete_owners"]:
            result["complete_owners"].append(ref)
        return key

    def module(module_id, role):
        if module_id not in modules:
            found = {}
            pattern = re.compile(rb'(?<![\w$])' + str(module_id).encode() + rb'(?=[(:])')
            for source in sources:
                for match in pattern.finditer(raw_inputs[source["path"]]):
                    node = module_at(source, match.start())
                    if node is not None and node.start_byte == match.start():
                        found[(source["sha256"], node.start_byte)] = (source, node)
            if len(found) != 1:
                raise ValueError("Legacy DualLink complete imported module is absent/ambiguous: " + str(module_id))
            modules[module_id] = next(iter(found.values()))
        source, node = modules[module_id]
        keep(role, source, node)
        return source, node

    def imported_module(source, owner, alias, role):
        matches = list(re.finditer(rb'(?<![\w$])' + re.escape(alias.encode()) + rb'=[\w$]+\((\d+)\)', owner.text))
        if len(matches) != 1:
            raise ValueError("Legacy DualLink actual import is absent/ambiguous: " + alias)
        module_id = int(matches[0][1])
        module(module_id, role)
        result.setdefault("actual_imports", []).append({"owner_module":int(owner.child_by_field_name("key").text if owner.type == "pair" else owner.child_by_field_name("name").text),
            "alias":alias, "module_id":module_id, "reference_byte":owner.start_byte + matches[0].start(), "role":role})
        return module_id

    def anchored_module(role, needle):
        found = {}
        for source in sources:
            for match in re.finditer(re.escape(needle), raw_inputs[source["path"]]):
                owner = module_at(source, match.start())
                if owner is not None:
                    found[(source["sha256"],owner.start_byte)] = (source,owner)
        if len(found) != 1:
            raise ValueError("Legacy DualLink semantic module is absent/ambiguous: " + role)
        source, owner = next(iter(found.values()))
        numeric = owner.child_by_field_name("key") if owner.type == "pair" else owner.child_by_field_name("name")
        if numeric is None or not numeric.text.isdigit():
            raise ValueError("Legacy DualLink module ID literal requires explicit decoding")
        module_id = int(numeric.text)
        modules[module_id] = (source,owner)
        keep(role,source,owner)
        result.setdefault("semantic_module_resolutions", []).append({"role":role,"module_id":module_id,"anchor":needle.decode(),"original":source})
        return module_id

    def exported(module_id, exported_name, role):
        source, owner = module(module_id, "complete_export_module_" + str(module_id))
        matches = list(re.finditer(rb'(?<![\w$])' + re.escape(exported_name.encode()) + rb':\(\)=>([\w$]+)(?=[,}])', owner.text))
        if len(matches) != 1:
            raise ValueError("Legacy DualLink export is absent/ambiguous: " + str(module_id) + "." + exported_name)
        match = matches[0]
        at = owner.start_byte + match.start()
        raw, tree = raw_inputs[source["path"]], tree_for(source)
        resolved = binding_for(source, match[1].decode(), at)
        if resolved["resolution"] != "declaration":
            raise ValueError("Legacy DualLink export binding is unresolved: " + exported_name)
        node = tree.root_node.descendant_for_byte_range(resolved["start_byte"], resolved["end_byte"] - 1)
        while node is not None and (node.start_byte != resolved["start_byte"] or node.end_byte != resolved["end_byte"] or node.type != resolved["syntax"]):
            node = node.parent
        if node is None or module_at(source, node.start_byte).start_byte != owner.start_byte:
            raise ValueError("Legacy DualLink export resolves outside the expected module")
        key = keep(role, source, node)
        result["export_resolutions"].append({"module_id": module_id, "export": exported_name,
            "binding": match[1].decode(), "reference_byte": at, "complete_owner": key})
        return source, node

    ids = {}
    for role, needle in {
        "complete_duallink_scan_bind_unbind_storage_callbacks":b'DUALLINK_SCAN_DEVICE:',
        "complete_duallink_factory_and_identity_helpers":b'[duallink] getRzDevice - Starting.',
        "complete_duallink_mouse_adapter":b'this.name="rzDevice25DualLinkMouse"',
        "complete_duallink_keyboard_adapter":b'this.name="rzDevice25DualLinkKeyboard"',
        "complete_protocol25_device_wrapper":b'getMultipleDeviceWirelessConnectionStatusV2(){',
        "complete_pair_scan_unpair_command_constants":b'"Get Multiple Device Wireless Connection Status V2"',
        "complete_notification_registration_and_parser_selection":b'rzHardwareEventsProtocol25Parser:()=>',
        "complete_protocol25_notification_parser":b'"rzHardwareEventsProtocol25Parser-parse"',
        "complete_mapping_engine_event_bridge":b'response("deviceEvent",',
        "complete_local_ipc_request_adapter":b'sendRzDeviceActionToElectronMain() data:',
        "complete_local_hid_host_adapter":b'this.getHidDevices=',
        "complete_device_adapter_factory":b'"handleDefaultSpeakerChangeForAutomation"',
        "complete_runtime_feature_getter":b'deviceInfo.runtimeData.isRegisterAudioServiceEvent',
        "complete_product_feature_initialization":b'"Derived features:"',
        "complete_feature_injector_mutation_semantics":b'static ERROR_MESSAGE="[RzMiddlewareInjector]"',
        "complete_product_device_info_and_defaults":b'DeviceInfo:()=>',
        "complete_protocol_integer_helpers":b'getRandomValues(e),32767&e[0]',
    }.items():
        ids[role] = anchored_module(role,needle)
    registration_source, registration_owner = modules[ids["complete_notification_registration_and_parser_selection"]]
    route = re.search(rb'rzHardwareEventsProtocol25Parser:\(\)=>([\w$]+)\.e\((\d+)\)\.then\(\1\.bind\(\1,(\d+)\)\)',registration_owner.text)
    if route is None or int(route[3]) != ids["complete_protocol25_notification_parser"]:
        raise ValueError("Legacy DualLink actual lazy Protocol25 parser route is unresolved")
    result["protocol25_parser_route"] = {"chunk_id":int(route[2]),"module_id":int(route[3]),
        "reference_byte":registration_owner.start_byte+route.start(),"original":registration_source}
    parser_source, parser_owner = modules[ids["complete_protocol25_notification_parser"]]
    # Recent bundles inline unused enum copies into unrelated modules. Resolve
    # the enums through this parser's actual imports instead of matching their
    # repeated literals (which can also select a different protocol's enum).
    for role, expression in {
        "complete_pair_scan_protocol_enums":rb'device_1_keyboardLayoutEnum:[\w$]+\.[\w$]+\(([\w$]+)\.([\w$]+),',
        "complete_notification_record_event_enums":rb'case\s+([\w$]+)\.([\w$]+)\.NOTIFICATION_EVENTS:',
    }.items():
        matches = list(re.finditer(expression,parser_owner.text))
        aliases = {(match[1],match[2]) for match in matches}
        if len(aliases) != 1:
            raise ValueError("Legacy DualLink parser enum import is absent/ambiguous: " + role)
        alias, exported_name = next(iter(aliases))
        ids[role] = imported_module(parser_source,parser_owner,alias.decode(),role)
        exported(ids[role],exported_name.decode(),role + "_selected_enum")
    initialization_source, initialization_owner = modules[ids["complete_product_feature_initialization"]]
    defaults = re.search(rb'console.warn\("Derived features:",\(0,[\w$]+\.[\w$]+\)\(([\w$]+)\.([\w$]+)\)\)',initialization_owner.text)
    if defaults is None:
        raise ValueError("Legacy DualLink feature initialization default import is unresolved")
    defaults_id = imported_module(initialization_source,initialization_owner,defaults[1].decode(),"complete_product_runtime_defaults")
    runtime_defaults_id = defaults_id
    exported(defaults_id,defaults[2].decode(),"current_product_runtime_defaults")
    factory_id = ids["complete_duallink_factory_and_identity_helpers"]
    factory_source, factory_module = modules[factory_id]
    at = factory_module.start_byte + factory_module.text.index(b'[duallink] getRzDevice - Starting.')
    factory_owner = tree_for(factory_source).root_node.descendant_for_byte_range(at,at)
    while factory_owner is not None and factory_owner.type not in {"variable_declarator","function_declaration"}:
        factory_owner = factory_owner.parent
    if factory_owner is None or factory_owner.child_by_field_name("name") is None:
        raise ValueError("Legacy DualLink actual factory declaration is unresolved")
    factory_binding = factory_owner.child_by_field_name("name").text
    factory_exports = re.findall(rb'([\w$]+):\(\)=>'+re.escape(factory_binding)+rb'(?=[,}])',factory_module.text)
    if len(factory_exports) != 1:
        raise ValueError("Legacy DualLink actual factory export is unresolved")
    exported(factory_id,factory_exports[0].decode(),"actual_duallink_adapter_factory")
    result["adapter_factory_export"] = {"module_id":factory_id,"export":factory_exports[0].decode(),
        "binding":factory_binding.decode()}
    exported(ids["complete_product_device_info_and_defaults"],"DeviceInfo","current_product_device_info")

    wrapper_id = ids["complete_protocol25_device_wrapper"]
    wrapper_source, wrapper = modules[wrapper_id]
    base_class = re.search(rb'\bclass(?:\s+[\w$]+)?\s+extends\s+([\w$]+)\.',wrapper.text)
    if base_class is None:
        raise ValueError("Legacy DualLink actual base-class import is unresolved")
    ids["complete_base_protocol_framing_lifecycle"] = imported_module(
        wrapper_source, wrapper, base_class[1].decode(), "complete_base_protocol_framing_lifecycle")
    protocol_id = None
    command_id = ids["complete_pair_scan_unpair_command_constants"]
    for name, payload in [
        ("setDevicePairingMode", "mode at byte0; target productId high/low at bytes1/2"),
        ("setDeviceUnpair", "target productId high/low at bytes0/1"),
        ("deviceScan", "scan status at byte0"),
        ("getMultipleDeviceWirelessConnectionStatusV2", "no request payload; response count followed by status + big-endian productId records"),
    ]:
        matches = list(re.finditer(rb'(?<![\w$])' + re.escape(name.encode()) + rb'\(', wrapper.text))
        methods = {}
        for match in matches:
            node = tree_for(wrapper_source).root_node.descendant_for_byte_range(wrapper.start_byte + match.start(), wrapper.start_byte + match.start())
            while node is not None and node.type != "method_definition":
                node = node.parent
            if node is not None and node.child_by_field_name("name").text.decode() == name:
                methods[node.start_byte] = node
        if len(methods) != 1:
            raise ValueError("Legacy DualLink device method is absent/ambiguous: " + name)
        method = next(iter(methods.values()))
        call = re.search(rb'\breturn\s+([\w$]+)\.([\w$]+)\(this', method.text)
        if call is None:
            raise ValueError("Legacy DualLink device method actual protocol import differs: " + name)
        actual_id = imported_module(wrapper_source,wrapper,call[1].decode(),"complete_pair_scan_unpair_protocol_exports")
        if protocol_id is not None and actual_id != protocol_id:
            raise ValueError("Legacy DualLink command methods use distinct unresolved protocol modules")
        protocol_id = actual_id
        exported_name = call[2].decode()
        result["wrapper_calls"].append({"method": name, "protocol_export": exported_name,
            "protocol_module":protocol_id,
            "complete_owner": keep("device_wrapper_" + name, wrapper_source, method)})
        protocol_source, protocol_owner = exported(protocol_id, exported_name, "protocol_" + name)
        send = re.search(rb'\.sendCommand\(([\w$]+)\.([\w$]+),([\w$]+)\.([\w$]+)(?=[,)])',protocol_owner.text)
        if send is None or send[1] != send[3]:
            raise ValueError("Legacy DualLink actual command/description binding is unresolved: " + name)
        constants_id = imported_module(protocol_source,modules[protocol_id][1],send[1].decode(),"complete_pair_scan_unpair_command_constants")
        if constants_id != command_id:
            raise ValueError("Legacy DualLink command constants differ from actual imported module")
        header, description = send[2].decode(),send[4].decode()
        _, header_owner = exported(command_id, header, "command_header_" + name)
        exported(command_id, description, "command_description_" + name)
        header_match = re.search(rb'new Uint8Array\(\[([\d,]+)\]\)', header_owner.text)
        if header_match is None:
            raise ValueError("Legacy DualLink actual command header literal is unresolved")
        result["protocol_commands"].append({"method": name, "header_export": header,
            "header_bytes": [int(value) for value in header_match[1].split(b',')], "payload": payload,
            "protocol_body_sha256": hashlib.sha256(protocol_owner.text).hexdigest()})
    codecs_id = ids["complete_protocol_integer_helpers"]
    codecs_source, codecs = modules[codecs_id]
    selected_codecs = {}
    codec_exports = {}
    for match in re.finditer(rb'([\w$]+):\(\)=>([\w$]+)(?=[,}])',codecs.text):
        codec_exports.setdefault(match[2],[]).append(match[1])
    stack = [codecs]
    while stack:
        candidate = stack.pop()
        name = candidate.child_by_field_name("name") if candidate.type == "variable_declarator" else None
        if name is not None and name.text in codec_exports:
            for role, expression in {"high8":rb'=>[\w$]+>>8&255$',"low8":rb'=>255&[\w$]+$',
                                     "big_endian_u16":rb'=>\(255&[\w$]+\)<<8\|255&[\w$]+$'}.items():
                if re.search(expression,candidate.text):
                    names = codec_exports[name.text]
                    if role in selected_codecs or len(names) != 1:
                        raise ValueError("Legacy DualLink integer codec is ambiguous: " + role)
                    _, actual = exported(codecs_id,names[0].decode(),"integer_codec_"+role)
                    if actual.start_byte != candidate.start_byte or actual.end_byte != candidate.end_byte:
                        raise ValueError("Legacy DualLink integer codec resolves to a different declaration")
                    selected_codecs[role] = names[0].decode()
        stack.extend(reversed(candidate.children))
    if set(selected_codecs) != {"high8","low8","big_endian_u16"}:
        raise ValueError("Legacy DualLink actual integer codecs are incomplete")
    result["integer_codec_exports"] = selected_codecs

    # Resolve the single-LED methods through this product's actual imports.
    # Their power module is distinct from the pairing command module above.
    result["indicator_protocol"] = []
    for name in ("getIndicatorLedConfiguration", "setIndicatorLedConfiguration", "getSerialNumber"):
        found = {}
        for match in re.finditer(rb'(?<![\w$])' + name.encode() + rb'\(', wrapper.text):
            node = tree_for(wrapper_source).root_node.descendant_for_byte_range(wrapper.start_byte + match.start(), wrapper.start_byte + match.start())
            while node is not None and node.type != "method_definition":
                node = node.parent
            if node is not None and node.child_by_field_name("name").text.decode() == name:
                found[node.start_byte] = node
        if len(found) != 1:
            raise ValueError("Legacy indicator actual device method is absent/ambiguous: " + name)
        method = next(iter(found.values()))
        call = re.search(rb'\breturn\s+([\w$]+)\.([\w$]+)\(this', method.text)
        if call is None:
            raise ValueError("Legacy indicator device protocol import differs: " + name)
        actual_id = imported_module(wrapper_source, wrapper, call[1].decode(), "complete_single_led_protocol_module")
        protocol_source, protocol_owner = exported(actual_id, call[2].decode(), "single_led_protocol_" + name)
        send = re.search(rb'\.sendCommand\(([\w$]+)\.([\w$]+),([\w$]+)\.([\w$]+)(?=[,)])', protocol_owner.text)
        if send is None or send[1] != send[3]:
            raise ValueError("Legacy indicator command header/description import differs: " + name)
        constants_id = imported_module(protocol_source, modules[actual_id][1], send[1].decode(), "complete_single_led_command_module")
        _, command = exported(constants_id, send[2].decode(), "single_led_header_" + name)
        exported(constants_id, send[4].decode(), "single_led_description_" + name)
        literal = re.search(rb'new Uint8Array\(\[([\d,]+)\]\)', command.text)
        if literal is None:
            raise ValueError("Legacy indicator header is not a literal byte array")
        keep("single_led_wrapper_" + name, wrapper_source, method)
        result["indicator_protocol"].append({"method": name, "command": [int(value) for value in literal[1].split(b',')],
            "protocol_module": actual_id, "protocol_export": call[2].decode(),
            "complete_protocol": keep("single_led_protocol_" + name, protocol_source, protocol_owner)})
        # Preserve complete data parser declarations used by the returned result.
        parse_calls = re.findall(rb'(?<![\w$.])([\w$]+)\(([\w$]+)\)', protocol_owner.text)
        for binding, argument in parse_calls:
            if binding in {b'Uint8Array', b'isNaN'}:
                continue
            try:
                resolved = binding_for(protocol_source, binding.decode(), protocol_owner.start_byte)
            except (ValueError, KeyError):
                continue
            if resolved.get("resolution") == "declaration":
                node = tree_for(protocol_source).root_node.descendant_for_byte_range(resolved["start_byte"], resolved["end_byte"] - 1)
                while node is not None and (node.start_byte != resolved["start_byte"] or node.end_byte != resolved["end_byte"]):
                    node = node.parent
                if node is not None:
                    keep("single_led_serial_result_parser" if name == "getSerialNumber" else "single_led_result_parser", protocol_source, node)

    factory_source, factory = modules[ids["complete_device_adapter_factory"]]
    offset = factory.start_byte + factory.text.index(b'[connectRZDevice]')
    factory_node = tree_for(factory_source).root_node.descendant_for_byte_range(offset, offset)
    while factory_node is not None and factory_node.type not in {"variable_declarator", "function_declaration"}:
        factory_node = factory_node.parent
    if factory_node is None:
        raise ValueError("Legacy receiver actual connection factory is unresolved")
    keep("actual_product_connect_factory", factory_source, factory_node)

    if pid in {158, 192, 194}:
        keep("single_led_actual_connect_factory", factory_source, factory_node)
        base_source, base = modules[ids["complete_base_protocol_framing_lifecycle"]]
        constants_alias = re.search(rb'=([\w$]+)\.SLEEP_TIME_BETWEEN_OUT', base.text)
        if constants_alias is None:
            raise ValueError("Legacy indicator transport defaults require explicit resolution")
        defaults_id = imported_module(base_source, base, constants_alias[1].decode(), "single_led_complete_transport_constants")
        defaults = {}
        for field in ("SLEEP_TIME_BETWEEN_OUT", "SLEEP_TIME_BETWEEN_OUT_IN", "SLEEP_TIME_BETWEEN_IN", "MAX_RETRY_IN", "MAX_RETRY_OUT"):
            _, value = exported(defaults_id, field, "single_led_transport_constant_" + field)
            literal = re.search(rb'=([0-9]+)$', value.text)
            if literal is None:
                raise ValueError("Legacy indicator transport default is not numeric: " + field)
            defaults[field] = int(literal[1])
        main_sources = [source for source in sources if re.search(r'/mw/main\.[^/]+\.js$', source["url"])]
        if len(main_sources) != 1:
            raise ValueError("Legacy indicator mounted middleware main is ambiguous")
        raw = raw_inputs[main_sources[0]["path"]]
        registration = re.search(rb'\.useFeature\("rzDeviceType","rzDevice25"(,\{isDualLinkDevice:!0\})?\)', raw)
        if registration is None:
            raise ValueError("Legacy indicator registered source factory differs")
        keep("single_led_mounted_feature_registration", main_sources[0], tree_for(main_sources[0]).root_node)
        dual = registration[1] is not None
        multiplier = 5 if dual else 1
        if dual and not re.search(rb'5\*[\w$]+\.SLEEP_TIME_BETWEEN_OUT,5\*[\w$]+\.SLEEP_TIME_BETWEEN_OUT_IN,5\*[\w$]+\.SLEEP_TIME_BETWEEN_IN', factory_node.text):
            raise ValueError("Legacy indicator DualLink timing branch differs")
        source, info = exported(ids["complete_product_device_info_and_defaults"], "DeviceInfo", "single_led_device_info")
        fields = {field: int(re.search(rb'(?<![\w$])' + field.encode() + rb':([0-9]+)', info.text)[1]) for field in ("productId", "dongleId", "vendorId", "claimInterface")}
        if fields["productId"] != pid:
            raise ValueError("Legacy indicator product identity differs")
