def _mouse_182_profile_slot_dependencies(audit, selections):
    import host
    receipt = ".analysis/results/frontend/mouse-mw-audit.json"
    prior = json.loads((a.ROOT / receipt).read_bytes())["mouse_dpi_active_slot_chain"]
    if (prior["product_id"] != 182 or prior["failures"] or not prior["snapshot_stable"]
            or not prior["bounded_observation_complete"] or prior["target_execution"]
            or any(selections[side]["acquisition"] != prior["source_sets"][side]["acquisition"]
                for side in ("ui", "mw"))):
        raise ValueError("Mouse182 profile exact inventory source selection requires review")
    upstream = [{"receipt": receipt, "pointer": "/mouse_dpi_active_slot_chain/remaining_chains/1",
        "canonical_sha256": _mouse_182_profile_slot_digest(prior["remaining_chains"][1]),
        "scope": "Continuation boundary only; profile rename does not close remaining CRUD/mapping/macro chains",
        "recaptured": False}]
    reused = {}
    old_owners = {row["id"]: row for row in prior["complete_source_owners"]}
    for role in ("storage_required", "storage_get", "storage_write", "storage_active_guid", "product_bootstrap"):
        row = old_owners[prior["roles"][role]]
        raw = audit.read(row["original"])[row["byte_start"]:row["byte_end"]]
        if raw.decode() != row["body"] or hashlib.sha256(raw).hexdigest() != row["body_sha256"]:
            raise ValueError("Mouse182 profile reused identity/storage owner changed: " + role)
        reused[role] = audit.retain_range("mouse_182_profile_slot_reuse_" + role, row["original"],
            row["byte_start"], row["byte_end"], row["syntax"])
    native_receipt = ".analysis/results/host-current/local-audit.json"
    shared = json.loads((a.ROOT / native_receipt).read_bytes())["mapping_input_producer_eligibility"]
    digest = _mouse_182_profile_slot_digest(shared)
    if (digest != _MOUSE_182_PROFILE_SLOT_NATIVE or shared["failures"] or shared["target_execution"]
            or not shared["selected_static_semantics_reviewed"] or not shared["snapshot_stable"]):
        raise ValueError("Mouse182 profile shared MappingEngine storage section requires review")
    owner = next(row for row in shared["complete_source_owners"]
        if row["id"] == shared["selected"]["host_storage_set"])
    raw = audit.read(owner["original"])[owner["byte_start"]:owner["byte_end"]]
    if raw.decode() != owner["body"] or hashlib.sha256(raw).hexdigest() != owner["body_sha256"]:
        raise ValueError("Mouse182 profile current Host MappingEngine storage bridge changed")
    reused["host_storage_set"] = audit.retain_range("mouse_182_profile_slot_host_storage_set", owner["original"],
        owner["byte_start"], owner["byte_end"], owner["syntax"])
    native = shared["native"]
    if (native["input"]["sha256"] != "c64e539437b50da2b1f2e4155d8cbb0fb1c3e1ebaad894caf509bad97e9857f9"
            or native["input"]["bytes"] != 3948744):
        raise ValueError("Mouse182 profile current MappingEngine native identity changed")
    audit.read(native["input"])
    audit.artifact(a.ROOT / native["capture_receipt"]["path"], native["capture_receipt"])
