    retained = []
    for rva in (0x20920, 0x2fa0, 0x3160, 0xd496c, 0xd4b80, 0x65cc0, 0xe3f10):
        row = functions[rva]
        if not row["input_chunks_verified"] or not row["pseudocode_captured"] or row["failures"]:
            raise ValueError("Mouse182 profile shared native storage owner is incomplete")
        capture = json.loads(audit.artifact(a.ROOT / row["artifact"]["path"], row["artifact"]))
        pseudo = "\n".join(line["text"] for line in capture["pseudocode"]["lines"])
        if hashlib.sha256(pseudo.encode()).hexdigest() != row["pseudocode_text_sha256"]:
            raise ValueError("Mouse182 profile shared native storage interpretation changed")
        retained.append({key: row[key] for key in ("rva", "artifact", "pseudocode_text_sha256")})
    upstream.append({"receipt": native_receipt, "pointer": "/mapping_input_producer_eligibility",
        "canonical_sha256": digest, "recaptured": False, "reused_native_functions": len(retained),
        "scope": "Current Host/native MappingEngine storage publication only; no mouse HID frame or OBM rename is inferred"})
    return upstream, reused, {"input": native["input"], "image_base": native["image_base"],
        "capture_receipt": native["capture_receipt"], "functions": retained}


