    factory("macro_storage_export", [mw], 22152)
    factory("macro_storage", [mw], 255)
    factory("hash_export", [mw], 4849)
    factory("hash", files["mw"], 11936)
    factory("hash_stable_json", [main], 39158)
    factory("hash_md5", [main], 1152)
    factory("buffer", [main], 31797)
    product_name = audit.webpack_export("mouse_182_profile_action_name", files["mw"], 96420, "Ky")
    roles["product_name"] = product_name["binding"]["owner_id"]
    service = host._help_binding_node(audit, main, audit.binding("mouse_182_profile_action_service", main, "E", 65236))
    _, roles["service_showFileSaveDialog"] = audit.callable_member("mouse_182_profile_action_save", main, service, "showFileSaveDialog")
    bound("service_electron_bridge", main, "l", 21546)
    host_receipt = ".analysis/results/host-current/local-audit.json"
    shared = json.loads((a.ROOT / host_receipt).read_bytes())["help_system_info"]
    index, owner = next((i, row) for i, row in enumerate(shared["complete_source_owners"])
        if "system_help_host_save_dialog_and_file_write" in row["roles"])
    if (_mouse_182_profile_action_digest(owner) != _MOUSE_182_PROFILE_ACTION_HOST or shared["failures"]
            or shared["target_execution"] or not shared["snapshot_stable"]):
        raise ValueError("Mouse182 Export current Host save owner requires review")
    keep("host_save", owner)
    upstream.append({"receipt": host_receipt, "pointer": f"/help_system_info/complete_source_owners/{index}",
        "canonical_sha256": _MOUSE_182_PROFILE_ACTION_HOST, "recaptured": False,
        "scope": "Reuse actual Electron save dialog and Node filesystem callback; no business DLL invoked by this action"})
    hmain = owner["original"]
    preload = next(row["original"] for row in shared["complete_source_owners"]
        if "system_help_preload_ffi_async" in row["roles"])
    current_host = host.verified_host_owners(audit, ("electron/main.js", "electron/preload.js"))
    for suffix, reused in (("electron/main.js", hmain), ("electron/preload.js", preload)):
        if any(current_host[suffix]["original"][key] != reused[key] for key in ("path", "bytes", "sha256")):
            raise ValueError("Mouse182 Export reused Host owner is not the current official package member: " + suffix)
    retain("host_dispatch", hmain, 'n.handle("electronAction",', {"call_expression"})
    for name in ("e", "u", "g", "d", "m", "In"):
        bound("host_import_" + name, hmain, name, owner["byte_start"])
    invoke = retain("preload_invoke", preload, "doElectronAction:async", {"pair"})
    bound("preload_ipc", preload, "e", invoke.start_byte)
    retain("preload_expose", preload, 't.exposeInMainWorld("apiElectron",', {"call_expression"})
    return roles, selections, upstream, current_host


