def collect_mouse_182_profile_action_chain(audit):
    roles, selections, upstream, current_host = _mouse_182_profile_action_sources(audit)
    semantics = _mouse_182_profile_action_verify({role: audit.owners[key] for role, key in roles.items()})
    return {"schema_version": 1, "kind": "current_mouse_182_profile_export_action", "product_id": 182,
        "scope": "One actual Profile Export mount, local selection/read/encoding, Host save and result/cancel consumers",
        "roles": roles, "source_sets": selections, "upstream_sections": upstream,
        "complete_host_sources": list(current_host.values()), "semantics": semantics,
        "failures": [], "source_slice_complete": True, "selected_static_semantics_reviewed": True,
        "source_chain_complete": False, "whole_product_complete": False, "target_execution": False,
        "real_device_operations": False, "product_code_modified": False,
        "rust_independent_implementation": "not_reviewed_by_this_query", "ui_backend_wiring": "unverified",
        "official_dll_comparison": "not_executed", "runtime_acceptance": "unverified", "temporary_resources_created": [],
        "remaining_chains": [
            "Current Host save dialog/filesystem outcomes need explicit runtime validation; task completed does not confirm file persistence.",
            "Other PID182 actual profile actions, mappings/macros and OBM inventory remain separate; this Export slice does not close import/reset/remaining CRUD or other products.",
            "Independent Rust, UI/backend lifecycle, pure/mock behavior and actual DLL/device/runtime acceptance remain separate unfinished stages."]}


def audit_mouse_182_profile_action_chain(args):
    import host
    if (args.family != "mouse" or args.function != "mw" or getattr(args, "prepare", False)
            or sorted(set(args.product or [182])) != [182]):
        raise ValueError("mouse-182-profile-action-chain requires PID182 mouse middleware without preparation")
    audit = host.HostLocalAudit()
    report = {"schema_version": 1, "recorded_at_utc": a.stamp(), "parser": audit.parser_versions,
        "kind": "current_mouse_182_profile_export_action", "product_id": 182, "failures": [],
        "bounded_observation_complete": False, "source_chain_complete": False, "whole_product_complete": False,
        "target_execution": False, "real_device_operations": False}
    try:
        for name in ("tools/families.py", "tools/host.py", "tools/frontend.py", "tools/evidence.py"):
            audit.artifact(a.ROOT / name)
        report.update(collect_mouse_182_profile_action_chain(audit))
        report["bounded_observation_complete"] = not report["failures"]
    except (OSError, ValueError, KeyError, IndexError, TypeError, StopIteration) as error:
        report["failures"].append(type(error).__name__ + ": " + str(error))
    changes = audit.final_snapshot() + host._otfm_macro_encoding_dependency_changes(report.get("upstream_sections", []))
    if changes:
        report["failures"].extend("Mouse182 Export source changed during query: " + name for name in changes)
        report["bounded_observation_complete"] = False
    report.update(changed_during_query=changes, snapshot_stable=not changes,
        complete_originals=list(audit.sources.values()), complete_source_owners=list(audit.owners.values()),
        verified_artifacts=list(audit.artifacts.values()))
    destination = a.ROOT / ".analysis/results/frontend/mouse-mw-audit.json"
    host.publish_host_static_query(report, destination, a, "mouse_182_profile_action_chain")
    print(json.dumps({"receipt": a.rel(destination), "query": "mouse-182-profile-action-chain",
        "failures": report["failures"], "bounded_observation_complete": report["bounded_observation_complete"],
        "target_execution": False}), flush=True)
    if report["failures"]:
        raise ValueError("Mouse182 Export source observation remains unresolved")
    return report


