def collect_mouse_182_profile_duplicate_chain(audit):
    roles, selections, upstream, native, recorder = _mouse_182_profile_duplicate_sources(audit)
    semantics = _mouse_182_profile_duplicate_verify({role: audit.owners[key] for role, key in roles.items()})
    return {"product_id": 182, "source_chain_complete": False, "whole_product_complete": False,
        "target_execution": False, "real_device_operations": False,
        "scope": "PID182 mounted Duplicate profile name/GUID, exact stored clone, active diff handoff and result lifecycle",
        "roles": roles, "source_sets": selections, "upstream_sections": upstream,
        "native_storage_dependency": native, "native_recorder_read_dependency": recorder,
        "semantics": semantics, "source_slice_complete": True,
        "selected_static_semantics_reviewed": True, "product_code_modified": False,
        "rust_independent_implementation": "unverified", "ui_backend_wiring": "unverified",
        "official_dll_comparison": "unverified; static native storage and optional recorder-mode read dependencies reused only",
        "runtime_acceptance": "unverified; no application or device executed", "temporary_resources_created": [],
        "remaining_chains": ["PID182 Duplicate static slice only; source acquisition, Rust implementation, UI/backend wiring and actual acceptance remain independent",
            "Other actual PID182 profile actions including Import/Reset and remaining CRUD, mappings/macros and OBM inventory are separate; no other product is closed"]}


def audit_mouse_182_profile_duplicate_chain(args):
    import host
    if (args.family != "mouse" or args.function != "mw" or getattr(args, "prepare", False)
            or sorted(set(args.product or [182])) != [182]):
        raise ValueError("mouse-182-profile-duplicate-chain requires PID182 mouse middleware without preparation")
    audit = host.HostLocalAudit()
    report = {"schema_version": 1, "recorded_at_utc": a.stamp(),
        "parser": audit.parser_versions, "kind": "mouse_182_profile_duplicate_chain", "product_id": 182,
        "failures": [], "bounded_observation_complete": False, "source_chain_complete": False,
        "whole_product_complete": False, "target_execution": False, "real_device_operations": False}
    try:
        for name in ("tools/families.py", "tools/host.py", "tools/frontend.py", "tools/evidence.py"):
            audit.artifact(a.ROOT / name)
        report.update(collect_mouse_182_profile_duplicate_chain(audit))
    except (OSError, ValueError, KeyError, IndexError, TypeError, StopIteration) as error:
        report["failures"].append(type(error).__name__ + ": " + str(error))
