def collect_keyboard_756_calibration_session_chain(audit):
    roles, selections = _keyboard_756_calibration_sources(audit)
    reused, upstream, transport = _keyboard_756_calibration_dependencies(audit, selections["mw"])
    semantics = _keyboard_756_calibration_verify({role: audit.owners[key] for role, key in roles.items()}, audit.parser)
    return {"schema_version": 1, "kind": "current_keyboard_756_calibration_session_chain", "product_id": 756,
        "roles": roles, "source_sets": selections, "reused_source_owners": reused, "upstream_sections": upstream,
        "semantics": semantics, "feature_report_transport": transport, "failures": [],
        "selected_session_semantics_reviewed": True, "selected_static_semantics_reviewed": True,
        "source_slice_complete": True, "source_chain_complete": False, "whole_product_complete": False,
        "target_execution": False, "real_device_operations": False, "product_code_modified": False,
        "rust_independent_implementation": "existing_not_revalidated_by_this_query", "ui_backend_wiring": "unverified",
        "official_dll_comparison": "not_executed", "runtime_acceptance": "unverified",
        "remaining_chains": [
            "Current MappingEngine native registration/provider -> actual notification128 production, failure/cancel/unregister and callback/I/O drain require an exact native source chain; feature HID send/get evidence cannot substitute for it.",
            "Calibration full-list batches, all-data reset and complete switch-type write/restore/reconcile are separate chains. This query only closes session semantics and the current UI restoration handoff.",
            "Other products, BLE/firmware/transport branches, independent Rust commands/observations, UI/backend wiring and official DLL/device comparison remain unfinished; this query implements no product behavior."],
        "cleanup": {"new_temporary_files": [], "new_capture_sessions": [], "new_private_databases": [],
            "existing_inputs_and_formal_receipts_retained": True}}


def audit_keyboard_756_calibration_session_chain(args):
    import host
    if (args.family != "keyboard" or args.function != "mw" or getattr(args, "prepare", False)
            or sorted(set(args.product or [756])) != [756]):
        raise ValueError("keyboard-756-calibration-session-chain requires PID756 keyboard middleware without preparation")
    audit = host.HostLocalAudit()
    report = {"schema_version": 1, "recorded_at_utc": a.stamp(), "parser": audit.parser_versions,
        "kind": "current_keyboard_756_calibration_session_chain", "product_id": 756, "failures": [],
        "bounded_observation_complete": False, "source_chain_complete": False, "whole_product_complete": False,
        "target_execution": False, "real_device_operations": False}
    try:
        for name in ("tools/families.py", "tools/host.py", "tools/frontend.py", "tools/evidence.py"):
            audit.artifact(a.ROOT / name)
        report.update(collect_keyboard_756_calibration_session_chain(audit))
        report["bounded_observation_complete"] = not report["failures"]
    except (OSError, ValueError, KeyError, IndexError, TypeError, StopIteration) as error:
        report["failures"].append(type(error).__name__ + ": " + str(error))
    changed = audit.final_snapshot() + host._otfm_macro_encoding_dependency_changes(report.get("upstream_sections", []))
    if changed:
        report["failures"].extend("Keyboard756 calibration input changed during query: " + name for name in changed)
        report["bounded_observation_complete"] = False
    report.update(changed_during_query=changed, snapshot_stable=not changed,
        complete_originals=list(audit.sources.values()), complete_source_owners=list(audit.owners.values()),
        verified_artifacts=list(audit.artifacts.values()))
    destination = a.ROOT / ".analysis/results/frontend/keyboard-main-audit.json"
