def collect_keyboard_756_switch_type_chain(audit):
    roles, selections, upstream, reused, transport, provider = _keyboard_756_switch_sources(audit)
    semantics = _keyboard_756_switch_verify({role: audit.owners[key] for role, key in roles.items()}, audit.parser)
    return {"schema_version": 1, "kind": "current_keyboard_756_switch_type_chain", "product_id": 756,
        "scope": "Current switch UI/queue/write/serial persistence/reset and travel reconciliation caller semantics",
        "roles": roles, "source_sets": selections, "upstream_sections": upstream, "reused_source_owners": reused,
        "feature_report_transport": transport, "notification_provider_dependency": provider, "semantics": semantics,
        "failures": [], "source_slice_complete": True, "selected_static_semantics_reviewed": True,
        "source_chain_complete": False, "whole_product_complete": False, "target_execution": False,
        "real_device_operations": False, "product_code_modified": False, "new_native_captures": 0,
        "new_analysis_sessions": [], "temporary_files_created": [], "rust_independent_implementation": "existing_not_modified_or_revalidated",
        "ui_backend_wiring": "unverified", "official_dll_comparison": "not_executed", "runtime_acceptance": "unverified",
        "remaining_chains": [
            "Resume40757 changed-profile consumer50574.generateAppEngineFromProfileMapping and selected current756 OBM engine setActuationPoint downstream; reuse existing current mapping/feature transport evidence and only fill unclosed generation/apply or engine-cache/ACK behavior. Analog skip-count refresh native registration is distinct from calibration128 notification provider.",
            "Independent Rust switch/restore/reconcile commands and actual UI/backend consumers remain unimplemented or unverified. Current DLL/device comparisons must exercise partial write/storage/reconcile failure, stale queue/token, restore timeout and cleanup; static source review is not runtime acceptance.",
            "Other products, firmware and transport branches remain separate actual-source work; this PID756 batch does not expand them."]}


def audit_keyboard_756_switch_type_chain(args):
    import host
    if (args.family != "keyboard" or args.function != "mw" or getattr(args, "prepare", False)
            or sorted(set(args.product or [756])) != [756]):
        raise ValueError("keyboard-756-switch-type-chain requires PID756 keyboard middleware without preparation")
    audit = host.HostLocalAudit()
    report = {"schema_version": 1, "recorded_at_utc": a.stamp(), "parser": audit.parser_versions,
        "kind": "current_keyboard_756_switch_type_chain", "product_id": 756, "failures": [],
        "bounded_observation_complete": False, "source_chain_complete": False, "whole_product_complete": False,
        "target_execution": False, "real_device_operations": False}
    try:
        for name in ("tools/families.py", "tools/host.py", "tools/frontend.py", "tools/evidence.py"):
            audit.artifact(a.ROOT / name)
        report.update(collect_keyboard_756_switch_type_chain(audit))
        report["bounded_observation_complete"] = not report["failures"]
    except (OSError, ValueError, KeyError, IndexError, TypeError, StopIteration) as error:
        report["failures"].append(type(error).__name__ + ": " + str(error))
    changes = audit.final_snapshot() + host._otfm_macro_encoding_dependency_changes(report.get("upstream_sections", []))
    if changes:
        report["failures"].extend("Keyboard756 switch source changed during query: " + name for name in changes)
        report["bounded_observation_complete"] = False
    report.update(changed_during_query=changes, snapshot_stable=not changes,
        complete_originals=list(audit.sources.values()), complete_source_owners=list(audit.owners.values()),
        verified_artifacts=list(audit.artifacts.values()))
    destination = a.ROOT / ".analysis/results/frontend/keyboard-main-audit.json"
    host.publish_host_static_query(report, destination, a, "keyboard_756_switch_type_chain")
    print(json.dumps({"receipt": a.rel(destination), "query": "keyboard-756-switch-type-chain",
        "failures": report["failures"], "bounded_observation_complete": report["bounded_observation_complete"],
        "target_execution": False}), flush=True)
    if report["failures"]:
        raise ValueError("Keyboard756 switch source observation remains unresolved")
    return report


