def _keyboard_756_appengine_sources(audit):
    import frontend
    import host
    receipt = ".analysis/results/frontend/keyboard-main-audit.json"
    prior = json.loads((a.ROOT / receipt).read_bytes())["keyboard_756_switch_type_chain"]
    if (_keyboard_756_batch_digest(prior) != _KEYBOARD_756_APPENGINE_UPSTREAM
            or _keyboard_756_batch_digest(prior["remaining_chains"][0]) != _KEYBOARD_756_APPENGINE_REMAINING
            or prior["failures"] or not prior["snapshot_stable"]
            or not prior["bounded_observation_complete"] or prior["target_execution"]):
        raise ValueError("Keyboard756 AppEngine exact switch continuation requires review")
    upstream = [{"receipt": receipt, "pointer": "/keyboard_756_switch_type_chain",
        "canonical_sha256": _KEYBOARD_756_APPENGINE_UPSTREAM, "recaptured": False},
        {"receipt": receipt, "pointer": "/keyboard_756_switch_type_chain/remaining_chains/0",
        "canonical_sha256": _KEYBOARD_756_APPENGINE_REMAINING, "recaptured": False}]
    upstream.extend(prior["upstream_sections"])
    shared_receipt = ".analysis/results/host-current/local-audit.json"
    document = json.loads((a.ROOT / shared_receipt).read_bytes())
    for section, digest in _KEYBOARD_756_APPENGINE_SHARED.items():
        row = document[section]
        if (_keyboard_756_batch_digest(row) != digest or row["failures"] or row["target_execution"]
                or not row["snapshot_stable"] or not row["selected_static_semantics_reviewed"]):
            raise ValueError("Keyboard756 AppEngine shared section needs review: " + section)
        upstream.append({"receipt": shared_receipt, "pointer": "/" + section,
            "canonical_sha256": digest, "recaptured": False})
    changes = host._otfm_macro_encoding_dependency_changes(upstream)
    if changes:
        raise ValueError("Keyboard756 AppEngine shared evidence changed: " + repr(changes))
    roles, selections, files, reused = {}, {}, {}, {}

    def keep(role, row, *, shared=False):
        raw = audit.read(row["original"])[row["byte_start"]:row["byte_end"]]
        if raw.decode() != row["body"] or hashlib.sha256(raw).hexdigest() != row["body_sha256"]:
            raise ValueError("Keyboard756 AppEngine reused owner changed: " + role)
        owner = audit.retain_range("keyboard_756_appengine_" + role, row["original"],
            row["byte_start"], row["byte_end"], row["syntax"])
        roles[role] = owner
        if shared:
            reused[role] = {"owner_id": owner, "recaptured": False}
        return host._help_binding_node(audit, row["original"], {"resolution": "declaration",
            "start_byte": row["byte_start"], "end_byte": row["byte_end"]})

    def factory(role, candidates, module):
        matches = audit.webpack_factories(candidates, module)
        if len(matches) != 1:
            raise ValueError("Keyboard756 AppEngine actual factory absent or ambiguous: " + role)
        source, node, _ = matches[0]
        roles[role] = audit.retain_range("keyboard_756_appengine_" + role, source,
            node.start_byte, node.end_byte, node.type)
        return source, node

    def exported(role, candidates, module, name):
        value = audit.webpack_export("keyboard_756_appengine_" + role, candidates, module, name)
        roles[role] = value["binding"]["owner_id"]
        return value["original"], host._help_binding_node(audit, value["original"], value["binding"])

    def retain(role, source, anchor, kinds):
        roles[role], = audit.retain("keyboard_756_appengine_" + role, source, anchor, kinds)

    for side, stem in (("ui", "keyboard-756-current"), ("mw", "keyboard-mw-756-current")):
        selected = frontend.current_source_selection(f"https://apps.razer.com/synapse/products/756/{side}/", audit,
            candidates=sorted((a.ROOT / ".analysis/inputs/frontend").glob(stem + "*/acquisition.json")),
            verify_capture=False)
        if selected["acquisition"] != prior["source_sets"][side]["acquisition"]:
            raise ValueError("Keyboard756 AppEngine current selection changed: " + side)
        selections[side] = {key: selected[key] for key in ("name", "acquisition", "candidate_decisions",
            "capture_failures", "failed_acquisition", "unresolved_acquisition")}
        files[side] = selected["originals"]
    old = {row["id"]: row for row in prior["complete_source_owners"]}
    for role in ("product_registration", "reconcile", "profile_clamp", "travel_helpers",
            "travel_owner", "firmware_mapping_conversion", "storage", "storage_hook"):
        keep(role, old[prior["roles"][role]])
    shared = document["mapping_input_producer_eligibility"]
    previous = {row["id"]: row for row in shared["complete_source_owners"]}
    for role in ("setup_environment", "cleanup_device", "pre_storage_hook", "post_storage_hook",
            "storage_hook_invocation", "mapping_storage_deduplication", "facade_storage_set",
            "facade_mapping_action", "host_storage_set"):
        keep(role, previous[shared["selected"][role]], shared=True)
    generator_source, generator = exported("generator", files["mw"], 50574, "generateAppEngineFromProfileMapping")
    for name in ("wp", "H", "V", "I", "d"):
        value = audit.binding("keyboard_756_appengine_generator_import_" + name,
            generator_source, name, generator.start_byte)
        roles["generator_import_" + name] = value["owner_id"]
    factory("input_transform", [generator_source], 6258)
    factory("self_mapping_repair", [generator_source], 42656)
    factory("compiler_wrapper", [generator_source], 32226)
    compiler_source, compiler, _ = audit.webpack_factories(files["mw"], 9299)[0]
    for name in ("setSynapseTurbos", "generateDefaultTurbos", "generateAppEngineMappings", "getAppEngineMapping",
            "getAnalogMapping", "generateAnalogMappings", "generateAppEngineAnalogMappings"):
        _, roles[name] = audit.callable_member("keyboard_756_appengine_" + name,
            compiler_source, compiler, name)
    retain("compiler_singleton", compiler_source, "yt=t.RzAppEngineMapping_default=new ct", {"assignment_expression"})
    factory("hash_wrapper", [generator_source], 4849)
    hash_source, _, _ = audit.webpack_factories(files["mw"], 59713)[0]
    retain("hash", hash_source, 't.getHash=(e,t=["hash","gamemode"])', {"assignment_expression"})
    exported("device_info", files["mw"], 26061, "DeviceInfo")
    selected_obm_source, _ = factory("obm_selected", files["mw"], 48363)
    factory("obm_cal", [selected_obm_source], 96236)
    obm_source, obm, _ = audit.webpack_factories(files["mw"], 2050)[0]
    setter, roles["obm_setActuationPoint"] = audit.callable_member("keyboard_756_appengine_obm_setActuationPoint",
        obm_source, obm, "setActuationPoint")
    current_class = setter
    while current_class is not None and current_class.type not in {"class", "class_declaration"}:
        current_class = current_class.parent
    if current_class is None:
        raise ValueError("Keyboard756 AppEngine actual OBM class is absent")
    for name in ("init", "batchSetButtonAssignmentsProperty"):
        _, roles["obm_" + name] = audit.callable_member("keyboard_756_appengine_obm_" + name,
            obm_source, current_class, name)
    exported("obm_result", [generator_source], 64116, "Oh")
    for name in ("iPi", "sO5", "MzU"):
        exported("header_" + name, [generator_source], 48967, name)
    for name in ("E4", "l7", "Jz"):
        exported("wire_" + name, files["mw"], 28277, name)
    protocol = next(row["original"] for row in prior["complete_source_owners"]
        if row["id"] == prior["roles"]["switch_protocol"])
    retain("actuation_protocol", protocol, "setMultiAnalogKeyActuationPoint(t,n,e){", {"method_definition"})
    retain("actuation_parser", protocol, "$=t=>{if(t.status===i.STATUS_SUCCESS&&t.packetSizeReturned>0)",
        {"variable_declarator"})
    runtime_source, runtime = exported("runtime_publish", [generator_source], 51765, "saveDeviceDataToWindowStorage")
    for name in ("re", "oe", "se"):
        value = audit.binding("keyboard_756_appengine_runtime_" + name, runtime_source, name, runtime.start_byte)
        roles["runtime_" + name] = value["owner_id"]
    factory("game_mode_wrapper", [generator_source], 9825)
    gm_source, gm, _ = audit.webpack_factories(files["mw"], 1101)[0]
    _, roles["game_mode_projection"] = audit.callable_member("keyboard_756_appengine_game_mode_projection",
        gm_source, gm, "getKeyMappingForGameMode", receiver="t")
    transport_roles, _, transport = _keyboard_756_calibration_dependencies(audit, selections["mw"])
    for role, owner in transport_roles.items():
        roles[role] = owner
        reused[role] = {"owner_id": owner, "recaptured": False}
    native = shared["native"]
    if (native["input"]["sha256"] != "c64e539437b50da2b1f2e4155d8cbb0fb1c3e1ebaad894caf509bad97e9857f9"
            or native["input"]["bytes"] != 3948744):
        raise ValueError("Keyboard756 AppEngine current MappingEngine native identity changed")
    audit.read(native["input"])
    audit.artifact(a.ROOT / native["capture_receipt"]["path"], native["capture_receipt"])
    functions = {int(row["rva"], 16): row for row in native["complete_selected_functions"]}
    native_references = []
    for rva in (0x20920, 0x2fa0, 0x3160, 0xd496c, 0xd4b80, 0x65cc0, 0xe3f10):
        row = functions[rva]
        if row["failures"] or not row["input_chunks_verified"] or not row["pseudocode_captured"]:
            raise ValueError("Keyboard756 AppEngine shared storage native boundary is incomplete")
        capture = json.loads(audit.artifact(a.ROOT / row["artifact"]["path"], row["artifact"]))
        pseudo = "\n".join(line["text"] for line in capture["pseudocode"]["lines"])
        if hashlib.sha256(pseudo.encode()).hexdigest() != row["pseudocode_text_sha256"]:
            raise ValueError("Keyboard756 AppEngine shared native interpretation changed")
        native_references.append({key: row[key] for key in ("rva", "artifact", "pseudocode_text_sha256")})
    return roles, selections, upstream, reused, transport, {
        "input": native["input"], "capture_receipt": native["capture_receipt"],
        "functions": native_references, "recaptured": False,
        "scope": "Current PID756 producer eligibility/storage queue/USB publication and analog result consumers reuse exact shared sections; no new native capture"}


