def _gamepad_profile_import_dependencies(audit):
    receipt = ".analysis/results/frontend/gamepad-mw-audit.json"
    document = json.loads((a.ROOT / receipt).read_bytes())
    upstream, reused, owners = [], {}, {}
    selections = {
        "profile_reset_chain": ("reimport_entry", "engine_guard", "import_guard", "engine_initialize_once",
            "import_metadata_entry", "clear_import_guard", "profile_defaults_provider", "device_defaults_provider", "device_defaults"),
        "profile_apply_chain": ("profile_default", "generic_manager", "runtime_apply", "runtime_identity",
            "getter_and_ui_circularity", "getter_and_ui_analog", "getter_and_ui_deadzone", "getter_and_ui_digital",
            "getter_and_ui_diagonals", "getter_and_ui_sensitivity"),
        "obm_mapping_chain": ("product_bootstrap", "product_mapping_overrides", "storage_override", "profile_storage",
            "serial_profile_storage", "storage_set", "storage_active_profile", "runtime_profile_update",
            "engine_init", "engine_getAllButtonAssignmentInfo", "engine_createButtonMappingFromFnDataByte",
            "product_DEFAULTMAPPINGS", "ui_reducer", "ui_obm_reducer"),
        "polling_native_chain": ("initial_import_gate", "connect_import_gate", "import_profile_fields", "import_field_dispatch",
            "import_polling_feature", "import_save", "import_update_ui", "getter", "storage_get")}
    for section, expected in _GAMEPAD_PROFILE_IMPORT_DEPENDENCIES.items():
        current = document[section]
        if (_gamepad_profile_apply_digest(current) != expected or current.get("product_id") != 2636
                or current.get("failures") or not current.get("bounded_observation_complete")
                or not current.get("snapshot_stable") or current.get("target_execution") is not False):
            raise ValueError("Gamepad profile import current dependency needs review: " + section)
        upstream.append({"receipt": receipt, "pointer": "/" + section, "canonical_sha256": expected, "recaptured": False})
        indexed = {row["id"]: row for row in current["complete_source_owners"]}
        for role in selections[section]:
            row = indexed[current["roles"][role]]
            raw = audit.read(row["original"])[row["byte_start"]:row["byte_end"]]
            if raw.decode() != row["body"] or hashlib.sha256(raw).hexdigest() != row["body_sha256"]:
                raise ValueError("Gamepad profile import reused current owner bytes differ: " + role)
            owners[role] = row
            reused[role] = {"receipt": receipt, "pointer": "/" + section + "/roles/" + role,
                **{key: row[key] for key in ("id", "original", "syntax", "byte_start", "byte_end", "body_sha256")}}
    current = document["profile_apply_chain"]
    indexed = {row["id"]: row for row in current["complete_source_owners"]}
    for role in ("protocol_getBrightness", "brightness_getter", "lighting_feature", "haptic_feature"):
        row = indexed[current["feature_chains"]["roles"][role]]
        raw = audit.read(row["original"])[row["byte_start"]:row["byte_end"]]
        if raw.decode() != row["body"] or hashlib.sha256(raw).hexdigest() != row["body_sha256"]:
            raise ValueError("Gamepad profile import reused feature bytes differ: " + role)
        owners[role] = row
        reused[role] = {"receipt": receipt, "pointer": "/profile_apply_chain/feature_chains/roles/" + role,
            **{key: row[key] for key in ("id", "original", "syntax", "byte_start", "byte_end", "body_sha256")}}
    for row in document["profile_reset_chain"]["upstream_sections"]:
        if not any((row["receipt"], row["pointer"]) == (item["receipt"], item["pointer"]) for item in upstream):
            upstream.append(row)
    return document, upstream, reused, owners


def _gamepad_profile_import_sources(audit, document, reused):
    import frontend
    import host
    roles, layers, selections = {}, {}, {}

    def keep(role, source, node):
        roles[role] = audit.retain_range("gamepad_profile_import_" + role, source,
            node.start_byte, node.end_byte, node.type)
        return node

    def bound(role, source, name, at):
        value = audit.binding("gamepad_profile_import_" + role, source, name, at)
        return keep(role, source, host._help_binding_node(audit, source, value))

    def exported(role, side, module, name):
        value = audit.webpack_export("gamepad_profile_import_" + role, layers[side], module, name)
        return value["original"], keep(role, value["original"],
            host._help_binding_node(audit, value["original"], value["binding"]))

    for side, stem in (("mw", "gamepad-mw-2636-current"), ("ui", "gamepad-2636-current")):
        current = frontend.current_source_selection(f"https://apps.razer.com/synapse/products/2636/{side}/", audit,
            candidates=sorted((a.ROOT / ".analysis/inputs/frontend").glob(stem + "*/acquisition.json")), verify_capture=False)
        if current["acquisition"] != document["profile_reset_chain"]["source_sets"][side]["acquisition"]:
            raise ValueError("Gamepad profile import deployment differs from reviewed current reset: " + side)
        layers[side] = current["originals"]
        selections[side] = {key: current[key] for key in ("name", "acquisition", "candidate_decisions",
            "capture_failures", "failed_acquisition", "unresolved_acquisition")}
    main = {side: next(row for row in rows if re.fullmatch(r"main\.[^.]+\.js", Path(row["path"]).name))
            for side, rows in layers.items()}
    mw = main["mw"]
    reference = reused["reimport_entry"]["byte_start"]
    for role, name in (("root_dispatch", "x"), ("root_skip", "V"), ("profile_skip", "W"),
            ("preserve_rules", "z"), ("preserve_local", "ee"), ("mapping_import", "f"),
            ("mapping_read", "v"), ("mapping_filter", "y"), ("root_power_import", "I"),
            ("brightness_import", "N"), ("quick_effects_import", "F"), ("haptic_import", "P"), ("audio_haptic_import", "L")):
        bound(role, mw, name, reference)
    for role, module, name in (("directory_reconcile", 31759, "eL"), ("directory_ids", 31759, "Hf"),
            ("directory_active", 31759, "bu"), ("directory_names", 31759, "GY"), ("directory_count", 31759, "rf"),
            ("read_document", 77846, "d8"), ("save_serial_active", 77846, "kS"),
            ("save_profile_stack", 96183, "EA"), ("runtime_publish", 50350, "pH"),
            ("ui_publish", 47399, "Q"), ("controller_lighting_import", 70784, "RM"),
            ("controller_haptic_import", 47442, "RJ"), ("root_power_getter", 87887, "S9")):
        exported(role, "mw", module, name)
    exported("profile_stack", "mw", 34791, "tf")
    exported("profile_stack_save", "mw", 34791, "Se")
    bound("runtime_metadata_gate", mw, "ge", reused["runtime_profile_update"]["byte_start"])
    bound("runtime_metadata_merge", mw, "me", reused["runtime_profile_update"]["byte_start"])
    for role, at, name in (("stack_import", roles["save_profile_stack"], "v"),
            ("directory_function_import", reused["reimport_entry"]["id"], "$")):
        offset = audit.owners[at]["byte_start"] if at in audit.owners else reference
        bound(role, mw, name, offset)
    engine = document["obm_mapping_chain"]
    indexed = {row["id"]: row for row in engine["complete_source_owners"]}
    row = indexed[engine["roles"]["obm_engine"]]
    root = audit.tree(row["original"]).root_node.descendant_for_byte_range(row["byte_start"], row["byte_end"] - 1)
    for name in ("getProfileIDList", "getActiveProfileID", "getProfileNameList", "getNumberOfProfiles"):
        node, _ = audit.callable_member("gamepad_profile_import_cached_" + name, row["original"], root, name)
        keep("cached_" + name, row["original"], node)
    for side, module in (("mw", 67061), ("ui", 13254)):
        for name in ("N_y", "XAX", "Bj5", "stD"):
            exported(side + "_event_" + name, side, module, name)
    return {"roles": roles, "source_sets": selections, "reviewed_inputs": main}


def _gamepad_profile_import_fields(owner, parser, *, array=False):
    raw = owner["body"].encode()
    root = parser.parse(raw).root_node
    values = []
    stack = [root]
    target = None
    while stack:
        node = stack.pop()
        if node.type == ("array" if array else "object"):
            target = node
            break
        stack.extend(reversed(node.named_children))
    if target is None:
        raise ValueError("Gamepad profile import field definition has no static boundary")
    for item in target.named_children:
        if array:
            if item.type != "string":
                raise ValueError("Gamepad profile import exclusion is not a literal string")
            values.append(json.loads(item.text))
        else:
            key = item.child_by_field_name("key")
            if item.type != "pair" or key is None or key.type not in {"property_identifier", "string"}:
                raise ValueError("Gamepad profile import field key is not static")
            values.append(json.loads(key.text) if key.type == "string" else key.text.decode())
    if len(values) != len(set(values)):
        raise ValueError("Gamepad profile import field definition contains duplicate keys")
    return values


