def collect_gamepad_profile_import_chain(audit):
    document, upstream, reused, prior = _gamepad_profile_import_dependencies(audit)
    result = _gamepad_profile_import_sources(audit, document, reused)
    owners = {**prior, **{role: audit.owners[key] for role, key in result["roles"].items()}}
    result["semantics"] = _gamepad_profile_import_contract(owners, reused, audit.parser)
    result.update(kind="current_gamepad_profile_import_chain", product_id=2636, failures=[],
        upstream_sections=upstream, reused_source_owners=reused, source_slice_complete=True,
        selected_static_semantics_reviewed=True, source_chain_complete=False, whole_product_complete=False,
        target_execution=False, real_device_operations=False, product_code_modified=False,
        rust_independent_implementation="unverified", ui_backend_wiring="unverified", runtime_acceptance="unverified",
        remaining_chains=["This PID2636 current import orchestration reuses exact formal mapping/polling/profile getter owners; no other product/firmware/transport or full notification/lifecycle closure is inferred.",
            "Actual getter outcomes, partial-source defaults, cached engine reuse and save/runtime/UI side effects require official DLL/device comparison; cancellation, old-connection rejection and shared callback/I/O drain remain unverified.",
            "Existing Rust initialization/conversion evidence is preserved separately; complete independent Rust migration, all production callers, UI/backend wiring and runtime acceptance are not established by this static batch."])
    return result


def audit_gamepad_profile_import_chain(args):
    import host
    if (args.family != "gamepad" or args.function != "mw" or getattr(args, "prepare", False)
            or sorted(set(args.product or [2636])) != [2636]):
        raise ValueError("gamepad-profile-import-chain requires PID2636 gamepad middleware without preparation")
    audit = host.HostLocalAudit()
    report = {"schema_version": 1, "recorded_at_utc": a.stamp(), "parser": audit.parser_versions,
        "kind": "current_gamepad_profile_import_chain", "product_id": 2636, "failures": [],
        "bounded_observation_complete": False, "source_chain_complete": False, "whole_product_complete": False,
        "target_execution": False, "real_device_operations": False, "rust_implementation": "not_reviewed",
        "official_dll_comparison": "not_executed", "runtime_acceptance": "unverified"}
    try:
        for name in ("tools/families.py", "tools/host.py", "tools/frontend.py", "tools/evidence.py"):
            audit.artifact(a.ROOT / name)
        report.update(collect_gamepad_profile_import_chain(audit))
        report["bounded_observation_complete"] = not report["failures"]
    except (OSError, ValueError, KeyError, IndexError, TypeError, StopIteration) as error:
        report["failures"].append(type(error).__name__ + ": " + str(error))
    changed = audit.final_snapshot() + _gamepad_profile_apply_upstream_changes(report.get("upstream_sections", []))
    if changed:
        report["failures"].extend("Gamepad profile import source changed during query: " + name for name in changed)
        report["bounded_observation_complete"] = False
    report.update(changed_during_query=changed, snapshot_stable=not changed,
        complete_originals=list(audit.sources.values()), complete_source_owners=list(audit.owners.values()),
        verified_artifacts=list(audit.artifacts.values()))
    destination = a.ROOT / ".analysis/results/frontend/gamepad-mw-audit.json"
    host.publish_host_static_query(report, destination, a, "profile_import_chain")
    print(json.dumps({"receipt": a.rel(destination), "query": "gamepad-profile-import-chain", "failures": report["failures"],
        "bounded_observation_complete": report["bounded_observation_complete"], "target_execution": False}), flush=True)
    if report["failures"]:
        raise ValueError("Gamepad profile import source observation remains unresolved")
    return report


