def audit_gamepad_2636_profile_lifecycle_chain(args):
    import host
    if (args.family != "gamepad" or args.function != "mw" or getattr(args, "prepare", False)
            or sorted(set(args.product or [2636])) != [2636]):
        raise ValueError("gamepad-2636-profile-lifecycle-chain requires PID2636 middleware without preparation")
    audit = host.HostLocalAudit()
    report = {"schema_version": 1, "recorded_at_utc": a.stamp(), "parser": audit.parser_versions,
        "kind": "current_gamepad_2636_profile_lifecycle_chain", "product_id": 2636, "failures": [],
        "bounded_observation_complete": False, "source_chain_complete": False, "whole_product_complete": False,
        "target_execution": False, "real_device_operations": False, "rust_implementation": "not_reviewed",
        "official_dll_comparison": "not_executed", "runtime_acceptance": "unverified"}
    try:
        for name in ("tools/families.py", "tools/host.py", "tools/frontend.py", "tools/evidence.py"):
            audit.artifact(a.ROOT / name)
        report.update(collect_gamepad_2636_profile_lifecycle_chain(audit))
        report["bounded_observation_complete"] = not report["failures"]
    except (OSError, ValueError, KeyError, IndexError, TypeError, StopIteration) as error:
        report["failures"].append(type(error).__name__ + ": " + str(error))
    changed = audit.final_snapshot() + _gamepad_profile_apply_upstream_changes(report.get("upstream_sections", []))
    if changed:
        report["failures"].extend("Gamepad2636 profile lifecycle source changed during query: " + name for name in changed)
        report["bounded_observation_complete"] = False
    report.update(changed_during_query=changed, snapshot_stable=not changed,
        complete_originals=list(audit.sources.values()), complete_source_owners=list(audit.owners.values()),
        verified_artifacts=list(audit.artifacts.values()))
    destination = a.ROOT / ".analysis/results/frontend/gamepad-mw-audit.json"
    host.publish_host_static_query(report, destination, a, "profile_lifecycle_2636_chain")
    print(json.dumps({"receipt": a.rel(destination), "query": "gamepad-2636-profile-lifecycle-chain",
        "failures": report["failures"], "bounded_observation_complete": report["bounded_observation_complete"],
        "target_execution": False}), flush=True)
    if report["failures"]:
        raise ValueError("Gamepad2636 profile lifecycle source observation remains unresolved")
    return report


