    audit = host.HostLocalAudit()
    report = {"schema_version": 1, "kind": "current_gamepad_2636_removal_notification_chain", "product_id": 2636,
        "failures": [], "bounded_observation_complete": False, "source_chain_complete": False,
        "whole_product_complete": False, "target_execution": False, "runtime_acceptance": "unverified"}
    try:
        for name in ("tools/families.py", "tools/host.py", "tools/frontend.py", "tools/evidence.py"):
            audit.artifact(a.ROOT / name)
        report.update(collect_gamepad_2636_removal_notification_chain(audit))
    except (OSError, ValueError, KeyError, IndexError, TypeError, StopIteration) as error:
        report["failures"].append(type(error).__name__ + ": " + str(error))
    changed = audit.final_snapshot() + _gamepad_profile_apply_upstream_changes(report.get("upstream_sections", []))
    report["failures"].extend("Gamepad2636 removal notification input changed: " + name for name in changed)
    report.update(recorded_at_utc=a.stamp(), changed_during_query=changed, snapshot_stable=not changed,
        complete_originals=list(audit.sources.values()), complete_source_owners=list(audit.owners.values()),
        verified_artifacts=list(audit.artifacts.values()))
    report["bounded_observation_complete"] = not report["failures"] and not changed and report.get("source_slice_complete", False)
    destination = a.ROOT / ".analysis/results/frontend/gamepad-mw-audit.json"
    host.publish_host_static_query(report, destination, a, "gamepad_2636_removal_notification_chain")
    print(json.dumps({"receipt": a.rel(destination), "query": "gamepad-2636-removal-notification-chain",
        "failures": report["failures"], "bounded_observation_complete": report["bounded_observation_complete"],
        "target_execution": False}), flush=True)
    if not report["bounded_observation_complete"]:
        raise ValueError("Gamepad2636 removal notification source observation remains unresolved")
    return report


