def _gamepad_2636_detection_data_contract(raw):
    import host
    pe = host.inspect_pe(raw)
    if (pe["architecture"] != "x64" or pe["image_base"] != "0x180000000" or pe["exports"]):
        raise ValueError("Gamepad2636 detector PE/Node registration boundary differs")
    expected = (
        ("node_module_descriptor", 0x45cd0,
            "91000000000000000000000000000000c0d90380010000000049008001000000"
            "000000000000000020da03800100000000000000000000000000000000000000"),
        ("crt_node_module_initializer", 0x303f8, "0010008001000000"),
        ("usb_device_interface_guid", 0x45cc0, "10bfdca53065d211901f00c04fb951ed"),
        ("bus_reported_description_property", 0x3e048, "7e940b54408bbc45a8a26a0b894cbda204000000"),
        ("container_id_property", 0x3e060, "06d27e8c8a3f2748b3abae9e1faefc6c02000000"))
    spans = []
    for role, rva, encoded in expected:
        value = bytes.fromhex(encoded)
        section = next((row for row in pe["sections"] if row["rva"] <= rva
            and rva + len(value) <= row["rva"] + row["bytes"]), None)
        if section is None:
            raise ValueError("Gamepad2636 detector PE data boundary is absent: " + role)
        offset = section["file_offset"] + rva - section["rva"]
        if raw[offset:offset + len(value)] != value:
            raise ValueError("Gamepad2636 detector PE data binding differs: " + role)
        spans.append({"role": role, "rva": hex(rva), "file_offset": offset,
            "bytes": len(value), "raw_hex": encoded, "actual_pe_bytes_verified": True})
    imports = {row["library"].lower(): [symbol.get("name") for symbol in row["symbols"]]
        for row in pe["imports"] + pe["delay_imports"]}
    if ("node_module_register" not in imports.get("node.exe", [])
            or not {"uv_queue_work", "uv_signal_init", "uv_signal_start", "uv_signal_stop", "uv_default_loop"}
                <= set(imports.get("node.exe", []))
            or not {"RegisterDeviceNotificationA", "UnregisterDeviceNotification", "GetMessageA",
                "PostMessageA", "DestroyWindow", "UnregisterClassA"} <= set(imports.get("user32.dll", []))):
        raise ValueError("Gamepad2636 detector actual import boundary differs")
    return {"spans": spans, "node_module_version_field": 145, "initializer_rva": "0x4900",
        "node_module_registration_rva": "0x1000", "callback_trampoline_rva": "0x12f0",
        "usb_interface_guid": "a5dcbf10-6530-11d2-901f-00c04fb951ed",
        "bus_reported_description_property": {"guid": "540b947e-8b40-45bc-a8a2-6a0b894cbda2", "pid": 4},
        "container_id_property": {"guid": "8c7ed206-3f8a-4827-b3ab-ae9e1faefc6c", "pid": 2},
        "imports": imports, "target_execution": False}


def _gamepad_2636_detection_native_verify(native):
    roles = _gamepad_2636_detection_native_roles()
    selected = native["complete_selected_functions"]
    if (native["input"]["sha256"] != "4ad56ab79f039f5146f6193e5020ee0aea080469212b8d3f8e3d2f67b2e5ca5c"
            or native["input"]["bytes"] != 304328 or native["image_base"] != "0x180000000"
            or not native["capture_complete"] or native["target_execution"]
            or len(selected) != len(roles)
            or {int(row["capture"]["rva"], 0): row["role"] for row in selected} != roles):
        raise ValueError("Gamepad2636 detector native selection is incomplete or changed")
    manifest = []
    for row in selected:
        body = row["capture"]
        if (row["failures"] or not row["assembly_captured"] or not row["pseudocode_captured"]
                or not row["input_chunks_verified"] or not body.get("pseudocode") or not body["assembly"]):
            raise ValueError("Gamepad2636 detector selected function is incomplete: " + body["rva"])
        manifest.append({"role": row["role"], "rva": body["rva"], "artifact": row["artifact"],
            "pseudocode_text_sha256": hashlib.sha256("\n".join(line["text"] for line in
                body["pseudocode"]["lines"]).encode()).hexdigest(),
            "assembly_text_sha256": hashlib.sha256("\n".join(line["text"] for line in body["assembly"]).encode()).hexdigest(),
            "input_chunks_verified": True})
    digest = _gamepad_profile_apply_digest(manifest)
    if digest != "a42692e69b6ba895d6719945072b08143425e9c4e659cf80f5b9752dc8bee411":
        raise ValueError("Gamepad2636 detector reviewed native bodies differ: " + digest)
    failures = native["failures"]
    if (len(failures) != 1 or failures[0]["stage"] != "20668:hexrays"
            or failures[0]["error"] != "Hex-Rays returned no function: call analysis failed (code -12, address 0x1800206f5)"):
        raise ValueError("Gamepad2636 detector unselected capture failure boundary changed")
    return manifest, digest


def _gamepad_2636_detection_global_references(audit, native):
    capture = json.loads(audit.artifact(a.ROOT / native["capture_receipt"]["path"], native["capture_receipt"]))
    aggregate, = [row for row in capture["outputs"] if row["path"] == "all-functions.asm"]
    if aggregate["sha256"] != "1bab278f652fb96c77f6869525c534937b137497f334480923a04de60c06e1ab":
        raise ValueError("Gamepad2636 detector full assembly reference boundary changed")
    artifact = {**aggregate, "path": str(Path(native["capture_receipt"]["path"]).parent / aggregate["path"]).replace("\\", "/")}
    text = audit.artifact(a.ROOT / artifact["path"], artifact).decode()
    refs = {name: [] for name in ("qword_180047A80", "byte_180047A71", "hEvent", "hHandle", "qword_180047D60")}
    owner = None
    for line in text.splitlines():
        if line.startswith("; ") and " RVA " in line:
            owner = line.split(" RVA ", 1)[1].split()[0]
        elif line.startswith("0x"):
            instruction = line.split("  ", 2)[2].split(";", 1)[0]
            for name in refs:
                if re.search(r"\bcs:" + re.escape(name) + r"\b", instruction):
                    refs[name].append({"owner_rva": owner, "address": line.split()[0], "instruction": instruction.rstrip()})
    expected = {"qword_180047A80": {"0x28d0", "0x29f0"}, "byte_180047A71": {"0x28d0", "0x29f0"},
        "hEvent": {"0x8b10", "0x8c20", "0x8ce0", "0x95c0"},
        "hHandle": {"0x8b70", "0x8ce0", "0x95c0"},
        "qword_180047D60": {"0x1010", "0x2f140", "0x50f0", "0x51f0", "0x54b0", "0x57d0", "0x80e0", "0x8e90"}}
    if any({row["owner_rva"] for row in refs[name]} != owners for name, owners in expected.items()):
        raise ValueError("Gamepad2636 detector callback/event/cache references changed")
    failed, = [row for row in capture["functions"] if row["rva"] == "0x20668"]
    failed_artifact = {"path": str(Path(native["capture_receipt"]["path"]).parent / failed["path"]).replace("\\", "/"),
        "sha256": failed["sha256"]}
    failed_raw = audit.artifact(a.ROOT / failed_artifact["path"])
    if hashlib.sha256(failed_raw).hexdigest() != failed_artifact["sha256"]:
        raise ValueError("Gamepad2636 detector retained unselected failure record changed")
    failed_artifact["bytes"] = len(failed_raw)
    return {"assembly_artifact": artifact, "direct_references": refs,
        "unselected_failure_artifact": failed_artifact,
        "failure_scope": "0x20668 retains complete assembly and original chunks; its Hex-Rays failure is outside the selected notification owners and is not promoted to semantic success",
        "source_database_required_by_this_query": False, "reserved_source_database_dependencies": [],
        "private_database_disposition": "No selected semantic or registered continuation depends on this private database; retained original/capture/failure assembly reproduce the analysis"}


