def audit_gamepad_2636_detection_native_chain(args):
    import host
    if (args.family != "gamepad" or args.function != "mw" or (args.product or [2636]) != [2636]
            or getattr(args, "prepare", False)):
        raise ValueError("Gamepad2636 detector native query requires gamepad/mw PID2636 without preparation")
    audit = host.HostLocalAudit()
    report = {"schema_version": 1, "kind": "current_gamepad_2636_detection_native_chain", "product_id": 2636,
        "failures": [], "bounded_observation_complete": False, "source_chain_complete": False,
        "whole_product_complete": False, "target_execution": False, "runtime_acceptance": "unverified"}
    try:
        for name in ("tools/families.py", "tools/host.py", "tools/frontend.py", "tools/evidence.py"):
            audit.artifact(a.ROOT / name)
        report.update(collect_gamepad_2636_detection_native_chain(audit))
    except (OSError, ValueError, KeyError, IndexError, TypeError, StopIteration) as error:
        report["failures"].append(type(error).__name__ + ": " + str(error))
    changed = audit.final_snapshot() + _gamepad_profile_apply_upstream_changes(report.get("upstream_sections", []))
    report["failures"].extend("Gamepad2636 detector native input changed: " + name for name in changed)
    report.update(recorded_at_utc=a.stamp(), changed_during_query=changed, snapshot_stable=not changed,
        complete_originals=list(audit.sources.values()), complete_source_owners=list(audit.owners.values()),
        verified_artifacts=list(audit.artifacts.values()))
    report["bounded_observation_complete"] = not report["failures"] and not changed and report.get("source_slice_complete", False)
    destination = a.ROOT / ".analysis/results/frontend/gamepad-mw-audit.json"
    host.publish_host_static_query(report, destination, a, "gamepad_2636_detection_native_chain")
    print(json.dumps({"receipt": a.rel(destination), "query": "gamepad-2636-detection-native-chain",
        "failures": report["failures"], "bounded_observation_complete": report["bounded_observation_complete"],
        "target_execution": False}), flush=True)
    if not report["bounded_observation_complete"]:
        raise ValueError("Gamepad2636 detector native source observation remains unresolved")
    return report


def _gamepad_profile_reset_dependencies(audit):
    receipt = ".analysis/results/frontend/gamepad-mw-audit.json"
    document = json.loads((a.ROOT / receipt).read_bytes())
    parent = document["profile_apply_chain"]
    if (_gamepad_profile_apply_digest(parent) != _GAMEPAD_PROFILE_RESET_APPLY_SHA
            or parent.get("product_id") != 2636 or parent.get("failures")
            or parent.get("snapshot_stable") is not True or parent.get("bounded_observation_complete") is not True
            or parent.get("target_execution") is not False):
        raise ValueError("Gamepad profile reset exact Apply dependency needs review")
    upstream = [{"receipt": receipt, "pointer": "/profile_apply_chain",
        "canonical_sha256": _GAMEPAD_PROFILE_RESET_APPLY_SHA, "recaptured": False}, *parent["upstream_sections"]]
    reused = {}
    selections = {
        "profile_apply_chain": ("profile_default", "product_profile_module", "runtime_apply", "runtime_identity", "profile_version",
            "ui_product_mount", "ui_profile_connector", "ui_profile_reducer", "ui_profile_de", "ui_profile_Oe", "ui_profile_ue",
            "ui_profile_renderProfileBar", "ui_profile_componentDidMount", "ui_profile_componentWillUnmount",
            "generic_manager", "generic_state", "generic_table", "generic_table_instantiation"),
        "obm_mapping_chain": ("product_bootstrap", "active_slot", "storage_override", "profile_storage", "serial_profile_storage",
            "storage_get", "storage_set", "storage_active_profile", "reset_removed_mapping", "engine_setSingleButtonMapping",
            "engine_init", "product_BUTTON_LIST", "product_DEFAULTMAPPINGS", "maker", "mapping_feature", "customHandler",
            "ui_reducer", "dispatch_lifecycle"),
        "polling_native_chain": ("sage_class", "controller_class"),
    }
    for section_name, names in selections.items():
        section = document[section_name]
        owners = {row["id"]: row for row in section["complete_source_owners"]}
        for name in names:
            row = owners[section["roles"][name]]
            raw = audit.read(row["original"])[row["byte_start"]:row["byte_end"]]
            if raw.decode() != row["body"] or hashlib.sha256(raw).hexdigest() != row["body_sha256"]:
                raise ValueError("Gamepad profile reset reused source changed: " + name)
            reused[section_name + "/" + name] = {"receipt": receipt, "pointer": "/" + section_name + "/roles/" + name,
                **{key: row[key] for key in ("id", "original", "syntax", "byte_start", "byte_end", "body_sha256")}}
    return document, upstream, reused


def _gamepad_profile_reset_sources(audit, document):
    import frontend
    import host
    roles, layers, selections = {}, {}, {}

    def retain(role, source, token, kinds):
        roles[role], = audit.retain("gamepad_profile_reset_" + role, source, token, kinds)
        row = audit.owners[roles[role]]
        return audit.tree(source).root_node.descendant_for_byte_range(row["byte_start"], row["byte_end"] - 1)

    def bound(role, source, name, at):
        value = audit.binding("gamepad_profile_reset_" + role, source, name, at)
        node = host._help_binding_node(audit, source, value)
        roles[role] = audit.retain_range("gamepad_profile_reset_" + role, source,
            node.start_byte, node.end_byte, node.type)
        return node

    def exported(role, side, module, name):
        value = audit.webpack_export("gamepad_profile_reset_" + role, layers[side], module, name)
        roles[role] = value["binding"]["owner_id"]
        return value["original"], host._help_binding_node(audit, value["original"], value["binding"])

    def member(role, source, root, name):
        node, roles[role] = audit.callable_member("gamepad_profile_reset_" + role, source, root, name)
        return node

    def enclosing_class(source, node):
        while node is not None and node.type not in {"class", "class_declaration"}:
            node = node.parent
        if node is None:
            raise ValueError("Gamepad profile reset actual UI class boundary is absent")
        return node

    for side, stem in (("mw", "gamepad-mw-2636-current"), ("ui", "gamepad-2636-current")):
        current = frontend.current_source_selection(f"https://apps.razer.com/synapse/products/2636/{side}/", audit,
            candidates=sorted((a.ROOT / ".analysis/inputs/frontend").glob(stem + "*/acquisition.json")), verify_capture=False)
        if current["acquisition"] != document["profile_apply_chain"]["source_sets"][side]["acquisition"]:
            raise ValueError("Gamepad profile reset current selection differs from reviewed Apply: " + side)
        selections[side] = {key: current[key] for key in ("name", "acquisition", "candidate_decisions",
            "capture_failures", "failed_acquisition", "unresolved_acquisition")}
        layers[side] = current["originals"]
    main = {side: next(row for row in rows if re.fullmatch(r"main\.[^.]+\.js", Path(row["path"]).name))
        for side, rows in layers.items()}
    mw, ui = main["mw"], main["ui"]
    exported("reset_profile_maker", "mw", 31759, "IH")
    source, default = exported("profile_defaults_provider", "mw", 69427, "getDefaultProfile")
    bound("profile_editions", source, "I", default.start_byte)
    source, default = exported("device_defaults_provider", "mw", 69427, "getDeviceDefaultLocalData")
    bound("device_defaults", source, "m", default.start_byte)
    retain("profile_reset_state", mw, "ON_RESET_PROFILE:{actions:", {"pair"})
    retain("profile_reset_dispatch", mw, 'case"ON_RESET_PROFILE":', {"switch_case"})
    retain("device_reset_state", mw, "ON_RESET_DEVICE:[", {"pair"})
    retain("device_reset_dispatch", mw, 'case"resetDevice":', {"switch_case"})
    retain("generic_event_gate", mw, "if(Ee.RzGenericFeatureManager.hasEventHandler(h))", {"if_statement"})
    bound("reset_device_maker", mw, "ne", 2710464)
    for label, module, name in (("clear_import_guard", 11365, "ho"), ("reimport_entry", 11365, "Rt"),
            ("reinitialize", 74867, "DD"), ("engine_initialize_once", 10511, "DY")):
        exported(label, "mw", module, name)
    bound("engine_guard", mw, "S", audit.owners[roles["engine_initialize_once"]]["byte_start"])
    bound("import_guard", mw, "te", audit.owners[roles["reimport_entry"]]["byte_start"])
    bound("import_metadata_entry", mw, "Z", audit.owners[roles["reimport_entry"]]["byte_start"])
    bound("runtime_sync", mw, "Pn", audit.owners[roles["reinitialize"]]["byte_start"])
    for name in ("X", "u", "v", "p", "ee", "te"):
        bound("reset_device_import_" + name, mw, name, audit.owners[roles["reset_device_maker"]]["byte_start"])
    parent = document["profile_apply_chain"]
    owners = {row["id"]: row for row in parent["complete_source_owners"]}
    row = owners[parent["roles"]["ui_profile_renderProfileBar"]]
    root = enclosing_class(ui, audit.tree(ui).root_node.descendant_for_byte_range(row["byte_start"], row["byte_end"] - 1))
    for name in ("getProfileMenu", "updateProfileSet", "menuClick", "getDisabledItems", "resetProfile", "resetAllKeyActuation"):
        member("ui_profile_" + name, ui, root, name)
    bound("ui_gamepad_profile_menu", ui, "xr", row["byte_start"])
    bound("ui_profile_reset_popup", ui, "qr", row["byte_start"])
    bound("ui_profile_reset_action", ui, "es", row["byte_start"])
    exported("ui_keybind_reset_action", "ui", 61350, "resetKeybinds")
    retain("ui_profile_reset_case", ui, "case ce.sG0:{", {"switch_case"})
    retain("ui_keybind_reset_case", ui, "case ce.cXd:{", {"switch_case"})
    row = owners[parent["roles"]["ui_product_mount"]]
    root = enclosing_class(ui, audit.tree(ui).root_node.descendant_for_byte_range(row["byte_start"], row["byte_end"] - 1))
    member("ui_product_constructor", ui, root, "constructor")
    member("ui_product_renderView", ui, root, "renderView")
    bound("ui_help_connector", ui, "SN", row["byte_start"])
    root = enclosing_class(ui, retain("ui_device_reset", ui, "this.resetDevice=()=>", {"assignment_expression"}))
    for name in ("render", "confirmDel", "openDelAlert", "componentDidUpdate"):
        member("ui_help_" + name, ui, root, name)
    if any(node.type == "method_definition" and node.child_by_field_name("name").text == b"componentWillUnmount"
            for node in root.child_by_field_name("body").named_children):
        raise ValueError("Gamepad profile reset Help timer cleanup changed; review its new owner")
    bound("ui_device_confirmation_alias", ui, "kr", audit.owners[roles["ui_help_render"]]["byte_start"])
    root = bound("ui_device_confirmation_class", ui, "Kr", audit.owners[roles["ui_device_confirmation_alias"]]["byte_start"])
    for name in ("mouseClick", "confirmDel", "componentWillUnmount"):
        member("ui_device_confirmation_" + name, ui, root, name)
    exported("ui_device_info", "ui", 22127, "DeviceInfo")
    polling = document["polling_native_chain"]
    owners = {row["id"]: row for row in polling["complete_source_owners"]}
    row = owners[polling["roles"]["controller_class"]]
    source = row["original"]
    root = audit.tree(source).root_node.descendant_for_byte_range(row["byte_start"], row["byte_end"] - 1)
    member("protocol_setDeviceReset", source, root, "setDeviceReset")
    exported("reset_header", "mw", 14397, "EV")
    exported("reset_description", "mw", 14397, "Up")
    for label in ("sage_class",):
        row = owners[polling["roles"][label]]
        if "setDeviceReset" in row["body"]:
            raise ValueError("Gamepad profile reset selected Sage override needs review")
    for side, module, names in (("ui", 13254, ("sG0", "cXd", "Vir", "yqg")),
            ("mw", 67061, ("Vir", "yqg"))):
        for name in names:
            exported(side + "_event_" + name, side, module, name)
    return {"roles": roles, "source_sets": selections, "reviewed_inputs": main}


