def collect_gamepad_profile_reset_chain(audit):
    document, upstream, reused = _gamepad_profile_reset_dependencies(audit)
    result = _gamepad_profile_reset_sources(audit, document)
    result["semantics"] = _gamepad_profile_reset_contract(
        {role: audit.owners[key] for role, key in result["roles"].items()}, audit.parser)
    result.update(schema_version=1, kind="current_gamepad_profile_reset_chain", product_id=2636, failures=[],
        upstream_sections=upstream, reused_source_owners=reused, source_slice_complete=True,
        selected_static_semantics_reviewed=True, source_chain_complete=False, whole_product_complete=False,
        target_execution=False, real_device_operations=False, rust_independent_implementation="unverified",
        official_dll_comparison="not_executed", ui_backend_wiring="unverified", runtime_acceptance="unverified",
        product_code_modified=False, remaining_chains=[
            "Import body/per-field initialization, notification and other product/firmware/transport lifecycle branches remain separate unfinished chains.",
            "Actual reset ACK/device state, reimport results, cancellation and callback/I/O drain require explicit official DLL/device comparison; selected source has no reset-specific post-write GET.",
            "Independent Rust, production UI/backend wiring, pure/mock behavior and runtime acceptance remain unfinished stages."])
    return result


def audit_gamepad_profile_reset_chain(args):
    import host
    if (args.family != "gamepad" or args.function != "mw" or getattr(args, "prepare", False)
            or sorted(set(args.product or [2636])) != [2636]):
        raise ValueError("gamepad-profile-reset-chain requires PID2636 gamepad middleware without preparation")
    audit = host.HostLocalAudit()
    report = {"schema_version": 1, "recorded_at_utc": a.stamp(), "parser": audit.parser_versions,
        "kind": "current_gamepad_profile_reset_chain", "product_id": 2636, "failures": [],
        "bounded_observation_complete": False, "source_chain_complete": False, "whole_product_complete": False,
        "target_execution": False, "real_device_operations": False, "rust_implementation": "not_reviewed",
        "official_dll_comparison": "not_executed", "runtime_acceptance": "unverified"}
    try:
        for name in ("tools/families.py", "tools/host.py", "tools/frontend.py", "tools/evidence.py"):
            audit.artifact(a.ROOT / name)
        report.update(collect_gamepad_profile_reset_chain(audit))
        report["bounded_observation_complete"] = not report["failures"]
    except (OSError, ValueError, KeyError, IndexError, TypeError, StopIteration) as error:
        report["failures"].append(type(error).__name__ + ": " + str(error))
    changed = audit.final_snapshot() + _gamepad_profile_apply_upstream_changes(report.get("upstream_sections", []))
    if changed:
        report["failures"].extend("Gamepad profile reset source changed during query: " + name for name in changed)
        report["bounded_observation_complete"] = False
    report.update(changed_during_query=changed, snapshot_stable=not changed,
        complete_originals=list(audit.sources.values()), complete_source_owners=list(audit.owners.values()),
        verified_artifacts=list(audit.artifacts.values()))
    destination = a.ROOT / ".analysis/results/frontend/gamepad-mw-audit.json"
    host.publish_host_static_query(report, destination, a, "profile_reset_chain")
    print(json.dumps({"receipt": a.rel(destination), "query": "gamepad-profile-reset-chain", "failures": report["failures"],
        "bounded_observation_complete": report["bounded_observation_complete"], "target_execution": False}), flush=True)
    if report["failures"]:
        raise ValueError("Gamepad profile reset source observation remains unresolved")
    return report


