def _mouse_dpi_active_slot_digest(value):
    return hashlib.sha256(json.dumps(value, ensure_ascii=False, sort_keys=True,
        separators=(",", ":"), allow_nan=False).encode()).hexdigest()


def _mouse_dpi_active_slot_dependencies():
    receipt = ".analysis/results/frontend/mouse-mw-audit.json"
    document = json.loads((a.ROOT / receipt).read_bytes())
    upstream = []
    for pointer, expected in _MOUSE_DPI_ACTIVE_SLOT_DEPENDENCIES.items():
        section = document
        for part in pointer.strip("/").split("/"):
            section = section[int(part)] if isinstance(section, list) else section[part]
        if _mouse_dpi_active_slot_digest(section) != expected:
            raise ValueError("Mouse DPI active-slot exact gap dependency needs review: " + pointer)
        upstream.append({"receipt": receipt, "pointer": pointer, "canonical_sha256": expected,
            "scope": "Prior PID182 gap and semantic boundary only; current deployment is reviewed independently",
            "recaptured": False})
    return upstream


