def collect_gamepad_profile_apply_chain(audit):
    document, upstream, reused = _gamepad_profile_apply_dependencies(audit)
    result = _gamepad_profile_apply_sources(audit, document)
    result["semantics"] = _gamepad_profile_apply_contract(
        {role: audit.owners[key] for role, key in result["roles"].items()}, audit.parser)
    features = collect_gamepad_profile_apply_feature_chains(audit)
    for row in features["upstream_sections"]:
        existing = next((old for old in upstream if old["receipt"] == row["receipt"] and old["pointer"] == row["pointer"]), None)
        if existing is None:
            upstream.append(row)
        elif existing["canonical_sha256"] != row["canonical_sha256"]:
            raise ValueError("Gamepad profile apply conflicting exact dependency")
    result.update(feature_chains=features, upstream_sections=upstream, reused_source_owners=reused,
        schema_version=1, kind="current_gamepad_profile_apply_chain", product_id=2636, failures=[],
        source_slice_complete=True, selected_static_semantics_reviewed=True, source_chain_complete=False,
        whole_product_complete=False, target_execution=False, real_device_operations=False,
        rust_independent_implementation="unverified", official_dll_comparison="not_executed",
        ui_backend_wiring="unverified", runtime_acceptance="unverified", product_code_modified=False,
        remaining_chains=[
            "Current PID2636 profile-switch/apply covers its13 setting fields, not reset/import/notification or remaining product/firmware/transport lifecycles.",
            "Actual official addon/device ACKs, cancellation, callback/I/O drain and runtime acceptance remain unverified; shared native pointers retain their own bounded limitations.",
            "Independent Rust, production UI/backend wiring, pure/mock behavior and actual official DLL/device comparison are separate unfinished stages."])
    return result


def audit_gamepad_profile_apply_chain(args):
    import host
    if (args.family != "gamepad" or args.function != "mw" or getattr(args, "prepare", False)
            or sorted(set(args.product or [2636])) != [2636]):
        raise ValueError("gamepad-profile-apply-chain requires PID2636 gamepad middleware without preparation")
    audit = host.HostLocalAudit()
    report = {"schema_version": 1, "recorded_at_utc": a.stamp(), "parser": audit.parser_versions,
        "kind": "current_gamepad_profile_apply_chain", "product_id": 2636, "failures": [],
        "bounded_observation_complete": False, "source_chain_complete": False, "whole_product_complete": False,
        "target_execution": False, "real_device_operations": False, "rust_implementation": "not_reviewed",
        "official_dll_comparison": "not_executed", "runtime_acceptance": "unverified"}
    try:
        for name in ("tools/families.py", "tools/host.py", "tools/frontend.py", "tools/evidence.py"):
            audit.artifact(a.ROOT / name)
        report.update(collect_gamepad_profile_apply_chain(audit))
        report["bounded_observation_complete"] = not report["failures"]
    except (OSError, ValueError, KeyError, IndexError, TypeError, StopIteration) as error:
        report["failures"].append(type(error).__name__ + ": " + str(error))
    changed = audit.final_snapshot() + _gamepad_profile_apply_upstream_changes(report.get("upstream_sections", []))
    if changed:
        report["failures"].extend("Gamepad profile apply source changed during query: " + name for name in changed)
        report["bounded_observation_complete"] = False
    report.update(changed_during_query=changed, snapshot_stable=not changed,
        complete_originals=list(audit.sources.values()), complete_source_owners=list(audit.owners.values()),
        verified_artifacts=list(audit.artifacts.values()))
    destination = a.ROOT / ".analysis/results/frontend/gamepad-mw-audit.json"
    host.publish_host_static_query(report, destination, a, "profile_apply_chain")
    print(json.dumps({"receipt": a.rel(destination), "query": "gamepad-profile-apply-chain", "failures": report["failures"],
        "bounded_observation_complete": report["bounded_observation_complete"], "target_execution": False}), flush=True)
    if report["failures"]:
        raise ValueError("Gamepad profile apply source observation remains unresolved")
    return report


_GAMEPAD_OBM_MAPPING_POLLING_SHA = "55d17ef995491555e4af6750b5c0c612e009feedfa725a36a22cadc3a8863eeb"
_GAMEPAD_OBM_MAPPING_REVIEWED = "03ba0563a041aa4b34c74661ec96a80d1e5d3afad57517ddb8fdb9b0de89adc6"


def _gamepad_obm_mapping_dependency(document):
    parent = document["polling_native_chain"]
    digest = hashlib.sha256(json.dumps(parent, ensure_ascii=False, sort_keys=True,
        separators=(",", ":"), allow_nan=False).encode()).hexdigest()
    if (digest != _GAMEPAD_OBM_MAPPING_POLLING_SHA or parent.get("product_id") != 2636
            or parent.get("bounded_observation_complete") is not True
            or parent.get("snapshot_stable") is not True or parent.get("target_execution") is not False
            or parent.get("failures") or not parent.get("complete_source_owners")):
        raise ValueError("Gamepad OBM exact polling dependency requires renewed review")
    return {"receipt": ".analysis/results/frontend/gamepad-mw-audit.json", "pointer": "/polling_native_chain",
        "canonical_sha256": digest, "semantic_dependency": True,
        "scope": "Reuse current PID2636 source selection, actual Sage/Controller/protocol25 inheritance, active-slot/storage and shared HID ACK/transport owners; mapping supplies its own submitted payload and result consumers"}


def _gamepad_obm_mapping_upstream_changes(upstream):
    changed = []
    for row in upstream:
        if row.get("pointer") != "/polling_native_chain":
            changed.extend(_system_battery_native_upstream_changes([row]))
            continue
        try:
            current = _gamepad_obm_mapping_dependency(json.loads((a.ROOT / row["receipt"]).read_bytes()))
            if current["canonical_sha256"] != row["canonical_sha256"]:
                changed.append(row["receipt"] + "#" + row["pointer"])
        except (OSError, ValueError, KeyError, TypeError):
            changed.append(row["receipt"] + "#" + row["pointer"])
    return changed


def _gamepad_obm_mapping_sources(audit):
    """Retain the mounted PID2636 Customize save, selected override and OBM consumers."""
    import frontend
    import host
    roles, selections, layers = {}, {}, {}
    document = json.loads((a.ROOT / ".analysis/results/frontend/gamepad-mw-audit.json").read_bytes())
    dependency = _gamepad_obm_mapping_dependency(document)
    upstream = document["polling_native_chain"]
    previous = {row["id"]: row for row in upstream["complete_source_owners"]}

    def one(rows, label):
        rows = list(rows)
        if len(rows) != 1:
            raise ValueError("Gamepad OBM owner is absent or ambiguous: " + label)
        return rows[0]

    def keep(role, source, node):
        roles[role] = audit.retain_range("gamepad_obm_mapping_" + role, source,
            node.start_byte, node.end_byte, node.type)
        return node

    def anchor(role, source, token, kinds):
        matches = {}
        for hit in re.finditer(re.escape(token.encode()), audit.read(source)):
            node = audit.tree(source).root_node.descendant_for_byte_range(hit.start(), hit.end() - 1)
            while node is not None and node.type not in kinds:
                node = node.parent
            if node is None:
                raise ValueError("Gamepad OBM complete AST boundary is absent: " + role)
            matches[node.start_byte, node.end_byte] = node
        return keep(role, source, one(matches.values(), role))

    def bound(role, source, name, at):
        value = audit.binding("gamepad_obm_mapping_" + role, source, name, at)
        return keep(role, source, host._help_binding_node(audit, source, value))

    def exported(role, layer, module, name):
        value = audit.webpack_export("gamepad_obm_mapping_" + role, layers[layer], module, name)
        return value["original"], keep(role, value["original"], host._help_binding_node(
            audit, value["original"], value["binding"]))

    for layer, stem in (("mw", "gamepad-mw-2636-current"), ("ui", "gamepad-2636-current")):
        selected = frontend.current_source_selection(
            f"https://apps.razer.com/synapse/products/2636/{layer}/", audit,
            candidates=sorted((a.ROOT / ".analysis/inputs/frontend").glob(stem + "*/acquisition.json")))
        selections[layer] = {key: selected[key] for key in ("name", "acquisition", "candidate_decisions",
            "capture_failures", "failed_acquisition", "unresolved_acquisition")}
        selections[layer]["complete_capture"] = selected["capture"]["manifest"] if selected["capture"] else None
        layers[layer] = selected["originals"]
    main = {layer: one((row for row in rows if re.fullmatch(r"main\.[^.]+\.js", Path(row["path"]).name)), layer)
        for layer, rows in layers.items()}
    mw, ui = main["mw"], main["ui"]
    reused = {}
    for role in ("product_bootstrap", "product_controller", "controller_gate", "mw_device_info", "active_slot",
            "storage_get", "storage_active_profile", "storage_set", "ui_result_de", "ui_result_Oe",
            "ui_result_Se", "ui_result_ue", "ui_result_Re", "ui_result_Ne", "ui_result_Ce", "ui_result_Le"):
        row = previous[upstream["roles"][role]]
        key = audit.retain_range("gamepad_obm_mapping_" + role, row["original"],
            row["byte_start"], row["byte_end"], row["syntax"])
        if audit.owners[key]["body_sha256"] != row["body_sha256"]:
            raise ValueError("Gamepad OBM reused source owner differs: " + role)
        roles[role] = key
        reused[role] = {"owner": row["id"], "body_sha256": row["body_sha256"],
            "pointer": "/polling_native_chain/roles/" + role}
    anchor("product_mapping_overrides", mw, "mappingOverrides:{getKeyMappings:G.hC,taskMakerSetKeyMapping:B.Hw}", {"pair"})
    boot = audit.owners[roles["product_bootstrap"]]["byte_start"]
    for role, name in (("product_maker_import", "B"), ("product_read_import", "G"), ("storage_override", "le")):
        bound(role, mw, name, boot)
    source, storage = exported("profile_storage", "mw", 52448, "A")
    bound("profile_storage_selection", source, "s", storage.start_byte)
    bound("serial_profile_storage", source, "r", storage.start_byte)
    anchor("dispatch", mw, 'case"keyMapping":if("ON_SET_KEYMAPPING"===h)', {"switch_case"})
    anchor("dispatch_lifecycle", mw, 'const{detail:{feature:_,lockHeld:m,actions:I,eventType:h}}=e', {"variable_declarator"})
    anchor("state_action", mw, 'ON_SET_KEYMAPPING:[{actions:[{type:"dispatchAllowAction"', {"pair"})
    source, maker = exported("maker", "mw", 21445, "Hw")
    feature = bound("mapping_feature", source, "g", maker.start_byte)
