def _system_battery_native_sources(audit):
    """Retain PID737 Battery owners; reuse the separately reviewed shared HID route."""
    import frontend
    import host
    roles, selections, layers = {}, {}, {}

    def one(rows, label):
        rows = list(rows)
        if len(rows) != 1:
            raise ValueError("System Battery owner is absent or ambiguous: " + label)
        return rows[0]

    def keep(role, source, node):
        roles[role] = audit.retain_range("system_battery_native_" + role, source,
            node.start_byte, node.end_byte, node.type)
        return node

    def anchor(role, source, token, kinds, *, callable_only=False):
        matches = {}
        for hit in re.finditer(re.escape(token.encode()), audit.read(source)):
            node = audit.tree(source).root_node.descendant_for_byte_range(hit.start(), hit.end() - 1)
            while node is not None:
                value = node.child_by_field_name("value")
                if node.type in kinds and (not callable_only or node.type != "variable_declarator"
                        or value is not None and value.type in {"arrow_function", "function_expression"}):
                    break
                node = node.parent
            if node is None:
                raise ValueError("System Battery complete AST boundary is absent: " + role)
            matches[(node.start_byte, node.end_byte)] = node
        return keep(role, source, one(matches.values(), role))

    def bound(role, source, name, at):
        binding = audit.binding("system_battery_native_" + role, source, name, at)
        return keep(role, source, host._help_binding_node(audit, source, binding))

    def exported(role, layer, module, name):
        result = audit.webpack_export("system_battery_native_" + role, layers[layer], module, name)
        node = keep(role, result["original"], host._help_binding_node(audit, result["original"], result["binding"]))
        return result["original"], node

    for layer, stem in (("mw", "system-mw-737-current"), ("ui", "system-737-current")):
        selected = frontend.current_source_selection(
            f"https://apps.razer.com/synapse/products/737/{layer}/", audit,
            candidates=sorted((a.ROOT / ".analysis/inputs/frontend").glob(stem + "*/acquisition.json")))
        selections[layer] = {key: selected[key] for key in ("name", "acquisition", "candidate_decisions",
            "capture_failures", "failed_acquisition", "unresolved_acquisition")}
        selections[layer]["complete_capture"] = selected["capture"]["manifest"] if selected["capture"] else None
        layers[layer] = selected["originals"]
    mw = one((x for x in layers["mw"] if re.fullmatch(r"6737\.[^.]+\.js", Path(x["path"]).name)), "MW core")
    main = one((x for x in layers["mw"] if re.fullmatch(r"main\.[^.]+\.js", Path(x["path"]).name)), "MW entry")
    ui_main = one((x for x in layers["ui"] if re.fullmatch(r"main\.[^.]+\.js", Path(x["path"]).name)), "UI entry")
    page = one((x for x in layers["ui"] if x["path"].endswith(".js")
                and b'const n=["50","55","60","65","70","75","80"]' in audit.read(x)), "mounted Battery page")
    kinds = {"variable_declarator", "function_declaration", "method_definition"}
    card = anchor("ui_card", page, "ea=(0,C.connect)", {"variable_declarator"})
    for role, name in (("ui_limiter_action", "Ki"), ("ui_override_action", "Qi"), ("ui_action_map", "d")):
        bound(role, page, name, card.start_byte)
    anchor("ui_action_exports", page, "s.d(d,{setBatteryChargingOverrideEnabled:()=>Qi,setBatteryOptimizer:()=>Ki})", {"call_expression"})
    mount = anchor("ui_battery_mount", page, "supportBatteryChargingOverrideEnabled:!0,supportsShortcut:!0", {"class_declaration"})
    bound("ui_battery_export", page, "sa", mount.end_byte + 1)
    anchor("ui_navigation_mount", page, "component:(0,N.jsx)(sa,{})", {"method_definition"})
    reducer = anchor("ui_reducer", ui_main, "systemBatteryReducer:function(", {"pair"})
    for name in ("Ht", "N", "C", "R", "L", "b"):
        bound("ui_result_" + name, ui_main, name, reducer.start_byte)
    for name in ("RKi", "M3l", "_PK", "gWc", "hoz", "Mg8", "gTK", "C8n", "QYT", "EN_", "pi2", "DaL", "Pck", "d0J"):
        exported("ui_constant_" + name, "ui", 13254, name)
    anchor("product_config", main, 'useFeature("deviceUI","config",', {"call_expression"})
    anchor("product_wrapper_registration", main, 'useFeature("rzDeviceType","rzDevice25LedMatrixBlade2")', {"call_expression"})
    anchor("product_read_from_firmware", main, 'useFeature("getBatteryOptimizerFromFW","yes")', {"call_expression"})
    anchor("fn_b_default", main, 'inputID:"KEY_B",bladeBatteryGroup:{assignment:"toggle"}', {"object"})
    anchor("fn_b_mapping_output", mw, 'i={type:"bladeBattery",id:e.bladeBatteryGroup.assignment}', {"pair"})
    anchor("fn_b_output_consumer", mw, 'case"bladeBattery":he(e,l)', kinds, callable_only=True)
    anchor("fn_b_event", mw, 'new n.VG("ON_SET_BATTERY_CHARGING_OVERRIDE_ENABLED_BY_DEVICE"', kinds, callable_only=True)
    for name in ("taskMakerSetBatteryOptimizer", "taskMakerSetBatteryChargingOverrideEnabled", "taskMakerSetBatteryChargingOverrideByDevice"):
        exported(name, "mw", 45496, name)
    for role, exported_name in (("runner", "yd"), ("runner_completion", "RO"),
                                ("override_runner", "nX"), ("override_completion", "EM")):
        exported(role, "mw", 46329, exported_name)
    exported("query_get", "mw", 34938, "Hj")
    exported("power_mode_helper", "mw", 34938, "_w")
    anchor("power_mode_bits", mw, 'e[e.oneTimeOverrideEnabled=4]="oneTimeOverrideEnabled"', {"expression_statement"})
    for role, event in (("dispatch_limiter", "ON_SET_BATTERY_OPTIMIZER"),
                        ("dispatch_override", "ON_SET_BATTERY_CHARGING_OVERRIDE_ENABLED"),
                        ("dispatch_fn_b", "ON_SET_BATTERY_CHARGING_OVERRIDE_ENABLED_BY_DEVICE")):
        anchor(role, mw, 'case"' + event + '":', {"switch_case"})
    anchor("state_machine", mw, 'systemBattery:{initial:"idle"', {"pair"})
    anchor("initial_read", mw, "function ko()", {"function_declaration"})
    anchor("ready_read", mw, "void 0!==n&&(t.batteryChargingOverrideEnabled=n)", {"generator_function"})
    anchor("cache_restore", mw, 'case"batteryOptimizer":', {"switch_case"})
    anchor("full_charge_reset", mw, "K=()=>N(", kinds, callable_only=True)
    anchor("full_charge_event", mw, "case n.Ym.BATTERY_FULLY_CHARGED_EVENT:", {"switch_case"})
    anchor("battery_level_event", mw, "i>=100&&K()", {"switch_case"})
    # Resolve every actual superclass export and retain its constructor and heritage.
    for label, module in (("blade2", 56193), ("blade", 77127), ("matrix", 71513), ("protocol25", 74503)):
        source, default = exported(label + "_default", "mw", module, "default")
        reference = default.child_by_field_name("value")
        cls = bound(label + "_class", source, reference.text.decode(), reference.start_byte)
        _, roles[label + "_constructor"] = audit.callable_member("system_battery_native_" + label + "_constructor", source, cls, "constructor")
        heritage = one((x for x in cls.named_children if x.type == "class_heritage"), label + " inheritance")
        keep(label + "_heritage", source, heritage)
        namespace = heritage.named_children[0].child_by_field_name("object")
        bound(label + "_superclass_import", source, namespace.text.decode(), namespace.start_byte)
        if label != "protocol25":
            for name in ("getBatteryChargeLimiterControl", "setBatteryChargeLimiterControl", "getPowerModeControl", "setPowerModeControl"):
                if (name + "(").encode() in cls.text:
                    if label == "blade" and name in {"getBatteryChargeLimiterControl", "setBatteryChargeLimiterControl"}:
                        _, roles[label + "_" + name] = audit.callable_member("system_battery_native_" + label + "_" + name, source, cls, name)
                    else:
                        raise ValueError("System Battery wrapper overrides need renewed semantic review: " + label + "." + name)
        else:
            bound("protocol25_command_import", source, "En", cls.start_byte)
            bound("protocol25_bridge_import", source, "pa", cls.start_byte)
            for name in ("getBatteryChargeLimiterControl", "setBatteryChargeLimiterControl", "getPowerModeControl", "setPowerModeControl",
                         "sendCommand", "_createDataSend", "_calculateChecksum", "_getTransactionId", "_getUSBTransferInResult", "releaseHIDMutex"):
                _, roles["protocol25_" + name] = audit.callable_member("system_battery_native_protocol25_" + name, source, cls, name)
    exported("electron_bridge", "mw", 19635, "dA")
    # Complete class bodies are retained only as lexical binding owners; the selected methods drive the contract.
    for role, name in (("limiter_get", "Hj"), ("limiter_set", "aW"), ("power_get", "Il"), ("power_set", "_w")):
        source, node = exported(role, "mw", 34836, name)
        if role.endswith("get"):
            decoder = "G" if role == "limiter_get" else "L"
            bound(role + "_decoder", source, decoder, node.start_byte)
    for name in ("nA", "$Q", "lJ", "FD", "Uk", "Rt", "$g", "N3"):
        exported("command_" + name, "mw", 31509, name)
    return {"roles": roles, "source_sets": selections}


