def _system_battery_native_header(body, parser):
    """Read the value of a JS command initializer without executing vendor code."""
    tree = parser.parse(("const " + body + ";").encode())
    if tree.root_node.has_error or len(tree.root_node.named_children) != 1:
        raise ValueError("System Battery command initializer grammar differs")
    declaration = tree.root_node.named_children[0]
    if declaration.type != "lexical_declaration" or len(declaration.named_children) != 1:
        raise ValueError("System Battery command initializer is not one declaration")
    node = declaration.named_children[0].child_by_field_name("value")
    while node is not None and node.type in {"parenthesized_expression", "sequence_expression"}:
        node = node.named_children[-1]
    if node is None or node.type != "new_expression" or node.child_by_field_name("constructor").text != b"Uint8Array":
        raise ValueError("System Battery command initializer is not Uint8Array")
    arguments = node.child_by_field_name("arguments").named_children
    if len(arguments) != 1 or arguments[0].type != "array":
        raise ValueError("System Battery command initializer is not a literal array")
    values = arguments[0].named_children
    if len(values) != 3 or any(x.type != "number" or not re.fullmatch(rb"\d+", x.text) for x in values):
        raise ValueError("System Battery command header is not three decimal bytes")
    result = [int(x.text) for x in values]
    if any(x > 255 for x in result):
        raise ValueError("System Battery command header exceeds a byte")
    return result


