def _system_battery_native_transport_dependency(document):
    parent = document["auto_pause_hid_chain"]
    if (parent.get("bounded_observation_complete") is not True or parent.get("snapshot_stable") is not True
            or parent.get("target_execution") is not False or parent.get("failures")):
        raise ValueError("System Battery shared HID parent is not a completed static observation")
    shared = parent["shared_feature_transport"]
    for name in ("host_release", "roles", "complete_source_owners", "native", "native_contract", "source_contract"):
        if not shared.get(name):
            raise ValueError("System Battery shared HID field is absent: " + name)
    actual = hashlib.sha256(json.dumps({key: value for key, value in shared.items() if key != "canonical_sha256"},
        ensure_ascii=False, sort_keys=True, separators=(",", ":")).encode()).hexdigest()
    if shared.get("canonical_sha256") != actual:
        raise ValueError("System Battery shared HID canonical digest differs")
    if actual != _SYSTEM_BATTERY_NATIVE_SHARED_REVIEWED:
        raise ValueError("System Battery shared HID complete contract needs renewed semantic review")
    release, native = shared["host_release"], shared["native"]
    if (release.get("version") != "4.0.896" or release.get("node_rz_hid_version") != "0.0.31"
            or release.get("addon_alias_bytes_equal") is not True
            or native.get("input", {}).get("sha256") != "5f185c3c865fb37a8cfb85d52a61704555543d70ea954bead84bbadda66fcfac"
            or native.get("capture_complete") is not True or native.get("target_execution") is not False
            or not native.get("functions") or not native.get("verified_indirect_slots")):
        raise ValueError("System Battery shared current Host/addon capture differs")
    for row in native["functions"]:
        if any(row.get(key) is not True for key in ("assembly_captured", "pseudocode_captured", "input_chunks_verified")):
            raise ValueError("System Battery shared selected native function is incomplete")
    if (shared["source_contract"].get("product_report_id_length_or_business_ack_inferred") is not False
            or any(name not in shared["source_contract"] for name in ("send", "get", "missing_device_or_exception", "mutex", "close"))
            or any(name not in shared["native_contract"] for name in ("prototype", "queue", "send", "get", "deferred", "close", "reviewed_selection_sha256"))):
        raise ValueError("System Battery shared feature-report semantic contract is incomplete")
    return {"receipt": _SYSTEM_BATTERY_NATIVE_SHARED_RECEIPT, "pointer": _SYSTEM_BATTERY_NATIVE_SHARED_POINTER,
        "canonical_sha256": hashlib.sha256(json.dumps(shared, ensure_ascii=False,
            sort_keys=True, separators=(",", ":")).encode()).hexdigest(), "semantic_dependency": True,
        "reviewed_contract_sha256": actual,
        "host_version": release["version"], "node_rz_hid_version": release["node_rz_hid_version"],
        "native_input": native["input"], "selected_native_functions": len(native["functions"]),
        "scope": "Reuse current Host HID feature-report, mutex and close owners/native functions; Battery supplies its own report ID/length, command/ACK and consumers"}


def _system_battery_native_upstream_changes(upstream):
    changed = []
    for row in upstream:
        try:
            current = _system_battery_native_transport_dependency(json.loads((a.ROOT / row["receipt"]).read_bytes()))
            if current["pointer"] != row["pointer"] or current["canonical_sha256"] != row["canonical_sha256"]:
                changed.append(row["receipt"] + "#" + row["pointer"])
        except (OSError, ValueError, KeyError, TypeError):
            changed.append(row["receipt"] + "#" + row["pointer"])
    return changed


def collect_system_battery_native_chain(audit):
    result = _system_battery_native_sources(audit)
    result["semantics"] = _system_battery_native_contract(
        {role: audit.owners[key] for role, key in result["roles"].items()}, audit.parser)
    dependency = _system_battery_native_transport_dependency(json.loads(
        (a.ROOT / _SYSTEM_BATTERY_NATIVE_SHARED_RECEIPT).read_bytes()))
    result.update(kind="current_system_battery_native_chain", product_id=737, failures=[],
        upstream_sections=[dependency], source_slice_complete=True, source_chain_complete=False,
        whole_product_complete=False, target_execution=False, real_device_operations=False,
        rust_independent_implementation="unverified", ui_backend_wiring="unverified", runtime_acceptance="unverified",
        remaining_chains=[
            "The referenced shared native feature-report route retains its own indirect/import and capture failure boundaries; it does not prove actual Windows/device behavior or pending-I/O/callback quiescence.",
            "This bounded PID737 Battery result-consumer slice does not establish all system products/firmware/transports, full hardware notification subscription/parser lifecycle, GPU/ICC or whole-device teardown.",
            "Independent Rust, complete production caller replacement, UI/backend wiring, pure/mock tests and actual official addon/device input/output/error/cancel/restore/release comparisons remain separately required and unverified."])
    return result


def audit_system_battery_native_chain(args):
    import host
    if (args.family != "system" or args.function != "mw" or getattr(args, "prepare", False)
            or sorted(set(args.product or [737])) != [737]):
        raise ValueError("system-battery-native-chain requires PID737 system middleware without preparation")
    audit = host.HostLocalAudit()
    report = {"schema_version": 1, "recorded_at_utc": a.stamp(), "parser": audit.parser_versions,
        "kind": "current_system_battery_native_chain", "product_id": 737, "failures": [],
        "bounded_observation_complete": False, "source_chain_complete": False, "whole_product_complete": False,
        "target_execution": False, "real_device_operations": False, "rust_implementation": "not_reviewed",
        "official_dll_comparison": "not_executed", "runtime_acceptance": "unverified"}
    try:
        for name in ("tools/families.py", "tools/host.py", "tools/frontend.py", "tools/evidence.py"):
            audit.artifact(a.ROOT / name)
        report.update(collect_system_battery_native_chain(audit))
        report["bounded_observation_complete"] = not report["failures"]
    except (OSError, ValueError, KeyError, IndexError, TypeError, StopIteration) as error:
        report["failures"].append(type(error).__name__ + ": " + str(error))
    changed = audit.final_snapshot() + _system_battery_native_upstream_changes(report.get("upstream_sections", []))
    if changed:
        report["failures"].extend("System Battery source changed during query: " + name for name in changed)
        report["bounded_observation_complete"] = False
    report.update(changed_during_query=changed, snapshot_stable=not changed,
        complete_originals=list(audit.sources.values()), complete_source_owners=list(audit.owners.values()),
        verified_artifacts=list(audit.artifacts.values()))
    destination = a.ROOT / ".analysis/results/frontend/system-mw-audit.json"
    host.publish_host_static_query(report, destination, a, "battery_native_chain")
    print(json.dumps({"receipt": a.rel(destination), "query": "system-battery-native-chain", "failures": report["failures"],
        "bounded_observation_complete": report["bounded_observation_complete"], "target_execution": False}), flush=True)
    if report["failures"]:
        raise ValueError("System Battery source observation remains unresolved")
    return report


_SYSTEM_GPU_ROUTE_REVIEWED = "7f5b912eed5467c6ec601b95b8160b9b8f0b3f8a75b606ec07b2467ad3725f81"


def _system_gpu_route_sources(audit):
    """Retain the mounted PID737 GPU draft, VGA protocol and restart consumers."""
    import frontend
    import host
    roles, selections, layers = {}, {}, {}

    def one(rows, label):
        rows = list(rows)
        if len(rows) != 1:
            raise ValueError("System GPU route owner is absent or ambiguous: " + label)
        return rows[0]

    def keep(role, source, node):
        roles[role] = audit.retain_range("system_gpu_route_" + role, source,
            node.start_byte, node.end_byte, node.type)
        return node

    def anchor(role, source, token, kinds, *, callable_only=False):
        matches = {}
        for hit in re.finditer(re.escape(token.encode()), audit.read(source)):
            node = audit.tree(source).root_node.descendant_for_byte_range(hit.start(), hit.end() - 1)
            while node is not None:
                value = node.child_by_field_name("value")
                if node.type in kinds and (not callable_only or node.type != "variable_declarator"
                        or value is not None and value.type in {"arrow_function", "function_expression"}):
                    break
                node = node.parent
            if node is None:
                raise ValueError("System GPU route complete AST boundary is absent: " + role)
            matches[(node.start_byte, node.end_byte)] = node
        return keep(role, source, one(matches.values(), role))

    def bound(role, source, name, at):
        result = audit.binding("system_gpu_route_" + role, source, name, at)
        return keep(role, source, host._help_binding_node(audit, source, result))

    def exported(role, layer, module, name):
        result = audit.webpack_export("system_gpu_route_" + role, layers[layer], module, name)
        return result["original"], keep(role, result["original"],
            host._help_binding_node(audit, result["original"], result["binding"]))

    for layer, stem in (("mw", "system-mw-737-current"), ("ui", "system-737-current")):
        selected = frontend.current_source_selection(
            f"https://apps.razer.com/synapse/products/737/{layer}/", audit,
            candidates=sorted((a.ROOT / ".analysis/inputs/frontend").glob(stem + "*/acquisition.json")))
        selections[layer] = {key: selected[key] for key in ("name", "acquisition", "candidate_decisions",
            "capture_failures", "failed_acquisition", "unresolved_acquisition")}
        selections[layer]["complete_capture"] = selected["capture"]["manifest"] if selected["capture"] else None
        layers[layer] = selected["originals"]
    mw = one((x for x in layers["mw"] if re.fullmatch(r"6737\.[^.]+\.js", Path(x["path"]).name)), "MW core")
    main = one((x for x in layers["mw"] if re.fullmatch(r"main\.[^.]+\.js", Path(x["path"]).name)), "MW entry")
    ui_main = one((x for x in layers["ui"] if re.fullmatch(r"main\.[^.]+\.js", Path(x["path"]).name)), "UI entry")
    page = one((x for x in layers["ui"] if x["path"].endswith(".js")
                and b"this.props.restartSystem(this.state.mode)" in audit.read(x)), "mounted GPU card")
    callables = {"variable_declarator", "function_declaration", "method_definition"}
    card = anchor("ui_card", page, "this.props.restartSystem(this.state.mode)", {"class_declaration"})
    bound("ui_connector", page, "Va", card.end_byte + 1)
    for role, name in (("ui_switch", "La"), ("ui_dds", "ka"), ("ui_mux", "Ua"), ("ui_action", "Pa")):
        bound(role, page, name, card.start_byte)
    anchor("ui_action_export", page, "s.d(u,{restartSystem:()=>Pa})", {"call_expression"})
    mount = anchor("ui_display", page, "(0,N.jsx)(Va,{})", {"class_declaration"})
    bound("ui_display_connector", page, "Ha", mount.end_byte + 1)
    anchor("ui_navigation_mount", page, "component:(0,N.jsx)(Ha,{})", {"method_definition"})
    reducer = anchor("ui_reducer", ui_main, "gpuModeReducer:function(", {"pair"})
    for name in ("ft", "N", "R", "L", "b"):
        bound("ui_result_" + name, ui_main, name, reducer.start_byte)
    for name in ("W0e", "mk1", "KyI", "oKk", "Wg8", "gHN", "dVq", "xij", "t34", "FuJ"):
        exported("ui_constant_" + name, "ui", 13254, name)
    for name in ("cwj", "fvD"):
        exported("ui_mode_" + name, "ui", 69937, name)
    anchor("product_config", main, 'useFeature("deviceUI","config",', {"call_expression"})
    anchor("product_wrapper_registration", main, 'useFeature("rzDeviceType","rzDevice25LedMatrixBlade2")', {"call_expression"})
    anchor("product_runtime_capability", main, "hasGPUmode:!0", {"object"})
    anchor("product_feature_projection", main, "e.runtimeData.hasGPUmode&&(t.hasGPUmode=", callables, callable_only=True)
    exported("product_dds_skus", "mw", 26061, "SupportedDDSSKU")
    exported("query_get", "mw", 34938, "tL")
    anchor("initial_read", mw, "function Vo()", {"function_declaration"})
    anchor("runtime_read", mw, "function ko()", {"function_declaration"})
    anchor("mode_cache", mw, "dt.A.mode=e", callables, callable_only=True)
    dds = anchor("dds_classification", mw, "SupportedDDSSKU.includes(n.charAt(11))", callables, callable_only=True)
    bound("switch_query", mw, "xo", dds.start_byte)
    anchor("ready_publish", mw, "{type:l.KyI,payload:be}", callables, callable_only=True)
    anchor("dispatch", mw, 'case"gpuMode":', {"switch_case"})
    anchor("state_machine", mw, 'gpuMode:{initial:"idle"', {"pair"})
    for name in ("taskMakerSetGpuMode", "taskMakerRestartSystem"):
        exported(name, "mw", 45496, name)
    for role, name in (("set_runner", "XY"), ("set_completion", "IC"),
                        ("restart_runner", "yi"), ("restart_completion", "$A")):
        exported(role, "mw", 46329, name)
    task_source, manager = exported("task_manager", "mw", 81988, "RzTaskManager")
    bound("task_queue", task_source, "y", manager.start_byte)
    bound("task", task_source, "f", manager.start_byte)
    anchor("task_categories", task_source, 'e[e.NORMAL_SKIPPABLE=', {"expression_statement"})
    for label, module in (("blade2", 56193), ("blade", 77127), ("matrix", 71513), ("protocol25", 74503)):
        source, default = exported(label + "_default", "mw", module, "default")
        reference = default.child_by_field_name("value")
        cls = bound(label + "_class", source, reference.text.decode(), reference.start_byte)
        _, roles[label + "_constructor"] = audit.callable_member("system_gpu_route_" + label + "_constructor", source, cls, "constructor")
        heritage = one((x for x in cls.named_children if x.type == "class_heritage"), label + " inheritance")
        keep(label + "_heritage", source, heritage)
        namespace = heritage.named_children[0].child_by_field_name("object")
        bound(label + "_superclass_import", source, namespace.text.decode(), namespace.start_byte)
        methods = ("getVGAConfigureSetting", "setVGAConfigureSetting", "getSynapseUISetting", "getVGAHardwareInformation")
        if label == "blade2":
            for name in ("restartSystem", "callDLLApi", "init"):
                _, roles["blade2_" + name] = audit.callable_member("system_gpu_route_blade2_" + name, source, cls, name)
        if label != "protocol25":
            if any((name + "(").encode() in cls.text for name in methods):
                raise ValueError("System GPU route wrapper gained a VGA protocol override: " + label)
        else:
            bound("protocol25_command_import", source, "qe", cls.start_byte)
            bound("protocol25_bridge_import", source, "pa", cls.start_byte)
            for name in methods + ("sendCommand", "_createDataSend", "_calculateChecksum", "_getTransactionId", "_getUSBTransferInResult", "releaseHIDMutex"):
                _, roles["protocol25_" + name] = audit.callable_member("system_gpu_route_protocol25_" + name, source, cls, name)
    for role, name in (("vga_get", "FD"), ("vga_set", "fI"), ("synapse_ui_get", "mE"), ("hardware_get", "vc")):
        source, node = exported(role, "mw", 13546, name)
        if role == "vga_get":
            bound("vga_decoder", source, "_", node.start_byte)
            bound("vga_constants_import", source, "i", node.start_byte)
    for name in ("YT", "Gs", "aO", "Su", "Pn", "Ng", "vy", "Fz"):
        exported("command_" + name, "mw", 94735, name)
    for name in ("dA", "yL", "I3"):
        exported("bridge_" + name, "mw", 19635, name)
    host_sources, release = _system_display_refresh_host_sources(audit)
    for role, suffix, token, kinds in (
        ("host_registration", "electron/main.js", 'n.handle("ffiPreload",', {"call_expression"}),
        ("host_preload", "electron/preload.js", "doDLLMainAction:", {"pair"}),
        ("host_legacy_preload", "electron/preload.js", "doDLLAction:", {"pair"}),
        ("host_dispatch", "electron/modules/ffi/FFIPreloadMain.js", "callDLL=", {"field_definition"}),
        ("host_configure", "electron/modules/ffi/FFIPreloadMain.js", "_handleAction_ConfigureFFI=", {"field_definition"}),
        ("host_call", "electron/modules/ffi/FFIPreloadMain.js", "_handleAction_Default=", {"field_definition"})):
        anchor(role, host_sources[suffix], token, kinds)
    return {"roles": roles, "source_sets": selections, "host_release": release}


def _system_gpu_route_native(audit, selected):
    import base64
    acquired = json.loads(audit.artifact(a.ROOT / selected["acquisition"]["path"]))
    manifests = [x for x in acquired["files"] if x.get("path")
                 and x.get("url") == "https://apps.razer.com/synapse/products/737/mw/manifest.json"]
    if len(manifests) != 1:
        raise ValueError("System GPU route current native manifest is absent or ambiguous")
    manifest = manifests[0]
    resources = [x for x in json.loads(audit.read(manifest))["resourceManifest"]["resources"]
                 if x.get("resourceName") == "BladeDLL"]
    if len(resources) != 1:
        raise ValueError("System GPU route BladeDLL resource is absent or ambiguous")
    resource = resources[0]
    if (resource.get("resourceVersion") != "1.0.50.0" or resource.get("size") != 932552
            or resource.get("sha256", "").lower() != _SYSTEM_DISPLAY_REFRESH_NATIVE_SHA
            or resource.get("integrity") != "sha256-" + base64.b64encode(bytes.fromhex(_SYSTEM_DISPLAY_REFRESH_NATIVE_SHA)).decode()):
        raise ValueError("System GPU route current BladeDLL needs renewed semantic review")
    native = {"path": f".analysis/inputs/official-native-current/blobs/{_SYSTEM_DISPLAY_REFRESH_NATIVE_SHA}/blade2Native_v1.0.50.0.dll",
              "bytes": resource["size"], "sha256": _SYSTEM_DISPLAY_REFRESH_NATIVE_SHA}
    result = audit.native_slice(native, ["RestartSystem"], depth=0,
        rvas=(0x81b1c, 0x914fc, 0x911ec, 0x91c78, 0x91564, 0x91fe4, 0x91c80,
              0x917b4, 0x9bda4, 0x9bf08, 0x91c20, 0x91524, 0x891e0, 0x79b4c, 0x7bcc8))
    if result["failures"] or result["decompiler_failures"]:
        raise ValueError("System GPU route selected native complete capture is unavailable")
    return {"manifest": manifest, "resource": resource, "slice": result}


