def _system_737_performance_shared_header(document):
    previous = document["gpu_route_native_chain"]
    if (previous.get("failures") or not previous.get("bounded_observation_complete")
            or not previous.get("snapshot_stable") or previous.get("product_id") != 737
            or previous["host_release"]["version"] != "4.0.896"):
        raise ValueError("System737 performance shared Host/task evidence is not current and complete")
    owners = {row["id"]: row for row in previous["complete_source_owners"]}
    return {"roles": {role: owners[previous["roles"][role]] for role in _SYSTEM_737_PERFORMANCE_SHARED_ROLES},
            "host_release": previous["host_release"]}


def _system_737_performance_digest(value):
    return hashlib.sha256(json.dumps(value, ensure_ascii=False, sort_keys=True,
                                    separators=(",", ":")).encode()).hexdigest()


def _system_737_performance_upstream_changes(upstream):
    changed = []
    for row in upstream:
        try:
            selected = _system_737_performance_shared_header(json.loads((a.ROOT / row["receipt"]).read_bytes()))
            if _system_737_performance_digest(selected) != row["canonical_sha256"]:
                changed.append(row["receipt"] + "#" + row["pointer"])
        except (OSError, ValueError, KeyError, TypeError):
            changed.append(row["receipt"] + "#" + row["pointer"])
    return changed


def _system_737_performance_sources(audit):
    import frontend
    import host
    roles, selections, layers = {}, {}, {}
    receipt = ".analysis/results/frontend/system-mw-audit.json"
    previous = json.loads((a.ROOT / receipt).read_bytes())
    shared = _system_737_performance_shared_header(previous)

    def one(rows, label):
        rows = list(rows)
        if len(rows) != 1:
            raise ValueError("System737 performance owner is absent or ambiguous: " + label)
        return rows[0]

    def keep(role, source, node):
        roles[role] = audit.retain_range("system_737_performance_" + role, source,
            node.start_byte, node.end_byte, node.type)
        return node

    def anchor(role, source, token, kinds):
        matches = {}
        for hit in re.finditer(re.escape(token.encode()), audit.read(source)):
            node = audit.tree(source).root_node.descendant_for_byte_range(hit.start(), hit.end() - 1)
            while node is not None and node.type not in kinds:
                node = node.parent
            if node is None:
                raise ValueError("System737 performance complete AST owner is absent: " + role)
            matches[(node.start_byte, node.end_byte)] = node
        return keep(role, source, one(matches.values(), role))

    def bound(role, source, name, at):
        result = audit.binding("system_737_performance_" + role, source, name, at)
        return keep(role, source, host._help_binding_node(audit, source, result))

    def exported(role, layer, module, name):
        result = audit.webpack_export("system_737_performance_" + role, layers[layer], module, name)
        return result["original"], keep(role, result["original"],
            host._help_binding_node(audit, result["original"], result["binding"]))

    for role, row in shared["roles"].items():
        source = row["original"]
        raw = audit.read(source)
        if (raw[row["byte_start"]:row["byte_end"]].decode() != row["body"]
                or hashlib.sha256(row["body"].encode()).hexdigest() != row["body_sha256"]):
            raise ValueError("System737 performance shared AST bytes differ: " + role)
        node = audit.tree(source).root_node.descendant_for_byte_range(row["byte_start"], row["byte_end"] - 1)
        while node is not None and (node.start_byte, node.end_byte, node.type) != (
                row["byte_start"], row["byte_end"], row["syntax"]):
            node = node.parent
        if node is None:
            raise ValueError("System737 performance shared AST boundary differs: " + role)
        keep(role, source, node)
    for layer, stem in (("mw", "system-mw-737-current"), ("ui", "system-737-current")):
        selected = frontend.current_source_selection(
            f"https://apps.razer.com/synapse/products/737/{layer}/", audit,
            candidates=sorted((a.ROOT / ".analysis/inputs/frontend").glob(stem + "*/acquisition.json")),
            verify_capture=False)
        selections[layer] = {key: selected[key] for key in ("name", "acquisition", "candidate_decisions",
            "capture_failures", "failed_acquisition", "unresolved_acquisition")}
        layers[layer] = selected["originals"]
    mw = one((x for x in layers["mw"] if re.fullmatch(r"6737\.[^.]+\.js", Path(x["path"]).name)), "MW core")
    main = one((x for x in layers["mw"] if re.fullmatch(r"main\.[^.]+\.js", Path(x["path"]).name)), "MW entry")
    ui_main = one((x for x in layers["ui"] if re.fullmatch(r"main\.[^.]+\.js", Path(x["path"]).name)), "UI entry")
    page = shared["roles"]["ui_navigation_mount"]["original"]
    if page not in layers["ui"]:
        one((x for x in layers["ui"] if all(x[k] == page[k] for k in ("path", "bytes", "sha256"))), "current mounted UI")
    anchor("ui_cpu", page, "As=(0,C.connect)", {"variable_declarator"})
    anchor("ui_performance", page, "Ji=()=>", {"variable_declarator"})
    anchor("ui_actions", page, "applyOverclockingProfile:()=>Ht", {"call_expression"})
    for role, name in (("ui_apply", "Ht"), ("ui_cancel", "zt"), ("ui_save", "Bt")):
        bound(role, page, name, 85926)
    setting = anchor("ui_setting_registration", ui_main, "overclockingSettingReducer:Wt", {"pair"})
    bound("ui_setting_reducer", ui_main, "Wt", setting.start_byte)
    profiles = anchor("ui_profiles_registration", ui_main, "overclockingProfilesReducer:zt", {"pair"})
    bound("ui_actual_reducer", ui_main, "zt", profiles.start_byte)
    for name in ("UkO", "sQ3", "lRg", "GaL", "L69", "nEb", "XGP"):
        exported("constant_" + name, "ui", 13254, name)
    for name in ("KmC", "cVR"):
        exported("constant_" + name, "mw", 93490, name)
    anchor("product_split_voltage", main, 'useFeature("splitOCCoreVoltageOffset","yes")', {"call_expression"})
    anchor("product_cpu_config", main, 'useFeature("deviceUI","config",', {"call_expression"})
    for name in ("ON_APPLY_OVERCLOCKING_PROFILE", "ON_RESET_ACTIVE_OVERCLOCKING_PROFILE", "ON_SAVE_OVERCLOCKING_PROFILE"):
        anchor("dispatch_" + name, mw, 'case"' + name + '":', {"switch_case"})
    anchor("state_machine", mw, 'cpuOverclocking:{initial:"idle"', {"pair"})
    for name in ("taskMakerApplyOverclockingProfile", "taskMakerResetActiveOverclockingProfile", "taskMakerSaveOverclockingProfiles"):
        exported(name, "mw", 45496, name)
    bound("cancel_restore_apply", mw, "Ip", 1315000)
    for role, name in (("runner", "rm"), ("completion", "Q4")):
        exported(role, "mw", 46329, name)
    bulk_source, bulk = exported("bulk", "mw", 23227, "DT")
    for role, name in (("split", "Yl"), ("split_projection", "It"), ("start", "j3"), ("stop", "h7")):
        exported(role, "mw", 23227, name)
    for role, name in (("projection", "T"), ("merger", "k"), ("callback", "D"),
            ("ffi", "E"), ("voltage_id", "I")):
        bound(role, bulk_source, name, bulk.start_byte)
    anchor("profile_defaults", bulk_source, '{profile:m}=(0,o.UF)("deviceUI")', {"variable_declarator"})
    return {"roles": roles, "source_sets": selections, "host_release": shared["host_release"],
        "upstream_sections": [{"receipt": receipt, "pointer": "/gpu_route_native_chain",
            "selection": "shared_host_tasks",
            "canonical_sha256": _system_737_performance_digest(shared),
            "reused_roles": list(_SYSTEM_737_PERFORMANCE_SHARED_ROLES),
            "scope": "Exact current Host4.0.896 ancestry and complete AST Host/task owners; no Blade/display/GPU native semantics reused"}]}


def _system_737_performance_native(audit, selected):
    import base64
    acquired = json.loads(audit.artifact(a.ROOT / selected["acquisition"]["path"]))
    manifest, = [x for x in acquired["files"] if x.get("path")
                 and x.get("url") == "https://apps.razer.com/synapse/products/737/mw/manifest.json"]
    resources = json.loads(audit.read(manifest))["resourceManifest"]["resources"]
    result = {"manifest": manifest}
    for name, size, sha, exports, rvas in (
        ("RzIntelOverClock", 441544, "55b50c56e92c582a39ef034c4e3c0d71be246ec15f945005286847b8f15c73ef",
            ["UpdateAllTuningControlDataAsync", "UpdateCoreVoltageOffsetAsync", "GetAllTuningControlDataAsync", "FreeMalloc"], (0x44f90,)),
        ("RzIntelOverClockDLL", 712904, "0278fc29d16fa8334d22b8d62347f73ba9819139ef02ee10d20f1aa0ec7d1d56",
            ["UpdateAllTuningControlData", "UpdateCoreVoltageOffset", "GetAllTuningControlData", "FreeMalloc"], (0x4a0a0, 0x4a0b0, 0x4a0c0))):
        resource, = [x for x in resources if x.get("resourceName") == name]
        if (resource.get("resourceVersion") != "1.2.23.0" or resource.get("size") != size
                or resource.get("sha256", "").lower() != sha
                or resource.get("integrity") != "sha256-" + base64.b64encode(bytes.fromhex(sha)).decode()):
            raise ValueError("System737 performance native resource needs renewed review: " + name)
        original = {"path": f".analysis/inputs/official-native-current/blobs/{sha}/{name}_v1.2.23.0.dll",
                    "bytes": size, "sha256": sha}
        sliced = audit.native_slice(original, exports, depth=0, rvas=rvas)
        if sliced["failures"] or sliced["decompiler_failures"] or not sliced["all_selected_pseudocode_captured"]:
            raise ValueError("System737 performance native complete capture is unavailable: " + name)
        result[name] = {"resource": resource, "slice": sliced}
    return result


def _system_737_performance_managed(audit, native):
    import struct
    import host
    original = native["RzIntelOverClockDLL"]["slice"]["original"]
    captures = json.loads((a.ROOT / ".analysis/results/host-current/managed/capture.json").read_bytes())
    capture, = [row for row in captures["assemblies"] if row.get("input_sha256") == original["sha256"]]
    if (capture["input"] != original["path"] or capture["input_bytes"] != original["bytes"]
            or not capture["capture_complete"] or not capture["input_bytes_unchanged"]
            or len(capture["commands"]) != 2 or any(row["exit_code"] != 0 for row in capture["commands"])):
        raise ValueError("System737 performance mixed CLR capture is incomplete")
    il, = [row for row in capture["outputs"] if row["path"].endswith("/il.stdout.txt")]
    csharp, = [row for row in capture["outputs"] if row["path"].endswith("/source/-Module-.cs")]
    il_raw = audit.artifact(a.ROOT / il["path"], il)
    csharp_raw = audit.artifact(a.ROOT / csharp["path"], csharp)
    raw = audit.read(original)
    metadata = host._profile_gog_clr(raw)
    names = ("ConvertDoubleToDecimal", "OnProposeChangesComplete", "OnApplyChangeDelegate", "GetTuningControl",
        "GetTuningControlSetting", "GetTuningControlState", "CheckAndReInitIntelSDKOC", "GetAllTuningControlData",
        "updateSeries11CoreVoltageOffset", "UpdateAllTuningControlData", "UpdateCoreVoltageOffset")
    methods = host._profile_gog_il_methods(original, il_raw.decode("utf-8-sig"), metadata,
        {"<Module>": tuple("RzIntelOverClockLib." + name for name in names)})
    if len(methods) != len(names):
        raise ValueError("System737 performance selected complete CLR methods differ")
    for method in methods:
        identity = metadata["methods"][int(method["token"], 16)]
        if identity["implementation_kind"] != "il" or not identity["body_decoded"]:
            raise ValueError("System737 performance selected method is not original IL")
        method["method_identity"] = {key: identity[key] for key in ("token", "rva", "implementation_flags",
            "method_flags", "implementation_kind", "metadata_row_hex", "body_decoded")}
    text = csharp_raw.decode("utf-8-sig")
    text_prefix_bytes = len(csharp_raw) - len(text.encode())
    declarations = list(re.finditer(r"(?m)^\t(?:internal|public|private|protected) [^\r\n]*", text))
    csharp_methods = []
    for name in names:
        hits = [(i, match) for i, match in enumerate(declarations) if " RzIntelOverClockLib_002E" + name + "(" in match[0]]
        if len(hits) != 1:
            raise ValueError("System737 performance complete C# method boundary differs: " + name)
        _, match = hits[0]
