def collect_system_737_performance_native_chain(audit):
    result = _system_737_performance_sources(audit)
    result["native"] = _system_737_performance_native(audit, result["source_sets"]["mw"])
    result["managed"] = _system_737_performance_managed(audit, result["native"])
    result["semantics"] = _system_737_performance_contract(
        {role: audit.owners[key] for role, key in result["roles"].items()}, result["native"], result["managed"])
    result.update(kind="current_system_737_performance_native_chain", product_id=737, failures=[],
        source_slice_complete=True, source_chain_complete=False, whole_product_complete=False,
        target_execution=False, real_device_operations=False, rust_independent_implementation="unverified",
        ui_backend_wiring="unverified", official_dll_comparison="unverified", runtime_acceptance="unverified",
        remaining_chains=["Selected CPU Apply/ResetActive-to-Apply and result consumers are retained; complete Intel SDK/XtuCommon driver/service implementations, RzDLLService request dispatch/reply and all initialization/termination/callback drain remain unresolved dependencies, not evidence of absence.",
            "Complete C# and IL methods retain original MethodDef/RVA/bytes/EH and all selected C# unresolved diagnostics; decompiler success or raw IL validation does not close external SDK semantics.",
            "Other thermal/CPU/GPU/monitoring/firmware/platform branches and other40 system products are separate; this slice does not establish them.",
            "Independent Rust replacement, UI/backend wiring, pure/mock tests, actual official DLL/device/error/cancel/restore/release comparisons and runtime acceptance remain unverified."])
    return result


def audit_system_737_performance_native_chain(args):
    import host
    if (args.family != "system" or args.function != "mw" or getattr(args, "prepare", False)
            or sorted(set(args.product or [737])) != [737]):
        raise ValueError("system-737-performance-native-chain requires PID737 system middleware without preparation")
    audit = host.HostLocalAudit()
    report = {"schema_version": 1, "recorded_at_utc": a.stamp(), "parser": audit.parser_versions,
        "kind": "current_system_737_performance_native_chain", "product_id": 737, "failures": [],
        "bounded_observation_complete": False, "source_chain_complete": False, "whole_product_complete": False,
        "target_execution": False, "real_device_operations": False, "rust_implementation": "not_reviewed",
        "official_dll_comparison": "not_executed", "runtime_acceptance": "unverified"}
    try:
        for name in ("tools/families.py", "tools/host.py", "tools/frontend.py", "tools/evidence.py"):
            audit.artifact(a.ROOT / name)
        report.update(collect_system_737_performance_native_chain(audit))
        report["bounded_observation_complete"] = not report["failures"]
    except (OSError, ValueError, KeyError, IndexError, TypeError, StopIteration) as error:
        report["failures"].append(type(error).__name__ + ": " + str(error))
    changed = audit.final_snapshot() + _system_737_performance_upstream_changes(report.get("upstream_sections", []))
    if changed:
        report["failures"].extend("System737 performance source changed during query: " + name for name in changed)
        report["bounded_observation_complete"] = False
    report.update(changed_during_query=changed, snapshot_stable=not changed,
        complete_originals=list(audit.sources.values()), complete_source_owners=list(audit.owners.values()),
        verified_artifacts=list(audit.artifacts.values()))
    destination = a.ROOT / ".analysis/results/frontend/system-mw-audit.json"
    host.publish_host_static_query(report, destination, a, "performance_native_chain")
    print(json.dumps({"receipt": a.rel(destination), "query": "system-737-performance-native-chain",
        "failures": report["failures"], "bounded_observation_complete": report["bounded_observation_complete"],
        "target_execution": False}), flush=True)
    if report["failures"]:
        raise ValueError("System737 performance source observation remains unresolved")
    return report


