def _system_737_overclock_sdk_upstream_changes(upstream):
    changed = []
    for row in upstream:
        try:
            value = json.loads((a.ROOT / row["receipt"]).read_bytes())["overclock_service_chain"]
            if _system_737_performance_digest(value) != row["canonical_sha256"]:
                changed.append(row["receipt"] + "#" + row["pointer"])
        except (OSError, ValueError, KeyError, TypeError):
            changed.append(row["receipt"] + "#" + row["pointer"])
    return changed


