    manifest, = [row for row in acquired["files"] if row.get("path")
                and row.get("url") == "https://apps.razer.com/synapse/products/737/mw/manifest.json"]
    declaration, = [row for row in json.loads(audit.read(manifest))["resourceManifest"]["resources"]
                   if row.get("resourceName") == "RazerIntelOverClock"]
    sha = "5040beb43ce5e2767a6d37bb92cde4146ee0c4592e393296ef50be8b11b9be69"
    if (declaration["resourceVersion"] != "1.0.4.0" or declaration["size"] != 1390072
            or declaration["sha256"].lower() != sha
            or declaration["integrity"] != "sha256-" + base64.b64encode(bytes.fromhex(sha)).decode()):
        raise ValueError("System737 overclock SDK package declaration needs renewed review")
    package, = [row for row in indexed["inputs"] if row.get("sha256") == sha and "/blobs/" in row["path"]]
    audit.read(package)
    originals = {}
