        if (not extracted.get("extracted") or not extracted.get("input_bytes_unchanged")
                or extracted.get("extraction_exit_code") != 0
                or not any(all(row.get(key) == original[key] for key in ("path", "sha256", "bytes"))
                           for row in extracted["files"])):
            raise ValueError("System737 overclock SDK extraction receipt differs: " + name)
        pe = host.inspect_pe(audit.read(original))
