    selected = {token: row for token, row in metadata["methods"].items()
                if row["name"] in selections.get(row["declaring_type"].split(".")[-1], ())}
    # The shared IL reader splits end labels on ::; retain exact PE names after parsing C++ template labels.
    aliases = {token: row["name"].rsplit("::", 1)[-1] for token, row in metadata["methods"].items() if "::" in row["name"]}
    parse_map = {token: {**row, "name": aliases.get(token, row["name"])} for token, row in metadata["methods"].items()}
    parse_selections = {owner: tuple(name.rsplit("::", 1)[-1] for name in names) for owner, names in selections.items()}
    methods = host._profile_gog_il_methods(original, text,
        {**metadata, "methods": parse_map, "selected_method_tokens": set(selected)}, parse_selections) if selected else []
    if {int(row["token"], 16) for row in methods} != set(selected):
        raise ValueError("System737 overclock SDK complete selected MethodDefs differ")
    for method in methods:
        identity = selected[int(method["token"], 16)]
        method["name"] = identity["name"]
        for call in method["calls"]:
            target = metadata["methods"].get(int(call["token"], 16))
            if target is not None and call["resolved_method"] is not None:
                call["resolved_method"]["name"] = target["name"]
        if identity["implementation_kind"] != "il" or not identity["body_decoded"]:
            raise ValueError("System737 overclock SDK method is not original IL")
        method["method_identity"] = {key: identity[key] for key in ("token", "rva", "implementation_flags",
            "method_flags", "implementation_kind", "metadata_row_hex", "body_decoded")}
    sources = []
    for suffix in source_names:
        source, = [row for row in capture["outputs"] if row["path"].endswith("/source/" + suffix)]
        audit.artifact(a.ROOT / source["path"], source)
        sources.append(source)
    slots = []
    if "<Module>" in selections:
        import struct
        raw = audit.read(original)
        optional = struct.unpack_from("<I", raw, 0x3c)[0] + 24
        directories = optional + (112 if struct.unpack_from("<H", raw, optional)[0] == 0x20b else 96)
        cli_rva, _ = struct.unpack_from("<II", raw, directories + 14 * 8)
        fixup_rva, fixup_size = struct.unpack_from("<II", metadata["read"](cli_rva, 72), 48)
        table = metadata["read"](fixup_rva, fixup_size)
        entries = [struct.unpack_from("<IHH", table, at) for at in range(0, len(table), 8)]
        for slot, token, thunk in ((0xa72c0, 0x06000043, 0x4a040), (0xa7310, 0x06000044, 0x4a090)):
            entry, = [row for row in entries if row[0] == slot]
            encoded = metadata["read"](slot, 8)
            if entry[1:] != (1, 10) or int.from_bytes(encoded, "little") != token:
                raise ValueError("System737 overclock SDK original CLR lifecycle fixup differs")
            slots.append({"slot_rva": hex(slot), "method_token": hex(token), "raw_hex": encoded.hex(),
                "thunk_rva": hex(thunk), "target_name": metadata["methods"][token]["name"],
                "target_rva": metadata["methods"][token]["rva"], "count": entry[1], "type": hex(entry[2])})
    return {"original": original, "il_artifact": il, "source_artifacts": sources, "complete_methods": methods,
        "vtable_slots": slots,
        "capture_input": {key: capture[key] for key in ("capture_complete", "all_csharp_resolved", "input_bytes_unchanged")},
        "diagnostic_count": len(capture["diagnostics"]), "target_execution": False}


