def audit_hanbo_gpu_temperature_chain(args):
    import host
    if (args.family != "accessories" or args.function != "main"
            or (args.product or [3893]) != [3893] or getattr(args, "prepare", False)):
        raise ValueError("Hanbo GPU temperature chain requires accessories/main PID3893 without preparation")
    audit = host.HostLocalAudit()
    report = {"schema_version": 1, "kind": "current_hanbo_gpu_temperature_chain", "failures": [],
        "bounded_observation_complete": False, "source_chain_complete": False,
        "target_execution": False, "runtime_acceptance": "unverified"}
    try:
        for name in ("tools/families.py", "tools/host.py", "tools/frontend.py", "tools/evidence.py"):
            audit.artifact(a.ROOT / name)
        report.update(collect_hanbo_gpu_temperature_chain(audit))
        report["bounded_observation_complete"] = True
    except (OSError, ValueError, KeyError, IndexError, TypeError, StopIteration) as error:
        report["failures"].append(type(error).__name__ + ": " + str(error))
    report.update(recorded_at_utc=a.stamp(), complete_originals=list(audit.sources.values()),
        complete_source_owners=list(audit.owners.values()), verified_artifacts=list(audit.artifacts.values()))
    changed = audit.final_snapshot()
    report.update(changed_during_query=changed, snapshot_stable=not changed)
    if changed:
        report["failures"].extend("Hanbo GPU temperature source changed: " + name for name in changed)
        report["bounded_observation_complete"] = False
    if json.loads(json.dumps(report, ensure_ascii=False, sort_keys=True)) != report:
        raise ValueError("Hanbo GPU temperature receipt changes during JSON roundtrip")
    destination = a.ROOT / ".analysis/results/frontend/accessories-main-audit.json"
    host.publish_host_static_query(report, destination, a, "hanbo_gpu_temperature_chain")
    print(json.dumps({"receipt": a.rel(destination), "query": args.query,
        "failures": report["failures"], "bounded_observation_complete": report["bounded_observation_complete"],
        "target_execution": False, "runtime_acceptance": "unverified"}), flush=True)
    if report["failures"]:
        raise ValueError("Hanbo GPU temperature observation remains unresolved")
    return report


def _hanbo_cpu_monitor_providers():
    """The actual Intel families sharing the consumed Package MSR capability."""
    return [
        {"name": name, "vtable_rva": table, "constructor_rva": constructor,
         "initialize_rva": initialize, "temperature_rva": temperature,
         "family": family, "models": models}
        for name, table, constructor, initialize, temperature, family, models in (
            ("sandy_bridge", 0x3062d8, 0x1527a0, 0x156b40, 0x156170, 6, [0x2a, 0x2d, 0x3a, 0x3e]),
            ("haswell", 0x305b38, 0x168a20, 0x168cb0, 0x167fa0, 6,
                [0x3c, 0x3d, 0x3f, 0x45, 0x46, 0x47, 0x4f, 0x56]),
            ("skylake", 0x306438, 0x14c9e0, 0x14ce40, 0x14b6e0, 6,
                [0x4e, 0x55, 0x5e, 0x66, 0x67, 0x6a, 0x7d, 0x7e, 0x8c, 0x8d, 0x8e,
                 0x8f, 0x97, 0x9a, 0x9e, 0xa5, 0xa6, 0xa7, 0xa8, 0xaa, 0xac, 0xad,
                 0xaf, 0xb5, 0xb6, 0xb7, 0xba, 0xbd, 0xbe, 0xbf, 0xc5, 0xc6, 0xcc,
                 0xcf, 0xd5, 0xd7, 0xe5]),
            ("silvermont", 0x306388, 0x1507b0, 0x151b80, 0x150d10, 6, [0x37, 0x4a, 0x4c, 0x4d]),
            ("goldmont", 0x305a78, 0x16acc0, 0x16bf40, 0x16b410, 6, [0x5c, 0x5f, 0x7a, 0x96, 0x9c]),
            ("family_12", 0x3059c8, 0x16dc20, 0x16df30, 0x16d5d0, 0x12, []))]


def _hanbo_cpu_monitor_roles():
    sdk = {
        0x141480: "cpu_vendor_identity", 0x1766a0: "intel_family_dispatch",
        0x1a6d50: "amd_family_dispatch_boundary", 0x17a3e0: "hygon_family_dispatch_boundary",
        0x13dbd0: "family_owner_attach_and_initialize", 0x13bff0: "cpu_temperature_provider_priority",
        0x13f930: "msr_actual_read_and_cached_register", 0x14e58: "driver_device_io_msr_read",
        0xc1630: "affinity_worker_periodic_temperature", 0xc1840: "initial_temperature_worker",
        0xbb3a0: "cpu_affinity_worker_creation", 0xbb2c0: "cpu_stop_and_join_retained_workers",
        0xbc760: "cpu_owner_list_release", 0x13bd60: "cpu_worker_provider_stop",
        0x13b1c0: "cpu_visible_sensor_adoption", 0xbde20: "cpu_sensor_owner_and_visible_registration",
        0x1b1660: "sdk_visible_sensor_result", 0x13b090: "sdk_valid_kind_filter",
        0x65a30: "temperature_sensor_constructor", 0x627d0: "temperature_sensor_validity",
        0xe990: "temperature_sensor_buffer_and_allocation_release"}
    for row in _hanbo_cpu_monitor_providers():
        for key, role in (("constructor_rva", "constructor"), ("initialize_rva", "initialize"),
                ("temperature_rva", "core_and_package_temperature")):
            sdk[row[key]] = row["name"] + "_" + role
    return {"sdk": sdk, "service": {
        0x14a40: "monitor_initialization", 0x14210: "actual_snapshot_sensor_kinds",
        0x14d50: "sensor_kind_json_group", 0x15070: "all_hardware_sensor_result_consumer",
        0x16000: "all_hardware_snapshot_and_status", 0x47ed0: "all_hardware_export_refresh_and_malloc",
        0x5420: "sdk_result_byte_bstr_release", 0x45090: "malloc_result_release"}}


def _hanbo_cpu_monitor_slots():
    rows = [("intel_family_dispatch", 0x305708, 48, 0x1766a0),
        ("amd_family_dispatch_boundary", 0x304b38, 48, 0x1a6d50),
        ("hygon_family_dispatch_boundary", 0x3054f8, 48, 0x17a3e0),
        ("cpu_vendor_identity", 0x306bd0, 0, 0x141480),
        ("cpu_worker_provider_stop", 0x306bd0, 8, 0x13bd60),
        ("cpu_initialize", 0x30c6a0, 0, 0xbb3a0),
        ("cpu_stop_join", 0x30c6a0, 8, 0xbb2c0),
        ("cpu_sensor_adoption", 0x30d888, 56, 0x13b1c0),
        ("temperature_sensor_delete", 0x30f148, 0, 0xe990),
        ("temperature_sensor_validity", 0x30f148, 8, 0x627d0)]
    for provider in _hanbo_cpu_monitor_providers():
        rows.extend((provider["name"] + "_" + key, provider["vtable_rva"], offset, provider[key])
            for key, offset in (("initialize_rva", 40), ("temperature_rva", 64)))
    return [{"role": role, "vtable_rva": table, "slot_byte_offset": offset, "target_rva": target}
        for role, table, offset, target in rows]


def _hanbo_cpu_monitor_native_contract(modules):
    expected = {"sdk": "b2945fa987aa3fe80a272866af4517184f78a4cbb24f6e7ef428cbf8ba1caeee",
        "service": "0203aae0c04f95313f1793c03037c6269c21ca8d8cfb195a3d21bbc95b0c4fd7"}
    roles, bodies, fingerprints = _hanbo_cpu_monitor_roles(), {}, {}
    if set(modules) != set(expected):
        raise ValueError("Hanbo CPU monitor selected native modules changed")
    for name, module in modules.items():
        selected = module["complete_selected_functions"]
        if (module["failures"] or not module["capture_complete"] or module["target_execution"]
                or len(selected) != len(roles[name])
                or {int(row["capture"]["rva"], 0): row["role"] for row in selected} != roles[name]):
            raise ValueError("Hanbo CPU monitor native owner set changed: " + name)
        rows, bodies[name] = [], {}
        for row in selected:
            body = row["capture"]
            if (row["failures"] or not row["input_chunks_verified"] or not row["assembly_captured"]
                    or not row["pseudocode_captured"] or not body["chunks"]):
                raise ValueError("Hanbo CPU monitor complete native owner is absent: " + name)
            text = "\n".join(line["text"] for line in body["pseudocode"]["lines"])
            bodies[name][int(body["rva"], 0)] = text
            rows.append([body["rva"], row["role"], text,
                [(line["rva"], line["text"], line["bytes"]) for line in body["assembly"]]])
        digest = hashlib.sha256(json.dumps(sorted(rows), ensure_ascii=False, separators=(",", ":")).encode()).hexdigest()
        if digest != expected[name]:
            raise ValueError("Hanbo CPU monitor complete native boundary changed: " + name)
        fingerprints[name] = digest
    for provider in _hanbo_cpu_monitor_providers():
        text = bodies["sdk"][provider["temperature_rva"]]
        if not all(token in text for token in ("sub_18013F930(a2, 433)", "a2 + 1264",
                "0x1802000u", "& 0x7F", "+ 376", "+ 360", "a2 + 1008")):
            raise ValueError("Hanbo CPU monitor actual Package provider differs: " + provider["name"])
    return {"complete_body_fingerprints": fingerprints,
        "scope": "Six current Intel Package MSR provider groups and their consumed result path; AMD/Hygon and other actual providers are unresolved.",
        "vendor_strings": ["GenuineIntel", "GenuineIotel"], "family_dispatch_rva": "0x1766a0",
        "provider_priority_owner_offsets": [32, 24, 16], "provider_temperature_slot": 64,
        "core_status_msr": 0x19c, "package_status_msr": 0x1b1, "temperature_target_msr": 0x1a2,
        "creation_requires_status_bit31": True, "existing_sensor_refresh_rechecks_status_bit31": False,
        "temperature_delta": {"shift": 16, "mask": 0x7f},
        "package_sensor_identifier": 0x1802001, "package_sensor_owner_offset": 1264,
        "temperature_target_source_default_celsius": 100, "target_default_is_observed_hardware": False,
        "driver": {"read_owner_rva": "0x14e58", "handle_offset": 528, "mode_offset": 2852,
            "modes": [{"mode": 1, "ioctl": 1, "input_bytes": 4, "output_capacity": 40},
                {"mode": 2, "ioctl": 0x9c402440, "input_bytes": 4, "output_capacity": 8}],
            "checks_returned_byte_count": False, "success_rejects_only_both_words_all_ones": True},
        "failed_read_clears_existing_temperature": False, "failed_read_is_fresh_observation": False,
        "service": {"version": "1.0.30.0", "device_class": 4, "sensor_kind": 0x2000,
            "json_path": "CPUInfo[*].Temperatures.Package", "iterator_rva": "0x15070",
            "iterates_all_valid_sensors_in_actual_callback_snapshot": True,
            "current_valid_above": -4294967300.0, "rounding_decimals": 2,
            "sensor_name_source": "SDK byte-BSTR", "byte_bstr_freed": True, "malloc_result_freed": True},
        "release": {"cpu_stop_sets_global_flag": True, "retained_worker_wait_ms": "INFINITE",
            "checks_worker_wait_result_before_close": False,
            "per_read_cancellation_token": False, "whole_service_callback_quiescence_proven": False}}


def _hanbo_cpu_monitor_native_reference(audit, native):
    audit.read(native["input"])
    audit.artifact(a.ROOT / native["capture_receipt"]["path"], native["capture_receipt"])
    functions = []
    for row in native["complete_selected_functions"]:
        audit.artifact(a.ROOT / row["artifact"]["path"], row["artifact"])
        body = row["capture"]
        functions.append({"role": row["role"], "rva": body["rva"], "artifact": row["artifact"],
            "pseudocode_sha256": hashlib.sha256("\n".join(line["text"] for line in
                body["pseudocode"]["lines"]).encode()).hexdigest(), "input_chunks_verified": row["input_chunks_verified"]})
    return {key: value for key, value in native.items() if key != "complete_selected_functions"} | {"functions": functions}


def collect_hanbo_cpu_monitor_chain(audit):
    """Continue only the current Hanbo CPU Package temperature capability."""
    import frontend
