def audit_hanbo_hygon_package_chain(args):
    import host
    if (args.family != "accessories" or args.function != "main"
            or (args.product or [3893]) != [3893] or getattr(args, "prepare", False)):
        raise ValueError("Hanbo Hygon Package chain requires accessories/main PID3893 without preparation")
    audit = host.HostLocalAudit()
    report = {"schema_version": 1, "query": "hanbo-hygon-package-chain", "kind": "current_hanbo_hygon_package_chain",
        "failures": [], "bounded_observation_complete": False, "source_chain_complete": False,
        "target_execution": False, "runtime_acceptance": "unverified"}
    try:
        for name in ("tools/families.py", "tools/host.py", "tools/frontend.py", "tools/evidence.py"):
            audit.artifact(a.ROOT / name)
        report.update(collect_hanbo_hygon_package_chain(audit))
    except (OSError, ValueError, KeyError, IndexError, TypeError, StopIteration) as error:
        report["failures"].append(type(error).__name__ + ": " + str(error))
    changed = audit.final_snapshot() + host._keypad_temporary_keymap_dependency_changes(report.get("upstream_sections", []))
    if changed:
        report["failures"].extend("Hanbo Hygon Package input changed: " + name for name in changed)
    report.update(recorded_at_utc=a.stamp(), changed_during_query=changed, snapshot_stable=not changed,
        bounded_observation_complete=not report["failures"],
        complete_originals=list(audit.sources.values()), complete_source_owners=list(audit.owners.values()),
        verified_artifacts=list(audit.artifacts.values()))
    destination = a.ROOT / ".analysis/results/frontend/accessories-main-audit.json"
    host.publish_host_static_query(report, destination, a, "hanbo_hygon_package_chain")
    print(json.dumps({"receipt": a.rel(destination), "query": report["query"], "failures": report["failures"],
        "bounded_observation_complete": report["bounded_observation_complete"], "target_execution": False}), flush=True)
    if report["failures"]:
        raise ValueError("Hanbo Hygon Package observation remains unresolved")
    return report


