def _hanbo_amd_package_slots():
    rows = []
    for name, table, targets in (
            ("amd_vendor", 0x304b38, (0x1a75e0, 0x1a7a10, 0x1a6d50, 0x38b0, 0x3af0, 0x1a83e0)),
            ("k10", 0x304c98, (0x1a8410, 0x1a5b70, 0x1a2ed0, 0x1a26b0, 0x3b90, 0x1a83e0)),
            ("k12", 0x304d58, (0x1a8410, 0x1a1f60, 0x1a0650, 0x1a1110, 0x3ea0, 0x1a83e0))):
        rows.extend((name + "_" + role, table, offset, target)
            for role, offset, target in zip(("identify", "initialize", "dispatch", "temperature", "delete", "stop"),
                (32, 40, 48, 64, 112, 120), targets))
    rows.extend((name + "_" + role, table, offset, target)
        for name, table, read, write in (("pci", 0x30dcb8, 0x769a0, 0x76950),
            ("pci_type2", 0x30dd08, 0x767d0, 0x76790), ("pci_type3", 0x30dd58, 0x76750, 0x76950))
        for role, offset, target in (("read", 56, read), ("write", 64, write)))
    rows.extend(("ecs_" + role, 0x303580, offset, target) for role, offset, target in
        (("delete", 0, 0x1250), ("original", 8, 0x1bc2a0), ("enable", 16, 0x1bc210), ("restore", 24, 0x1bc170)))
    rows.extend((name + "_temperature_boundary", table, 64, target) for name, table, target in
        (("k8", 0x3052e8, 0x17d850), ("k14", 0x304e08, 0x19ed50), ("k15", 0x304eb8, 0x19d2c0),
            ("k16", 0x304f68, 0x195330), ("k17", 0x305018, 0x1841d0)))
    return [{"role": role, "vtable_rva": table, "slot_byte_offset": offset, "target_rva": target}
        for role, table, offset, target in rows]


