def _hanbo_hid_write_current_native_contract(native):
    functions = {row["capture"]["rva"]: row for row in native["complete_selected_functions"]}
    expected = {
        "0xcc90": ('*v7 = (unsigned __int64)sub_1800094E0', 'v36[0] = (unsigned __int64)"close"',
            '*v9 = (unsigned __int64)sub_18000A110', 'v36[8] = (unsigned __int64)"write"',
            '*v17 = (unsigned __int64)sub_180006FB0', 'v36[40] = (unsigned __int64)"readTimeout"'),
        "0xa110": ('napi_get_array_length', 'hid_write(v35, v44, *((_QWORD *)&v44 + 1) - v44) >= 0',
            'napi_create_double', 'Cannot write to hid device', 'Cannot write to closed device'),
        "0x175e0": ('v4 = *(unsigned __int16 *)(a1 + 12)', 'v5 = a3', 'v7 = -1',
            'if ( a3 < v4 )', 'v8 = a2', 'WriteFile(*(HANDLE *)a1, v8, v5, 0,',
            'WaitForSingleObject(*(HANDLE *)(a1 + 104), 0x3E8u)',
            'v7 = NumberOfBytesTransferred', 'if ( v8 != a2 )', 'return v7'),
        "0x6fb0": ('hid_read_timeout(*(_QWORD *)(a1 + 40), v27, 2048, (unsigned int)v19)',
            'if ( timeout == -1 )', 'could not read data from device', 'napi_create_array_with_length(v7, timeout,'),
        "0x17800": ('ReadFile(*(HANDLE *)a1, *v10, *(_DWORD *)(a1 + 16)',
            'WaitForSingleObject(v11, a4)', '*(_DWORD *)(a1 + 36) = 1',
            'if ( WaitForSingleObject(v11, a4) )\n      return 0;', 'if ( !*(_BYTE *)*v10 )',
            'a3 > --NumberOfBytesRead', 'sub_18003E5D0(a2, v18 + 1, v4)', 'return 0xFFFFFFFFLL'),
        "0x94e0": ('sub_180006170(a1)', 'napi_get_null(v7, &v8)'),
        "0x6170": ('v1 = *(HANDLE **)(a1 + 40)', 'CancelIo(*v1)', 'CloseHandle(v1[9])',
            'CloseHandle(v1[13])', 'CloseHandle(*v1)', 'LocalFree(v1[3])',
            'sub_180026870(v1[5])', 'sub_180026870(v1)', '*(_QWORD *)(a1 + 40) = 0'),
    }
    bodies = {}
    for rva, tokens in expected.items():
        row = functions.get(rva, {})
        body = "\n".join(line["text"] for line in row.get("capture", {}).get("pseudocode", {}).get("lines", []))
        if (row.get("failures") or not row.get("assembly_captured") or not row.get("pseudocode_captured")
                or not row.get("input_chunks_verified") or not all(token in body for token in tokens)):
            raise ValueError("Hanbo current HID complete native boundary changed: " + rva)
        bodies[rva] = body
    instructions = {row["rva"]: row for function in functions.values() for row in function["capture"]["assembly"]}
    assertions = []
    for rva, raw in (("0xa7da", "e801ce0000"), ("0xa87b", "660f6ec8"),
            ("0xa87f", "f30fe6c9"), ("0xa88b", "ff155f1f0500")):
        if rva not in instructions or instructions[rva]["bytes"] != raw:
            raise ValueError("Hanbo current HID native return-count instructions changed: " + rva)
        assertions.append({"rva": rva, "bytes": raw, "instruction": instructions[rva]["text"]})
    if ("CancelIo" in bodies["0x175e0"] or "WaitForSingleObject" in bodies["0x6170"]
            or bodies["0x6170"].index("CancelIo(*v1)") >= bodies["0x6170"].index("CloseHandle(*v1)")):
        raise ValueError("Hanbo current HID native timeout/close waiting boundary changed")
    return {"prototype": {"write": "0xa110", "readTimeout": "0x6fb0", "close": "0x94e0"},
        "write_uses_entire_array_length": True, "pads_only_when_shorter_than_output_caps": True,
        "truncates_oversized_buffer": False, "native_count_encoded_as_js_number": True,
        "overlapped_write_wait_ms": 1000, "overlapped_completion_supplies_returned_count": True,
        "synchronous_write_success_retains_initial_negative_result": True,
        "write_wait_failure_cancels_pending_io": False,
        "read_buffer_capacity": 2048, "read_strips_report_id_only_if_zero": True,
        "read_timeout_keeps_pending_read_for_next_call": True,
        "close_cancels_io_closes_handles_frees_buffer_and_clears_pointer": True,
        "close_waits_for_complete_pending_io_or_callback_drain": False,
        "instruction_assertions": assertions, "actual_66_byte_write_acceptance": "unverified"}


def collect_hanbo_hid_write_current_chain(audit):
    """Rebind the established 66/65 boundary to current retained callers only."""
    selected, sources, runtime, upstream, release = _hanbo_hid_write_current_inputs(audit)
    roles = _hanbo_hid_write_current_owners(audit, selected, sources)
    source_contract = _hanbo_hid_write_current_source_contract({role: audit.owners[key] for role, key in roles.items()})
    native = verify_native_functions(sources["addon"], {"0xcc90": "node_hid_prototype_registration",
        "0xa110": "node_hid_write_array_and_native_return_count", "0x6fb0": "node_hid_read_timeout",
        "0x175e0": "hid_write_windows_WriteFile", "0x17800": "hid_read_timeout_windows_ReadFile_and_zero_report_id",
        "0x94e0": "node_hid_close_callback", "0x6170": "node_hid_close_io_handles_buffer_and_pointer"})
    audit.artifact(a.ROOT / native["capture_receipt"]["path"], native["capture_receipt"])
    for row in native["complete_selected_functions"]:
        audit.artifact(a.ROOT / row["artifact"]["path"], row["artifact"])
    native_contract = _hanbo_hid_write_current_native_contract(native)
    comparison = []
    for role in ("elsa_constructor", "elsa__sendCommand", "elsa__getHIDInputReportResult", "host_hidRead"):
        prior, = [row for row in runtime["complete_owners"].values() if role in row["roles"]]
        comparison.append({"role": role, "prior_owner": prior["id"], "current_owner": roles[role],
            "complete_body_equal": prior["body"] == audit.owners[roles[role]]["body"]})
    references = {key: native[key] for key in ("input", "capture_receipt", "image_base", "ida_version",
        "hexrays_version", "capture_tool", "capture_complete", "functions_total", "functions_captured",
        "failures", "target_execution")} | {"functions": [{"role": row["role"],
            "rva": row["capture"]["rva"], "artifact": row["artifact"],
            "assembly_captured": row["assembly_captured"], "pseudocode_captured": row["pseudocode_captured"],
            "input_chunks_verified": row["input_chunks_verified"],
            "verified_original_chunks": row["verified_original_chunks"]}
            for row in native["complete_selected_functions"]]}
    return {"schema_version": 1, "kind": "current_hanbo_hid_write_chain", "query": "hanbo-hid-write-current-chain",
        "product_id": 3893, "upstream_sections": upstream, "host_release": release,
        "source_selection": {key: selected[key] for key in ("name", "acquisition", "candidate_decisions")},
        "roles": roles, "native": references, "source_contract": source_contract,
        "native_contract": native_contract, "retained_owner_comparisons": comparison,
        "selected_current_transport_semantics_reviewed": True,
        "semantics": {
            "write": "Current Elsa still prefixes its65-byte buffer with claimInterface, forwards66 array elements through the actual MW/apiElectron/preload/main route, and accepts only count65. Current Host does not truncate by reportLength. The selected node-rz-hid package binds native prototype methods to its raw HID object; native write sends the whole array, pads only below output caps, and exposes the signed native count as a JS number. The retained66/65 conclusion is reused, not a claim that Windows or a device accepts it.",
            "response": "Only count65 reaches the inter-operation delay and hid.read. Host performs at most five readTimeout(10) calls and does not use payload reportId/reportLength; getInputReport remains a separate action. Native uses a2048-byte destination and strips only a leading zero report ID. Elsa requires64 bytes and the expected two header bytes, retries reads up to maxRetryIn, then may retry the write up to maxRetryOut. Host write exceptions return undefined and read exceptions return an empty array; neither is a successful response. A thrown exception inside the selected send try exits its write loop and becomes the source failure exception.",
            "release": "Host hid.removeDevice closes matching HID objects and cancels their mutex before removing maps. The actually bound close callback calls the selected CancelIo/CloseHandle/buffer-release owner and clears its native pointer. There is no selected wait proving pending I/O or callback drain, and the selected navigator lock/send/read chain has no AbortSignal. Write timeout likewise has no selected CancelIo. These observations do not establish whole-session cancellation or concurrent-removal safety."},
        "remaining_chains": [
            "Actual Windows/device acceptance of the66-byte write and65 returned count, response/error/timeout behavior, cancellation, restore and release require actual official addon/device comparison and remain unverified.",
            "Other Hanbo product, firmware and transport branches, previously recorded sensor/provider chains and complete concurrent session/callback quiescence remain separately unresolved; this current-input rebinding does not close the whole product or HID addon.",
            "Independent Rust implementation, production caller replacement, UI/backend wiring, pure/mock validation and actual official DLL/device/runtime acceptance remain required and separately recorded."],
        "source_chain_complete": False, "whole_product_complete": False, "target_execution": False,
        "real_device_operations": False, "actual_dll_comparison": "unverified",
        "rust_independent_implementation": "unverified", "ui_backend_wiring": "unverified",
        "runtime_acceptance": "unverified", "product_code_modified": False}


def _hanbo_hid_write_current_upstream_changes(upstream):
    """Recheck upstream sections without freezing the shared destination file."""
    changed, receipts = [], {}
    for row in upstream:
        try:
            if row["receipt"] not in receipts:
                receipts[row["receipt"]] = json.loads((a.ROOT / row["receipt"]).read_bytes())
            value = receipts[row["receipt"]]
            for part in row["pointer"].lstrip("/").split("/"):
                value = value[part.replace("~1", "/").replace("~0", "~")]
            actual = hashlib.sha256(json.dumps(value, ensure_ascii=False,
                sort_keys=True, separators=(",", ":")).encode()).hexdigest()
            if actual != row["canonical_sha256"]:
                changed.append(row["receipt"] + "#" + row["pointer"])
        except (OSError, ValueError, KeyError, TypeError):
            changed.append(row["receipt"] + "#" + row["pointer"])
    return changed


def audit_hanbo_hid_write_current_chain(args):
    import host
    if (args.family != "accessories" or args.function != "main"
            or (args.product or [3893]) != [3893] or getattr(args, "prepare", False)):
        raise ValueError("Hanbo current HID chain requires accessories/main PID3893 without preparation")
    audit = host.HostLocalAudit()
    report = {"schema_version": 1, "kind": "current_hanbo_hid_write_chain", "failures": [],
        "bounded_observation_complete": False, "source_chain_complete": False,
        "target_execution": False, "runtime_acceptance": "unverified"}
    try:
        for name in ("tools/families.py", "tools/host.py", "tools/frontend.py", "tools/evidence.py"):
            audit.artifact(a.ROOT / name)
        report.update(collect_hanbo_hid_write_current_chain(audit))
        report["bounded_observation_complete"] = not report["failures"]
    except (OSError, ValueError, KeyError, IndexError, TypeError, StopIteration) as error:
        report["failures"].append(type(error).__name__ + ": " + str(error))
    report.update(recorded_at_utc=a.stamp(), complete_originals=list(audit.sources.values()),
        complete_source_owners=list(audit.owners.values()), verified_artifacts=list(audit.artifacts.values()))
    changed = audit.final_snapshot() + _hanbo_hid_write_current_upstream_changes(report.get("upstream_sections", []))
    report.update(changed_during_query=changed, snapshot_stable=not changed)
    if changed:
        report["failures"].extend("Hanbo current HID source changed: " + name for name in changed)
        report["bounded_observation_complete"] = False
    if json.loads(json.dumps(report, ensure_ascii=False, sort_keys=True)) != report:
        raise ValueError("Hanbo current HID receipt changes during JSON roundtrip")
    destination = a.ROOT / ".analysis/results/frontend/accessories-main-audit.json"
    host.publish_host_static_query(report, destination, a, "hanbo_hid_write_current_chain")
    print(json.dumps({"receipt": a.rel(destination), "query": args.query,
        "failures": report["failures"], "bounded_observation_complete": report["bounded_observation_complete"],
        "target_execution": False, "runtime_acceptance": "unverified"}), flush=True)
    if report["failures"]:
        raise ValueError("Hanbo current HID observation remains unresolved")
    return report


