    originals, source_owners = {}, []
    for row in report["products"]:
        if row["product_id"] not in selected:
            continue
        if row.get("failures"):
            raise ValueError("Camera review requires a complete successful current source query")
        for ref in row["complete_owners"]:
            if ref["role"] not in roles:
                continue
            owner = report["complete_owners"][ref["key"]]
            source = owner["original"]
            if not valid(source):
                raise ValueError("Camera review original byte identity differs: " + source["path"])
            body = (a.ROOT / source["path"]).read_bytes()[owner["byte_start"]:owner["byte_end"]]
            if body.decode("utf-8") != owner["body"] or hashlib.sha256(body).hexdigest() != owner["body_sha256"]:
                raise ValueError("Camera review complete owner no longer matches original bytes")
