def audit_keyboard_brightness(args):
    """Capture current active brightness owners, then prepare typed descriptors."""
    import sys
    import importlib.metadata
    sys.path.insert(0, str(a.ROOT / "tools/analyzers/python-static"))
    from tree_sitter import Language, Parser
    import tree_sitter_javascript
    if args.family != "keyboard" or args.function != "mw":
        raise ValueError("keyboard-brightness requires keyboard middleware")
    requested = sorted(set(args.product or [631, 658, 756]))
    if set(requested) - {631, 658, 756}:
        raise ValueError("Resolve additional current brightness factories before extending this query")
    parser = Parser(Language(tree_sitter_javascript.language()))
    indexed = {item["path"]: item for item in json.loads((a.ROOT / ".analysis/inputs.json").read_bytes())["inputs"]}
    anchors = {"getter": "getBrightness({", "setter": "setBrightness({", "runner": "taskRunnerSetBrightnessToDevice",
               "task_maker": "taskMakerSetBrightness", "state_machine": "brightnessNestedIdle",
               "ui_action": "ON_SET_BRIGHTNESS", "ui_label": "BRIGHTNESS_HEADER",
               "ui_storage": "brightness:{isEnabled:", "registration": 'useFeature("rzDeviceType"',
               "radio_factory": 'this.name="rzDevice25DualLinkKeyboard"',
               "region_constants": "BacklightLED", "host_sender": "getFeatureReport"}
    modules, functions, products, descriptors = {}, {}, [], []
    def retain(node, raw, store):
        body = raw[node.start_byte:node.end_byte]
        sha = hashlib.sha256(body).hexdigest()
        store[sha] = {"bytes": len(body), "sha256": sha, "complete_body": body.decode("utf-8")}
        return {"syntax": node.type, "byte_start": node.start_byte, "byte_end": node.end_byte, "body_sha256": sha}
    for pid in requested:
        row = {"product_id": pid, "acquisitions": [], "modules": [], "functions": [], "failures": [], "unresolved": []}
        products.append(row)
        try:
            layers = {}
            for layer, name in [("mw", f"keyboard-mw-{pid}-current"), ("ui", f"keyboard-{pid}-current")]:
                receipt_path = a.ROOT / ".analysis/inputs/frontend" / name / "acquisition.json"
                acquired = json.loads(receipt_path.read_bytes())
                if acquired.get("source_current_during_acquisition") is not True:
                    raise ValueError("Current stable deployment is absent: " + name)
                files = [item for item in acquired["files"] if item.get("path")]
                if not all(valid(item) and all(indexed.get(item["path"], {}).get(key) == value for key, value in identity(a.ROOT / item["path"]).items()) for item in files):
                    raise ValueError("Original bytes or acquisition index differ: " + name)
                row["acquisitions"].append({"name": name, "receipt": identity(receipt_path), "stability": acquired.get("stability"),
                    "complete_original_inputs": files, "declared_references_fetched": acquired.get("declared_references_fetched"),
                    "unresolved": acquired.get("unresolved", []), "acquisition_failures": [item for item in acquired["files"] if not item.get("path")]})
                layers[layer] = []
                for original in files:
                    if not original["path"].endswith(".js"):
                        continue
                    raw = (a.ROOT / original["path"]).read_bytes()
                    text = raw.decode("utf-8")
                    if not any(anchor in text for anchor in anchors.values()):
                        continue
                    tree = parser.parse(raw)
                    if tree.root_node.has_error:
                        raise ValueError("JavaScript grammar failed: " + original["path"])
                    owners = keyboard_source_modules(text)
                    for owner in owners:
                        if not isinstance(owner["module_id"], int):
                            continue
                        roles = [role for role, anchor in anchors.items() if anchor in owner["body"]]
                        layers[layer].append((original, owner))
                        if not roles:
                            continue
                        node = tree.root_node.descendant_for_byte_range(owner["byte_start"], owner["byte_end"] - 1)
                        while node is not None and (node.start_byte != owner["byte_start"] or node.end_byte != owner["byte_end"]):
                            node = node.parent
                        if node is None:
                            raise ValueError("Module source boundary changed")
                        row["modules"].append({"layer": layer, "original": identity(a.ROOT / original["path"]), "module_id": owner["module_id"], "roles": roles, **retain(node, raw, modules)})
                        pending = list(node.named_children)
                        while pending:
                            child = pending.pop()
                            pending.extend(child.named_children)
                            if child.type not in {"method_definition", "function_declaration", "arrow_function", "function_expression", "generator_function"}:
                                continue
                            child_roles = [role for role, anchor in anchors.items() if anchor.encode() in child.text]
                            if child_roles:
                                row["functions"].append({"layer": layer, "original": identity(a.ROOT / original["path"]), "module_id": owner["module_id"], "roles": child_roles, **retain(child, raw, functions)})
            def one(layer, predicate):
                selected = [(original, owner) for original, owner in layers[layer] if predicate(original, owner)]
                if len(selected) != 1:
                    raise ValueError("Brightness owner selection is ambiguous: " + str([(Path(source["path"]).name, owner["module_id"]) for source, owner in selected]))
                return selected[0]
            main, registration = one("mw", lambda source, owner: Path(source["path"]).name.startswith("main.") and 'useFeature("rzDeviceType"' in owner["body"])
            _, protocol = one("mw", lambda source, owner: Path(source["path"]).name.startswith("rzDevice25.") and "getBrightness({" in owner["body"])
            _, config = one("mw", lambda source, owner: Path(source["path"]).name.startswith("main.") and f"productId:{pid}," in owner["body"] and "claimInterface:" in owner["body"])
            if '"rzDevice25",{' not in registration["body"] or "isDualLinkDevice:!0" not in registration["body"] or "brightness:{hasTwoMode:!1}" not in registration["body"]:
                raise ValueError("Active source brightness factory changed")
            body = protocol["body"]
            for token in ["getBrightness({profileId:t,regionId:n})", "setBrightness({profileId:t,regionId:n,brightness:e})", "Math.floor(o/100*255)", "Math.ceil(t.data[2]/255*100)", "t+=5", "catch(t){n=1}"]:
                if token not in body:
                    raise ValueError("Brightness protocol body changed: " + token)
            # Resolve command exports from the actual imported constant module,
            # rather than accepting identical numeric literals in another chunk.
            alias = "kt" if pid == 756 else "Pt"
            constant_id = int(re.search(r'\b' + alias + r'=e\((\d+)\)', body)[1])
            command_source, constants = one("mw", lambda source, owner: owner["module_id"] == constant_id and Path(source["path"]).name.startswith("rzDevice25."))
            # Retain the complete constant module even when no visible text anchor occurs.
            raw = (a.ROOT / command_source["path"]).read_bytes()
            const_body = raw[constants["byte_start"]:constants["byte_end"]]
            sha = hashlib.sha256(const_body).hexdigest()
            modules[sha] = {"bytes": len(const_body), "sha256": sha, "complete_body": const_body.decode()}
            row["modules"].append({"layer": "mw", "original": identity(a.ROOT / command_source["path"]), "module_id": constant_id, "roles": ["brightness_command_constants"], "byte_start": constants["byte_start"], "byte_end": constants["byte_end"], "body_sha256": sha})
            commands = {}
            for role, export, expected in [("get", "a5" if pid == 756 else "_9", [3, 15, 132]), ("set", "CX" if pid == 756 else "ne", [3, 15, 4]), ("regions", "eg" if pid == 756 else "Z1", [80, 15, 128])]:
                expression = re.search(re.escape(export) + r':(?:\(\)=>([\w$]+)|function\(\)\{return ([\w$]+)\})', constants["body"])
                if expression is None:
                    raise ValueError("Command export is unresolved: " + export)
                name = next(value for value in expression.groups() if value is not None)
                declaration = re.search(r'\b' + re.escape(name) + r'=(.*?)(?=,[a-zA-Z_$][\w$]*=|;)', constants["body"])[1]
                values = re.findall(r'new Uint8Array\((\[[^\]]+\])\)', declaration)
                if not values or json.loads(values[-1]) != expected:
                    raise ValueError("Command constant differs: " + role)
                commands[role] = {"export": export, "symbol": name, "command": expected}
            region = 5 if 'regionIdEnum:"BacklightLED"' in registration["body"] else 0
            if (region == 5) != (pid == 631):
                raise ValueError("Brightness source region selection changed")
            wired = 2 if pid == 631 else 3
            if pid == 658:
                if "claimInterface:{656:2,657:3,658:3}" not in config["body"]:
                    raise ValueError("Wired interface map changed")
            elif f"claimInterface:{wired}" not in config["body"]:
                raise ValueError("Wired interface changed")
            slot = re.search(r'OBMSlots:(\d+)', config["body"])
            slots = int(slot[1]) if slot else 0
            if slots != {631: 0, 658: 4, 756: 5}[pid]:
                raise ValueError("Source hardware-profile count changed")
            roles = {role for owner in row["modules"] for role in owner["roles"]}
            required = {"getter", "setter", "runner", "state_machine", "ui_label", "registration", "radio_factory"}
            if required - roles:
                raise ValueError("Brightness owner closure is missing: " + str(sorted(required - roles)))
            row["active_capability"] = {"product_id": pid, "wired_interface": wired, "region_id": region, "hardware_profile_slots": slots, "commands": commands}
            row["semantics"] = {"source_region": "BacklightLED5" if region else "AllRegion0 resolves first returned region, rejection selects1",
                "write": "profile1 active setter; floor(percent/100*255); source setter returns its acknowledgement without a getter",
                "read": "ceil(raw/255*100); no source getter-to-visible-slider synchronization is introduced",
                "task": "Mounted single-mode brightness; local draft/state-machine/task-runner owners retained in full including source persistence, error and cancellation branches",
                "rust_confirmation": "Existing Rust diagnostic readback remains separate from source draft persistence and optimistic UI; whole-page equality is not inferred"}
            descriptors.append((pid, wired, slots))
        except Exception as error:
            row["failures"].append(str(error).replace(str(a.ROOT), "<project>"))
    report_path = a.ROOT / ".analysis/results/frontend/keyboard-mw-audit.json"
    report = json.loads(report_path.read_bytes()) if report_path.exists() else {"schema_version": 1}
    report["brightness"] = {"recorded_at_utc": a.stamp(), "query_tool": identity(Path(__file__)), "products": products, "complete_modules": modules, "complete_functions": functions,
        "parser_versions": {name: importlib.metadata.version(name) for name in ["tree-sitter", "tree-sitter-javascript"]},
        "target_execution": False, "whole_page_complete": False, "runtime_acceptance": "unverified"}
    a.save(report_path, report)
    if args.prepare:
        if any(row["failures"] for row in products) or requested != [631, 658, 756]:
            raise ValueError("All three current brightness sources must verify before preparing descriptors")
        generated = "// Generated by tools/workspace.py audit-family-function --query keyboard-brightness.\n// Current complete source bodies: .analysis/results/frontend/keyboard-mw-audit.json brightness.\nconst CURRENT_AUDITED_KEYBOARDS: &[KeyboardSettingsDescriptor] = &[\n"
        for pid, interface, slots in descriptors:
            generated += f"    KeyboardSettingsDescriptor {{ product_id: {pid}, claim_interface: {interface}, claim_interfaces_by_pid: &[], hardware_profile_slots: {slots} }},\n"
        generated += "];\n"
        (a.ROOT / "crates/razer-device/src/keyboard/keyboard_brightness_current_generated.rs").write_text(generated, encoding="utf-8")
    print(json.dumps({"receipt": a.rel(report_path), "field": "brightness", "products": len(products), "modules": len(modules), "functions": len(functions), "failures": [{"product_id": row["product_id"], "failures": row["failures"]} for row in products if row["failures"]]}), flush=True)


def audit_runtime_setup(args):
    """Verify source setup publication separately from telemetry/settings I/O."""
    families = list(FAMILY_CANDIDATES) if args.family == "all" else [args.family]
    catalog_path = a.builtin_data_path("razer-model", "RUNTIME_SETUP_DATA")
    policies = {row["product_id"]: row for row in json.loads(catalog_path.read_bytes())} if catalog_path.exists() else {}
    for family in families:
        report_path = a.ROOT / f".analysis/results/frontend/{family}-mw-audit.json"
        report = json.loads(report_path.read_bytes()) if report_path.exists() else {}
        previous = report.get("runtime_setup", {}).get("products", [])
        products = {row["product_id"]: row for row in previous}
        matrix = a.ROOT / f".analysis/results/families/{family}-mw.json"
        ids = args.product or sorted({item["product_id"] for item in json.loads(matrix.read_bytes())["products"]})
        for pid in ids:
            row = {"product_id": pid, "failures": [], "original_inputs": []}
            products[pid] = row
            try:
                receipt = a.ROOT / f".analysis/inputs/frontend/{family}-mw-{pid}-current/acquisition.json"
                captured_path = a.ROOT / f".analysis/results/frontend/{family}-mw-{pid}-current/analysis.json"
                acquired, captured = json.loads(receipt.read_bytes()), json.loads(captured_path.read_bytes())
                row.update({"acquisition": identity(receipt), "capture": identity(captured_path),
                            "tool": captured["tool"], "declared_references_fetched": acquired.get("declared_references_fetched"),
                            "unresolved_acquisition": acquired.get("unresolved", []),
                            "capture_failures": [item for item in captured.get("commands", []) if item.get("exit_code")]})
                if not acquired.get("source_current_during_acquisition") or not captured.get("input_bytes_unchanged"):
                    raise ValueError("Current middleware acquisition/capture is unverified")
                roots = [item for item in acquired["files"] if item.get("url") == acquired["entry_url"]
                         or item.get("url") == urllib.parse.urljoin(acquired["entry_url"], "webpackManifest.json")]
                if not roots or any(not valid(item) for item in roots):
                    raise ValueError("Current mounted entry/webpack manifest identity differs")
                reachable = {item["url"] for item in roots}
                for _ in range(len(acquired["edges"]) + 1):
                    following = reachable | {edge["to"] for edge in acquired["edges"] if edge["from"] in reachable}
                    if following == reachable:
                        break
                    reachable = following
                mounted_mains = {edge["to"] for edge in acquired["edges"]
                                 if edge["from"] == acquired["entry_url"] and edge["kind"] == "html:script:src"
                                 and Path(urllib.parse.urlparse(edge["to"]).path).name.startswith("main.")}
                row["roots"] = roots
                initial, setups = [], []
                firmware_owners = {}
                for source in acquired["files"]:
                    if not source.get("path") or not source["path"].endswith(".js") or source["url"] not in reachable:
                        continue
                    if not valid(source):
                        raise ValueError("Original differs from acquisition: " + source["path"])
                    row["original_inputs"].append({key: source[key] for key in ("path", "bytes", "sha256")})
                    text = (a.ROOT / source["path"]).read_text(encoding="utf-8")
                    if pid in (164, 179, 241) and "getExtendedFirmwareVersion(){" in text and "isSetup already true, prevent setup!" in text:
                        for role, firmware_anchor in {
                            "base_getter": "getExtendedFirmwareVersion(){",
                            "command_constants": "new Uint8Array([4,0,135])",
                            "firmware_runtime_publication": "Fail to check firmware version",
                        }.items():
                            module = complete_raw_module(text, firmware_anchor)
                            firmware_owners[role] = {**module, "original": source,
                                "complete_capture_modules": source_capture_modules(captured, source)}
                    if pid in (164, 179, 241):
                        sender = {164: "rzDevice25Linker.", 179: "rzDevice25LinkerUma.", 241: "rzDevice25LinkerMultiDevices."}[pid]
                        if Path(source["path"]).name.startswith(sender):
                            if "getExtendedFirmwareVersion" in text:
                                raise ValueError("Receiver firmware getter is overridden; re-audit required")
                            firmware_owners["physical_sender"] = {"original": source,
                                "complete_capture_modules": source_capture_modules(captured, source)}
                    if source["url"] in mounted_mains:
                        for match in re.finditer(r"runtimeData:\{", text):
                            start = match.end() - 1
                            end = javascript_delimited(text, start)
                            body = text[start:end]
                            source_pid = re.search(r"\bproductId:(\d+)[,}]", body)
                            source_status = re.search(r'setupStatus:"(waiting|unknown)"', body)
                            if source_pid and source_status:
                                initial.append({"original": source, "character_start": start, "character_end": end,
                                                "source_product_id": int(source_pid[1]), "setup_status": source_status[1],
                                                "body": body, "complete_capture_modules": source_capture_modules(captured, source)})
                    anchor = "isSetup already true, prevent setup! This causes multiple state machine listener to occur."
                    if anchor not in text:
                        continue
                    offset = text.index(anchor)
                    functions = list(re.finditer(r"function ([\w$]+)\([^{}]*\)\{", text[:offset]))
                    for match in reversed(functions):
                        end = javascript_delimited(text, match.end() - 1)
                        if end <= offset:
                            continue
                        body = text[match.start():end]
                        ready = re.search(r"setupStatus:[\w$.]+\.READY", body)
                        if ready is None or ready.start() > body.index(anchor) or "window.location.reload()" not in body:
                            continue
                        try:
                            module = complete_raw_module(text, text[match.start():match.end()])
                        except ValueError:
                            module = next((module for module in keyboard_source_modules(text)
                                           if module["character_start"] <= match.start() < module["character_end"]),
                                          {"module_id": None})
                        setups.append({"original": source, "name": match.group(1), "module_id": module["module_id"],
                                       "character_start": match.start(), "character_end": end, "body": body,
                                       "complete_capture_modules": source_capture_modules(captured, source)})
                        break
                if len(initial) != 1 or len(setups) != 1:
                    raise ValueError(f"Setup producer is not unique: initial={len(initial)}, setup={len(setups)}")
                row.update({"initial_runtime_data": initial[0], "setup_on_device_ready": setups[0],
                            "ready_before_profile_initialization": True,
                            "ready_is_not_device_read_or_write_success": True})
                if pid in (164, 179, 241):
                    if set(firmware_owners) != {"base_getter", "command_constants", "firmware_runtime_publication", "physical_sender"}:
                        raise ValueError("Receiver firmware chain is incomplete")
                    row["receiver_firmware"] = {"method": "getExtendedFirmwareVersion", "command": [4, 0, 135],
                        "minimum_response_bytes": 4, "version_fields": [0, 1, 2, 3], "complete_owners": firmware_owners}
                source_pid = initial[0]["source_product_id"]
                row["source_product_id"] = source_pid
                if source_pid != pid:
                    row["route_alias"] = {"requested_route": pid, "runtime_product_id": source_pid}
                policies[source_pid] = {"product_id": source_pid, "ready_before_profile_initialization": True,
                                        "initial_setup_status": initial[0]["setup_status"]}
            except (OSError, ValueError, KeyError, StopIteration) as error:
                row["failures"].append(str(error) or type(error).__name__)
            print(json.dumps({"family": family, "product_id": pid, "runtime_setup_failures": row["failures"]}), flush=True)
        report["runtime_setup"] = {"tool": identity(Path(__file__)), "products": list(products.values()),
                                   "target_execution": False, "runtime_acceptance": "unverified"}
        a.save(report_path, report)
    a.save(catalog_path, [policies[pid] for pid in sorted(policies)])


def keyboard_gamepad_compiler_contract(transaction, compiler, registration, unregister, callback, ui_class):
    """Check the retained non-FW producer and its distinct observation lifecycle."""
    compact = lambda body: re.sub(r"\s+", "", body)
    transaction, compiler, registration, unregister, callback, ui_class = map(compact,
        (transaction, compiler, registration, unregister, callback, ui_class))
    required = {
        "mapping registration": (transaction, ("DeviceInfo.isFWAnalogMapping||", ".analogV3", ".XC)()", ".Y$)()")),
        "document commit": (transaction, (".version=", ".Pf)(", ".qw)(", 'status:"completed"', 'status:"error"', "finally{")),
        "compiler": (compiler, ("generateAnalogMappings(", "generateAppEngineMappings(", "JSON.stringify(", ".actuations=", ".rapidTriggers=", ".hash=", "RzLockableStorageError", "while(", "<3")),
        "registration": (registration, ("isXboxGamepadEventRegistered(", "=50", "PollingRateSkipMap", "registerXboxGamepadEvent(", '.on("xboxGamepadEvent",')),
        "unregister": (unregister, ("isXboxGamepadEventRegistered(", "unregisterXboxGamepadEvent(", '.off("xboxGamepadEvent",', 'console.warn("Failedtounregister')),
        "callback": (callback, ("DeviceInfo.productId", "Array.isArray(", "JSON.parse(e.jsonEvent)", "O!==t", "setTimeout(", ",5)")),
    }
    for role, (body, tokens) in required.items():
        if any(token not in body for token in tokens):
            raise ValueError("Non-FW keyboard gamepad " + role + " source contract differs")
    if (transaction.index(".XC)()") > transaction.index(".Y$)()")
            or unregister.index("unregisterXboxGamepadEvent(") > unregister.index('.off("xboxGamepadEvent",')
            or "O=null" in unregister):
        raise ValueError("Non-FW keyboard gamepad registration/release order differs")
    if (not re.search(r'registerXboxGamepadEvent\([^;]+\)\)\?[\w$.]+\.on\("xboxGamepadEvent",', registration)
            or not re.search(r'unregisterXboxGamepadEvent\([^;]+\)\)\?[\w$.]+\.off\("xboxGamepadEvent",', unregister)
            or not transaction.index(".Pf)(") < transaction.index('status:"completed"') < transaction.index("enqueueTask(")):
        raise ValueError("Non-FW keyboard gamepad status/commit consumer changed")
    if "toggleXboxRegistration" in ui_class or "IntersectionObserver" in ui_class:
        raise ValueError("Non-FW keyboard tester now requires an independent in-view lifecycle review")
    return {"source_chain": "current_mapping_document_and_tester_consumers_verified",
        "mapping_mode": "analogV3_non_firmware", "events_requested_skip": 50,
        "assignment_source": "MW52418.$T_ten_analog_controller_assignments",
        "compiler_outputs": ["mappings", "actuations", "rapidTriggers", "hash"],
        "turbo_storage_conflict_attempts": 3,
        "registration": "unregister then register Events only when matching AnalogInput assignments and analogV3 are present",
        "registration_failure": "false registration does not attach the callback; false unregister does not detach it",
        "callback_playback_ms": 5, "new_callback_replaces_old_playback": True,
        "unregister_cancels_started_playback": False, "ui_in_view_interval5_mounted": False,
        "document_commit_is_device_confirmation": False, "callback_is_device_readback": False,
        "target_execution": False, "runtime_acceptance": "unverified"}


def keyboard_non_firmware_gamepad_sources(audit, pid, ui_files, mw_files, tester):
    """Join each selected compiler to its actual UI consumer and source imports."""
    import evidence
    ui = next(source for source in ui_files if Path(source["path"]).name.startswith("main."))
    entry = next(source for source in mw_files if Path(source["path"]).name.startswith("main."))
    loader = re.findall(rb'Promise\.all\(\[([\w$]+)\.e\(2291\),\1\.e\(6737\),\1\.e\(1364\)\]\)'
                        rb'\.then\(\1\.bind\(\1,16737\)\)', audit.read(entry))
    if len(loader) != 1:
        raise ValueError("Non-FW keyboard mapping startup chunk selection differs")
    selected = []
    if b'1364:"onLoad"' not in audit.read(entry):
        raise ValueError("Non-FW keyboard startup chunk1364 no longer resolves to onLoad")
    for prefix in ("main", "2291", "6737", "onLoad"):
        matches = [source for source in mw_files if Path(source["path"]).name.startswith(prefix + ".")
                   and source["path"].endswith(".js")]
        if len(matches) != 1:
            raise ValueError("Non-FW keyboard selected startup chunk is absent or ambiguous: " + prefix)
        selected.append(matches[0])
    modules, bindings = {}, {}
    for source in selected:
        pending = [audit.tree(source).root_node]
        while pending:
            node = pending.pop()
            if node.type in {"pair", "method_definition"}:
                name = node.child_by_field_name("key" if node.type == "pair" else "name")
                value = node.child_by_field_name("value") if node.type == "pair" else node
                if name is not None and name.type == "number" and value is not None and value.type in {
                        "method_definition", "arrow_function", "function_expression"}:
                    modules.setdefault(javascript_integer_literal(name.text.decode()), []).append((source, node))
                    continue
            pending.extend(node.named_children)
    dependencies, pending = {}, [32226]
    while pending:
        mid = pending.pop()
        if str(mid) in dependencies:
            continue
        matches = modules.get(mid, [])
        if len(matches) != 1:
            raise ValueError("Non-FW keyboard compiler dependency is absent or ambiguous: " + str(mid))
        source, node = matches[0]
        if source["path"] not in bindings:
            bindings[source["path"]] = evidence.JavascriptBindings(audit.read(source), audit.tree(source))
        imports = javascript_factory_static_imports(node, bindings[source["path"]])
        owner = audit.retain_range("gamepad_compiler_dependency_" + str(mid), source,
                                   node.start_byte, node.end_byte, node.type)
        dependencies[str(mid)] = {"complete_owner": owner, "static_imports": imports}
        pending.extend(imports)
    wrapper = audit.owners[dependencies["32226"]["complete_owner"]]["body"]
    if not re.search(r'var ([\w$]+)=[\w$]+\(69183\);', wrapper) or "t.A=n.RzAppEngineMapping_default" not in wrapper:
        raise ValueError("Non-FW keyboard compiler wrapper selects a different factory")
    exports = {role: audit.webpack_export("gamepad_" + str(pid) + "_" + role, selected, mid, exported)
        for role, mid, exported in (("transaction", 42124, "tB"), ("compiler", 42124, "yH"),
            ("register_events", 14486, "Y$"), ("register_interval", 14486, "q6"),
            ("unregister", 14486, "XC"), ("assignment_filter", 52418, "$T"),
            ("device_info", 26061 if pid == 678 else 69427, "DeviceInfo"))}
    source = exports["compiler"]["original"]
    owners = {role: value["binding"]["owner_id"] for role, value in exports.items()}
    device = exports["device_info"]["binding"]
    device_source = exports["device_info"]["original"]
    declaration = audit.tree(device_source).root_node.descendant_for_byte_range(device["start_byte"], device["end_byte"] - 1)
    value = declaration.child_by_field_name("value")
    if value is None or value.type != "object":
        raise ValueError("Non-FW keyboard DeviceInfo is no longer a direct object")
    fields = {pair.child_by_field_name("key").text.decode(): pair.child_by_field_name("value").text.decode()
              for pair in value.named_children if pair.type == "pair"}
    if (fields.get("productId") != str(pid) or fields.get("useTwoBytesActuation") != "!0"
            or fields.get("isFWAnalogMapping") not in (None, "!1")
            or fields.get("is8kAnalogDevice") not in (None, "!1")):
        raise ValueError("Non-FW keyboard actual product/mapping/registration metadata differs")
    for role, anchor, kinds in (
            ("callback", "O=t;const i=JSON.parse(e.jsonEvent)", {"variable_declarator"}),
            ("mapping_dispatch", 'case"ON_SET_KEYMAPPING":', {"switch_case"}),
            ("mapping_state_guard", "ON_SET_KEYMAPPING:[", {"pair"}),
            ("visibility_toggle", "toggleXboxRegistration(e)", {"variable_declarator", "method_definition"}),
            ("two_byte_setup", "DeviceInfo.useTwoBytesActuation&&", {"function_declaration"})):
        owners[role] = audit.retain("gamepad_" + str(pid) + "_" + role, source, anchor, kinds, unique=False)
    feature = [item for item in selected if b'useFeature("analogV3","yes",{})' in audit.read(item)]
    if len(feature) != 1:
        raise ValueError("Non-FW keyboard analogV3 startup owner is absent or ambiguous")
    owners["analog_v3_setup"] = audit.retain("gamepad_" + str(pid) + "_analog_v3_setup", feature[0],
        'useFeature("analogV3","yes",{})', {"function_declaration", "arrow_function", "method_definition"})
    tester_owner = audit.owners[tester[0]]
    raw = audit.read(ui)
    node = audit.tree(ui).root_node.descendant_for_byte_range(tester_owner["byte_start"], tester_owner["byte_end"] - 1)
    name = node.child_by_field_name("name")
    hits = list(re.finditer(rb'jsx\)\(' + re.escape(name.text) + rb',', raw))
    if len(hits) != 1:
        raise ValueError("Non-FW keyboard tester actual render consumer is absent or ambiguous")
    node = audit.tree(ui).root_node.descendant_for_byte_range(hits[0].start(), hits[0].end() - 1)
    while node is not None and node.type not in {"class_declaration", "class"}:
        node = node.parent
    if node is None:
        raise ValueError("Non-FW keyboard tester owning class is absent")
    owners["ui_class"] = audit.retain_range("gamepad_" + str(pid) + "_actual_ui_class", ui,
                                             node.start_byte, node.end_byte, node.type)
    owners["ui_lifecycle"] = {}
    for child in node.child_by_field_name("body").named_children:
        name = child.child_by_field_name("name") if child.type == "method_definition" else None
        if name is not None and name.text in {b"componentDidMount", b"componentDidUpdate", b"componentWillUnmount", b"render"}:
            owners["ui_lifecycle"][name.text.decode()] = audit.retain_range("gamepad_" + str(pid) + "_" + name.text.decode(),
                ui, child.start_byte, child.end_byte, child.type)
    owners["ui_reducer"] = audit.retain("gamepad_" + str(pid) + "_ui_reducer", ui,
        "gamepadTester:t.payload", {"variable_declarator"})
    for role, anchor in (("analog_collection", "this.generateAnalogMappings="),
                         ("analog_mapping", "this.generateAppEngineAnalogMappings="),
                         ("ordinary_mapping", "this.generateAppEngineMappings="),
                         ("two_byte_enable", "this.enableUseTwoBytesActuation=")):
        candidates = [item for item in selected if anchor.encode() in audit.read(item)]
        if len(candidates) != 1:
            raise ValueError("Non-FW keyboard mapping algorithm owner is absent or ambiguous: " + role)
        owners[role] = audit.retain("gamepad_" + str(pid) + "_" + role, candidates[0], anchor, {"assignment_expression"})
    contract = keyboard_gamepad_compiler_contract(*(audit.owners[owners[role]]["body"]
        for role in ("transaction", "compiler", "register_events", "unregister")),
        audit.owners[owners["callback"][0]]["body"], audit.owners[owners["ui_class"]]["body"])
    return {"exports": exports, "owners": owners, "compiler_static_dependencies": dependencies,
        "device_metadata": {"product_id": pid, "use_two_bytes_actuation": True,
            "firmware_mapping_property": fields.get("isFWAnalogMapping", "absent"),
            "is_8k_property": fields.get("is8kAnalogDevice", "absent"),
            "analog_generation_property": fields.get("AnalogGenVersion", "absent")},
        "selected_startup_chunks": selected, "semantics": contract,
        "rust_consumer": "incomplete", "target_execution": False, "runtime_acceptance": "unverified"}


def driver_install_nsis_chunk(raw, offset, end, *, maximum_output=8 * 1024 * 1024):
    """Decode one file-backed non-solid LZMA record without executing its VM."""
    import lzma
    import struct
    if not 0 <= offset <= end - 4 <= len(raw) - 4 or maximum_output <= 0:
        raise ValueError("Driver NSIS chunk has invalid file bounds")
    field = struct.unpack_from("<I", raw, offset)[0]
    size = field & 0x7fffffff
    if not 0 < size <= end - offset - 4:
        raise ValueError("Driver NSIS chunk exceeds its container")
    body = raw[offset + 4:offset + 4 + size]
    if field & 0x80000000:
        if len(body) <= 5 or body[0] >= 225:
            raise ValueError("Driver NSIS LZMA properties are invalid")
        value, dictionary = body[0], struct.unpack_from("<I", body, 1)[0]
        if not 4096 <= dictionary <= 64 * 1024 * 1024:
            raise ValueError("Driver NSIS LZMA dictionary is unbounded")
        filters = [{"id": lzma.FILTER_LZMA1, "dict_size": dictionary,
                    "lc": value % 9, "lp": value // 9 % 5, "pb": value // 45}]
        try:
            decoder = lzma.LZMADecompressor(format=lzma.FORMAT_RAW, filters=filters)
            value = decoder.decompress(body[5:], max_length=maximum_output + 1)
        except lzma.LZMAError as error:
            raise ValueError("Driver NSIS LZMA stream is invalid") from error
        if len(value) > maximum_output or not decoder.eof or decoder.unused_data:
            raise ValueError("Driver NSIS LZMA stream is incomplete, oversized or has trailing bytes")
    else:
        value = body
        if len(value) > maximum_output:
            raise ValueError("Driver NSIS uncompressed record is oversized")
    return value, {"file_offset": offset, "packed_bytes": size + 4, "bytes": len(value),
        "sha256": hashlib.sha256(value).hexdigest(), "compressed": bool(field & 0x80000000)}


def driver_install_nsis_header(raw, offset):
    """Read the observed ANSI, non-solid NSIS entry/string tables with bounds."""
    import struct
    if not 0 <= offset <= len(raw) - 32:
        raise ValueError("Driver NSIS firstheader is outside the file")
    fields = struct.unpack_from("<7I", raw, offset)
    if fields[1:5] != (0xdeadbeef, 0x6c6c754e, 0x74666f73, 0x74736e49):
        raise ValueError("Driver NSIS firstheader signature differs")
    logical, following = fields[5:7]
    if not 68 <= logical <= 1024 * 1024 or not 32 <= following <= len(raw) - offset:
        raise ValueError("Driver NSIS header/container lengths are invalid")
    header, record = driver_install_nsis_chunk(raw, offset + 28, offset + following,
                                              maximum_output=1024 * 1024)
    if len(header) != logical:
        raise ValueError("Driver NSIS header logical length differs")
    blocks = [struct.unpack_from("<II", header, 4 + index * 8) for index in range(8)]
    nonzero = [start for start, count in blocks if start]
    if nonzero != sorted(nonzero) or any(not 68 <= start <= len(header) for start in nonzero):
        raise ValueError("Driver NSIS block offsets are unordered or outside the header")
    entries, count = blocks[2]
    strings = blocks[3][0]
    string_end = next((start for start, _ in blocks[4:] if start), len(header))
    if not 0 < count <= 32768 or entries + count * 28 != strings or not strings < string_end <= len(header):
        raise ValueError("Driver NSIS entry/string boundary is invalid")
    result = {"firstheader_offset": offset, "firstheader_fields": list(fields),
        "header_record": record, "header_bytes": len(header), "header_sha256": hashlib.sha256(header).hexdigest(),
        "entry_offset": entries, "entry_count": count, "string_offset": strings,
        "string_bytes": string_end - strings, "data_offset": offset + 28 + record["packed_bytes"],
        "container_end": offset + following,
        "entries": [list(struct.unpack_from("<7i", header, entries + index * 28)) for index in range(count)]}
    return result, header[strings:string_end]


def driver_install_nsis_string(strings, offset):
    """Keep NSIS variable, shell and language tokens instead of dropping them."""
    if type(offset) is not int or not 0 <= offset < len(strings):
        raise ValueError("Driver NSIS string offset is outside its table")
    tokens, literal, cursor = [], bytearray(), offset
    def flush():
        if literal:
            try:
                value = literal.decode("ascii")
            except UnicodeDecodeError as error:
                raise ValueError("Driver NSIS string requires an independently reviewed code page") from error
            tokens.append({"kind": "literal", "value": value})
            literal.clear()
    while cursor < len(strings):
        code = strings[cursor]
        cursor += 1
        if code == 0:
            flush()
            return tokens
        if code in (1, 2, 3):
            flush()
            if cursor + 2 > len(strings) or not all(strings[cursor:cursor + 2]):
                raise ValueError("Driver NSIS string has a truncated encoded token")
            lo, hi = strings[cursor:cursor + 2]
            tokens.append({"kind": {1: "language", 2: "shell", 3: "variable"}[code],
                           "index": (lo & 127) | ((hi & 127) << 7), "encoded": [lo, hi]})
            cursor += 2
        elif code == 4:
            if cursor >= len(strings) or strings[cursor] == 0:
                raise ValueError("Driver NSIS string has a truncated escape")
            literal.append(strings[cursor])
            cursor += 1
        else:
            literal.append(code)
    raise ValueError("Driver NSIS string is unterminated")


